local _safePlayersCache = nil
local function getSafePlayers()
    if _safePlayersCache then return _safePlayersCache end
    local list = {}
    for _, p in ipairs(Players:GetChildren()) do
        if p:IsA("Player") then list[#list+1] = p end
    end
    _safePlayersCache = list   -- read-only; rebuilt only when the player list changes
    return list
end
Players.PlayerAdded:Connect(function() _safePlayersCache = nil end)
Players.PlayerRemoving:Connect(function() _safePlayersCache = nil end)

-- ═══════════════════════════════════════════════════════════════════════
-- LOADING GUARD — prevents crashes when joining a new game
-- ═══════════════════════════════════════════════════════════════════════
local function waitForGameReady()
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer
    -- Kicia waits on exactly this and nothing else (leak 20422 / 20744) before running its bypasses;
    -- UE does not even wait on it. Keep it: everything below indexes lp.PlayerScripts.
    repeat task.wait() until game:IsLoaded()
    if not lp then
        repeat task.wait() until Players.LocalPlayer
        lp = Players.LocalPlayer
    end
    if not lp:FindFirstChild("PlayerScripts") then
        repeat task.wait() until lp:FindFirstChild("PlayerScripts")
    end
    -- ★ THE CHARACTER WAIT IS BOUNDED, 2026-08-15. This used to be
    --       repeat task.wait() until lp and lp.Character
    -- which blocks the ENTIRE script for as long as the player has no character — the lobby before a
    -- spawn, a spectator slot, the between-rounds gap. NEITHER reference script waits on a character at
    -- all. Nothing below needs one: the gun hook is (re)bound from CharacterAdded, and every feature
    -- already nil-checks the character. So this is now a courtesy wait for the common case where the
    -- character is a frame away, and it gives up instead of hanging.
    local deadline = tick() + 5
    while lp.Character == nil and tick() < deadline do task.wait() end
    return true
end
waitForGameReady()

-- ═══════════════════════════════════════════════════════════════════════
-- SAFE REQUIRE — timeout‑based, no more nil crashes
-- ═══════════════════════════════════════════════════════════════════════
local function safeRequire(path, timeout)
    if not path then return nil end
    timeout = timeout or 5
    local start = tick()
    while tick() - start < timeout do
        local ok, result = pcall(require, path)
        if ok then return result end
        task.wait(0.2)
    end
    return nil
end

-- Resolve a module path WITHOUT throwing if a segment hasn't replicated yet (rare slow joins): WaitForChild
-- per segment with a timeout, so we never error at the top level and never index a nil child.
local function waitModule(root, names, timeout)
    timeout = timeout or 10
    local obj = root
    for _, n in ipairs(names) do
        if not obj then return nil end
        local ok, child = pcall(function() return obj:WaitForChild(n, timeout) end)
        obj = ok and child or nil
    end
    return obj
end

-- ═══════════════════════════════════════════════════════════════════════
-- MOBILE SUPPORT DETECTION & INPUT ABSTRACTION
-- ═══════════════════════════════════════════════════════════════════════
local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled

local function isMouseButtonDown()
    if isMobile then
        return true   -- on mobile, always allow firing (can be toggled via button)
    else
        return UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
    end
end

local function isInputActive(key)
    if key == "MB1" then return isMouseButtonDown() end
    if key == "MB2" then
        if isMobile then return true end
        return UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
    end
    if key == "Always" then return true end
    local kc = Enum.KeyCode[key]
    if kc and not isMobile then
        return UserInputService:IsKeyDown(kc)
    end
    -- fallback for mobile – assume active if not a keyboard key
    return false
end


-- ═══════════════════════════════════════════════════════════════════════
-- RIVALS MODULES — loaded once, no poller needed
-- ═══════════════════════════════════════════════════════════════════════
-- THE RARE "whole game breaks / no guns" crash: if WE require a game ModuleScript before the game does,
-- it can run before its deps are ready, ERROR, and Roblox CACHES that error — so the game's own require
-- re-throws forever and the weapon system never initializes. Fix: if the executor exposes getloadedmodules,
-- WAIT until the GAME has already loaded the module, so our require only ever returns the game's cached
-- (good) result and can never be the one that runs (and bricks) it. No-op if the API is unavailable.
local function awaitGameLoaded(moduleInst, timeout)
    if not moduleInst or type(getloadedmodules) ~= "function" then return end
    local deadline = tick() + (timeout or 15)
    repeat
        local ok, loaded = pcall(getloadedmodules)
        if ok and type(loaded) == "table" then
            for _, m in ipairs(loaded) do
                if m == moduleInst then return end
            end
        end
        task.wait(0.1)
    until tick() >= deadline
end
local function loadGameModule(root, names)
    local inst = waitModule(root, names)
    awaitGameLoaded(inst, 15)
    return safeRequire(inst)
end

local Rivals = { Ready = false }

-- Forward-declared ABOVE the module resolution because the background weapon resolver below re-runs it
-- the moment Rivals.Gun arrives, and the CharacterAdded closure captures it too. The body is assigned
-- in 08_gunhook.lua (bundled after this file); without this hoist both references would bind to a nil
-- global and the gun hook would silently never run.
local hookGunModule

-- ★ WHY THIS IS PARALLEL — THE LOAD DELAY, FIXED 2026-08-15.
-- Every loadGameModule is `waitModule` (WaitForChild, ≤10 s per path segment) THEN `awaitGameLoaded`,
-- which polls getloadedmodules() every 0.1 s for up to 15 s waiting for the GAME to require the module
-- first. Eight of those IN SERIES is up to ~2 minutes of blocking before the GUI can exist, and that is
-- what the operator saw as "the script loads after the whole game loads / after some timer".
-- Neither reference script pays this. Kicia waits only `repeat task.wait() until game:IsLoaded()`
-- (leak 20422 / 20744) and then requires directly; UE has no game-load wait at all and no
-- getloadedmodules gate anywhere. We keep the guard — it prevents the real "no guns" brick described
-- above awaitGameLoaded — but we stop paying for it eight times end to end.
local function resolveAll(jobs, timeout)
    local pending = #jobs
    for _, job in ipairs(jobs) do
        task.spawn(function()
            pcall(job)
            pending = pending - 1
        end)
    end
    local deadline = tick() + (timeout or 25)
    while pending > 0 and tick() < deadline do task.wait() end
    return pending == 0
end

-- THE FAST SET. Every one of these is required by the game's own UI during join, so awaitGameLoaded
-- returns on its first poll and this whole block costs ~nothing. We block on it because the GUI and
-- every read-only feature need it.
resolveAll({
    function() Rivals.Util    = loadGameModule(ReplicatedStorage, {"Modules","Utility"}) end,
    function() Rivals.Fighter = loadGameModule(lp.PlayerScripts,  {"Controllers","FighterController"}) end,
    function() Rivals.Enums   = loadGameModule(ReplicatedStorage, {"Modules","EnumLibrary"}) end,
    -- Game Visuals reads its catalogue out of these rather than shipping a hardcoded skin list, which
    -- goes stale on every content update and then applies a viewmodel name the game does not have.
    function() Rivals.Cosmetics = loadGameModule(ReplicatedStorage, {"Modules","CosmeticLibrary"}) end,
    function() Rivals.ItemLib   = loadGameModule(ReplicatedStorage, {"Modules","ItemLibrary"}) end,
})

-- ★ Ready NOW MEANS "the fast set resolved", not "Gun resolved". That is safe because every single
-- consumer already conjoins Ready with the specific module it needs — 05_utils tests
-- `Rivals.Ready and Rivals.Fighter`, 07b tests `Rivals.Ready and Rivals.Enums and Rivals.Util`, and
-- 08_gunhook opens with `if not Rivals.Ready or not Rivals.Gun then return end`. Nothing reads Gun
-- through Ready alone.
Rivals.Ready = (Rivals.Util ~= nil and Rivals.Fighter ~= nil)

-- THE WEAPON SET, RESOLVED IN THE BACKGROUND. These are the three that actually cost the 15 s wait:
-- the game only requires an ItemType when it builds a weapon, so in the lobby getloadedmodules never
-- contains them and awaitGameLoaded times out. Nothing here is needed until you are holding a gun, so
-- the wait is moved off the critical path and re-driven on spawn.
-- Melee is the SHARED base class, the exact counterpart of Gun: Melee.StartShooting is the light attack
-- for Fists / Riot Shield / Battle Axe / every katana. Knife is a SUBCLASS that adds StartAiming as its
-- heavy attack, the same way Minigun/Revolver subclass Gun — so both are needed to cover melee.
local _weaponResolving = false
local function resolveWeaponModules()
    if _weaponResolving then return end
    if Rivals.Gun ~= nil and Rivals.Melee ~= nil and Rivals.Knife ~= nil then return end
    _weaponResolving = true
    task.spawn(function()
        resolveAll({
            function() if Rivals.Gun   == nil then Rivals.Gun   = loadGameModule(lp.PlayerScripts, {"Modules","ItemTypes","Gun"})   end end,
            function() if Rivals.Melee == nil then Rivals.Melee = loadGameModule(lp.PlayerScripts, {"Modules","ItemTypes","Melee"}) end end,
            function() if Rivals.Knife == nil then Rivals.Knife = loadGameModule(lp.PlayerScripts, {"Modules","Items","Knife"})     end end,
        })
        _weaponResolving = false
        -- 08_gunhook.lua calls hookGunModule() at bundle load and it bails on a nil Rivals.Gun, so this
        -- is the call that actually binds the gun hook when the module arrives late. Without it the
        -- backgrounding would silently cost us silent aim and rage.
        if Rivals.Gun ~= nil and hookGunModule ~= nil then pcall(hookGunModule) end
    end)
end
resolveWeaponModules()

-- When the local character respawns (new round), ensure hooks are re‑applied. This is also the natural
-- retry for the weapon modules: spawning is precisely when the game requires an ItemType, so a lobby
-- load that timed out above resolves here on the first spawn.
lp.CharacterAdded:Connect(function()
    task.wait(0.5)
    resolveWeaponModules()
    if Rivals.Ready and hookGunModule then
        hookGunModule()
    end
end)

local function getEquippedItem()
    if not Rivals.Ready then return nil end
    local f = Rivals.Fighter and Rivals.Fighter.LocalFighter
    return f and f.EquippedItem or nil
end

-- ── AC BYPASS  Layer 1 — installed at the TOP of this file (right after the unload guard, before the
-- game-load waits) to win the race against the MiscellaneousController weak-GC probe. See that block. ──

-- ── CONSTANT-PATCH ENGINE + VERSION GATE ────────────────────────────────────────────────────────
-- Modify a live game function WITHOUT hooking it, by rewriting an entry in its constant pool.
-- The function object is untouched, so `isfunctionhooked` stays false, `debug.info` is unchanged, and
-- there is no wrapper closure for an integrity probe to find. This is the primitive Kicia is built on:
-- the leaked source (2026-08-06) hooks ZERO game functions and installs ZERO metamethods, yet has 61
-- `debug.setconstant` sites. `"FireServer"` -> `"GetChildren"` neuters a remote send; index-2 `1` -> `999`
-- inflates a loop's interval constant until the loop never runs again.
--
-- PORTED (Kicia `f7409`, L112091-112149, cross-checked against its second emission at L240465-240531):
--   * resolve every target function FIRST, patch only after all resolve  (L112091-112110)
--   * match a constant BY VALUE, not by a hard-coded index               (L112124-112126)
--   * record {method, index, constant} for every write                   (L112128)
--   * on ANY miss, roll back every write already applied, then error     (L112134-112146)
--   * resolve `holder.name` with rawget, never an index                  (copy B L240475, `rawget3`)
--   * one level of proto descent via getprotos/getproto(fn, i, true)[1]  (RemoteEventBlocker L106375)
--
-- OURS, and the reason each exists — a constant patch is a WRITE INTO LIVE GAME CODE, and the failure
-- mode is not "the feature does not work", it is "a game function is now silently corrupt":
--   * FULL DRY RUN. Kicia patches as it walks and unwinds on failure; we validate the entire set with
--     zero writes, so a set that fails its gate never touches the process at all.
--   * VERSION GATE. Rivals ships silent updates. Value-matching already survives index drift, but not
--     the case where the constant we key on has MOVED ROLE — patching the first `"FireServer"` in a
--     function that grew a second one corrupts the wrong call. Two independent checks below.
--   * TYPE LOCK. A string constant may only become a string. Changing a pool entry's type is how you
--     turn a working function into one that errors on its next call.
--   * CROSS-EXECUTION LEDGER. Patches outlive our chunk. An instance killed without unloading leaves
--     the game permanently modified — a persistent, readable anomaly on an account we care about.
--
-- The version gate is TWO checks, because they catch different things:
--   1. OCCURRENCE COUNT (always on, free). The target value must appear exactly as many times as the
--      source declares — once, unless stated. An extra occurrence means the function changed shape and
--      we no longer know which site is ours, so we refuse instead of guessing. This is the check that
--      actually protects us today.
--   2. FINGERPRINT (opt-in per source, off until enrolled). A hash over the whole constant pool plus the
--      proto count. Any edit to the target function changes it. We have no live client to capture these
--      from, so shipped sources start without one; `ConstPatch.learn` reads them in a real match and the
--      numbers get baked into the source table. UNTIL THEN CHECK 1 IS THE ONLY GATE — do not describe a
--      source as version-gated because this file exists.

local ConstPatch = {}

;(function()

-- Executors differ on whether these live bare or under `debug`. Resolve both; a missing API is not an
-- error here, it degrades `available()` so callers fail closed instead of erroring at a call site.
local _getconstants = getconstants or (debug and debug.getconstants)
local _setconstant  = setconstant  or (debug and debug.setconstant)
local _getprotos    = getprotos    or (debug and debug.getprotos)
local _getproto     = getproto     or (debug and debug.getproto)

local HAVE_CONST  = type(_getconstants) == "function" and type(_setconstant) == "function"
local HAVE_PROTOS = type(_getprotos) == "function" and type(_getproto) == "function"

local _sets = {}

-- Every applied write, shared across executions via getgenv so a NEXT run can undo what a dead run left
-- behind. Same survival pattern as __LH_SetmtBP (01_bootstrap) and shared._LH_GunOrig (08_gunhook).
-- Created only when something is actually written: with no patch sources shipped the engine is dormant
-- and must leave no getgenv key behind for anything to enumerate.
local function ledger(create)
    if not getgenv then
        return nil
    end
    local g = getgenv()
    local t = rawget(g, "__LH_ConstLedger")
    if not t and create then
        t = {}
        g.__LH_ConstLedger = t
    end
    return t
end

-- ── FINGERPRINT ─────────────────────────────────────────────────────────────────────────────────
-- djb2 over the constant pool. Chosen over FNV because `h * 33` stays exact under bit32 (h < 2^32, so
-- lshift(h,5)+h+b < 2^53) whereas FNV's 16777619 multiply silently loses mantissa bits. We are detecting
-- an accidental change from a game update, not resisting an adversary, so 32 bits is ample.
-- Deliberately NOT folded in: anything from debug.getinfo. `nups`/`numparams`/`is_vararg` are reported
-- inconsistently across executors, and a fingerprint that varies by executor would refuse to patch on a
-- machine where nothing is actually wrong. The constant pool is both stable and far more discriminating.
local HASH_SEED = 5381
local STR_CAP   = 256

local function hashByte(h, b)
    return bit32.band(bit32.lshift(h, 5) + h + b, 0xFFFFFFFF)
end

local function hashString(h, s)
    local n = #s
    h = hashByte(h, bit32.band(n, 0xFF))
    h = hashByte(h, bit32.band(bit32.rshift(n, 8), 0xFF))
    local upto = math.min(n, STR_CAP)
    for i = 1, upto do
        h = hashByte(h, string.byte(s, i))
    end
    return h
end

local function hashValue(h, v)
    local t = typeof(v)
    h = hashString(h, t)
    if t == "string" then
        return hashString(h, v)
    end
    if t == "number" then
        return hashString(h, string.format("%.17g", v))
    end
    if t == "boolean" then
        if v then
            return hashByte(h, 1)
        end
        return hashByte(h, 0)
    end
    -- table/function constants: the type tag only. Their contents are not stably readable and a
    -- template table's identity changes per closure, so including either would produce false refusals.
    return h
end

-- nil on any failure, which callers treat as "gate not satisfied" — a fingerprint that cannot be computed
-- must never read as a pass. Wrapped whole because a constant pool can hold values whose typeof/tostring
-- throws, and this runs inside Apply where an error would escape as a hard failure rather than a refusal.
function ConstPatch.fingerprint(fn)
    if not HAVE_CONST or type(fn) ~= "function" then
        return nil
    end
    local ok, result = pcall(function()
        local consts = _getconstants(fn)
        if type(consts) ~= "table" then
            return nil
        end
        local h = HASH_SEED
        for i, v in consts do
            h = hashValue(h, i)
            h = hashValue(h, v)
        end
        if HAVE_PROTOS then
            local protos = _getprotos(fn)
            if type(protos) == "table" then
                h = hashValue(h, #protos)
            end
        end
        return h
    end)
    if not ok then
        return nil
    end
    return result
end

-- ── RESOLUTION ──────────────────────────────────────────────────────────────────────────────────
-- rawget, never holder[name]: a game class table's __index would otherwise run on our behalf, and the
-- whole point of this engine is that nothing of the game's executes because we looked at it. The cost is
-- that an INHERITED method does not resolve — walk to the table that actually owns it, or pass `fn`.
local function resolveFn(src)
    if type(src.fn) == "function" then
        return src.fn
    end
    if type(src.holder) ~= "table" then
        return nil
    end
    local v = rawget(src.holder, src.name)
    if type(v) ~= "function" then
        return nil
    end
    return v
end

-- Which function objects this source may write to. "self" is the resolved function; "protos" is one
-- level of its children, each taken as its first ACTIVE closure. A proto with no live closure yields
-- nil and is skipped rather than failed — Kicia's RemoteEventBlocker skips them the same way.
local function candidates(fn, src)
    if src.scan ~= "protos" then
        return { fn }
    end
    if not HAVE_PROTOS then
        return nil, "executor lacks getprotos/getproto"
    end
    local ok, protos = pcall(_getprotos, fn)
    if not ok or type(protos) ~= "table" then
        return nil, "getprotos failed"
    end
    local out = {}
    for i in protos do
        local okG, live = pcall(_getproto, fn, i, true)
        if okG and type(live) == "table" and type(live[1]) == "function" then
            out[#out + 1] = live[1]
        end
    end
    return out
end

-- Every pool position this source matches in ONE function. Returns an array (possibly empty), or
-- nil + reason when the pool could not be read or an index-mode precondition failed.
local function collectMatches(fn, src)
    local ok, consts = pcall(_getconstants, fn)
    if not ok or type(consts) ~= "table" then
        return nil, "getconstants failed"
    end
    if src.index ~= nil then
        -- Index mode exists for Kicia's loop-disable shape (setconstant(fn, 2, 999)), where the target
        -- is a bare number that would match in a dozen places. `expect` is mandatory: writing blind into
        -- a pool position is precisely the corruption this engine exists to prevent.
        if src.expect == nil then
            return nil, "index mode requires `expect`"
        end
        local cur = consts[src.index]
        if cur == nil then
            return nil, "no constant at index " .. tostring(src.index)
        end
        if cur ~= src.expect then
            return nil, string.format("index %s holds %s, expected %s",
                tostring(src.index), tostring(cur), tostring(src.expect))
        end
        return { { index = src.index, old = cur } }
    end
    local hits = {}
    for i, v in consts do
        if v == src.target then
            hits[#hits + 1] = { index = i, old = v }
        end
    end
    return hits
end

-- A malformed source would otherwise surface as a misleading gate failure ("found 0 target sites") three
-- layers down, so shape errors are caught here and named for what they are.
local function validateSource(src)
    if type(src) ~= "table" then
        return "source is not a table"
    end
    -- `name` is mandatory even when `fn` is supplied: it is what every gate failure is reported against,
    -- and an unnamed source produces messages nobody can act on.
    if type(src.name) ~= "string" then
        return "needs `name`"
    end
    if type(src.fn) ~= "function" and type(src.holder) ~= "table" then
        return "needs `fn`, or `holder` + `name`"
    end
    if (src.target == nil) == (src.index == nil) then
        return "needs exactly one of `target` or `index`"
    end
    if src.new == nil then
        return "needs `new`"
    end
    if src.scan ~= nil and src.scan ~= "self" and src.scan ~= "protos" then
        return "`scan` must be \"self\" or \"protos\""
    end
    -- A pool position means nothing across sibling protos — index 2 of one child has no relationship to
    -- index 2 of the next. The combination has no coherent semantics, so it is refused rather than defined.
    if src.index ~= nil and src.scan == "protos" then
        return "`index` mode cannot be combined with scan=\"protos\""
    end
    return nil
end

-- ── PATCH SET ───────────────────────────────────────────────────────────────────────────────────
local Set = {}
Set.__index = Set

-- sources: array of tables, each
--   fn      = <function>                     resolved target, OR
--   holder  = <table>, name = "Method"       rawget resolution (name also labels errors)
--   scan    = "self" (default) | "protos"    where to look for the constant
--   target  = <value>                        match by value, OR
--   index   = <n>, expect = <value>          match by pool position, value asserted
--   new     = <value>                        replacement; must be the same type as the old value
--   count   = <n>                            expected match total (default: self=1, protos=any >=1)
--   fingerprint = <number>                   version gate; see ConstPatch.learn
function ConstPatch.new(name, sources)
    local set = setmetatable({
        name     = name,
        sources  = sources,
        restores = nil,
    }, Set)
    _sets[#_sets + 1] = set
    return set
end

function Set:Apply()
    if not HAVE_CONST then
        return false, "executor lacks debug.getconstants/debug.setconstant"
    end
    if self.restores then
        return false, self.name .. ": already applied"
    end

    -- PHASE 1 — resolve, gate, plan. NOTHING is written in this phase, so a set that fails validation
    -- leaves the game process bit-identical to never having run us.
    local plan = {}
    for _, src in self.sources do
        local label = self.name .. "/" .. tostring(src.name or "?")
        local shapeErr = validateSource(src)
        if shapeErr then
            return false, label .. ": " .. shapeErr
        end
        local fn = resolveFn(src)
        if not fn then
            return false, label .. ": cannot resolve target function"
        end
        if src.fingerprint ~= nil then
            local got = ConstPatch.fingerprint(fn)
            if got ~= src.fingerprint then
                return false, string.format("%s: VERSION GATE — fingerprint %s, expected %s",
                    label, tostring(got), tostring(src.fingerprint))
            end
        end
        local cands, cerr = candidates(fn, src)
        if not cands then
            return false, label .. ": " .. cerr
        end
        local found = 0
        for _, cand in cands do
            local hits, herr = collectMatches(cand, src)
            if not hits then
                return false, label .. ": " .. herr
            end
            if #hits > 1 then
                return false, string.format("%s: AMBIGUOUS — %d occurrences in one function; refusing to guess",
                    label, #hits)
            end
            if #hits == 1 then
                local hit = hits[1]
                if typeof(src.new) ~= typeof(hit.old) then
                    return false, string.format("%s: type change %s -> %s refused",
                        label, typeof(hit.old), typeof(src.new))
                end
                found = found + 1
                plan[#plan + 1] = { fn = cand, index = hit.index, old = hit.old, new = src.new }
            end
        end
        local exact = src.count
        if exact == nil and src.scan ~= "protos" then
            exact = 1
        end
        if exact ~= nil then
            if found ~= exact then
                return false, string.format("%s: found %d target sites, expected %d", label, found, exact)
            end
        elseif found == 0 then
            return false, label .. ": found no target sites"
        end
    end

    -- PHASE 2 — write. Each write is recorded before the next is attempted, so a setconstant that fails
    -- mid-set still unwinds every earlier write in this set.
    local restores = {}
    self.restores = restores
    local led = ledger(true)
    for _, p in plan do
        local ok = pcall(_setconstant, p.fn, p.index, p.new)
        if not ok then
            self:Revert()
            return false, string.format("%s: setconstant failed at index %s", self.name, tostring(p.index))
        end
        local rec = { fn = p.fn, index = p.index, old = p.old }
        restores[#restores + 1] = rec
        if led then
            led[#led + 1] = rec
        end
    end
    return true
end

function Set:Revert()
    local restores = self.restores
    if not restores then
        return
    end
    self.restores = nil
    local led = ledger()
    -- Reverse order: if two sources ever land on the same pool slot, the FIRST write holds the true
    -- original, so it must be the last one restored.
    for i = #restores, 1, -1 do
        local rec = restores[i]
        pcall(_setconstant, rec.fn, rec.index, rec.old)
        if led then
            for j = #led, 1, -1 do
                if led[j] == rec then
                    table.remove(led, j)
                    break
                end
            end
        end
    end
end

function Set:IsApplied()
    return self.restores ~= nil
end

-- ── LIFECYCLE ───────────────────────────────────────────────────────────────────────────────────
-- Undo every patch this execution applied, then drain anything a PREVIOUS execution left behind.
-- Called from Library.Unload (13_gui) and once at load, below. Safe to call repeatedly.
function ConstPatch.revertAll()
    for _, set in _sets do
        pcall(function() set:Revert() end)
    end
    local led = ledger()
    if not led or not _setconstant then
        return
    end
    for i = #led, 1, -1 do
        local rec = led[i]
        if type(rec) == "table" and type(rec.fn) == "function" then
            pcall(_setconstant, rec.fn, rec.index, rec.old)
        end
        led[i] = nil
    end
end

function ConstPatch.available()
    if not HAVE_CONST then
        return false, "no debug.getconstants/debug.setconstant"
    end
    if not HAVE_PROTOS then
        return true, "no getprotos/getproto — scan=\"protos\" sources will fail"
    end
    return true, "ok"
end

-- ── ENROLMENT + RECONNAISSANCE (operator tools, run live) ───────────────────────────────────────
-- Read the current fingerprint of every source so the numbers can be baked into the source table.
-- This is the ONLY way the fingerprint half of the version gate gets turned on.
function ConstPatch.learn(sources)
    local out = {}
    for _, src in sources do
        local fn = resolveFn(src)
        if fn then
            out[#out + 1] = string.format("%s = %s", tostring(src.name), tostring(ConstPatch.fingerprint(fn)))
        else
            out[#out + 1] = string.format("%s = <unresolved>", tostring(src.name))
        end
    end
    return table.concat(out, "\n")
end

-- Print a function's constant pool. Writing a correct source means knowing which constants exist and how
-- many times the one you want appears — the occurrence gate is unusable without being able to see this.
function ConstPatch.dump(fn, includeProtos)
    if not HAVE_CONST or type(fn) ~= "function" then
        return "<not a function, or executor lacks debug.getconstants>"
    end
    local out = {}
    local function poolOf(f, tag)
        local ok, consts = pcall(_getconstants, f)
        if not ok or type(consts) ~= "table" then
            out[#out + 1] = tag .. ": <unreadable>"
            return
        end
        out[#out + 1] = string.format("%s  fingerprint=%s", tag, tostring(ConstPatch.fingerprint(f)))
        for i, v in consts do
            out[#out + 1] = string.format("  [%s] %s %s", tostring(i), typeof(v), string.sub(tostring(v), 1, 120))
        end
    end
    poolOf(fn, "self")
    if includeProtos and HAVE_PROTOS then
        local ok, protos = pcall(_getprotos, fn)
        if ok and type(protos) == "table" then
            for i in protos do
                local okG, live = pcall(_getproto, fn, i, true)
                if okG and type(live) == "table" and type(live[1]) == "function" then
                    poolOf(live[1], "proto[" .. tostring(i) .. "]")
                else
                    out[#out + 1] = "proto[" .. tostring(i) .. "]: <no live closure>"
                end
            end
        end
    end
    return table.concat(out, "\n")
end

-- A previous execution that died without unloading leaves the game patched. Drain its ledger before any
-- source runs, so value-matching in Phase 1 always sees a pristine constant pool.
ConstPatch.revertAll()

end)()

