    local function ambientId(mood)
        local map = cfg("WeatherSoundIds", nil)
        if type(map) == "table" and map[mood] and map[mood] ~= "" then return map[mood] end
        return nil
    end

    -- ── active state ──
    local _partLayers = {}
    local _ambient  = nil
    local _moodCC   = nil
    local _moodTween = nil
    local FADE_TI = TweenInfo.new(2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)   -- layer Rate crossfade
    local MOOD_TI = TweenInfo.new(3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)   -- mood CC lerp
    local _followConn = nil
    local _lightFolder = nil
    local _rays = nil   -- SunRaysEffect; declared here so setIntensity can retune it live
    -- special-type + scheduler state
    local _special = { moon = nil, shell = nil, sky = nil, cc = nil, atmo = nil, halo = nil, kind = nil }
    local _specialConn = nil
    local _clockConn = nil

    local function clearPartLayers()
        for _, L in _partLayers do
            if L.rateTween then L.rateTween:Cancel() end
            if L.host then pcall(function() L.host:Destroy() end) end
        end
        table.clear(_partLayers)
    end

    -- ── crossfade plumbing ──────────────────────────────────────────────────
    -- PARTICLE-layer type switches fade instead of hard-cutting: outgoing layers
    -- ramp Rate→0 over FADE_TI, then die after their longest Lifetime has drained
    -- (still camera-followed while fading — no stranded volumes); incoming layers
    -- ramp 0→target (mkPartLayer rampIn). At most ONE outgoing batch lives at a
    -- time: a switch mid-fade fast-forwards the pending batch, and killFade bumps
    -- _fadeToken so the stale task.delay no-ops (no orphan hosts, no stacked
    -- delays). Rain (beam pool) + BloodMoon keep their instant swap — out of scope.
    local _fadeLayers = {}   -- { host, oy } draining out
    local _fadeToken = 0

    local function killFade()
        _fadeToken = _fadeToken + 1
        for _, F in _fadeLayers do
            local host = F.host
            pcall(function() host:Destroy() end)
        end
        table.clear(_fadeLayers)
    end
    local function beginLayerFade()
        killFade()
        local maxLife = 0
        for _, L in _partLayers do
            if L.rateTween then L.rateTween:Cancel() end
            if L.emitter then
                TweenService:Create(L.emitter, FADE_TI, { Rate = 0 }):Play()
            end
            if L.life2 > maxLife then maxLife = L.life2 end
            _fadeLayers[#_fadeLayers + 1] = { host = L.host, oy = L.oy }
        end
        table.clear(_partLayers)
        local tok = _fadeToken
        task.delay(FADE_TI.Time + maxLife, function()
            if tok == _fadeToken then killFade() end
        end)
    end

    -- ── spectacle-event scheduler (mechanism only; events register later) ──
    -- registerSpectacle(name, weight, fn): weighted pick, ~one event / 2-4 min
    -- while weather is on, fn run in pcall from the follow loop. Empty registry
    -- = pure no-op. Registration is load-time + permanent (no unregister).
    local _spectacles, _spectWeight, _spectNextT = {}, 0, 0
    local function registerSpectacle(name, weight, fn)
        _spectacles[#_spectacles + 1] = { name = name, weight = weight, fn = fn }
        _spectWeight = _spectWeight + weight
    end
    -- shared wind-swell envelope (SnowBlizzard / SakuraGale spectacles): while tick() is inside
    -- [_blizzT0, _blizzT0+_blizzDur] the follow loop multiplies every gust layer's wind
    -- term by one shared sine swell — a coherent surge through all layers. Self-expires.
    local _blizzT0, _blizzDur = 0, 1

    -- This layer's emitter Rate at intensity I, before any effect multiplier.
    local function layerRate(L, I)
        if L.spec.tag == "settle" then
            return L.spec.rate * iRate(I, SET_LO, SET_HI)
        end
        return L.spec.rate * iRate(I, L.ir.lo, L.ir.hi)
    end
    -- LIVE intensity re-apply for one layer, everything except Rate. Acceleration, Speed,
    -- Size and Transparency are all writable on a RUNNING ParticleEmitter, so the slider
    -- never rebuilds a layer — which is what makes "more than rate" affordable at all.
    -- `settle` layers keep their fall and drive untouched: a carpet doesn't fall harder,
    -- and the litter layer's VelocityPerpendicular plane depends on its tiny fixed
    -- downward terminal (see the preset comment) — scaling it is not worth the artifact.
    local function tuneLayer(L, I)
        local spec, R, e = L.spec, L.ir, L.emitter
        local am = 1
        if spec.tag ~= "settle" then
            am = 1 - R.acc + R.acc * I
        end
        L.accel = spec.accel * am
        if not spec.gust then
            e.Acceleration = L.accel   -- gust layers get theirs written by the follow loop
        end
        e.Speed = NumberRange.new(spec.speed[1] * am, spec.speed[2] * am)
        if spec.gust then
            local gm = 1 - R.gst + R.gst * I
            L.gax, L.gaz = spec.gust.ax * gm, spec.gust.az * gm
        end
        local sm = 1 - R.sz + R.sz * I
        if spec.skeys then
            local ks = spec.skeys
            local kps = table.create(#ks)
            for i = 1, #ks do
                local k = ks[i]
                kps[i] = NumberSequenceKeypoint.new(k[1], k[2] * sm, (k[3] or 0) * sm)
            end
            e.Size = NumberSequence.new(kps)
        else
            e.Size = NumberSequence.new(spec.size0 * sm, spec.size1 * sm)
        end
        -- tkeys layers encode blink/pulse CHOREOGRAPHY, not density — leave them alone.
        -- Opacity scales, so the same clamp self-limits: an already-opaque layer has
        -- nothing to give and barely moves, while a faint veil layer moves a lot.
        if not spec.tkeys then
            local om = 1 - R.alp + R.alp * I
            e.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0,    1),
                NumberSequenceKeypoint.new(0.12, math.clamp(1 - (1 - spec.transp0) * om, 0, 1)),
                NumberSequenceKeypoint.new(0.8,  math.clamp(1 - (1 - spec.transp1) * om, 0, 1)),
                NumberSequenceKeypoint.new(1,    1),
            })
        end
    end

    local function mkPartLayer(spec, ir, rampIn)
        local host = Instance.new("Part")
        host.Name = "_wxHost"; host.Anchored = true; host.CanCollide = false; host.CanQuery = false
        host.CanTouch = false; host.CastShadow = false; host.Transparency = 1; host.Massless = true
        host.Size = spec.size; host:SetAttribute("WX_Custom", true)
        host.Parent = getFolder()
        local e = Instance.new("ParticleEmitter")
        e:SetAttribute("WX_Custom", true)
        e.Texture = spec.tex
        local colorSeq = spec.color
        if typeof(colorSeq) ~= "ColorSequence" then
            colorSeq = ColorSequence.new(colorSeq)
        end
        e.Color = colorSeq
        local glow = spec.glow or 0
        e.LightEmission  = glow
        e.LightInfluence = 1 - math.min(glow, 1)   -- partial glow keeps daylight shading
        e.Lifetime = NumberRange.new(spec.life[1], spec.life[2])
        e.SpreadAngle = Vector2.new(spec.spread, spec.spread)
        local rot0, rot1 = 0, 360
        if spec.rot then
            rot0, rot1 = spec.rot[1], spec.rot[2]
        end
        e.Rotation = NumberRange.new(rot0, rot1)
        e.RotSpeed = NumberRange.new(-(spec.rotSpd or 45), spec.rotSpd or 45)
        -- qseq = a prebuilt Squash sequence (flutterSeq); plain `squash` is the constant case.
        -- 0 = undistorted (engine default; the old `or 1` stretched every sprite).
        if spec.qseq then
            e.Squash = spec.qseq
        else
            e.Squash = NumberSequence.new(spec.squash or 0)
        end
        -- Size / Transparency / Acceleration / Speed are intensity-driven: tuneLayer below
        -- owns them. Only the choreographed tkeys sequence is static.
        if spec.tkeys then
            local kps = table.create(#spec.tkeys)
            for i = 1, #spec.tkeys do kps[i] = NumberSequenceKeypoint.new(spec.tkeys[i][1], spec.tkeys[i][2]) end
            e.Transparency = NumberSequence.new(kps)
        end
        e.Drag = spec.drag or 0
        -- zoff pulls a layer forward in depth: a defocus/lens layer composites in FRONT of the
        -- midground instead of intersecting walls and blooming on them.
        e.ZOffset = spec.zoff or 0
        e.EmissionDirection = spec.dir
        -- orient: VelocityPerpendicular lays a sprite FLAT on the ground (emit up, speed ~0) —
        -- the only way settled leaves stop reading as cards standing on edge. VelocityParallel
        -- + negative Squash stretches a sprite ALONG travel, which is what makes a fast
        -- gust-driven leaf read as a streak in a still frame.
        if spec.orient then
            e.Orientation = spec.orient
        end
        e.Parent = host
        -- accel/gax/gaz stored so the follow loop can retune live wind (gust layers only);
        -- uw/aim = upwind spawn bias + downwind host aim (both need the unit wind vector);
        -- life2 = longest particle Lifetime (crossfade teardown waits it out);
        -- spec+ir = the intensity source of truth, so a slider move is a pure re-read;
        -- rateMul = the effect multiplier currently in force (swell / gust surge / devil
        -- duck), so an intensity change mid-effect re-targets instead of snapping to base.
        local L = { host = host, oy = spec.oy, emitter = e, spec = spec, ir = ir,
                    accel = spec.accel, gust = spec.gust, tag = spec.tag,
                    gax = 0, gaz = 0, rateMul = 1,
                    uw = spec.uw, aim = spec.aim,
                    life2 = spec.life[2], rateTween = nil }
        local I = iAmt()
        tuneLayer(L, I)
        local targetRate = layerRate(L, I)
        if rampIn then   -- crossfade in: emitter starts silent, ramps to target
            e.Rate = 0
            L.rateTween = TweenService:Create(e, FADE_TI, { Rate = targetRate })
            L.rateTween:Play()
        else
            e.Rate = targetRate
        end
        _partLayers[#_partLayers + 1] = L
    end

    local function clearMood()
        if _moodTween then _moodTween:Cancel(); _moodTween = nil end
        if _moodCC then pcall(function() _moodCC:Destroy() end); _moodCC = nil end
    end
    -- mood rides ONE persistent CC: type switches lerp its grade over MOOD_TI
    -- instead of popping; a fresh apply (nothing on screen yet) sets it instantly
    local function applyMood(name)
        if not cfg("WeatherMood", true) then
            clearMood()
            return
        end
        local m = MOOD[name]
        if not m then
            clearMood()
            return
        end
        if _moodTween then _moodTween:Cancel(); _moodTween = nil end
        -- grade strength rides intensity (0.66 / 1.0 / 1.4): a heavy sky grades harder.
        -- Tint is NOT scaled — the hues were picked per type and a stronger tint just
        -- colour-casts the ground. This is the only "visibility" axis the weather layer
        -- owns outright; a shared Lighting Atmosphere would fight 06_visuals (see notes).
        local g = 0.6 + 0.4 * iAmt()
        local cc = _moodCC
        if cc and cc.Parent then
            _moodTween = TweenService:Create(cc, MOOD_TI,
                { Brightness = m.B * g, Contrast = m.C * g, Saturation = m.S * g, TintColor = m.tint })
            _moodTween:Play()
            return
        end
        cc = Instance.new("ColorCorrectionEffect")
        cc.Name = "_wxMood"; cc:SetAttribute("WX_Custom", true)
        cc.Brightness = m.B * g; cc.Contrast = m.C * g; cc.Saturation = m.S * g; cc.TintColor = m.tint
        cc.Parent = Lighting
        _moodCC = cc
    end

    local function startAmbient(mood)
        if _ambient then pcall(function() _ambient:Destroy() end); _ambient = nil end
        local id = mood and ambientId(mood)
        if not id then return end
        local s = Instance.new("Sound")
        s.Name = "_wxAmb"; s:SetAttribute("WX_Custom", true)
        s.SoundId = id; s.Looped = true; s.Volume = cfg("WeatherSoundVolume", 0.35)
        s.Parent = SoundService
        pcall(function() s:Play() end)
        _ambient = s
    end

    -- one-shot SFX (thunder cracks, meteor impacts). These are IMPACT sounds: they scale the
    -- ambient slider up hard (the old code played them AT loop volume ≈0.35 — inaudible).
    local function oneShot(id, vol, pitch)
        if not id or id == "" then return end
        local s = Instance.new("Sound")
        s.Name = "_wxSfx"; s:SetAttribute("WX_Custom", true)
        s.SoundId = id; s.Volume = math.clamp(vol, 0, 10)
        if pitch then s.PlaybackSpeed = pitch end
        s.Parent = SoundService
        pcall(function() s:Play() end)
        Debris:AddItem(s, 8)   -- covers the 6.8s thunder roll
    end

    -- ── STORM ──
    -- SHARED host for storm bolts + meteors + shooting stars — only stopStorm (disable/unload) destroys it
    local function getLightFolder()
        if _lightFolder and _lightFolder.Parent then return _lightFolder end
        local f = Instance.new("Folder"); f.Name = "_wxBolts"; f:SetAttribute("WX_Custom", true)
        f.Parent = getFolder()
        _lightFolder = f; return f
    end
    local function mkBoltPart(color, transp, size, cf, parent)
        local p = Instance.new("Part")
        p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
        p.CastShadow = false; p.Massless = true; p.Material = Enum.Material.Neon
        p.Color = color; p.Transparency = transp; p:SetAttribute("WX_Custom", true)
        p.Size = size; p.CFrame = cf; p.Parent = parent
        return p
    end
    -- THUNDERSTORM (rework 2026-07-24, Studio-verified): pre-flash telegraph in the cloud →
    -- 18-seg meandering channel + recursive branches (cylinder segs: round cross-section, no
    -- boxy sleeves up close) in THREE layers — white-violet CORE (dies fast), wide soft GLOW,
    -- violet AFTERGLOW that outlives both (retinal persistence) → 30% same-channel re-strike
    -- 80-150ms later → distance-delayed thunder (dist/343 at 1/3 sound speed) + CC pop with
    -- flicker pulses. Nested IIFE keeps ~14 storm locals off the weather proto budget.
    local startStorm, stopStormLoop, stopStorm, rescheduleStorm
    ;(function()
        local TX_BGLOW   = "rbxassetid://78582616787441"     -- soft radial glow (flarecore)
        local TX_BSTREAK = "rbxassetid://102481842205398"    -- thin tapered streak (contact sparks)
        local BOLT_CORE  = Color3.fromRGB(245, 242, 255)
        local BOLT_GLOW  = Color3.fromRGB(162, 145, 255)
        local BOLT_AFTER = Color3.fromRGB(126, 96, 228)
        local ROT90 = CFrame.Angles(0, math.rad(90), 0)      -- cylinder X axis → segment axis
        local FLICK = 0.12                                    -- initial hot-flicker window (s)
        local _stormConn, _stormNextT = nil, 0
        local _boltRp = RaycastParams.new()
        _boltRp.FilterType = Enum.RaycastFilterType.Exclude

        local function mkSeg(color, transp, dia, len, cf, parent)
            local p = Instance.new("Part")
            p.Shape = Enum.PartType.Cylinder
            p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
            p.CastShadow = false; p.Massless = true; p.Material = Enum.Material.Neon
            p.Color = color; p.Transparency = transp; p:SetAttribute("WX_Custom", true)
            p.Size = Vec(len, dia, dia); p.CFrame = cf * ROT90; p.Parent = parent
            return p
        end
        -- one channel: n segments top→bot, lateral offsets follow a random-walking drift angle
        -- (meander, not zigzag). Returns the path points so branches can attach anywhere.
        -- segs records: { p, on = peak transparency, fade = seconds to die after flicker ends }.
        local function boltChannel(model, segs, top, bot, n, thick, jitter, layer3)
            local pts = { top }
            local prev = top
            local driftAng = math.random() * 6.283
            for i = 1, n do
                local t = i / n
                local point = top:Lerp(bot, t)
                if i < n then
                    driftAng = driftAng + (math.random() - 0.5) * 2.2
                    local j = jitter * (0.5 + 0.5 * (1 - t))
                    local off = j * (0.3 + math.random() * 0.7)
                    point = point + Vec(math.cos(driftAng) * off, (math.random() - 0.5) * j * 0.25, math.sin(driftAng) * off)
                end
                local len = math.max((point - prev).Magnitude, 0.1)
                local cf = CFrame.lookAt((point + prev) * 0.5, point)
                segs[#segs + 1] = { p = mkSeg(BOLT_CORE, 0.02, thick, len + thick * 1.6, cf, model), on = 0.02, fade = 0.16 }
                segs[#segs + 1] = { p = mkSeg(BOLT_GLOW, 0.78, thick * 5.5, len + thick * 1.8, cf, model), on = 0.78, fade = 0.38 }
                if layer3 then
                    segs[#segs + 1] = { p = mkSeg(BOLT_AFTER, 0.88, thick * 2.2, len + thick * 1.6, cf, model), on = 0.75, fade = 0.85 }
                end
                pts[#pts + 1] = point
                prev = point
            end
            return pts
        end
        -- recursive sub-branches: 2-4 off the main channel, thinner + shorter, each may fork again
        local function boltBranch(model, segs, fromPts, groundY, thick, depth)
            local count = 1
            if depth == 1 then count = math.random(2, 4) end
            for _ = 1, count do
                local idx = math.random(math.floor(#fromPts * 0.2), math.floor(#fromPts * 0.7))
                local a = fromPts[math.max(idx, 2)]
                local ang = math.random() * 6.283
                local drop = (a.Y - groundY) * (0.3 + math.random() * 0.25)
                local outw = drop * (0.55 + math.random() * 0.4)
                local endp = a + Vec(math.cos(ang) * outw, -drop, math.sin(ang) * outw)
                local n = 5
                if depth == 1 then n = 8 end
                -- jitter scales with branch length (fixed jitter left long branches ruler-straight)
                local blen = (endp - a).Magnitude
                local pts = boltChannel(model, segs, a, endp, n, thick, math.max(5, blen * 0.1) / depth, false)
                if depth < 3 and math.random() < 0.5 then
                    boltBranch(model, segs, pts, groundY, thick * 0.45, depth + 1)
                end
            end
        end
        -- pre-flash telegraph: two soft glow pulses at the cloud base over the strike azimuth.
        -- Also reused at ignite (scale >1) as the channel lighting the deck it exits.
        local function preFlash(pos, scale)
            local host = mkBoltPart(BOLT_CORE, 1, Vec(2, 2, 2), CFrame.new(pos), getLightFolder())
            local e = Instance.new("ParticleEmitter")
            e:SetAttribute("WX_Custom", true)
            e.Texture = TX_BGLOW
            e.Color = ColorSequence.new(Color3.fromRGB(206, 192, 255))
            e.LightEmission = 0.85; e.LightInfluence = 0
            e.Size = NumberSequence.new(60 * scale, 85 * scale)
            e.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.25, 0.55),
                NumberSequenceKeypoint.new(0.7, 0.75), NumberSequenceKeypoint.new(1, 1),
            })
            e.Lifetime = NumberRange.new(0.22, 0.3)
            e.Rate = 0; e.Speed = NumberRange.new(0, 0.5)
            e.Parent = host
            e:Emit(1)
            task.delay(0.09, function() pcall(function() e:Emit(1) end) end)
            Debris:AddItem(host, 1.2)
        end
        -- screen flash: CC pop decaying over ~0.45s with 1-2 rapid flicker pulses riding the decay
        local function screenFlash()
            local cc = Instance.new("ColorCorrectionEffect")
            cc.Name = "_wxFlash"; cc:SetAttribute("WX_Custom", true); cc.Brightness = 0.35; cc.Parent = Lighting
            local pulseA = 0.3 + math.random() * 0.25
            local pulseB = -1
            if math.random() < 0.6 then pulseB = pulseA + 0.18 + math.random() * 0.12 end
            local st = tick(); local c2
            c2 = RunService.Heartbeat:Connect(function()
                if not cc.Parent then if c2 then c2:Disconnect() end return end
                local a = (tick() - st) / 0.45
                if a >= 1 then pcall(function() cc:Destroy() end); if c2 then c2:Disconnect() end return end
                local b = 0.35 * (1 - a)
                if a >= pulseA and a < pulseA + 0.14 then
                    b = b + 0.22 * (1 - (a - pulseA) / 0.14)
                elseif pulseB > 0 and a >= pulseB and a < pulseB + 0.14 then
                    b = b + 0.16 * (1 - (a - pulseB) / 0.14)
                end
                cc.Brightness = b
            end)
            Debris:AddItem(cc, 0.7)
        end
        local function igniteBolt(ground, top)
            local model = Instance.new("Model"); model.Name = "_bolt"; model:SetAttribute("WX_Custom", true)
            local segs = {}
            local mainPts = boltChannel(model, segs, top, ground, 18, 1.0, 14, true)
            boltBranch(model, segs, mainPts, ground.Y, 0.55, 1)
            -- ground hit: flat expanding shock disc (a swelling ball read as a solid pearl in
            -- Studio verify) + strike light + one bloom flash + upward spark streaks
            local dome = mkBoltPart(Color3.fromRGB(228, 240, 255), 0.5, Vec(0.6, 5, 5),
                CFrame.new(ground + Vec(0, 0.3, 0)) * CFrame.Angles(0, 0, math.rad(90)), model)
            dome.Shape = Enum.PartType.Cylinder
            local fl = Instance.new("PointLight"); fl.Color = BOLT_GLOW; fl.Range = 150; fl.Brightness = 8; fl.Parent = dome
            TweenService:Create(dome, TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                { Size = Vec(0.6, 30, 30), Transparency = 1 }):Play()
            TweenService:Create(fl, TweenInfo.new(0.5), { Brightness = 0 }):Play()
            local cb = mkBoltPart(BOLT_CORE, 1, Vec(2, 2, 2), CFrame.new(ground + Vec(0, 1.5, 0)), model)
            local ce = Instance.new("ParticleEmitter")
            ce:SetAttribute("WX_Custom", true)
            ce.Texture = TX_BGLOW
            ce.Color = ColorSequence.new(Color3.fromRGB(235, 228, 255))
            ce.LightEmission = 1; ce.LightInfluence = 0
            ce.Size = NumberSequence.new(13, 17)
            ce.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.3), NumberSequenceKeypoint.new(1, 1),
            })
            ce.Lifetime = NumberRange.new(0.3, 0.4)
            ce.Rate = 0; ce.Speed = NumberRange.new(0, 0.1)
            ce.Parent = cb
            local se = Instance.new("ParticleEmitter")
            se:SetAttribute("WX_Custom", true)
            se.Texture = TX_BSTREAK
            se.Color = ColorSequence.new(Color3.fromRGB(220, 205, 255))
            se.LightEmission = 1; se.LightInfluence = 0
            se.Size = NumberSequence.new(2, 3)
            se.Transparency = NumberSequence.new(0.25, 1)
            se.Lifetime = NumberRange.new(0.5, 0.9)
            se.Rate = 0; se.Speed = NumberRange.new(26, 44)
            se.SpreadAngle = Vector2.new(38, 38)
            se.Orientation = Enum.ParticleOrientation.VelocityParallel
            se.EmissionDirection = Enum.NormalId.Top
            se.Acceleration = Vec(0, -40, 0)
            se.Parent = cb
            ce:Emit(1)
            se:Emit(9)
            model.Parent = getLightFolder()
            preFlash(top + Vec(0, 10, 0), 1.5)   -- the channel lights the cloud base it exits
            -- animation: hot flicker → (30%) re-strike of the SAME channel → per-layer fade.
            -- segs prebuilt = zero per-frame allocation.
            local flickEnd = FLICK
            local restrikeAt = -1
            if math.random() < 0.3 then restrikeAt = FLICK + 0.08 + math.random() * 0.07 end
            local startT = tick(); local conn
            conn = RunService.Heartbeat:Connect(function()
                if not model.Parent then if conn then conn:Disconnect() end return end
                local a = tick() - startT
                if restrikeAt > 0 and a >= restrikeAt then
                    restrikeAt = -1
                    flickEnd = a + 0.1
                    fl.Brightness = 6
                    TweenService:Create(fl, TweenInfo.new(0.4), { Brightness = 0 }):Play()
                end
                if a < flickEnd then
                    local dim = 0   -- flicker: mostly ON, brief dips toward off
                    if math.random() < 0.28 then dim = 0.85 end
                    for i = 1, #segs do
                        local s = segs[i]
                        s.p.Transparency = s.on + (1 - s.on) * dim
                    end
                    return
                end
                local f = a - flickEnd
                if f >= 0.85 then
                    if conn then conn:Disconnect() end
                    pcall(function() model:Destroy() end)
                    return
                end
                for i = 1, #segs do
                    local s = segs[i]
                    local k = math.clamp(f / s.fade, 0, 1)
                    s.p.Transparency = s.on + (1 - s.on) * k
                end
            end)
            Debris:AddItem(model, 1.8)   -- covers max flicker+restrike+fade
            if cfg("WeatherStormFlash", true) then screenFlash() end
            local tid = cfg("WeatherThunderId", "")
            if tid ~= "" then
                local cam = Camera
                local dist = 120
                if cam then dist = (ground - cam.CFrame.Position).Magnitude end
                task.delay(dist * (3 / 343), function()   -- dist/343 at 1/3 sound speed: readable delay
                    oneShot(tid, cfg("WeatherSoundVolume", 0.35) * 8 * (0.85 + math.random() * 0.3),
                        0.92 + math.random() * 0.16)
                end)
            end
        end
        local function spawnBolt()
            -- re-gate: barrage task.delay may land after disable/unload (getFolder would resurrect _wx)
            if not Config.Weather or not cfg("WeatherStorm", false) then return end
            local cam = Camera; if not cam then return end
            local base = cam.CFrame.Position
            -- Place the strike IN VIEW: project ahead along the camera's flattened look direction with a
            -- moderate lateral spread, so the bolt lands in FRONT of the player.
            local lv = cam.CFrame.LookVector
            local flat = Vec(lv.X, 0, lv.Z)
            if flat.Magnitude < 0.05 then flat = Vec(0, 0, -1) else flat = flat.Unit end
            local right = Vec(flat.Z, 0, -flat.X)      -- ground-plane perpendicular
            local fwd  = 55 + math.random() * 95        -- studs ahead of the camera
            local side = (math.random() - 0.5) * 85     -- lateral spread (stays within FOV)
            local gx = base.X + flat.X * fwd + right.X * side
            local gz = base.Z + flat.Z * fwd + right.Z * side
            -- plant the strike on real ground when there is any (lit floor + flash dome sell the hit)
            local ground = Vec(gx + (math.random() - 0.5) * 20, base.Y - 45, gz + (math.random() - 0.5) * 20)
            local ch = lp and lp.Character
            if ch then
                _boltRp.FilterDescendantsInstances = { getFolder(), ch }
            else
                _boltRp.FilterDescendantsInstances = { getFolder() }
            end
            local hit = Workspace:Raycast(Vec(gx, base.Y + 140, gz), Vec(0, -400, 0), _boltRp)
            if hit then ground = hit.Position end
            -- channel leans: cloud origin offset from the ground point (real bolts rarely drop plumb)
            local top = Vec(gx + (math.random() - 0.5) * 90, base.Y + 280, gz + (math.random() - 0.5) * 90)
            preFlash(Vec(top.X, top.Y - 20, top.Z), 1)
            task.delay(0.1 + math.random() * 0.2, function()   -- storms telegraph: flicker leads the strike
                if not Config.Weather or not cfg("WeatherStorm", false) then return end
                pcall(function() igniteBolt(ground, top) end)
            end)
        end
        function startStorm()
            if _stormConn then return end
            _stormNextT = tick() + 2 + math.random() * 3
            _stormConn = RunService.Heartbeat:Connect(function()
                if not Config.Weather or not cfg("WeatherStorm", false) then return end
                local now = tick()
                if now >= _stormNextT then
                    -- the Min/Var sliders ARE the storm's frequency control, alone
                    _stormNextT = now + cfg("WeatherStormMin", 4)
                        + math.random() * cfg("WeatherStormVar", 8)
                    pcall(spawnBolt)
                end
            end)
        end
        -- slider drag: pull a stale wait down into the new window. Clamping (never zeroing)
        -- is what keeps a drag from machine-gunning bolts one per tick.
        function rescheduleStorm()
            if not _stormConn then
                return
            end
            local cap = tick() + cfg("WeatherStormMin", 4) + cfg("WeatherStormVar", 8)
            _stormNextT = math.min(_stormNextT, cap)
        end
        function stopStormLoop()   -- toggle-off path: drop the scheduler, keep the shared folder
            if _stormConn then _stormConn:Disconnect(); _stormConn = nil end
        end
        function stopStorm()   -- disable/unload only: also destroys the SHARED light folder
            stopStormLoop()
            if _lightFolder then pcall(function() _lightFolder:Destroy() end); _lightFolder = nil end
        end
        -- spectacle: barrage — three telegraphed strikes in quick succession (self-gated)
        registerSpectacle("StormBarrage", 1, function()
            if not Config.Weather or not cfg("WeatherStorm", false) then return end
            for i = 0, 2 do
                task.delay(i * (0.35 + math.random() * 0.3), function() pcall(spawnBolt) end)
            end
        end)
    end)()

    -- ── camera-follow for PARTICLE layers (rain sim + special types follow in their own loops) ──
    -- Also the weather-gated tick that drives Wind.update + the spectacle scheduler.
    -- Layers with spec.gust ride the SHARED wind: Acceleration = base + Wind × per-layer
    -- scale (g.ax/g.az) × a slow per-layer phase breath (g.wx/g.wz/g.ph keep each layer's
    -- character; the direction + gust surges are one coherent field). Emitter Acceleration
    -- acts on ALREADY-LIVE particles, so the whole sky sways together — one property write
    -- per gust layer per tick. Generic (any preset may set gust); only Snow uses it today.
    local function startFollow()
        if _followConn then return end
        local now0 = tick()
        Wind.reset(now0)
        _spectNextT = now0 + 120 + math.random() * 120
        _followConn = RunService.Heartbeat:Connect(function()
            if not Config.Weather then return end
            local now = tick()
            Wind.update(now)
            local amb = _ambient   -- LIVE volume sync: slider/saved-config applies WITHOUT retoggling weather
            if amb then
                local vol = cfg("WeatherSoundVolume", 0.35)
                if amb.Volume ~= vol then amb.Volume = vol end
            end
            local cam = Camera; if not cam then return end
            local pos = cam.CFrame.Position
            -- one weighted event / 2-4 min, FIXED (no intensity): 3 of the 7 entries are
            -- sky events and the other 4 are type-gated, so at most ONE ambient spectacle
            -- is ever eligible — an intensity-driven period would mostly just re-couple
            -- the meteor/storm/star peaks we are decoupling.
            if now >= _spectNextT then
                _spectNextT = now + 120 + math.random() * 120
                if _spectWeight > 0 then
                    local r = math.random() * _spectWeight
                    for i = 1, #_spectacles do
                        local s = _spectacles[i]
                        r = r - s.weight
                        if r <= 0 then
                            pcall(s.fn)
                            break
                        end
                    end
                end
            end
            local wgain = 1   -- shared blizzard-swell envelope (1 outside a swell)
            local bt = (now - _blizzT0) / _blizzDur
            if bt >= 0 and bt < 1 then
                wgain = 1 + 1.7 * math.sin(bt * math.pi)
            end
            -- unit wind, hoisted: drives the upwind spawn bias (a windward/leeward density
            -- gradient is the strongest "the wind is real" cue in a still frame) and the
            -- downwind aim of the gust-streak hosts.
            local nwx, nwz = 1, 0
            local wl = math.sqrt(Wind.x * Wind.x + Wind.z * Wind.z)
            if wl > 0.05 then
                nwx = Wind.x / wl
                nwz = Wind.z / wl
            end
            for i = 1, #_partLayers do
                local L = _partLayers[i]
                if L.host and L.host.Parent then
                    local hx, hz = pos.X, pos.Z
                    if L.uw then
                        hx = hx - nwx * L.uw
                        hz = hz - nwz * L.uw
                    end
                    local hy = pos.Y + L.oy
                    if L.aim then
                        L.host.CFrame = CFrame.lookAt(Vec(hx, hy, hz), Vec(hx + nwx, hy, hz + nwz))
                    else
                        L.host.CFrame = CFrame.new(hx, hy, hz)
                    end
                    local g = L.gust
                    if g then
                        -- gax/gaz = the layer's coupling AFTER the intensity response
                        L.emitter.Acceleration = L.accel + Vec(
                            Wind.x * wgain * L.gax * (1 + 0.3 * math.sin(now * g.wx + g.ph)), 0,
                            Wind.z * wgain * L.gaz * (1 + 0.3 * math.cos(now * g.wz + g.ph)))
                    end
                end
            end
            for i = 1, #_fadeLayers do   -- draining layers keep following (no stranded volumes)
                local F = _fadeLayers[i]
                if F.host and F.host.Parent then
                    F.host.CFrame = CFrame.new(pos.X, pos.Y + F.oy, pos.Z)
                end
            end
        end)
    end
    local function stopFollow()
        if _followConn then _followConn:Disconnect(); _followConn = nil end
    end

    -- spectacle: WIND SWELL — a stretch where the fall thickens (Rate tween) while the wind
    -- surges (peak ×~2.7 via the _blizz envelope the follow loop reads), then eases back.
    -- SnowBlizzard = alpine whiteout; SakuraGale = the hanami gale that strips the trees and
    -- drives one long petal wave across the frame. Layers tagged "settle" (the sakura ground
    -- carpet) ride the wind but are NOT thickened — a carpet doesn't fall harder. Self-gated on
    -- type; the ease-back only touches layers still live in _partLayers (a mid-swell type switch
    -- hands them to beginLayerFade, which owns their Rate).
    do
        local SWELL_UP = TweenInfo.new(2.5, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
        local SWELL_DOWN = TweenInfo.new(3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        local function windSwell(kind, dur, rateMul)
            if not Config.Weather or _curType ~= kind then return end
            _blizzT0, _blizzDur = tick(), dur
            local surged = {}
            local I = iAmt()
            for _, L in _partLayers do
                if L.emitter and L.tag ~= "settle" then
                    if L.rateTween then L.rateTween:Cancel() end
                    L.rateMul = rateMul
                    local tw = TweenService:Create(L.emitter, SWELL_UP, { Rate = layerRate(L, I) * rateMul })
                    L.rateTween = tw
                    tw:Play()
                    surged[#surged + 1] = L
                end
            end
            task.delay(dur - 3, function()
                local I2 = iAmt()
                for _, L in surged do
                    local live = false
                    for _, cur in _partLayers do
                        if cur == L then live = true break end
                    end
                    if live and L.emitter and L.emitter.Parent then
                        if L.rateTween then L.rateTween:Cancel() end
                        L.rateMul = 1
                        local tw = TweenService:Create(L.emitter, SWELL_DOWN, { Rate = layerRate(L, I2) })
                        L.rateTween = tw
                        tw:Play()
                    end
                end
            end)
        end
        registerSpectacle("SnowBlizzard", 1, function()
            windSwell("Snow", 11 + math.random() * 3, 1.9)
        end)
        registerSpectacle("SakuraGale", 1, function()
            windSwell("Petals", 9 + math.random() * 4, 1.7)
        end)
    end

    -- AUTUMN gust surge — a gust is an EVENT, not a rate multiplier: streak layers fire leaf
    -- streams downwind across frame (staggered over ~1s so the wave has a front and a tail), a
    -- dust puff kicks off the floor, and the ambient fall thickens behind them. Ambient body rate
    -- sits low between gusts on purpose, so the lull is real negative space.
    -- Self-gated on type, rides the shared gust scheduler; the ground carpet ("settle") keeps its
    -- density (a carpet doesn't fall harder). Cancels L.rateTween first and re-stores it, so it
    -- obeys the same Rate-tween precedence as the crossfade ramp / intensity slider.
    do
        local GUST_UP   = TweenInfo.new(1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
        local GUST_DOWN = TweenInfo.new(2.4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        local STREAK_BURST = { {0.3, 18}, {0.65, 14}, {1.05, 9} }
        Wind.onGust(function(dur)
            if not Config.Weather or _curType ~= "Autumn" then return end
            local I = iAmt()
            -- the burst counts were hard literals — identical at 0.15 and 2.0, which made
            -- the signature moment of the type ignore the slider entirely. They ride the
            -- same rate response as the ambient fall; the surge multiplier opens up too.
            local em = iRate(I, IR.Autumn.lo, IR.Autumn.hi)
            local gm = 1 + 0.4 * I
            local surged = {}
            for _, L in _partLayers do
                if L.emitter and L.tag == "dust" then
                    local e = L.emitter
                    local n2 = math.max(1, math.floor(10 * em + 0.5))
                    e:Emit(math.max(1, math.floor(14 * em + 0.5)))
                    task.delay(0.4, function()
                        if e.Parent then e:Emit(n2) end
                    end)
                elseif L.emitter and L.tag == "streak" then
                    local e = L.emitter
                    e:Emit(math.max(1, math.floor(20 * em + 0.5)))
                    for _, b in STREAK_BURST do
                        local n = math.max(1, math.floor(b[2] * em + 0.5))
                        task.delay(b[1], function()
                            if e.Parent then e:Emit(n) end
                        end)
                    end
                elseif L.emitter and L.tag ~= "settle" then
                    if L.rateTween then L.rateTween:Cancel() end
                    L.rateMul = gm
                    local tw = TweenService:Create(L.emitter, GUST_UP, { Rate = layerRate(L, I) * gm })
                    L.rateTween = tw
                    tw:Play()
                    surged[#surged + 1] = L
                end
            end
            task.delay(dur, function()
                local I2 = iAmt()
                for _, L in surged do
                    local live = false
                    for _, cur in _partLayers do
                        if cur == L then live = true break end
                    end
                    if live and L.emitter and L.emitter.Parent then
                        if L.rateTween then L.rateTween:Cancel() end
                        L.rateMul = 1
                        local tw = TweenService:Create(L.emitter, GUST_DOWN, { Rate = layerRate(L, I2) })
                        L.rateTween = tw
                        tw:Play()
                    end
                end
            end)
        end)
    end

    -- ════════════════════════════════════════════════════════════════════════
    -- SPECIAL WEATHER TYPES (not particle presets): BloodMoon. Its own
    -- ~10Hz anim loop parallax-follows the camera XZ; cleared
    -- like every other layer on type-switch/disable. All Instances tagged WX_Custom.
    -- ════════════════════════════════════════════════════════════════════════
    local function clearSpecial()
        if _specialConn then _specialConn:Disconnect(); _specialConn = nil end
        if _special.moon  then pcall(function() _special.moon:Destroy() end);  _special.moon  = nil end
        if _special.shell then pcall(function() _special.shell:Destroy() end); _special.shell = nil end
        if _special.sky   then pcall(function() _special.sky:Destroy() end);   _special.sky   = nil end
        if _special.cc    then pcall(function() _special.cc:Destroy() end);    _special.cc    = nil end
        if _special.atmo  then pcall(function() _special.atmo:Destroy() end);  _special.atmo  = nil end
        _special.halo = nil   -- parented to the moon; dies with it
        _special.kind = nil
    end

    -- BloodMoon's whole intensity axis. It owns its own Atmosphere already, so the pall
    -- (density / haze / glare) is the one place in the file where reduced visibility can
    -- ride the slider without a second Lighting.Atmosphere fighting the Visuals presets.
    local function tuneBloodMoon(I)
        local ms = 0.72 + 0.28 * I          -- 0.762 / 1.0 / 1.28 on every diameter
        local gr = 0.5 + 0.5 * I            -- grade strength
        if _special.moon then
            _special.moon.Size = Vec(130, 130, 130) * ms
        end
        if _special.shell then
            _special.shell.Size = Vec(160, 160, 160) * ms
        end
        if _special.halo then
            _special.halo.Rate = 25 * iRate(I, 1.45, 1.05)
            _special.halo.Size = NumberSequence.new(330 * ms)
        end
        if _special.cc then
            _special.cc.Saturation = -0.15 * gr
            _special.cc.Brightness = -0.04 * gr
        end
        if _special.atmo then
            _special.atmo.Density = 0.12 + 0.18 * I
            _special.atmo.Haze    = 0.9 + 0.9 * I
            _special.atmo.Glare   = 0.4 + 0.4 * I
        end
        if _special.sky then
            _special.sky.StarCount = math.floor(4000 * (0.55 + 0.45 * I))
        end
    end

    local function buildBloodMoon()
        local folder = getFolder()
        -- night sky (Space set) with celestial zeroed. Ids inlined (the SKY table is declared LATER
        -- in this file, so an upvalue ref here would bind to a nil global — inline keeps it correct).
        local s = Instance.new("Sky"); s.Name = "_wxSkyBM"; s:SetAttribute("WX_Custom", true)
        s.SkyboxBk = "rbxassetid://159454299"; s.SkyboxDn = "rbxassetid://159454296"
        s.SkyboxFt = "rbxassetid://159454293"; s.SkyboxLf = "rbxassetid://159454286"
        s.SkyboxRt = "rbxassetid://159454300"; s.SkyboxUp = "rbxassetid://159454288"
        s.SunAngularSize = 0; s.MoonAngularSize = 0; s.StarCount = 4000
        s.Parent = Lighting; _special.sky = s
        -- the moon: crimson disc + rim shell + soft red halo emitter, parallax-locked ~700 out
        -- (closer than the old 1500 so the red atmosphere doesn't swallow it — Studio-verified).
        local moon = Instance.new("Part")
        moon.Shape = Enum.PartType.Ball; moon.Size = Vec(130, 130, 130)
        moon.Material = Enum.Material.Neon; moon.Color = Color3.fromRGB(215, 45, 35)
        moon.Anchored = true; moon.CanCollide = false; moon.CanQuery = false; moon.CanTouch = false
        moon.CastShadow = false; moon.Massless = true; moon:SetAttribute("WX_Custom", true)
        local att = Instance.new("Attachment"); att.Parent = moon
        local halo = Instance.new("ParticleEmitter")
        halo.Texture = TX_SOFT; halo.Color = ColorSequence.new(Color3.fromRGB(255, 60, 42))
        halo.LightEmission = 1; halo.LightInfluence = 0
        halo.Rate = 25; halo.Lifetime = NumberRange.new(0.22, 0.28)
        halo.Speed = NumberRange.new(0, 0); halo.Size = NumberSequence.new(330)
        halo.Transparency = NumberSequence.new(0.72); halo.RotSpeed = NumberRange.new(0, 0)
        halo.Parent = att; _special.halo = halo
        moon.Parent = folder; _special.moon = moon
        local shell = Instance.new("Part")
        shell.Shape = Enum.PartType.Ball; shell.Size = Vec(160, 160, 160)
        shell.Material = Enum.Material.Neon; shell.Color = Color3.fromRGB(255, 60, 45); shell.Transparency = 0.7
        shell.Anchored = true; shell.CanCollide = false; shell.CanQuery = false; shell.CanTouch = false
        shell.CastShadow = false; shell.Massless = true; shell:SetAttribute("WX_Custom", true)
        shell.Parent = folder; _special.shell = shell
        -- CC tint + red atmosphere pall
        local cc = Instance.new("ColorCorrectionEffect"); cc.Name = "_wxBM"; cc:SetAttribute("WX_Custom", true)
        cc.TintColor = Color3.fromRGB(255, 165, 160); cc.Saturation = -0.15; cc.Brightness = -0.04
        cc.Parent = Lighting; _special.cc = cc
        local at = Instance.new("Atmosphere"); at.Name = "_wxBMAtmo"; at:SetAttribute("WX_Custom", true)
        at.Density = 0.3; at.Color = Color3.fromRGB(125, 35, 35); at.Decay = Color3.fromRGB(190, 55, 50)
        at.Glare = 0.8; at.Haze = 1.8; at.Parent = Lighting; _special.atmo = at
        _special.kind = "BloodMoon"
        tuneBloodMoon(iAmt())   -- the slider was a dead control on this type until now
    end

    local function startSpecialAnim()
        if _specialConn then return end
        local accum = 0
        _specialConn = RunService.Heartbeat:Connect(function(dt)
            if not Config.Weather or not _special.kind then return end
            accum = accum + dt
            if accum < 0.1 then return end   -- ~10Hz is plenty for slow sky motion
            accum = 0
            local cam = Camera; if not cam then return end
            local pos = cam.CFrame.Position
            if _special.kind == "BloodMoon" and _special.moon then
                -- parallax-lock moon + rim shell at a fixed azimuth ~700 studs out (reads celestial)
                local cf = CFrame.new(pos + Vec(0.45, 0.62, -0.64).Unit * 700)
                _special.moon.CFrame = cf
                if _special.shell then _special.shell.CFrame = cf end
            end
        end)
    end

    -- shared sequence constructors + the soft radial glow id (also used by the sky-event
    -- and lantern blocks below) — declared here so they outlive the meteor IIFE.
    local CSK, NSK = ColorSequenceKeypoint.new, NumberSequenceKeypoint.new
    local TX_MGLOW = "rbxassetid://78582616787441"     -- soft radial glow (flarecore)

    -- ════════════════════════════════════════════════════════════════════════
    -- METEORS → CINEMATIC BOLIDE. Ground-up rebuild 2026-07-25 (Studio-graded,
    -- WX_DEV_meteor v3). Own toggle WeatherMeteors, own scheduler.
    --
    -- TWO DISTANCE TIERS run in the same sky — depth is only legible relatively:
    --   FAR  (cap 2) crosses 3000-3900 studs of sky 1400-2600 out and 820-1180 up,
    --        ~12s per crossing (≈7°/s angular). Colours lerp toward MET_HAZE and
    --        base alpha rises with `hz` → smaller, dimmer, lower contrast. Ends in
    --        a terminal ablation FLARE then extinction — no impact.
    --   NEAR (cap 1) lands 90-200 studs ahead of the player after a long shallow
    --        1750-2200 stud entry from 640-800 up (~25°/s). Full contrast, sparks,
    --        shed fragment, impact. That band is the play area underfoot, so a plain
    --        ground raycast is all the landing needs.
    -- The two angular speeds side by side are what sells "huge and far away".
    --
    -- HEAD = a BURNING ROCK, never a ball: 7 dark Slate chunks tumbling as one rigid
    -- irregular body (silhouette changes in flight) + 4 velocity-locked Neon ablation
    -- fissures over the LEADING hemisphere + a nose PointLight that burns the leading
    -- faces and leaves the trailing side dark. Plasma is a TEARDROP, not a halo: four
    -- LockedToPart glow sprites stepped BACK along the velocity axis, each larger and
    -- dimmer (compact white-hot nose ahead of the rock → wide faint deep-orange wake).
    -- Three incommensurate sines (≈6.5/10.7/16.5 Hz) drive an irregular combustion
    -- flicker on every glow, fissure and light.
    --
    -- TAIL carries the visual mass (head glow ≈7% of ribbon length). Continuity is
    -- structural: a Trail cannot bead. Four CONCENTRIC Stretch-mapped soft-glow Trails
    -- with staggered lifetimes (0.26 / 0.72 / 1.85 / 3.2s) and a cross-section
    -- temperature ramp — white → gold → deep orange → red → dark ember. (Wrap-tiling a
    -- radial texture beads at speed; an untextured Trail reads as a hard polyline;
    -- one Stretch layer alone fades at head AND tail. The stagger fixes all three.)
    -- SMOKE is particles only, in two ranks, both LightInfluence-shaded (never
    -- self-lit) and both wind-driven: a dense TRAIN behind the fire and a sparse,
    -- huge, 24-38s SCAR that lingers and shears with the wind after the pass. Both
    -- rates are SOLVED from flight speed so spacing stays a fraction of the puff
    -- diameter at any speed — that is what kills the old string-of-pearls.
    --
    -- IMPACT: soft-sprite flash + brief hard core + light pop → ground shockwave → flat
    -- 360° dust ring → ember fountain → fire column → mushrooming smoke pillar, all
    -- under a lingering crater afterglow light so the dust column reads at night.
    -- The flash is a SPRITE: an expanding Neon ball big enough to read from 100 studs
    -- shows a hard silhouette rim and looks like a glass dome, not an explosion.
    -- SPECTACLE "MeteorBigOne": a big near bolide that calves 2-3 children mid-flight.
    -- Live-particle budget ≈460 at full occupancy (2 far + 1 near).
    -- ════════════════════════════════════════════════════════════════════════
    local startMeteors, stopMeteors, rescheduleMeteors
    ;(function()
        local MET_TXS  = "rbxassetid://77935321198144"   -- billowy smoke puff
        local MET_TXK  = "rbxassetid://102481842205398"  -- thin tapered streak
        local MET_TXD  = "rbxassetid://341828512"        -- tan dust billow
        local MET_HAZE = Color3.fromRGB(128, 146, 176)   -- atmospheric-perspective target
        -- plasma teardrop: z = offset along velocity (−ahead), b0/b1 = flicker base/gain
        local MET_GLOW = {
            { z = -0.80, size = 0.85, tr = 0.03, col = Color3.fromRGB(255, 246, 216), life = 0.09, rate = 34, b0 = 1.35, b1 = 2.1 },
            { z = -0.10, size = 1.75, tr = 0.55, col = Color3.fromRGB(255, 194, 106), life = 0.10, rate = 30, b0 = 0.85, b1 = 1.4 },
            { z =  1.30, size = 3.10, tr = 0.80, col = Color3.fromRGB(255, 124,  46), life = 0.11, rate = 26, b0 = 0.5, b1 = 0.8 },
            { z =  3.20, size = 5.20, tr = 0.92, col = Color3.fromRGB(224,  72,  26), life = 0.12, rate = 22, b0 = 0.4, b1 = 0.6 },
        }
        -- rock: { sx, sy, sz, ox, oy, oz, rx, ry, rz, r, g, b, transparency, tumbles }
        local MET_ROCK = {
            { 1.00, 0.74, 1.28,  0.00,  0.00,  0.00, 0.25, 0.40, 0.18, 58, 51, 47, 0.00, true },
            { 0.70, 0.60, 0.76,  0.40,  0.20,  0.12, 0.80, 0.50, 1.10, 47, 41, 39, 0.00, true },
            { 0.58, 0.48, 0.64, -0.38, -0.26,  0.34, 1.20, 0.90, 0.30, 36, 31, 30, 0.00, true },
            { 0.46, 0.40, 0.52,  0.06, -0.42, -0.24, 0.40, 1.30, 0.70, 52, 45, 42, 0.00, true },
            { 0.36, 0.30, 0.40, -0.32,  0.36, -0.08, 0.90, 0.20, 1.40, 42, 36, 34, 0.00, true },
            { 0.30, 0.26, 0.34,  0.22, -0.10,  0.46, 1.50, 0.70, 0.20, 38, 33, 32, 0.00, true },
            { 0.26, 0.34, 0.22, -0.20, -0.34, -0.02, 0.60, 1.10, 0.90, 33, 29, 28, 0.00, true },
            { 0.52, 0.40, 0.16,  0.10,  0.06, -0.56, 0.00, 0.00, 0.50, 255, 244, 214, 0.10, false },
            { 0.30, 0.46, 0.14, -0.30, -0.14, -0.44, 0.00, 0.00, -0.90, 255, 190, 104, 0.28, false },
            { 0.34, 0.20, 0.12,  0.16, -0.34, -0.40, 0.00, 0.00, 0.20, 255, 158,  66, 0.36, false },
            { 0.22, 0.16, 0.10, -0.10,  0.34, -0.38, 0.00, 0.00, 1.20, 255, 214, 150, 0.30, false },
        }
        local MET_ABL0 = 8            -- MET_ROCK index where the Neon ablation fissures start
        local MET_ABLA = { 0.06, 0.20, 0.26, 0.22 }   -- fissure base alpha (flicker rides on top)
        local MET_ABLK = { 0.20, 0.24, 0.26, 0.26 }
        local MET_UP, MET_DOWN = Vec(0, 300, 0), Vec(0, -800, 0)
        local _metConn = nil
        local _metNextFar, _metNextNear = 0, 0
        local _metFar, _metNear = 0, 0
        local _metLive = {}
        local _metRp = RaycastParams.new()
        _metRp.FilterType = Enum.RaycastFilterType.Exclude

        local function hz(c, k)
            return c:Lerp(MET_HAZE, k)
        end
        local function metPart(sx, sy, sz, cf)
            local p = Instance.new("Part")
            p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
            p.CastShadow = false; p.Massless = true
            p.TopSurface = Enum.SurfaceType.Smooth; p.BottomSurface = Enum.SurfaceType.Smooth
            p.Size = Vec(sx, sy, sz); p.CFrame = cf
            p:SetAttribute("WX_Custom", true)
            p.Parent = getLightFolder()
            return p
        end
        -- our own folder and the player must never be raycast against
        local function metFilter()
            local ch = nil
            if lp then ch = lp.Character end
            if ch then
                _metRp.FilterDescendantsInstances = { getFolder(), ch }
            else
                _metRp.FilterDescendantsInstances = { getFolder() }
            end
        end
        -- Land in the play area ahead of the player: 90-200 studs out with a modest lateral
        -- spread, plain ground raycast. That band is the ground the player is standing on,
        -- so no visibility/occlusion cleverness is needed. One retry at half distance covers
        -- a cramped map; only a player over a true void falls through to an airburst.
        local function metSolveLand(base, out, tang)
            local d = 90 + math.random() * 110
            local lat = (math.random() - 0.5) * 160
            for _ = 1, 2 do
                local c = base + out * d + tang * lat
                local h = Workspace:Raycast(c + MET_UP, MET_DOWN, _metRp)
                if h then
                    return h.Position + Vec(0, 1.5, 0)
                end
                d = d * 0.5
                lat = lat * 0.5
            end
            return nil
        end
        -- LockedToPart glow sprite. Parent MUST be a Part: a "locked" emitter parented
        -- to an Attachment does not lock and smears a dotted line along the arc.
        local function metGlow(host, size, transp, color, life, rate)
            local g = Instance.new("ParticleEmitter")
            g:SetAttribute("WX_Custom", true)
            g.Texture = TX_MGLOW; g.Color = ColorSequence.new(color)
            g.LightEmission = 1; g.LightInfluence = 0
            g.Rate = rate; g.Lifetime = NumberRange.new(life, life)
            g.Size = NumberSequence.new(size); g.Transparency = NumberSequence.new(transp)
            g.Speed = NumberRange.new(0, 0); g.LockedToPart = true
            g.Parent = host
            return g
        end
        -- one concentric ribbon layer; sep is the MAX width (WidthScale only scales down)
        local function metRibbon(part, sep, c0, c1, a0, w1, life, emit, inf)
            local aT = Instance.new("Attachment"); aT.Position = Vec(0, sep * 0.5, 0); aT.Parent = part
            local aB = Instance.new("Attachment"); aB.Position = Vec(0, -sep * 0.5, 0); aB.Parent = part
            local tr = Instance.new("Trail")
            tr:SetAttribute("WX_Custom", true)
            tr.Attachment0 = aT; tr.Attachment1 = aB; tr.FaceCamera = true
            tr.Texture = TX_MGLOW; tr.TextureMode = Enum.TextureMode.Stretch; tr.TextureLength = 1
            tr.Color = ColorSequence.new(c0, c1)
            tr.Transparency = NumberSequence.new({ NSK(0, a0), NSK(0.6, a0 + (1 - a0) * 0.45), NSK(1, 1) })
            tr.WidthScale = NumberSequence.new({ NSK(0, 1), NSK(1, w1) })
            tr.Lifetime = life; tr.LightEmission = emit; tr.LightInfluence = inf
            tr.MinLength = 0.05
            tr.Parent = part
            return { t = tr, a = aT, b = aB, sep = sep }
        end
        -- shaded smoke rank. rate is SOLVED by the caller from flight speed so that
        -- spacing (spd/rate) stays a fraction of the birth diameter → never beads.
        local function metSmoke(host, sb, lo, hi, rate, aBase, drift, spread, k)
            local e = Instance.new("ParticleEmitter")
            e:SetAttribute("WX_Custom", true)
            e.Texture = MET_TXS
            e.Color = ColorSequence.new({
                CSK(0,   hz(Color3.fromRGB(178, 164, 152), k * 0.5)),
                CSK(0.2, hz(Color3.fromRGB(146, 142, 138), k * 0.5)),
                CSK(1,   hz(Color3.fromRGB(84, 82, 80), k * 0.5)) })
            e.LightEmission = 0.02; e.LightInfluence = 0.6   -- shaded, never self-illuminated
            e.Rate = rate; e.Lifetime = NumberRange.new(lo, hi)
            e.Size = NumberSequence.new({ NSK(0, sb), NSK(0.35, sb * 1.9), NSK(1, sb * 3) })
            e.Transparency = NumberSequence.new({
                NSK(0, 0.94), NSK(0.07, aBase + 0.16 * k), NSK(0.62, aBase + 0.16), NSK(1, 1) })
            e.Speed = NumberRange.new(0, spread); e.SpreadAngle = Vector2.new(60, 60)
            e.Drag = 0.5
            e.RotSpeed = NumberRange.new(-8, 8); e.Rotation = NumberRange.new(0, 360)
            -- one-shot wind sample: the scar outlives the bolide by ~40s, so a live
            -- coupling would need its own loop for an imperceptible gain
            e.Acceleration = Vec(Wind.x * drift, 0.35, Wind.z * drift)
            e.Parent = host
            return e
        end
        local function bez(p0, p1, p2, a)
            return p0:Lerp(p1, a):Lerp(p1:Lerp(p2, a), a)
        end

        local function metImpact(pos, sc)
            -- lens safety: pulled-in landings can be close, and a flash that sweeps
            -- THROUGH the camera reads as a frame-filling cutout. Scale down, never up.
            if Camera then
                sc = math.min(sc, math.max(0.85, (pos - Camera.CFrame.Position).Magnitude / 44))
            end
            local host = metPart(4 * sc, 4 * sc, 4 * sc, CFrame.new(pos))
            host.Shape = Enum.PartType.Ball; host.Material = Enum.Material.Neon
            host.Color = Color3.fromRGB(255, 240, 202); host.Transparency = 0.05
            local fl = Instance.new("PointLight")
            fl.Color = Color3.fromRGB(255, 176, 90); fl.Range = 150; fl.Brightness = 9; fl.Parent = host
            -- crater afterglow: without it the shaded dust column reads as a black blob at night
            local glow = metPart(2, 2, 2, CFrame.new(pos + Vec(0, 3, 0)))
            glow.Transparency = 1
            local gl = Instance.new("PointLight")
            gl.Color = Color3.fromRGB(255, 148, 68); gl.Range = 120 * sc; gl.Brightness = 4; gl.Parent = glow
            local ring = metPart(12 * sc, 2 * sc, 12 * sc, CFrame.new(pos))
            ring.Shape = Enum.PartType.Ball; ring.Material = Enum.Material.Neon
            ring.Color = Color3.fromRGB(255, 150, 60); ring.Transparency = 0.35
            local scorch = metPart(15 * sc, 0.6, 15 * sc, CFrame.new(pos - Vec(0, 0.4, 0)))
            scorch.Shape = Enum.PartType.Ball; scorch.Material = Enum.Material.Neon
            scorch.Color = Color3.fromRGB(255, 104, 24); scorch.Transparency = 0.2
            local att = Instance.new("Attachment"); att.Parent = host
            -- sideways attachment + yaw-only spread sweeps the dust as a flat 360° disc
            local datt = Instance.new("Attachment"); datt.Orientation = Vec(0, 0, -90); datt.Parent = host

            -- the flash proper: soft radial sprite, so there is no silhouette rim
            local flash = Instance.new("ParticleEmitter")
            flash:SetAttribute("WX_Custom", true)
            flash.Texture = TX_MGLOW; flash.Rate = 0
            flash.Color = ColorSequence.new({
                CSK(0,    Color3.fromRGB(255, 246, 214)),
                CSK(0.45, Color3.fromRGB(255, 186, 96)),
                CSK(1,    Color3.fromRGB(226, 96, 34)) })
            flash.LightEmission = 1; flash.LightInfluence = 0
            flash.Lifetime = NumberRange.new(0.30, 0.30)
            flash.Size = NumberSequence.new({ NSK(0, 14 * sc), NSK(0.35, 34 * sc), NSK(1, 44 * sc) })
            flash.Transparency = NumberSequence.new({ NSK(0, 0.05), NSK(0.45, 0.42), NSK(1, 1) })
            flash.Speed = NumberRange.new(0, 0); flash.Rotation = NumberRange.new(0, 360)
            flash.Parent = att
            flash:Emit(2)

            local dust = Instance.new("ParticleEmitter")
            dust:SetAttribute("WX_Custom", true)
            dust.Texture = MET_TXD; dust.Rate = 0
            dust.Color = ColorSequence.new(Color3.fromRGB(198, 178, 152), Color3.fromRGB(120, 112, 104))
            dust.LightEmission = 0.05; dust.LightInfluence = 0.5
            dust.Lifetime = NumberRange.new(5.5, 9)
            dust.Size = NumberSequence.new({ NSK(0, 6 * sc), NSK(1, 22 * sc) })
            dust.Transparency = NumberSequence.new({ NSK(0, 0.6), NSK(0.1, 0.42), NSK(0.6, 0.68), NSK(1, 1) })
            dust.Speed = NumberRange.new(22, 38); dust.SpreadAngle = Vector2.new(0, 180)
            dust.Drag = 1.9; dust.EmissionDirection = ND.Top
            dust.RotSpeed = NumberRange.new(-16, 16); dust.Rotation = NumberRange.new(0, 360)
            dust.Acceleration = Vec(Wind.x * 6, 0.4, Wind.z * 6)
            dust.Parent = datt
            dust:Emit(math.floor(24 * sc))

            local fount = Instance.new("ParticleEmitter")
            fount:SetAttribute("WX_Custom", true)
            fount.Texture = MET_TXK; fount.Rate = 0
            fount.Color = ColorSequence.new(Color3.fromRGB(255, 200, 110), Color3.fromRGB(196, 52, 14))
            fount.LightEmission = 1; fount.LightInfluence = 0
            fount.Lifetime = NumberRange.new(1.1, 2.2)
            fount.Size = NumberSequence.new({ NSK(0, 1.7 * sc), NSK(1, 0.08) })
            fount.Transparency = NumberSequence.new({ NSK(0, 0), NSK(0.7, 0.35), NSK(1, 1) })
            fount.Orientation = Enum.ParticleOrientation.VelocityParallel
            fount.Speed = NumberRange.new(48, 96); fount.SpreadAngle = Vector2.new(30, 30)
            fount.Acceleration = Vec(0, -74, 0); fount.Drag = 0.35
            fount.EmissionDirection = ND.Top; fount.Parent = att
            fount:Emit(math.floor(52 * sc))

            local col = Instance.new("ParticleEmitter")
            col:SetAttribute("WX_Custom", true)
            col.Texture = TX_MGLOW; col.Rate = 0
            col.Color = ColorSequence.new({
                CSK(0,    Color3.fromRGB(255, 236, 180)),
                CSK(0.35, Color3.fromRGB(255, 130, 40)),
                CSK(1,    Color3.fromRGB(122, 40, 18)) })
            col.LightEmission = 0.9; col.LightInfluence = 0
            col.Lifetime = NumberRange.new(0.55, 1.05)
            col.Size = NumberSequence.new({ NSK(0, 5 * sc), NSK(1, 14 * sc) })
            col.Transparency = NumberSequence.new({ NSK(0, 0.12), NSK(0.6, 0.55), NSK(1, 1) })
            col.Speed = NumberRange.new(32, 62); col.SpreadAngle = Vector2.new(10, 10)
            col.EmissionDirection = ND.Top; col.Parent = att
            col:Emit(18)

            local pil = Instance.new("ParticleEmitter")
            pil:SetAttribute("WX_Custom", true)
            pil.Texture = MET_TXS; pil.Rate = 0
            pil.Color = ColorSequence.new({
                CSK(0,   Color3.fromRGB(186, 150, 118)),   -- fire-lit base
                CSK(0.3, Color3.fromRGB(146, 140, 132)),
                CSK(1,   Color3.fromRGB(88, 85, 82)) })
            pil.LightEmission = 0.02; pil.LightInfluence = 0.5
            pil.Lifetime = NumberRange.new(4.5, 8)
            pil.Size = NumberSequence.new({ NSK(0, 4.5 * sc), NSK(1, 20 * sc) })
            pil.Transparency = NumberSequence.new({ NSK(0, 0.52), NSK(0.5, 0.68), NSK(1, 1) })
            pil.Speed = NumberRange.new(16, 30); pil.SpreadAngle = Vector2.new(9, 9)
            pil.Acceleration = Vec(Wind.x * 7, 2.6, Wind.z * 7); pil.Drag = 0.6
            pil.EmissionDirection = ND.Top
            pil.RotSpeed = NumberRange.new(-12, 12); pil.Rotation = NumberRange.new(0, 360)
            pil.Parent = att
            -- staggered bursts = a COLUMN; one same-age burst reads as a detached cannonball
            task.delay(0.12, function() if pil.Parent then pil:Emit(7) end end)
            task.delay(0.62, function() if pil.Parent then pil:Emit(5) end end)
            task.delay(1.30, function() if pil.Parent then pil:Emit(4) end end)

            local t0 = tick()
            local conn
            conn = RunService.Heartbeat:Connect(function()
                if not host.Parent then
                    conn:Disconnect()
                    return
                end
                local k = tick() - t0
                local f1 = math.clamp(k / 0.10, 0, 1)   -- core snaps out; the sprite carries the flash
                host.Size = Vec(1, 1, 1) * (4 + 6 * f1) * sc
                host.Transparency = 0.05 + 0.95 * f1
                fl.Brightness = 9 * (1 - math.clamp(k / 0.55, 0, 1))
                gl.Brightness = 4 * (1 - math.clamp(k / 5, 0, 1))
                local f2 = math.clamp(k / 0.55, 0, 1)
                ring.Size = Vec(12 + 52 * f2, 2 - 1.2 * f2, 12 + 52 * f2) * sc
                ring.Transparency = 0.35 + 0.65 * f2
                scorch.Transparency = 0.2 + 0.8 * math.clamp(k / 7, 0, 1)
                if k > 7.2 then
                    conn:Disconnect()
                end
            end)
            Debris:AddItem(ring, 1.1)
            Debris:AddItem(glow, 5.2)
            Debris:AddItem(scorch, 7.5)
            Debris:AddItem(host, 11)   -- dust (9) + pillar (1.3 delay + 8 life) need the host alive
        end

        -- One bolide. opts (all optional): big, ang, land, start, scaleMul, noSplit.
        local function launch(far, opts)
            local ang = math.random() * 6.28318
            local mul = 1
            local big = false
            if opts then
                if opts.ang then ang = opts.ang end
                if opts.scaleMul then mul = opts.scaleMul end
                big = opts.big == true
            end
            local tang = Vec(-math.sin(ang), 0, math.cos(ang))
            local out = Vec(math.cos(ang), 0, math.sin(ang))
            local sgn = 1
            if math.random() < 0.5 then sgn = -1 end
            local base = Camera.CFrame.Position

            local startP, endP, spd, rs, ws, k, doImpact, smk
            if far then
                local ctr = base + out * (1400 + math.random() * 1200)
                          + Vec(0, 820 + math.random() * 360, 0)
                local travel = 3000 + math.random() * 900
                local drop = 320 + math.random() * 200
                startP = ctr - tang * (travel * 0.5 * sgn) + Vec(0, drop * 0.5, 0)
                endP = ctr + tang * (travel * 0.5 * sgn) - Vec(0, drop * 0.5, 0)
                spd = 255 + math.random() * 70
                rs = 14 + math.random() * 5
                ws = 3.9 + math.random()
                k = 0.14 + math.random() * 0.10
                doImpact = false
                smk = 1.6   -- far puffs are 4x wider; the same overlap needs proportionally less rate
            else
                metFilter()
                local land = nil
                if opts and opts.land then
                    local h = Workspace:Raycast(opts.land + MET_UP, MET_DOWN, _metRp)
                    if h then land = h.Position + Vec(0, 1.5, 0) end
                end
                if not land then land = metSolveLand(base, out, tang) end
                doImpact = land ~= nil
                if not land then
                    land = base + out * 150 + Vec(0, 40, 0)   -- player over a void ⇒ airburst
                end
                local travel = 1750 + math.random() * 450
                startP = land - tang * (travel * sgn) + out * (190 + math.random() * 190)
                         + Vec(0, 640 + math.random() * 160, 0)
                if opts and opts.start then startP = opts.start end
                endP = land
                spd = 175 + math.random() * 38
                -- head is deliberately scaled UP without ws: the ratio, not the absolute
                -- size, is what makes the rock read against its own ribbon
                rs = (7.0 + math.random() * 2.6) * mul
                ws = (1.3 + math.random() * 0.28) * mul
                k = 0
                smk = 1
            end
            if big then
                rs = rs * 1.7
                ws = ws * 1.5
                spd = spd * 0.92
            end
            local flare = far or (not doImpact)
            local splitAt = nil
            if big and not (opts and opts.noSplit) then
                splitAt = 0.42 + math.random() * 0.12
            end

            local mid = startP:Lerp(endP, 0.5) + Vec(0, (endP - startP).Magnitude * 0.075, 0)
            local dur = ((startP - mid).Magnitude + (mid - endP).Magnitude) / spd
            local cf0 = CFrame.lookAt(startP, endP)
            local root = metPart(0.2, 0.2, 0.2, cf0)
            root.Transparency = 1
            local a0 = Instance.new("Attachment"); a0.Parent = root

            local glows = table.create(4)
            for i, s in MET_GLOW do
                local hp = metPart(0.2, 0.2, 0.2, cf0)
                hp.Transparency = 1
                glows[i] = { p = hp, z = s.z * rs, b0 = s.b0, b1 = s.b1,
                    e = metGlow(hp, s.size * rs, math.min(0.97, s.tr + 0.18 * k),
                        hz(s.col, k * 0.55), s.life, s.rate) }
            end
            local chunks = table.create(#MET_ROCK)
            for i, r in MET_ROCK do
                local p = metPart(r[1] * rs, r[2] * rs, r[3] * rs, cf0)
                p.Transparency = r[13]
                if r[14] then
                    p.Material = Enum.Material.Slate
                    p.Color = Color3.fromRGB(r[10], r[11], r[12])
                else
                    p.Material = Enum.Material.Neon
                    p.Color = hz(Color3.fromRGB(r[10], r[11], r[12]), k * 0.4)
                end
                chunks[i] = { p = p, tumble = r[14],
                    off = CFrame.new(r[4] * rs, r[5] * rs, r[6] * rs) * CFrame.Angles(r[7], r[8], r[9]) }
            end
            local noseLight, bodyLight = nil, nil
            if not far then
                -- sits AHEAD of the rock: burns the leading faces, trailing side stays dark
                noseLight = Instance.new("PointLight")
                noseLight.Color = Color3.fromRGB(255, 186, 108)
                noseLight.Range = 4.2 * rs; noseLight.Brightness = 11
                noseLight.Parent = glows[1].p
                bodyLight = Instance.new("PointLight")
                bodyLight.Color = Color3.fromRGB(255, 150, 70)
                bodyLight.Range = 16 * rs; bodyLight.Brightness = 3
                bodyLight.Parent = root
            end

            local ha = 0.20 * k
            local ribbons = {
                metRibbon(root, 7.5 * ws, hz(Color3.fromRGB(255, 253, 248), k * 0.3),
                    hz(Color3.fromRGB(255, 226, 156), k * 0.6), ha, 0.45, 0.26, 1, 0),
                metRibbon(root, 14 * ws, hz(Color3.fromRGB(255, 222, 146), k * 0.5),
                    hz(Color3.fromRGB(255, 136, 40), k * 0.9), 0.06 + ha, 0.36, 0.72, 1, 0),
                metRibbon(root, 23 * ws, hz(Color3.fromRGB(255, 138, 42), k * 0.9),
                    hz(Color3.fromRGB(196, 50, 14), k), 0.22 + ha, 0.28, 1.85, 1, 0),
                metRibbon(root, 33 * ws, hz(Color3.fromRGB(196, 62, 18), k),
                    hz(Color3.fromRGB(88, 26, 14), k), 0.52 + ha, 0.30, 3.20, 0.55, 0.12),
            }
            -- rate is solved so consecutive puffs sit ~0.30 of a birth diameter apart.
            -- At 0.55 (train) and 0.85 (scar) the ranks beaded into a string of pearls
            -- the moment the landing came inside ~200 studs; the old clamp CEILINGS were
            -- the binding limit, so both the ceiling and the birth size went up.
            local trainRate = math.clamp(spd / (17 * ws * 0.30 * smk), 6, 30)
            local train = metSmoke(a0, 17 * ws, 5, 7.5, trainRate, 0.56, 5.6, 3, k)
            local scarRate = math.clamp(spd / (50 * ws * 0.28 * smk), 1.6, 9)
            local scar = metSmoke(a0, 50 * ws, 20, 32, scarRate, 0.74, 7.8, 7, k)

            local sparks = nil
            if not far then
                sparks = Instance.new("ParticleEmitter")
                sparks:SetAttribute("WX_Custom", true)
                sparks.Texture = MET_TXK
                sparks.Color = ColorSequence.new(Color3.fromRGB(255, 172, 70), Color3.fromRGB(186, 44, 12))
                sparks.LightEmission = 1; sparks.LightInfluence = 0
                sparks.Rate = 60; sparks.Lifetime = NumberRange.new(0.6, 1.5)
                sparks.Size = NumberSequence.new({ NSK(0, 2.2 * ws), NSK(1, 0.06) })
                sparks.Transparency = NumberSequence.new({ NSK(0, 0.08), NSK(1, 1) })
                sparks.Orientation = Enum.ParticleOrientation.VelocityParallel
                sparks.Speed = NumberRange.new(6, 20); sparks.SpreadAngle = Vector2.new(32, 32)
                sparks.Acceleration = Vec(0, -12, 0); sparks.Drag = 0.6
                sparks.Parent = a0
            end

            if far then _metFar = _metFar + 1 else _metNear = _metNear + 1 end
            local rec = { root = root }
            _metLive[#_metLive + 1] = rec

            local t0 = tick()
            local ph = math.random() * 20
            local spinX, spinY, spinZ = (math.random() - 0.5) * 3, (math.random() - 0.5) * 3.4,
                0.6 + math.random() * 1.6
            local flareAt = 0.76 + math.random() * 0.10
            local shedAt = 0.25 + math.random() * 0.2
            local dead, endT = false, nil
            local conn
            local function retire()
                if dead then
                    return
                end
                dead = true
                if far then
                    _metFar = math.max(0, _metFar - 1)
                else
                    _metNear = math.max(0, _metNear - 1)
                end
                for i = #_metLive, 1, -1 do
                    if _metLive[i] == rec then table.remove(_metLive, i) end
                end
            end
            conn = RunService.Heartbeat:Connect(function()
                if not root.Parent then
                    conn:Disconnect()
                    retire()
                    return
                end
                local now = tick()
                local a = math.clamp((now - t0) / dur, 0, 1)
                local p = bez(startP, mid, endP, a)
                local d = (mid - startP) * (2 * (1 - a)) + (endP - mid) * (2 * a)
                if d.Magnitude < 1e-3 then d = endP - startP end
                local cf = CFrame.lookAt(p, p + d)
                -- irregular combustion: three incommensurate sines ≈ 6.5 / 10.7 / 16.5 Hz
                local n = math.clamp(0.5 + 0.27 * math.sin(now * 41 + ph)
                    + 0.17 * math.sin(now * 67.3 + ph * 2.1)
                    + 0.09 * math.sin(now * 103.7 + ph * 0.7), 0, 1)
                local burn = 1
                if flare and a > flareAt then
                    local u = (a - flareAt) / (1 - flareAt)
                    burn = math.clamp((1 + 1.7 * math.exp(-((u - 0.14) ^ 2) / 0.011))
                        * (1 - u) ^ 1.5, 0, 3)   -- terminal ablation flare, then extinction
                end
                if endT then burn = burn * math.clamp(1 - (now - endT) / 0.4, 0, 1) end
                local bw = math.clamp(burn, 0, 1)

                if not endT then
                    root.CFrame = cf
                    for _, g in glows do
                        g.p.CFrame = cf * CFrame.new(0, 0, g.z)
                    end
                    local tum = CFrame.Angles(now * spinX, now * spinY, now * spinZ)
                    for _, c in chunks do
                        if c.tumble then
                            c.p.CFrame = cf * tum * c.off
                        else
                            c.p.CFrame = cf * c.off
                        end
                    end
                end
                for _, g in glows do
                    g.e.Brightness = (g.b0 + g.b1 * n) * burn
                end
                for i = 1, 4 do
                    local c = chunks[MET_ABL0 + i - 1]
                    c.p.Transparency = math.clamp(1 - (1 - (MET_ABLA[i] + MET_ABLK[i] * (1 - n))) * bw, 0, 1)
                end
                if noseLight then
                    noseLight.Brightness = (7 + 9 * n) * bw
                    bodyLight.Brightness = (2 + 3 * n) * bw
                end
                train.Rate = trainRate * bw
                scar.Rate = scarRate * bw
                if sparks then sparks.Rate = 60 * bw * (0.6 + 0.8 * n) end
                local pinch = (0.5 + 0.5 * bw) * (0.9 + 0.2 * n)   -- flame flutter + burn-out taper
                for _, L in ribbons do
                    local h = L.sep * 0.5 * pinch
                    L.a.Position = Vec(0, h, 0)
                    L.b.Position = Vec(0, -h, 0)
                end

                if splitAt and a >= splitAt then   -- the big one calves child bolides
                    splitAt = nil
                    if sparks then sparks:Emit(30) end
                    for _ = 1, math.random(2, 3) do
                        launch(false, {
                            ang = ang,
                            noSplit = true,
                            scaleMul = 0.40 + math.random() * 0.14,
                            start = p + Vec((math.random() - 0.5) * 30, (math.random() - 0.5) * 20,
                                (math.random() - 0.5) * 30),
                            land = endP + Vec((math.random() - 0.5) * 110, 0, (math.random() - 0.5) * 110),
                        })
                    end
                end
                if (not far) and a > shedAt then   -- ablation: shed one burning fragment
                    shedAt = 2
                    local fp = metPart(0.3 * rs, 0.24 * rs, 0.38 * rs, CFrame.new(p))
                    fp.Material = Enum.Material.Slate
                    fp.Color = Color3.fromRGB(40, 35, 33)
                    metRibbon(fp, 6, Color3.fromRGB(255, 220, 160), Color3.fromRGB(150, 34, 12),
                        0.12, 0.2, 0.8, 1, 0)
                    local fdir = (d.Unit * 0.65
                        + Vec(math.random() - 0.5, -0.5, math.random() - 0.5).Unit * 0.5).Unit
                    local fv, ft0 = fdir * spd * 0.6, tick()
                    local fc
                    fc = RunService.Heartbeat:Connect(function()
                        if not fp.Parent then
                            fc:Disconnect()
                            return
                        end
                        local age = tick() - ft0
                        if age > 2.4 then
                            fc:Disconnect()
                            fp:Destroy()
                            return
                        end
                        fv = fv + Vec(0, -0.88, 0)
                        fp.CFrame = CFrame.new(fp.Position + fv * 0.016)
                            * CFrame.Angles(age * 5, age * 3, age * 4)
                    end)
                end

                if not endT then
                    if a >= 1 then
                        endT = now
                        if doImpact then
                            -- coefficient tracks rs so a bigger head does NOT grow the blast
                            metImpact(endP, rs * 0.215 + 0.6)
                            local tid = cfg("WeatherThunderId", "")
                            if tid ~= "" then
                                task.delay(0.15, function()
                                    oneShot(tid, cfg("WeatherSoundVolume", 0.35) * 6)
                                end)
                            end
                        end
                    elseif flare and burn < 0.02 and a > flareAt then
                        endT = now
                    end
                elseif now - endT >= 0.4 then
                    retire()
                    conn:Disconnect()
                    train.Enabled = false; scar.Enabled = false
                    if sparks then sparks.Enabled = false end
                    for _, g in glows do
                        g.e.Enabled = false
                        g.p:Destroy()
                    end
                    for _, L in ribbons do L.t.Enabled = false end
                    for _, c in chunks do c.p:Destroy() end
                    if noseLight then noseLight:Destroy(); bodyLight:Destroy() end
                    Debris:AddItem(root, 42)   -- the 24-38s scar has to finish drifting first
                end
            end)
            Debris:AddItem(root, dur + 46)   -- safety net if the loop never reaches a terminal state
        end

        local function spawnMeteor(far, opts)
            -- re-gate: a scheduled spawn may land after disable/unload
            if not Config.Weather or not cfg("WeatherMeteors", false) then
                return
            end
            -- the rate slider also widens how many may share the sky (a fast cadence into
            -- a cap of 1 just silently drops spawns), but both tiers stay hard-bounded:
            -- 3 near + 4 far at the top of the bar.
            local r = evRate("WeatherMeteorRate")
            local capped
            if far then
                capped = _metFar >= math.clamp(math.floor(1 + 1.5 * r), 1, 4)
            elseif r >= 2.5 then
                capped = _metNear >= 3
            elseif r >= 1.5 then
                capped = _metNear >= 2
            else
                capped = _metNear >= 1
            end
            if capped then
                return
            end
            launch(far, opts)
        end

        startMeteors = function()
            if _metConn then
                return
            end
            local t = tick()
            _metNextFar = t + 1 + math.random() * 2
            _metNextNear = t + 5 + math.random() * 6
            _metConn = RunService.Heartbeat:Connect(function()
                if not Config.Weather or not cfg("WeatherMeteors", false) then
                    return
                end
                local now = tick()
                local r = evRate("WeatherMeteorRate")
                if now >= _metNextFar then
                    _metNextFar = now + (6 + math.random() * 5) / r
                    pcall(spawnMeteor, true)
                end
                if now >= _metNextNear then
                    _metNextNear = now + (14 + math.random() * 10) / r
                    pcall(spawnMeteor, false)
                end
            end)
        end
        -- slider drag: clamp a stale wait to the new tier maximum (11s / 24s at rate 1) so
        -- the change is felt now. Clamping never lands ON `now`, so a drag can't burst.
        rescheduleMeteors = function()
            if not _metConn then
                return
            end
            local now, r = tick(), evRate("WeatherMeteorRate")
            _metNextFar = math.min(_metNextFar, now + 11 / r)
            _metNextNear = math.min(_metNextNear, now + 24 / r)
        end
        stopMeteors = function()
            if _metConn then _metConn:Disconnect(); _metConn = nil end
            -- the shared light folder survives a toggle-off, so kill live bolides here:
            -- destroying the root drops each flight loop on its next tick
            for _, rec in _metLive do
                pcall(function() rec.root:Destroy() end)
            end
            table.clear(_metLive)
            -- counters are NOT zeroed here: each destroyed root's flight loop still fires
            -- once and retires itself, which is what brings them back to 0
        end

        -- rare spectacle: the big one, which fragments mid-flight. Self-gated (the
        -- scheduler does not filter by type/toggle) and cap-exempt by design.
        registerSpectacle("MeteorBigOne", 1, function()
            if not Config.Weather or not cfg("WeatherMeteors", false) then
                return
            end
            launch(false, { big = true })
        end)
    end)()

    -- ════════════════════════════════════════════════════════════════════════
    -- SKY EVENTS — shooting stars (own toggle). Studio-verified night 2026-07-25.
    -- Each streak is a three-beat event: a star-point TWINKLE at the spawn site
    -- 0.3-0.6s early (the catch-your-eye), then the STREAK — a tapered FaceCamera
    -- Trail led by a tiny locked-sprite head — and, on long crossings only, a faint
    -- ionization TRAIN that outlives the head. Three flight classes (zip / medium /
    -- long graceful) × three compositions (white / ice-blue / rare faint gold);
    -- gold runs slow and long, as real iron-rich meteors do. ~6% of events are a
    -- RADIANT SHOWER: 3-5 streaks over a couple of seconds on great circles leaving
    -- one sky point, sharing one composition.
    -- TRAIL SAFETY (this ribbon moves 100-350 studs/s — the hard-white-polyline
    -- failure mode lives here): textured (soft radial glow) + Stretch + FaceCamera +
    -- width AND transparency tapers + Lifetime derived from the desired tail length
    -- (life = tail / speed, so a fast zip gets a short-lived ribbon, never a smear).
    -- The head-end pinch-ball is killed structurally: over the last 30% the
    -- attachment separation is lerped to zero, so the ribbon tapers to nothing at
    -- the head while still travelling, and Enabled goes false at flight end so the
    -- remainder ages out instead of collapsing onto a stopped part.
    -- Nested IIFE keeps ~23 locals off this proto's registers.
    -- ════════════════════════════════════════════════════════════════════════
    local startStars, stopStars, rescheduleStars
    ;(function()
        local TX_SGLOW = "rbxassetid://78582616787441"     -- soft radial glow (flarecore)
        local TX_STAR4 = "rbxassetid://17726943419"        -- 4-point star (twinkle-in)
        local GLINT_C  = Color3.fromRGB(246, 250, 255)
        local MIN_SIN  = 0.3                               -- ≈17°: never seed a streak into the horizon
        local FLOOR_H  = 60                                -- studs above the eye the head may never sink past
        -- head, mid, tail per composition
        local PAL = {
            { WHITE, Color3.fromRGB(222, 234, 255), Color3.fromRGB(150, 184, 240) },
            { Color3.fromRGB(242, 250, 255), Color3.fromRGB(160, 206, 255), Color3.fromRGB(78, 138, 255) },
            { Color3.fromRGB(255, 246, 220), Color3.fromRGB(255, 205, 122), Color3.fromRGB(222, 140, 44) },
        }
        -- dist0, distSpan, speed0, speedSpan, tail0, tailSpan, ribbon width
        local CLS = {
            { 80, 55, 250, 105, 50, 28, 3.6 },
            { 145, 90, 158, 62, 76, 44, 5.4 },
            { 240, 150, 98, 46, 118, 62, 7.2 },
        }
        local TR_TRANSP  = NumberSequence.new({ NSK(0, 0.04), NSK(0.12, 0.12), NSK(0.45, 0.55), NSK(1, 1) })
        local TR_WIDTH   = NumberSequence.new({ NSK(0, 0.4), NSK(0.08, 1), NSK(1, 0.02) })
        local ION_TRANSP = NumberSequence.new({ NSK(0, 0.86), NSK(0.3, 0.9), NSK(1, 1) })
        local ION_WIDTH  = NumberSequence.new({ NSK(0, 0.5), NSK(0.25, 1), NSK(1, 0.35) })
        local HEAD_TR    = NumberSequence.new({ NSK(0, 1), NSK(0.05, 0), NSK(0.72, 0.06), NSK(1, 1) })
        local HALO_TR    = NumberSequence.new({ NSK(0, 1), NSK(0.07, 0.82), NSK(0.7, 0.88), NSK(1, 1) })
        local GLINT_TR   = NumberSequence.new({ NSK(0, 1), NSK(0.3, 0.12), NSK(0.55, 0.42), NSK(1, 1) })
        local _starConn, _starNextT = nil, 0
        local _starLive = {}

        -- one locked billboard sprite: emitted once, its own sequences do the fade,
        -- so a streak needs zero per-frame work beyond position + ribbon taper
        local function mkSprite(parent, tex, col, sizeSeq, transpSeq, life, emit)
            local e = Instance.new("ParticleEmitter")
            e.Texture = tex
            e.Color = ColorSequence.new(col)
            e.Size = sizeSeq
            e.Transparency = transpSeq
            e.Lifetime = NumberRange.new(life)
            e.Rate = 0
            e.Speed = NumberRange.new(0, 0)
            e.SpreadAngle = Vector2.new(0, 0)
            e.LightEmission = emit
            e.LightInfluence = 0
            e.Drag = 0
            e.Parent = parent
            return e
        end

        -- `floorY` = the eye height + FLOOR_H, resolved by the caller (spawns are
        -- camera-relative, but a streak is world-anchored once it exists)
        local function spawnStreak(start, dir, ci, pi, floorY)
            if not Config.Weather or not cfg("WeatherShootingStars", false) then
                return
            end
            if #_starLive >= math.clamp(math.floor(4 + 2 * evRate("WeatherStarRate")), 4, 8) then
                return
            end
            local cls, pal = CLS[ci], PAL[pi]
            local dist = cls[1] + math.random() * cls[2]
            local spd  = cls[3] + math.random() * cls[4]
            local tail = cls[5] + math.random() * cls[6]
            -- re-pitch so a long flight can never carry the head down through the horizon
            if start.Y + dir.Y * dist < floorY then
                local ny = (floorY - start.Y) / dist
                local hl = math.sqrt(dir.X * dir.X + dir.Z * dir.Z)
                if hl > 1e-4 then
                    local k = math.sqrt(math.max(0, 1 - ny * ny)) / hl
                    dir = Vec(dir.X * k, ny, dir.Z * k)
                end
            end
            local dur  = dist / spd
            local life = math.min(tail / spd, dur * 0.9)   -- tail length in TIME: never a smear
            local sep  = cls[7] * (0.85 + math.random() * 0.3)
            local glintD = 0.3 + math.random() * 0.3
            local cf0 = CFrame.lookAt(start, start + dir)
            local host = mkBoltPart(WHITE, 1, Vec(0.2, 0.2, 0.2), cf0, getLightFolder())
            local aT = Instance.new("Attachment"); aT.Position = Vec(0, sep * 0.5, 0); aT.Parent = host
            local aB = Instance.new("Attachment"); aB.Position = Vec(0, -sep * 0.5, 0); aB.Parent = host
            local tr = Instance.new("Trail")
            tr.Attachment0 = aT; tr.Attachment1 = aB
            tr.FaceCamera = true
            tr.Texture = TX_SGLOW; tr.TextureMode = Enum.TextureMode.Stretch; tr.TextureLength = 1
            tr.Color = ColorSequence.new({ CSK(0, pal[1]), CSK(0.24, pal[2]), CSK(1, pal[3]) })
            tr.Transparency = TR_TRANSP; tr.WidthScale = TR_WIDTH
            tr.Lifetime = life; tr.LightEmission = 1; tr.LightInfluence = 0
            tr.MinLength = 0.08; tr.Enabled = false
            tr.Parent = host
            local ion = nil
            if ci == 3 then                                -- long crossings keep a faint train
                ion = Instance.new("Trail")
                ion.Attachment0 = aT; ion.Attachment1 = aB
                ion.FaceCamera = true
                ion.Texture = TX_SGLOW; ion.TextureMode = Enum.TextureMode.Stretch; ion.TextureLength = 1
                ion.Color = ColorSequence.new({ CSK(0, pal[2]), CSK(1, pal[3]) })
                ion.Transparency = ION_TRANSP; ion.WidthScale = ION_WIDTH
                ion.Lifetime = life * 2.6; ion.LightEmission = 0.85; ion.LightInfluence = 0
                ion.MinLength = 0.1; ion.Enabled = false
                ion.Parent = host
            end
            local hub = Instance.new("Attachment"); hub.Parent = host
            local coreS = sep * 0.62                       -- head stays a POINT, never an orb
            local core = mkSprite(hub, TX_SGLOW, pal[1], NumberSequence.new({
                NSK(0, coreS * 0.55), NSK(0.1, coreS), NSK(1, coreS * 0.3) }), HEAD_TR, dur, 1)
            core.LockedToPart = true
            local haloS = sep * 1.7
            local halo = mkSprite(hub, TX_SGLOW, pal[2], NumberSequence.new({
                NSK(0, haloS * 0.5), NSK(0.12, haloS), NSK(1, haloS * 0.35) }), HALO_TR, dur, 1)
            halo.LockedToPart = true
            -- twinkle-in: world-space (NOT locked) so it stays behind at the seed point;
            -- LightEmission 0.55 keeps the 4-point silhouette from blooming into a blob
            local gs = sep * 1.9
            local gl = mkSprite(hub, TX_STAR4, GLINT_C, NumberSequence.new({
                NSK(0, gs * 0.1), NSK(0.32, gs), NSK(1, gs * 0.14) }), GLINT_TR, glintD * 1.2, 0.55)
            gl.Rotation = NumberRange.new(0, 90)
            gl.RotSpeed = NumberRange.new(-16, 16)
            gl:Emit(1)
            table.insert(_starLive, {
                host = host, tr = tr, ion = ion, core = core, halo = halo, aT = aT, aB = aB,
                cf0 = cf0, dir = dir, dist = dist, dur = dur, sep = sep,
                t0 = tick() + glintD, started = false,
            })
            Debris:AddItem(host, glintD + dur + life * 2.8 + 0.6)
        end

        local function pickPal()
            local r = math.random()
            if r < 0.55 then
                return 1
            end
            if r < 0.92 then
                return 2
            end
            return 3
        end
        local function pickCls(pi)
            if pi == 3 then                                -- gold burns slow: long or medium only
                if math.random() < 0.6 then
                    return 3
                end
                return 2
            end
            local r = math.random()
            if r < 0.25 then
                return 1
            end
            if r < 0.7 then
                return 2
            end
            return 3
        end

        -- soft bias toward the camera's facing so the effect is actually SEEN, without
        -- pinning every streak to screen centre
        local function viewAz(cam)
            local lv = cam.CFrame.LookVector
            local az = math.atan2(lv.Z, lv.X)
            if math.random() < 0.35 then
                return math.random() * 6.283
            end
            return az
        end

        local function spawnSingle()
            local cam = Camera
            if not cam then
                return
            end
            local base = cam.CFrame.Position
            local az = viewAz(cam) + (math.random() - 0.5) * 1.5
            local el = math.rad(24 + math.random() * 30)
            local r  = 190 + math.random() * 130
            local ce = math.cos(el)
            local start = base + Vec(ce * math.cos(az) * r, math.sin(el) * r, ce * math.sin(az) * r)
            local hd = az + 1.5708 + (math.random() - 0.5) * 2.2
            local pi = pickPal()
            spawnStreak(start, Vec(math.cos(hd), -(0.05 + math.random() * 0.34), math.sin(hd)).Unit,
                pickCls(pi), pi, base.Y + FLOOR_H)
        end

        -- radiant shower: every member leaves the SAME sky point along a great circle,
        -- angular offset drives class (near the radiant = short zip, far = long crossing)
        local function spawnShower()
            local cam = Camera
            if not cam then
                return
            end
            local base = cam.CFrame.Position
            local floorY = base.Y + FLOOR_H
            local raz = viewAz(cam) + (math.random() - 0.5) * 0.9
            local rel = math.rad(36 + math.random() * 16)
            local cr = math.cos(rel)
            local rv = Vec(cr * math.cos(raz), math.sin(rel), cr * math.sin(raz))
            local dn = (Vec(0, -1, 0) + rv * rv.Y).Unit    -- tangent at the radiant pointing down
            local sd = rv:Cross(dn).Unit
            local pi = pickPal()
            local t = 0
            for _ = 1, 3 + math.random(0, 2) do
                t = t + 0.16 + math.random() * 0.42
                task.delay(t, function()
                    if not Config.Weather or not cfg("WeatherShootingStars", false) then
                        return
                    end
                    local phi = (math.random() - 0.5) * 2.8
                    local off = dn * math.cos(phi) + sd * math.sin(phi)
                    local th = math.rad(9 + math.random() * 24)
                    local ct, st = math.cos(th), math.sin(th)
                    local u = (rv * ct + off * st).Unit
                    if u.Y < MIN_SIN then                  -- mirror to the far side of the radiant
                        off = -off
                        u = (rv * ct + off * st).Unit
                    end
                    if u.Y < MIN_SIN then
                        return
                    end
                    local ci = 2
                    if th < 0.22 then
                        ci = 1
                    elseif th > 0.44 then
                        ci = 3
                    end
                    pcall(spawnStreak, base + u * (215 + math.random() * 75),
                        (off * ct - rv * st).Unit, ci, pi, floorY)
                end)
            end
        end

        local function stepStars(now)
            for i = #_starLive, 1, -1 do                   -- reverse: entries are removed in place
                local s = _starLive[i]
                if not s.host.Parent then
                    table.remove(_starLive, i)
                else
                    local a = (now - s.t0) / s.dur
                    if a >= 1 then
                        s.tr.Enabled = false               -- ribbon ages out; never collapses on a stopped part
                        if s.ion then
                            s.ion.Enabled = false
                        end
                        table.remove(_starLive, i)
                    elseif a >= 0 then
                        if not s.started then
                            s.started = true
                            s.tr.Enabled = true
                            s.core:Emit(1)
                            s.halo:Emit(1)
                            if s.ion then
                                s.ion.Enabled = true
                            end
                        end
                        s.host.CFrame = s.cf0 + s.dir * (s.dist * a)
                        if a > 0.7 then                    -- taper the ribbon to nothing at the head
                            local h = s.sep * 0.5 * (1 - (a - 0.7) / 0.3)
                            s.aT.Position = Vec(0, h, 0)
                            s.aB.Position = Vec(0, -h, 0)
                        end
                    end
                end
            end
        end

        startStars = function()
            if _starConn then
                return
            end
            _starNextT = tick() + 2 + math.random() * 4
            _starConn = RunService.Heartbeat:Connect(function()
                if not Config.Weather or not cfg("WeatherShootingStars", false) then
                    return
                end
                local now = tick()
                if now >= _starNextT then
                    local r = evRate("WeatherStarRate")
                    _starNextT = now + (5 + math.random() * 6) / r
                    if math.random() < math.min(0.06 * r, 0.35) then
                        pcall(spawnShower)
                    else
                        pcall(spawnSingle)
                        if math.random() < math.min(0.22 * r, 0.6) then   -- occasional companion
                            task.delay(0.3 + math.random() * 0.5, function()
                                pcall(spawnSingle)
                            end)
                        end
                    end
                end
                pcall(stepStars, now)
            end)
        end
        -- slider drag: clamp a stale wait to the new maximum event gap (11s at rate 1)
        rescheduleStars = function()
            if not _starConn then
                return
            end
            _starNextT = math.min(_starNextT, tick() + 11 / evRate("WeatherStarRate"))
        end
        stopStars = function()
            if _starConn then
                _starConn:Disconnect()
                _starConn = nil
            end
            -- the shared light folder survives a toggle-off, so drop our hosts ourselves
            for _, s in _starLive do
                pcall(function() s.host:Destroy() end)
            end
            table.clear(_starLive)
        end

        -- rare peak: a radiant shower on the spectacle scheduler (registry is permanent —
        -- module load only, gated on our own toggle)
        registerSpectacle("StarShower", 1, function()
            if not cfg("WeatherShootingStars", false) then
                return
            end
            spawnShower()
        end)
    end)()

    -- ════════════════════════════════════════════════════════════════════════
    -- HERO FIREFLIES — 4 real neon motes, each with a warm PointLight, gliding
    -- between smoothstep-lerped waypoints near the ground (the light pools grazing
    -- floor/walls sell the night). One ~20Hz loop; waypoint picks ground-raycast.
    -- Runs only while _curType == "Fireflies" (started/stopped by applyType).
    -- SPECTACLE "FireflySwarm": heroes converge on a point, orbit it trailing
    -- soft-glow Trail ribbons, then disperse; an Emit-burst emitter at the point
    -- densifies the swarm. Studio-verified 2026-07-24.
    -- TRAIL SAFETY (the ribbon degenerates to a hard white polyline the moment one
    -- frame's segment stretches over many studs): FaceCamera + textured + tapered +
    -- short Lifetime, movement hard-clamped to FF_STEP studs per update, and the
    -- ribbon only ever runs during the calm phases (wander + orbit) below FF_SEG —
    -- every jump/sprint leg runs Enabled=false + :Clear(). Measured under an
    -- adversarial 44-stud-teleport stress: max segment while enabled = 1.16 studs.
    -- Nested IIFE keeps ~20 locals off the weather proto budget.
    -- ════════════════════════════════════════════════════════════════════════
    local startFireflies, stopFireflies, refreshFireflies
    ;(function()
        local FF_N     = 7                               -- built once; intensity PARKS the spares
        local FF_BODY  = Color3.fromRGB(215, 255, 120)
        local FF_LIGHT = Color3.fromRGB(244, 232, 120)
        local FF_DOWN  = Vec(0, -80, 0)
        local WANDER   = 28                              -- waypoint box (studs) around the camera
        local FF_STEP  = 2                               -- hard movement clamp, studs per update
        local FF_SEG   = 1.2                             -- ribbon allowed only below this segment
        local FF_TRC = ColorSequence.new({ CSK(0, Color3.fromRGB(198, 255, 128)),
            CSK(0.45, Color3.fromRGB(216, 238, 108)), CSK(1, Color3.fromRGB(255, 196, 86)) })
        local FF_TRT = NumberSequence.new({ NSK(0, 0.36), NSK(0.35, 0.66), NSK(1, 1) })
        local FF_TRW = NumberSequence.new({ NSK(0, 0.8), NSK(0.3, 1), NSK(1, 0) })
        local _ff = { list = nil, conn = nil, folder = nil, burst = nil, burstHost = nil, n = 4 }
        local _swarm = { active = false, t0 = 0, cx = 0, cz = 0, y = 0 }
        local _ffRp = RaycastParams.new()
        _ffRp.FilterType = Enum.RaycastFilterType.Exclude

        -- ground height near (x, z); fixed drop below the camera on void maps
        local function groundY(camPos, x, z)
            local ch = lp and lp.Character
            if ch then
                _ffRp.FilterDescendantsInstances = { getFolder(), ch }
            else
                _ffRp.FilterDescendantsInstances = { getFolder() }
            end
            local hit = Workspace:Raycast(Vec(x, camPos.Y + 6, z), FF_DOWN, _ffRp)
            if hit then
                return hit.Position.Y
            end
            return camPos.Y - 7
        end
        local function pickWaypoint(H, camPos)
            local x = camPos.X + (math.random() - 0.5) * WANDER
            local z = camPos.Z + (math.random() - 0.5) * WANDER
            H.a = H.pos
            H.bpt = Vec(x, groundY(camPos, x, z) + 0.5 + math.random() * 3, z)
            H.dur = math.clamp((H.bpt - H.a).Magnitude / 2.2, 1.5, 6)
            H.t = 0
        end
        -- move `cur` toward `target` but never further than `maxStep` in one update:
        -- caps every segment the ribbon can lay down, whatever the choreography asks for
        local function stepToward(cur, target, maxStep)
            local d = target - cur
            local m = d.Magnitude
            if m <= maxStep or m < 1e-4 then
                return target
            end
            return cur + d * (maxStep / m)
        end
        local function trailOff(H)
            H.calm = 0
            if H.trail.Enabled then
                H.trail.Enabled = false
                H.trail:Clear()
            end
        end
        local function buildFlies()
            local folder = Instance.new("Folder")
            folder.Name = "_wxFlies"; folder:SetAttribute("WX_Custom", true)
            folder.Parent = getFolder()
            _ff.folder = folder
            _ff.list = {}
            local cam = Camera
            local camPos
            if cam then camPos = cam.CFrame.Position else camPos = Vec(0, 0, 0) end
            for i = 1, FF_N do
                local b = mkBoltPart(FF_BODY, 0, Vec(0.25, 0.25, 0.25), CFrame.new(camPos), folder)
                b.Shape = Enum.PartType.Ball
                local light = Instance.new("PointLight")
                light.Color = FF_LIGHT; light.Range = 8; light.Brightness = 2.5
                light.Parent = b
                local halo = Instance.new("ParticleEmitter")
                halo:SetAttribute("WX_Custom", true)
                halo.Texture = TX_MGLOW
                halo.Color = ColorSequence.new(FF_BODY)
                halo.LightEmission = 1; halo.LightInfluence = 0
                halo.Size = NumberSequence.new(1.1, 1.5)
                halo.Transparency = NumberSequence.new({ NSK(0, 0.75), NSK(1, 1) })
                halo.Rate = 12; halo.Lifetime = NumberRange.new(0.25, 0.4)
                halo.Speed = NumberRange.new(0, 0)
                halo.LockedToPart = true    -- unlocked, a fast hero smears it into a beaded dot-line
                halo.Parent = b
                local a0 = Instance.new("Attachment")
                a0.Position = Vec(0, 0.6, 0); a0.Parent = b
                local a1 = Instance.new("Attachment")
                a1.Position = Vec(0, -0.6, 0); a1.Parent = b
                local tr = Instance.new("Trail")
                tr:SetAttribute("WX_Custom", true)
                tr.Attachment0 = a0; tr.Attachment1 = a1
                tr.Texture = TX_MGLOW; tr.TextureMode = Enum.TextureMode.Stretch
                tr.Color = FF_TRC; tr.Transparency = FF_TRT; tr.WidthScale = FF_TRW
                tr.Lifetime = 0.65
                tr.LightEmission = 1; tr.LightInfluence = 0
                tr.FaceCamera = true        -- an edge-on untextured ribbon is the white-line failure
                tr.MinLength = 0.25; tr.MaxLength = 14
                tr.Enabled = false          -- armed by the loop once the hero is moving slowly
                tr.Parent = b
                local H = { part = b, light = light, trail = tr, halo = halo, bm = 1,
                            calm = 0, jump = true,
                            pos = camPos, a = camPos, bpt = camPos, t = 0, dur = 1,
                            ph = math.random() * 6.283, spin = 1.7 + i * 0.25,
                            blinkT = math.random() * 3, period = 2.4 + math.random() * 1.4 }
                pickWaypoint(H, camPos)     -- first pick = spawn point
                H.pos = H.bpt
                pickWaypoint(H, camPos)     -- real first leg starts from the spawn point
                b.CFrame = CFrame.new(H.pos)
                _ff.list[i] = H
            end
            -- swarm density burst: tiny invisible host repositioned at the swarm point
            local bh = mkBoltPart(FF_BODY, 1, Vec(1.5, 1.5, 1.5), CFrame.new(camPos), folder)
            local be = Instance.new("ParticleEmitter")
            be:SetAttribute("WX_Custom", true)
            be.Texture = TX_MGLOW
            be.Color = ColorSequence.new(Color3.fromRGB(220, 255, 130), Color3.fromRGB(255, 200, 80))
            be.LightEmission = 0.95; be.LightInfluence = 0.05
            be.Size = NumberSequence.new({ NSK(0, 0.1), NSK(0.08, 0.62, 0.15), NSK(0.45, 0.5, 0.1), NSK(1, 0.08) })
            be.Transparency = NumberSequence.new({ NSK(0, 1), NSK(0.08, 0.08), NSK(0.4, 0.45), NSK(0.75, 0.85), NSK(1, 1) })
            be.Rate = 0; be.Lifetime = NumberRange.new(1.6, 2.8)
            be.Speed = NumberRange.new(0.8, 2.2); be.SpreadAngle = Vector2.new(180, 180)
            be.Drag = 2.5; be.EmissionDirection = Enum.NormalId.Top
            be.Parent = bh
            _ff.burst = be; _ff.burstHost = bh
        end
        -- INTENSITY for the hero motes: how many are awake (1 / 4 / 7) and how far their
        -- light pools reach. All FF_N exist from the start, so the slider parks or wakes
        -- them with property writes only — no rebuild, no reseeded wander.
        refreshFireflies = function()
            local list = _ff.list
            if not list then
                return
            end
            local I = iAmt()
            _ff.n = math.clamp(math.floor(1.5 + 3 * I), 1, FF_N)
            local rm, bm = 0.8 + 0.2 * I, 0.7 + 0.3 * I
            for i = 1, FF_N do
                local H = list[i]
                local on = i <= _ff.n
                H.bm = bm
                H.light.Range = 8 * rm
                H.halo.Enabled = on
                if not on then
                    H.light.Brightness = 0
                    H.part.Transparency = 1
                    H.jump = true   -- so waking it later can't lay a ribbon across the gap
                    trailOff(H)
                end
            end
        end
        startFireflies = function()
            if _ff.conn then return end
            buildFlies()
            refreshFireflies()
            local accum = 0
            _ff.conn = RunService.Heartbeat:Connect(function(dt)
                if not Config.Weather then return end
                accum = accum + dt
                if accum < 0.05 then return end          -- ~20Hz is plenty for a glide
                local step = accum; accum = 0
                local cam = Camera; if not cam then return end
                local camPos = cam.CFrame.Position
                local now = tick()
                local sw = -1
                if _swarm.active then
                    sw = now - _swarm.t0
                    if sw > 9 then _swarm.active = false; sw = -1 end
                end
                local list = _ff.list
                for i = 1, _ff.n do
                    local H = list[i]
                    local prev = H.pos
                    local newPos
                    if sw >= 0 then
                        -- swarm: converge (0-2.5s) → orbit (2.5-6.5s) → disperse (6.5-9s)
                        local ang = H.ph + now * H.spin
                        local r
                        if sw < 2.5 then r = 10 - 7.4 * (sw / 2.5)
                        elseif sw < 6.5 then r = 2.6
                        else r = 2.6 + (sw - 6.5) * 6 end
                        local target = Vec(_swarm.cx + math.cos(ang) * r,
                            _swarm.y + 0.55 * math.sin(now * 1.3 + H.ph * 2),
                            _swarm.cz + math.sin(ang) * r)
                        newPos = stepToward(prev, prev:Lerp(target, math.min(step * 3, 1)), FF_STEP)
                        H.bpt = newPos; H.t = 1; H.dur = 1  -- swarm exit rolls straight into a fresh waypoint
                    else
                        H.t = H.t + step
                        local relX, relZ = prev.X - camPos.X, prev.Z - camPos.Z
                        if H.t >= H.dur or (relX * relX + relZ * relZ) > 3600 then
                            pickWaypoint(H, camPos)      -- leg done, or the player outran the flies
                        end
                        local u = H.t / H.dur
                        u = u * u * (3 - 2 * u)          -- smoothstep glide
                        newPos = stepToward(prev, H.a:Lerp(H.bpt, u), FF_STEP)
                    end
                    H.pos = newPos
                    -- ribbon gate: calm phases only (wander + orbit), and only while this
                    -- update's segment stayed short — anything else clears it before it draws
                    if H.jump or (sw >= 0 and (sw < 2.5 or sw >= 6.4))
                        or (newPos - prev).Magnitude > FF_SEG then
                        H.jump = false
                        trailOff(H)
                    else
                        H.calm = H.calm + step
                        if H.calm >= 0.25 and not H.trail.Enabled then
                            H.trail:Clear()
                            H.trail.Enabled = true
                        end
                    end
                    H.part.CFrame = CFrame.new(H.pos.X, H.pos.Y + 0.3 * math.sin(now * 1.7 + H.ph), H.pos.Z)
                    -- blink: sharp attack, slow exponential decay, never fully dark
                    local pulse = math.exp(-((now + H.blinkT) % H.period) * 1.4)
                    H.light.Brightness = (0.5 + 2.6 * pulse) * H.bm
                    H.part.Transparency = 0.4 * (1 - pulse)
                end
            end)
        end
        stopFireflies = function()
            if _ff.conn then _ff.conn:Disconnect(); _ff.conn = nil end
            if _ff.folder then pcall(function() _ff.folder:Destroy() end); _ff.folder = nil end
            _ff.list = nil; _ff.burst = nil; _ff.burstHost = nil
            _swarm.active = false
        end
        -- spectacle: converging swarm — self-gated (the scheduler doesn't filter by type)
        registerSpectacle("FireflySwarm", 1, function()
            if not Config.Weather or _curType ~= "Fireflies" or not _ff.list then return end
            local cam = Camera; if not cam then return end
            local camPos = cam.CFrame.Position
            local ang = math.random() * 6.283
            local d = 8 + math.random() * 8
            local cx = camPos.X + math.cos(ang) * d
            local cz = camPos.Z + math.sin(ang) * d
            _swarm.cx = cx; _swarm.cz = cz
            _swarm.y = groundY(camPos, cx, cz) + 2.2
            _swarm.t0 = tick(); _swarm.active = true
            _ff.burstHost.CFrame = CFrame.new(cx, _swarm.y, cz)
            for _, H in _ff.list do
                trailOff(H)                               -- kill the ribbon before the convergence sprint
            end
            local em = math.max(1, math.floor(7 * iRate(iAmt(), IR.Fireflies.lo, IR.Fireflies.hi) + 0.5))
            for n = 0, 5 do
                task.delay(1.6 + n * 0.7, function()
                    if _swarm.active and _ff.burst then _ff.burst:Emit(em) end
                end)
            end
        end)
    end)()

    -- ════════════════════════════════════════════════════════════════════════
    -- LEAF DEVIL (Autumn spectacle) — a ground vortex that spins up out of the
    -- floor, climbs, spirals leaves up a flaring column, wanders downwind, then
    -- LETS GO and blows the whole spiral away.
    -- What makes it read as a VORTEX and not a clump:
    --  (1) a STACK of ring emitters, one per height band, each ORBITING its own
    --      radius — every band paints an actual ring of leaves in world space,
    --      and a per-band phase twist up the stack lays those rings into a
    --      helix silhouette. Scattered "arms" produce a cloud instead.
    --  (2) radius profile: narrow foot, u^0.9 flare, extra crown flare — the
    --      silhouette is a funnel, never a bar.
    --  (3) rate proportional to ring radius (wide bands carry more leaves) and
    --      an 8° spread, so SKY STAYS VISIBLE BETWEEN THE ORBITS. Anything that
    --      fills the column interior kills the rotation read.
    --  (4) each ring emits along its orbit TANGENT at a speed below the ring's
    --      own sweep, so leaves stream sideways and get left behind — that lag
    --      is what the eye reads as spin.
    --  (5) a FOOT: leaf skirt + dry-dust skirt + a ground scuff decal, so the
    --      column visibly touches down. A dark tall smoke column was the single
    --      loudest "this is a fire" cue — the base is dry tan dust, low.
    --  (6) it ARRIVES: rings ramp in bottom-up and the column climbs over ~1.5s.
    --  (7) ambient leaf rate is suppressed to 45% for the event — against ~800
    --      ambient leaves already in frame, a local column simply does not
    --      register as a spectacle.
    -- Nested IIFE keeps its locals off the weather proto budget. One folder,
    -- one connection, self-terminating; stopLeafDevil is the disable/unload path.
    -- ════════════════════════════════════════════════════════════════════════
    local stopLeafDevil
    ;(function()
        local RING_N   = 11        -- ring emitters stacked up the column
        local DEV_H    = 25        -- column height (studs)
        local DEV_R    = 9.5       -- crown radius; the foot is 15% of it
        local DEV_LIFE = 14        -- total event: climb + sustain + release + drain
        local DEV_HOLD = 9.6       -- sustain ends / release begins
        local DEV_DOWN = Vec(0, -80, 0)
        local RELEASE  = Vec(-8, -3.5, 3)
        -- species palette, cycled up the stack: gold and straw glow, the rest stay silhouettes
        local RING_TEX  = { TX_LEAFA, TX_LEAFB, TX_LEAFA, TX_LEAFB, TX_LEAFC }
        local RING_GLOW = { 0.62, 0.07, 0.6, 0.08, 0.1 }
        local RING_COL  = {
            ColorSequence.new({ CSK(0, Color3.fromRGB(226,190,128)), CSK(0.45, Color3.fromRGB(255,246,200)),
                                CSK(1, Color3.fromRGB(190,132,62)) }),
            ColorSequence.new({ CSK(0, Color3.fromRGB(160,80,52)), CSK(1, Color3.fromRGB(104,44,30)) }),
            ColorSequence.new({ CSK(0, Color3.fromRGB(230,222,176)), CSK(0.5, Color3.fromRGB(255,254,228)),
                                CSK(1, Color3.fromRGB(200,180,122)) }),
            ColorSequence.new({ CSK(0, Color3.fromRGB(156,74,255)), CSK(1, Color3.fromRGB(106,46,200)) }),
            ColorSequence.new({ CSK(0, Color3.fromRGB(196,156,112)), CSK(1, Color3.fromRGB(146,110,74)) }),
        }
        local RING_SIZE = NumberSequence.new({ NSK(0, 0.56, 0.14), NSK(1, 0.46, 0.1) })
        local RING_TR   = NumberSequence.new({ NSK(0, 1), NSK(0.07, 0.05), NSK(0.78, 0.4), NSK(1, 1) })
        local RING_SQ   = NumberSequence.new({ NSK(0, -0.6), NSK(0.25, 0.16), NSK(0.5, -0.6),
                                               NSK(0.75, 0.16), NSK(1, -0.6) })
        local SKIRT_SIZE = NumberSequence.new({ NSK(0, 1.5), NSK(1, 4.4) })
        local SKIRT_TR   = NumberSequence.new({ NSK(0, 1), NSK(0.22, 0.82), NSK(0.75, 0.92), NSK(1, 1) })
        local LEAF_SIZE  = NumberSequence.new({ NSK(0, 0.52, 0.12), NSK(1, 0.44, 0.1) })
        local LEAF_TR    = NumberSequence.new({ NSK(0, 1), NSK(0.1, 0.08), NSK(0.75, 0.42), NSK(1, 1) })
        local DUCK_TI = TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
        local BACK_TI = TweenInfo.new(2.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
        local _dev = { folder = nil, conn = nil }
        local _devRp = RaycastParams.new()
        _devRp.FilterType = Enum.RaycastFilterType.Exclude

        -- ambient duck/restore: untagged layers only (the carpet and the event-driven layers keep
        -- their own rates). Same rateTween precedence as the gust surge.
        local function ambientRate(mul, ti)
            local I = iAmt()
            for _, L in _partLayers do
                if L.emitter and L.tag == nil then
                    if L.rateTween then L.rateTween:Cancel() end
                    L.rateMul = mul
                    local tw = TweenService:Create(L.emitter, ti, { Rate = layerRate(L, I) * mul })
                    L.rateTween = tw
                    tw:Play()
                end
            end
        end

        stopLeafDevil = function()
            if _dev.conn then _dev.conn:Disconnect(); _dev.conn = nil end
            if _dev.folder then pcall(function() _dev.folder:Destroy() end); _dev.folder = nil end
            if _dev.rings then   -- flag: an ambient duck is still in effect
                _dev.rings = nil
                ambientRate(1, BACK_TI)
            end
        end

        -- one orbiting ring emitter. EmissionDirection = Front so leaves inherit the orbit
        -- tangent the update loop aims the part along.
        local function mkRing(folder, cf, i, r)
            local p = mkBoltPart(WHITE, 1, Vec(0.3, 0.3, 0.3), cf, folder)
            local k = ((i - 1) % 5) + 1
            local glow = RING_GLOW[k]
            local e = Instance.new("ParticleEmitter")
            e:SetAttribute("WX_Custom", true)
            e.Texture = RING_TEX[k]
            e.Color = RING_COL[k]
            e.LightEmission = glow; e.LightInfluence = 1 - glow
            e.Size = RING_SIZE; e.Transparency = RING_TR; e.Squash = RING_SQ
            e.Rate = 0
            e.Lifetime = NumberRange.new(2, 3)
            e.Speed = NumberRange.new(5, 9)
            e.SpreadAngle = Vector2.new(8, 8)
            e.Rotation = NumberRange.new(-180, 180)
            e.RotSpeed = NumberRange.new(-300, 300)
            e.Acceleration = Vec(0, 2.6, 0)
            e.Drag = 1.4
            e.EmissionDirection = ND.Front
            e.Parent = p
            return { part = p, e = e, r = r }
        end

        registerSpectacle("LeafDevil", 1, function()
            if not Config.Weather or _curType ~= "Autumn" or _dev.conn then return end
            local cam = Camera; if not cam then return end
            local camPos = cam.CFrame.Position
            local bearing = math.random() * 6.283
            local dist = 18 + math.random() * 12
            local cx = camPos.X + math.cos(bearing) * dist
            local cz = camPos.Z + math.sin(bearing) * dist
            local ch = lp and lp.Character
            if ch then
                _devRp.FilterDescendantsInstances = { getFolder(), ch }
            else
                _devRp.FilterDescendantsInstances = { getFolder() }
            end
            local hit = Workspace:Raycast(Vec(cx, camPos.Y + 6, cz), DEV_DOWN, _devRp)
            local gy = camPos.Y - 4.6
            if hit then gy = hit.Position.Y end

            local folder = Instance.new("Folder")
            folder.Name = "_wxDevil"; folder:SetAttribute("WX_Custom", true)
            folder.Parent = getFolder()
            _dev.folder = folder

            -- the column's own density rides the slider like the ambient fall does
            local em = iRate(iAmt(), IR.Autumn.lo, IR.Autumn.hi)
            local seed = CFrame.new(cx, gy + 1, cz)
            local rings = table.create(RING_N)
            for i = 1, RING_N do
                local h = 0.8 + (i - 1) * (DEV_H - 0.8) / (RING_N - 1)
                local u = h / DEV_H
                local r = DEV_R * (0.15 + 0.85 * u ^ 0.9)
                if u > 0.72 then r = r * (1 + (u - 0.72) * 1.5) end
                local R = mkRing(folder, seed, i, r)
                R.h = h
                R.ph = (i - 1) * 0.62          -- helix twist up the stack
                R.t0 = 0.12 * (i - 1)          -- bottom-up spin-up
                R.rate = (10 + 34 * (r / DEV_R)) * em   -- rate follows ring circumference
                rings[i] = R
            end
            _dev.rings = rings

            local foot = mkBoltPart(WHITE, 1, Vec(6.5, 0.4, 6.5), CFrame.new(cx, gy + 0.35, cz), folder)
            local leafSkirt = Instance.new("ParticleEmitter")
            leafSkirt:SetAttribute("WX_Custom", true)
            leafSkirt.Texture = TX_LEAFA
            leafSkirt.Color = RING_COL[1]
            leafSkirt.LightEmission = 0.3; leafSkirt.LightInfluence = 0.7
            leafSkirt.Size = LEAF_SIZE; leafSkirt.Transparency = LEAF_TR; leafSkirt.Squash = RING_SQ
            leafSkirt.Rate = 0
            leafSkirt.Lifetime = NumberRange.new(1.2, 2.2)
            leafSkirt.Speed = NumberRange.new(2, 5)
            leafSkirt.SpreadAngle = Vector2.new(70, 70)
            leafSkirt.Rotation = NumberRange.new(-180, 180)
            leafSkirt.RotSpeed = NumberRange.new(-260, 260)
            leafSkirt.Acceleration = Vec(0, 1.2, 0)
            leafSkirt.Drag = 2.2
            leafSkirt.EmissionDirection = ND.Top
            leafSkirt.Parent = foot
            local dustSkirt = Instance.new("ParticleEmitter")
            dustSkirt:SetAttribute("WX_Custom", true)
            dustSkirt.Texture = TX_DUST
            dustSkirt.Color = ColorSequence.new(Color3.fromRGB(190,166,130), Color3.fromRGB(140,118,90))
            dustSkirt.LightEmission = 0.04; dustSkirt.LightInfluence = 0.96
            dustSkirt.Size = SKIRT_SIZE; dustSkirt.Transparency = SKIRT_TR
            dustSkirt.Rate = 0
            dustSkirt.Lifetime = NumberRange.new(0.9, 1.4)
            dustSkirt.Speed = NumberRange.new(1, 2.6)
            dustSkirt.SpreadAngle = Vector2.new(85, 85)
            dustSkirt.RotSpeed = NumberRange.new(-25, 25)
            dustSkirt.Acceleration = Vec(0, 1, 0)
            dustSkirt.Drag = 2.4
            dustSkirt.EmissionDirection = ND.Top
            dustSkirt.Parent = foot
            local scuff = mkBoltPart(WHITE, 1, Vec(15, 0.08, 15), CFrame.new(cx, gy + 0.05, cz), folder)
            scuff.Material = Enum.Material.SmoothPlastic   -- Neon would bloom the scuff decal
            local sd = Instance.new("Decal")
            sd:SetAttribute("WX_Custom", true)
            sd.Face = ND.Top; sd.Texture = TX_DUST
            sd.Color3 = Color3.fromRGB(96, 74, 52); sd.Transparency = 0.55
            sd.Parent = scuff

            ambientRate(0.45, DUCK_TI)

            local t0 = tick()
            local ang, px, pz = 0, cx, cz
            local lean = math.random() * 6.283
            _dev.conn = RunService.Heartbeat:Connect(function(dt)
                if not folder.Parent then stopLeafDevil() return end
                local t = tick() - t0
                if t > DEV_LIFE then stopLeafDevil() return end
                ang = ang + dt * 2.7               -- slow enough that the orbit sweep is READ, not blurred
                px = px + Wind.x * dt * 0.75       -- the devil wanders downwind
                pz = pz + Wind.z * dt * 0.75
                -- a slow lean on a wander: a perfectly vertical column reads as fire
                local lx = math.cos(lean + t * 0.21) * 0.13
                local lz = math.sin(lean + t * 0.17) * 0.13
                local climb = math.min(t / 1.5, 1)
                local release = t > DEV_HOLD
                for i = 1, RING_N do
                    local R = rings[i]
                    local h = R.h * climb
                    local th = ang + R.ph
                    local cs, sn = math.cos(th), math.sin(th)
                    local r = R.r * (0.55 + 0.45 * climb)
                    local p = Vec(px + lx * h + cs * r, gy + 0.35 + h, pz + lz * h + sn * r)
                    R.part.CFrame = CFrame.lookAt(p, p + Vec(-sn, 0.3, cs))
                    if release then
                        R.e.Rate = 0
                        R.e.Acceleration = RELEASE
                    else
                        R.e.Rate = R.rate * math.clamp((t - R.t0) / 0.6, 0, 1)
                    end
                end
                foot.CFrame = CFrame.new(px, gy + 0.35, pz)
                scuff.CFrame = CFrame.new(px, gy + 0.05, pz) * CFrame.Angles(0, t * 0.35, 0)
                if release then
                    leafSkirt.Rate = 0
                    dustSkirt.Rate = 0
                    leafSkirt.Acceleration = RELEASE
                    sd.Transparency = math.min(0.55 + (t - DEV_HOLD) * 0.35, 1)
                    if t > DEV_HOLD + 0.1 and _dev.rings then
                        _dev.rings = nil
                        ambientRate(1, BACK_TI)
                    end
                else
                    local k = math.min(t / 0.8, 1)
                    leafSkirt.Rate = 26 * em * k
                    dustSkirt.Rate = 15 * em * k
                    sd.Transparency = 0.95 - 0.4 * math.min(t / 1.2, 1)
                end
            end)
        end)
    end)()

    -- ════════════════════════════════════════════════════════════════════════
    -- INTERACTIVE PUDDLES (WeatherPuddles) — standing water that reacts to the
    -- players walking through it. Dark slate tint at LOW Reflectance reads as wet
    -- ground — Roblox Reflectance mirrors only the skybox, so pushing it any
    -- higher just makes an ice rink.
    -- THE FIELD IS A PARTITION, NOT A SCATTER. Water lives on a fixed world grid of
    -- CELL-sized cells and EVERY water surface is contained inside the one cell (or
    -- sub-cell) that owns it. Cells are disjoint, so two water pieces can never
    -- intersect — that is a geometric guarantee, not a spacing heuristic. It matters
    -- because the slabs are translucent: two that OVERLAP composite to roughly double
    -- opacity and read as a dark blotch, while two that merely ABUT read as one sheet.
    -- A smooth noise field over world XZ decides each cell: above the intensity
    -- threshold = water, and the threshold sweeps from "a few isolated cells" at 0.15
    -- to BELOW the noise minimum at 2.0, where every cell floods and the floor is
    -- solid water. A cell whose four neighbours are all water is INTERIOR: it tiles
    -- its area with a 2×2 of rectangular slabs that abut edge-to-edge at one shared
    -- Y — no stacking, no seam. Any other water cell is the SHORELINE and gets the
    -- organic pool (one elongated base slab plus 4-5 rotated lobes on a random spine,
    -- two sheen patches), so the flood never ends on a straight line. Intensity moves
    -- how MUCH of the floor floods, never how much water stacks. Slider moves
    -- re-decide cells ONCE, debounced (`puddlesIntensity`), never per tick; the grid
    -- itself never moves, so a drag grows and shrinks the flood instead of rebuilding.
    -- OVERHANG RULE (general, no map tuning): no part of a puddle may extend past
    -- the surface it rests on. Every slab is fitted independently against the ground
    -- by its own RIM (fitSlab for lobes, fitRect for tiles) and is shrunk, slid or
    -- dropped on its own, so the outline hugs a ledge instead of the whole pool being
    -- accepted or thrown away. Tiles may only SHRINK about their sub-cell centre —
    -- never slide — which is what keeps containment true after a trim.
    -- Ambient rain rings per puddle: VelocityPerpendicular + EmissionDirection
    -- Top + a hair of Speed makes the ring texture lie FLAT and expand. The emitter
    -- host is clipped to the surviving footprint so rings never spray over the drop.
    -- INTERACTION is triggered VFX, no fluid sim: a 20Hz loop reads nearby
    -- characters through the swappable `actorsProvider` seam (shipped = real
    -- players, a Studio rig swaps in a dummy and exercises the SAME detection
    -- and splash code), detects a grounded footfall inside a puddle's ellipse
    -- union under a per-character stride throttle, and fires a POOLED splash at
    -- the contact point — flat expanding ring + white foam streaks + droplets
    -- arcing up and falling back under gravity, all scaled by move speed; a hard
    -- landing crowns at full scale; leaving the water drops fading wet
    -- footprints. Nothing is created per footstep. Active while type == Rain or
    -- Storm is on; type switch fades out, disable/unload tears down hard.
    -- Nested IIFE keeps ~45 locals off the weather proto budget.
    -- ════════════════════════════════════════════════════════════════════════
    local puddlesRefresh, puddlesIntensity, stopPuddles
    ;(function()
        local TXP_RING = "rbxassetid://17738857765"   -- thin circle outline (TX kit ripple)
        local TXP_DROP = "rbxassetid://14964503448"   -- glassy teardrop (TX kit droplet)
        local TXP_STAR = "rbxassetid://17726943419"   -- 4-point star (rain-hit glints)
        local WATER_C  = Color3.fromRGB(22, 28, 37)
        local SHEEN_C  = Color3.fromRGB(150, 175, 205)
        local FOAM_C   = Color3.fromRGB(236, 246, 255)
        local PUD_DOWN = Vec(0, -90, 0)
        local FIT_DOWN = Vec(0, -4.2, 0)              -- rim probe: just outreaches FIT_TOL
        local HALF_PI  = 1.5707963
        local FIT_TOL  = 1.5                          -- off the water plane by this = a drop
        local FIT_R    = 1.09                         -- rim probes sit 9% PAST the water: the
        -- 8-sample octagon's incircle is then 1.09*cos(22.5°) = 1.007 of the rim, so a
        -- straight ledge that cuts the pool anywhere is always caught between samples
        -- shrink ladder; the last rung is what lets a narrow walkway or a crate top
        -- carry a thin ribbon of water instead of staying bone dry
        local FIT_K    = { 1, 0.66, 0.44, 0.28 }
        local FIT_C = {                               -- 8 rim directions, cos/sin interleaved
            1, 0, 0.70711, 0.70711, 0, 1, -0.70711, 0.70711,
            -1, 0, -0.70711, -0.70711, 0, -1, 0.70711, -0.70711,
        }
        local FIT_Q = {                               -- 12 rect-rim points: 4 corners + 2 per edge
            1, 1, 0.333, 1, -0.333, 1, -1, 1,
            -1, 0.333, -1, -0.333, -1, -1, -0.333, -1,
            0.333, -1, 1, -1, 1, -0.333, 1, 0.333,
        }
        local CELL     = 32                           -- flood-grid pitch; also the pool spacing
        local HALF     = 16                           -- CELL/2: containment limit AND sub-cell side
        local NOISE_F  = 0.018                        -- ~55-stud flood regions (2-3 cells across)
        local POOL_F   = 0.74                         -- shoreline pool span as a fraction of CELL
        local TILE_K   = 1 / 470                      -- tile ring rate per stud², matched to pools
        local K_CAP    = 48                           -- aggregate ring/glint budget over the field
        local MAX_REC  = 96                           -- hard ceiling on live water pieces
        local _pud = { folder = nil, conn = nil }
        local _plist = {}                             -- puddle records (see mkPuddle/mkFloodCell)
        local _pmap = {}                              -- cell key → record, so a cell is placed once
        local _pfail = {}                             -- cell key → true: no ground here, stop retrying
        -- one reused cell descriptor: keeps the constructors at 4 args and allocates nothing
        local _cd = { i = 0, j = 0, key = 0, kind = 0, cx = 0, cz = 0, gy = 0 }
        local _units, _uIdx = {}, 1                   -- splash pool
        local _prints, _pIdx = {}, 1                  -- wet-footprint pool
        local _pstates = {}                           -- per-actor stride/wet/fall state
        local _abuf = {}                              -- pooled actor records, zero alloc per tick
        local _prp = RaycastParams.new()
        _prp.FilterType = Enum.RaycastFilterType.Exclude
        local _pfilter = {}                           -- reused raycast filter list
        local _fieldToken, _rebuild = 0, false
        local _int, _thr, _placeR, _seed = 1, 0, 50, 0   -- field params, frozen between rebuilds
        local _wTr, _wRf = 0.35, 0.16                 -- water look, deepens with intensity
        local _homeI, _homeJ = 1e9, 1e9               -- player's cell, drives the _pfail flush

        local function pudActive()
            if not Config.Weather or not cfg("WeatherPuddles", false) then
                return false
            end
            if _curType == "Rain" then
                return true
            end
            return cfg("WeatherStorm", false)
        end
        local function pudIntensity()
            return iAmt()
        end

        local function mkFlatPart(size, cf, parent)
            local p = Instance.new("Part")
            p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
            p.CastShadow = false; p.Transparency = 1
            p.Size = size; p.CFrame = cf
            p:SetAttribute("WX_Custom", true)
            p.Parent = parent
            return p
        end
        -- one flat elliptical water lobe; sheen slabs are the surface-variation glints
        local function mkSlab(d1, d2, cf, parent, sheen)
            local p = Instance.new("Part")
            p.Shape = Enum.PartType.Cylinder
            p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
            p.CastShadow = false; p.Material = Enum.Material.SmoothPlastic
            if sheen then
                p.Color = SHEEN_C; p.Transparency = 0.74; p.Reflectance = 0.38
            else
                p.Color = WATER_C; p.Transparency = _wTr; p.Reflectance = _wRf
                p:SetAttribute("WX_W", true)   -- water proper: retinted on an intensity change
            end
            p.Size = Vec(0.05, d1, d2)
            p.CFrame = cf
            p:SetAttribute("WX_Custom", true)
            p.Parent = parent
        end
        -- flooded-interior tile: the SAME water look as a lobe on a square footprint,
        -- because only squares tile a plane edge-to-edge without stacking
        local function mkTile(w, l, cf, parent)
            local p = Instance.new("Part")
            p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
            p.CastShadow = false; p.Material = Enum.Material.SmoothPlastic
            p.Color = WATER_C; p.Transparency = _wTr; p.Reflectance = _wRf
            p.Size = Vec(w, 0.05, l)
            p.CFrame = cf
            p:SetAttribute("WX_Custom", true)
            p:SetAttribute("WX_W", true)
            p.Parent = parent
        end

        -- FOOTPRINT FIT — the overhang rule. A slab may only exist where the ground
        -- actually holds it, so sample the slab's RIM: 8 points ON the ellipse
        -- boundary, which is exactly what hangs off a ledge (interior probes can never
        -- see it). A sample is supported only over near-vertical collidable ground
        -- within FIT_TOL of the water plane — a hit far below is a drop-off, no hit at
        -- all is a void or the inside of a prop. If any rim sample fails, shrink and
        -- slide toward the centroid of the supported ones and retest; if the ladder
        -- runs out the caller drops that slab and the pool simply ends at the ledge.
        -- Bounded at 32 short rays per slab, placement-time only.
        local function fitSlab(cx, cz, d1, d2, yaw, gy)
            local cs, sn = math.cos(yaw), math.sin(yaw)
            for k = 1, 4 do
                local f = FIT_K[k] * FIT_R * 0.5
                local a, b = d1 * f, d2 * f
                local ok, gx, gz, n = true, 0, 0, 0
                for i = 1, 8 do
                    local ct, st = FIT_C[i * 2 - 1], FIT_C[i * 2]
                    local ox = sn * b * st - cs * a * ct
                    local oz = sn * a * ct + cs * b * st
                    local h = Workspace:Raycast(Vec(cx + ox, gy + 2, cz + oz), FIT_DOWN, _prp)
                    local sup = false
                    if h and h.Normal.Y >= 0.86 and h.Instance.CanCollide then
                        local dy = h.Position.Y - gy
                        sup = dy < FIT_TOL and dy > -FIT_TOL
                    end
                    if sup then
                        gx, gz, n = gx + ox, gz + oz, n + 1
                    else
                        ok = false
                    end
                end
                if ok then
                    return cx, cz, d1 * FIT_K[k], d2 * FIT_K[k]
                end
                if n == 0 then
                    return nil
                end
                cx, cz = cx + gx / n * 0.5, cz + gz / n * 0.5
            end
            return nil
        end

        -- TILE FIT — the same overhang rule for a square footprint, sampled at 12 rim
        -- points (corners plus thirds, so an 8-stud-wide ledge cannot slip between two
        -- samples of a 16-stud tile). A tile may only SHRINK about its own centre: any
        -- slide would let it cross into the neighbouring sub-cell and stack, and the
        -- no-overlap guarantee is worth more than the last few studs of a trimmed edge.
        local function fitRect(cx, cz, w, l, gy)
            for k = 1, 4 do
                local f = FIT_K[k] * FIT_R * 0.5
                local a, b = w * f, l * f
                local ok = true
                for i = 1, 12 do
                    local h = Workspace:Raycast(
                        Vec(cx + FIT_Q[i * 2 - 1] * a, gy + 2, cz + FIT_Q[i * 2] * b), FIT_DOWN, _prp)
                    local sup = false
                    if h and h.Normal.Y >= 0.86 and h.Instance.CanCollide then
                        local dy = h.Position.Y - gy
                        sup = dy < FIT_TOL and dy > -FIT_TOL
                    end
                    if not sup then
                        ok = false
                        break
                    end
                end
                if ok then
                    return w * FIT_K[k], l * FIT_K[k]
                end
            end
            return nil
        end

        -- ambient rain rings + glints for one water piece. The host is clipped to the
        -- footprint that SURVIVED the fit, so nothing sprays over a trimmed edge, and
        -- the rate rides `k` (area-scaled) so density per stud² is constant everywhere.
        local function mkHost(m, cf, size, k, I)
            local host = mkFlatPart(size, cf, m)
            local e = Instance.new("ParticleEmitter")
            e:SetAttribute("WX_Custom", true)
            e.Texture = TXP_RING
            e.Orientation = Enum.ParticleOrientation.VelocityPerpendicular
            e.EmissionDirection = Enum.NormalId.Top
            e.Speed = NumberRange.new(0.05, 0.05)
            e.Rate = (2.1 + 4.2 * I) * k
            e.Lifetime = NumberRange.new(1.1, 1.6)
            e.Size = NumberSequence.new({ NSK(0, 0.12), NSK(1, 4.4) })
            e.Transparency = NumberSequence.new({ NSK(0, 0.9), NSK(0.14, 0.12), NSK(0.62, 0.5), NSK(1, 1) })
            e.Color = ColorSequence.new(Color3.fromRGB(215, 234, 250))
            e.LightEmission = 0.45
            e.Parent = host
            local g = Instance.new("ParticleEmitter")
            g:SetAttribute("WX_Custom", true)
            g.Texture = TXP_STAR
            g.EmissionDirection = Enum.NormalId.Top
            g.Speed = NumberRange.new(0, 0)
            g.Rate = 0.8 * I * k
            g.Lifetime = NumberRange.new(0.16, 0.28)
            g.Size = NumberSequence.new({ NSK(0, 0.06), NSK(0.4, 0.3), NSK(1, 0.04) })
            g.Transparency = NumberSequence.new({ NSK(0, 0.6), NSK(1, 1) })
            g.Color = ColorSequence.new(Color3.fromRGB(240, 248, 255))
            g.LightEmission = 0.5
            g.Parent = host
            return e, g
        end

        -- SHORELINE POOL — one cell's worth of water where the flood ends: the
        -- elongated base slab plus lobes and sheen patches, i.e. exactly the pool a
        -- lone puddle has always been. The only new rule is CONTAINMENT: the pool is
        -- anchored in its cell and any piece that would reach past the cell edge is
        -- dropped rather than trimmed inwards, so it can never touch a neighbour's water.
        local function mkPuddle(cd, span, nslab, I)
            local x, z, gy = cd.cx, cd.cz, cd.gy
            local m = Instance.new("Model")
            m.Name = "_pud"
            -- anchor jittered off the cell centre so a sparse field never reads as a lattice
            local px = x + (math.random() - 0.5) * CELL * 0.16
            local pz = z + (math.random() - 0.5) * CELL * 0.16
            -- lobes strung along one spine → an elongated organic pool, not a rosette
            local spine = math.random() * 6.28318
            local sx, sz = math.cos(spine), math.sin(spine)
            local lx, lz = -sz, sx
            local yaw0 = math.pi - spine   -- puts the slab's d1 axis ON the spine
            local slabs, rmax = {}, 0
            -- ring-host extent, in the spine frame, of the slabs that SURVIVED the fit
            local s0, s1, l0, l1 = 1e9, -1e9, 1e9, -1e9
            local function place(cx, cz, d1, d2, yaw, yoff, sheen)
                local fx, fz, fd1, fd2 = fitSlab(cx, cz, d1, d2, yaw, gy)
                if not fx then
                    return false
                end
                -- bounding circle vs the cell square: holds for any yaw and after any
                -- fit slide, and it is measured from the CELL centre, not the anchor
                local rad = math.max(fd1, fd2) * 0.5
                local ex, ez = fx - x, fz - z
                if math.abs(ex) + rad > HALF or math.abs(ez) + rad > HALF then
                    return false
                end
                mkSlab(fd1, fd2, CFrame.new(fx, gy + yoff, fz)
                    * CFrame.Angles(0, yaw, 0) * CFrame.Angles(0, 0, HALF_PI), m, sheen)
                if not sheen then   -- sheen glints are decoration, not part of the water union
                    slabs[#slabs + 1] = {
                        cx = fx, cz = fz,
                        cs = math.cos(yaw), sn = math.sin(yaw),
                        ia = 2 / fd1, ib = 2 / fd2, rect = false,
                    }
                    rmax = math.max(rmax, math.sqrt(ex * ex + ez * ez) + rad)
                end
                local dx, dz = fx - px, fz - pz
                local t, lat = dx * sx + dz * sz, dx * lx + dz * lz
                local ins = math.min(fd1, fd2) * 0.375   -- keep rings INSIDE the water
                s0, s1 = math.min(s0, t - ins), math.max(s1, t + ins)
                l0, l1 = math.min(l0, lat - ins), math.max(l1, lat + ins)
                return true
            end
            -- base first: a spot that cannot hold even a shrunk base is a bad spot, and
            -- bailing here keeps a rejected candidate at ≤32 rays instead of ~250
            if not place(px, pz, span, span * 0.62, yaw0, 0.002, false) then
                m:Destroy()
                return false
            end
            for i = 1, nslab do
                local t = ((i - 0.5) / nslab - 0.5) * span * 0.62 + (math.random() - 0.5) * span * 0.14
                local lat = (math.random() - 0.5) * span * 0.24
                local d1 = span * (0.34 + math.random() * 0.3)
                -- stacked micro-offsets: never coplanar with the floor or each other
                place(px + sx * t + lx * lat, pz + sz * t + lz * lat,
                    d1, d1 * (0.6 + math.random() * 0.34),
                    yaw0 + (math.random() - 0.5) * 1.6, 0.008 + i * 0.004, false)
            end
            for _ = 1, 2 do
                local t = (math.random() - 0.5) * span * 0.5
                local lat = (math.random() - 0.5) * span * 0.16
                local d1 = span * (0.14 + math.random() * 0.18)
                place(px + sx * t + lx * lat, pz + sz * t + lz * lat,
                    d1, d1 * (0.4 + math.random() * 0.35), math.random() * math.pi, 0.036, true)
            end
            -- host = the approved rect CLIPPED to what survived, so flat ground is
            -- pixel-identical and a trimmed pool never sprays rings over the drop
            s0, s1 = math.max(s0, span * -0.425), math.min(s1, span * 0.425)
            l0, l1 = math.max(l0, span * -0.225), math.min(l1, span * 0.225)
            local hw, hl = math.max(s1 - s0, 1), math.max(l1 - l0, 1)
            local hm, hn = (s0 + s1) * 0.5, (l0 + l1) * 0.5
            -- ring/glint rate follows the surviving AREA (ratio 1 on open ground)
            local k = (span / 26) ^ 1.5 * hw * hl / (span * span * 0.3825)
            local e, g = mkHost(m, CFrame.new(px + sx * hm + lx * hn, gy + 0.1, pz + sz * hm + lz * hn)
                * CFrame.Angles(0, -spine, 0), Vec(hw, 0.05, hl), k, I)
            m.Parent = _pud.folder
            local P = {
                cx = x, cz = z, top = gy + 0.06, r2 = rmax * rmax, k = k,
                key = cd.key, ci = cd.i, cj = cd.j, kind = cd.kind,
                slabs = slabs, ring = e, glint = g, model = m,
            }
            _plist[#_plist + 1] = P
            _pmap[cd.key] = P
            return true
        end

        -- FLOODED INTERIOR — a cell with water on all four sides, so nothing here needs
        -- an organic outline: it just has to be WATER, edge to edge, with no stacking.
        -- The cell is split 2×2 and each sub-cell gets one tile fitted inside itself.
        -- Every tile shares one Y, one colour and one transparency, so abutting tiles
        -- are literally indistinguishable from a single sheet — and because each is
        -- confined to its own sub-cell they abut and never intersect.
        local function mkFloodCell(cd, I)
            local gy = cd.gy
            local m = Instance.new("Model")
            m.Name = "_pud"
            local slabs = {}
            local area, rmax = 0, 0
            local x0, x1, z0, z1 = 1e9, -1e9, 1e9, -1e9
            for a = 0, 1 do
                for b = 0, 1 do
                    local scx = cd.cx + (a - 0.5) * HALF
                    local scz = cd.cz + (b - 0.5) * HALF
                    local fw, fl = fitRect(scx, scz, HALF, HALF, gy)
                    if fw then
                        mkTile(fw, fl, CFrame.new(scx, gy + 0.002, scz), m)
                        slabs[#slabs + 1] = {
                            cx = scx, cz = scz, cs = 1, sn = 0,
                            ia = 2 / fw, ib = 2 / fl, rect = true,
                        }
                        area = area + fw * fl
                        rmax = math.max(rmax, 0.7072 * (HALF + fw))
                        x0 = math.min(x0, scx - fw * 0.5)
                        x1 = math.max(x1, scx + fw * 0.5)
                        z0 = math.min(z0, scz - fl * 0.5)
                        z1 = math.max(z1, scz + fl * 0.5)
                    end
                end
            end
            if area <= 0 then
                m:Destroy()
                return false
            end
            -- one sheen patch on some UNTRIMMED cells: it is BRIGHT over dark water, so
            -- the pair composites lighter and reads as a glint, never as the dark blotch
            -- two stacked water slabs would make. Skipped on a trimmed cell, where it
            -- could land on the dry part. Fitted and contained like everything else.
            if area > CELL * CELL * 0.98 and math.random() < 0.45 then
                local d1 = CELL * (0.15 + math.random() * 0.1)
                local sx = cd.cx + (math.random() - 0.5) * CELL * 0.4
                local sz = cd.cz + (math.random() - 0.5) * CELL * 0.4
                local yaw = math.random() * math.pi
                local fx, fz, fd1, fd2 = fitSlab(sx, sz, d1, d1 * (0.4 + math.random() * 0.35), yaw, gy)
                if fx and math.abs(fx - cd.cx) + fd1 * 0.5 < HALF
                    and math.abs(fz - cd.cz) + fd1 * 0.5 < HALF then
                    mkSlab(fd1, fd2, CFrame.new(fx, gy + 0.036, fz)
                        * CFrame.Angles(0, yaw, 0) * CFrame.Angles(0, 0, HALF_PI), m, true)
                end
            end
            local hw, hl = math.max(x1 - x0, 1), math.max(z1 - z0, 1)
            local e, g = mkHost(m, CFrame.new((x0 + x1) * 0.5, gy + 0.1, (z0 + z1) * 0.5),
                Vec(hw, 0.05, hl), area * TILE_K, I)
            m.Parent = _pud.folder
            local P = {
                cx = cd.cx, cz = cd.cz, top = gy + 0.06, r2 = rmax * rmax, k = area * TILE_K,
                key = cd.key, ci = cd.i, cj = cd.j, kind = cd.kind,
                slabs = slabs, ring = e, glint = g, model = m,
            }
            _plist[#_plist + 1] = P
            _pmap[cd.key] = P
            return true
        end

        local function mkSplashUnit(parent)
            local p = mkFlatPart(Vec(1.1, 0.1, 1.1), CFrame.new(0, -900, 0), parent)
            local ring = Instance.new("ParticleEmitter")
            ring:SetAttribute("WX_Custom", true)
            ring.Texture = TXP_RING
            ring.Orientation = Enum.ParticleOrientation.VelocityPerpendicular
            ring.EmissionDirection = Enum.NormalId.Top
            ring.Speed = NumberRange.new(0.05, 0.05)
            ring.Rate = 0
            ring.Lifetime = NumberRange.new(0.45, 0.7)
            ring.Size = NumberSequence.new({ NSK(0, 0.1), NSK(1, 4) })
            ring.Transparency = NumberSequence.new({ NSK(0, 0.75), NSK(0.1, 0.05), NSK(0.5, 0.4), NSK(1, 1) })
            ring.Color = ColorSequence.new(Color3.fromRGB(230, 244, 255))
            ring.LightEmission = 0.5
            ring.Parent = p
            -- foam = the white water torn off the surface; the streak read comes from
            -- VelocityParallel + Squash, and the arc from the downward Acceleration
            local foam = Instance.new("ParticleEmitter")
            foam:SetAttribute("WX_Custom", true)
            foam.Texture = TX_SNOWSOFT
            foam.Orientation = Enum.ParticleOrientation.VelocityParallel
            foam.EmissionDirection = Enum.NormalId.Top
            foam.Rate = 0
            foam.SpreadAngle = Vector2.new(56, 56)
            foam.Acceleration = Vec(0, -80, 0)
            foam.Lifetime = NumberRange.new(0.3, 0.6)
            foam.Size = NumberSequence.new({ NSK(0, 0.6, 0.22), NSK(1, 0.2) })
            foam.Squash = NumberSequence.new({ NSK(0, 1.5), NSK(1, 0.4) })
            foam.Speed = NumberRange.new(6, 12)
            foam.Color = ColorSequence.new(FOAM_C)
            foam.Transparency = NumberSequence.new({ NSK(0, 0.18), NSK(0.7, 0.45), NSK(1, 1) })
            foam.LightEmission = 0.18
            foam.Parent = p
            local drops = Instance.new("ParticleEmitter")
            drops:SetAttribute("WX_Custom", true)
            drops.Texture = TXP_DROP
            drops.Orientation = Enum.ParticleOrientation.VelocityParallel
            drops.EmissionDirection = Enum.NormalId.Top
            drops.Rate = 0
            drops.SpreadAngle = Vector2.new(52, 52)
            drops.Acceleration = Vec(0, -80, 0)
            drops.Lifetime = NumberRange.new(0.32, 0.62)
            drops.Size = NumberSequence.new({ NSK(0, 0.55, 0.18), NSK(1, 0.28) })
            drops.Speed = NumberRange.new(6, 12)
            drops.Color = ColorSequence.new(Color3.fromRGB(210, 232, 250))
            drops.Transparency = NumberSequence.new({ NSK(0, 0.1), NSK(0.75, 0.3), NSK(1, 1) })
            drops.LightEmission = 0.25
            drops.Parent = p
            local mist = Instance.new("ParticleEmitter")
            mist:SetAttribute("WX_Custom", true)
            mist.Texture = TX_SNOWSOFT
            mist.EmissionDirection = Enum.NormalId.Top
            mist.Rate = 0
            mist.Speed = NumberRange.new(1.2, 2.8)
            mist.SpreadAngle = Vector2.new(48, 48)
            mist.Lifetime = NumberRange.new(0.3, 0.5)
            mist.Size = NumberSequence.new({ NSK(0, 0.5), NSK(1, 1.6) })
            mist.Transparency = NumberSequence.new({ NSK(0, 0.75), NSK(1, 1) })
            mist.Color = ColorSequence.new(FOAM_C)
            mist.LightEmission = 0.1
            mist.Parent = p
            return { part = p, ring = ring, foam = foam, drops = drops, mist = mist }
        end

        local function fireSplash(x, y, z, speed)
            local u = _units[_uIdx]
            if not u then
                return
            end
            _uIdx = (_uIdx % #_units) + 1
            local s = math.clamp(speed, 4, 36)
            u.part.CFrame = CFrame.new(x, y + 0.12, z)
            u.ring.Size = NumberSequence.new({ NSK(0, 0.1), NSK(1, 3.2 + s * 0.18) })
            local lo, hi = 5 + s * 0.38, 8 + s * 0.6
            u.foam.Speed = NumberRange.new(lo, hi)
            u.drops.Speed = NumberRange.new(lo * 0.8, hi * 0.9)
            u.ring:Emit(2)
            u.foam:Emit(9 + math.floor(s * 0.75))
            u.drops:Emit(4 + math.floor(s * 0.3))
            u.mist:Emit(3)
        end
        local function dropPrint(x, y, z, heading, side)
            local p = _prints[_pIdx]
            if not p then
                return
            end
            _pIdx = (_pIdx % #_prints) + 1
            p.CFrame = CFrame.new(x, y + 0.02, z) * CFrame.Angles(0, heading, 0) * CFrame.new(side * 0.4, 0, 0)
            p.Transparency = 0.42
            TweenService:Create(p, TweenInfo.new(2.2), { Transparency = 1 }):Play()
        end

        -- ACTOR SOURCE SEAM: the shipped path reports every nearby character
        -- (local player AND opponents — seeing someone else kick up water is the
        -- whole point). A Studio harness swaps this local for a dummy provider
        -- and gets the identical detection + splash path. Records are pooled.
        local function defaultActors()
            local n = 0
            local cam = Camera
            if not cam then
                return _abuf, 0
            end
            local camPos = cam.CFrame.Position
            for _, plr in Players:GetPlayers() do
                local ch = plr.Character
                local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local pos = hrp.Position
                    local dx, dy, dz = pos.X - camPos.X, pos.Y - camPos.Y, pos.Z - camPos.Z
                    if dx * dx + dy * dy + dz * dz < 12100 then   -- hard 110-stud cull
                        local vel = hrp.AssemblyLinearVelocity
                        -- tolerant grounded: small vertical speed, else the humanoid
                        -- floor (remote characters often replicate FloorMaterial Air)
                        local grounded = vel.Y > -6 and vel.Y < 6
                        if not grounded then
                            local hum = ch:FindFirstChildOfClass("Humanoid")
                            grounded = hum ~= nil and hum.FloorMaterial ~= Enum.Material.Air
                        end
                        n = n + 1
                        local rec = _abuf[n]
                        if not rec then
                            rec = {}
                            _abuf[n] = rec
                        end
                        rec.key = plr
                        rec.fx, rec.fy, rec.fz = pos.X, pos.Y - 2.9, pos.Z
                        rec.vx, rec.vy, rec.vz = vel.X, vel.Y, vel.Z
                        rec.speed = math.sqrt(vel.X * vel.X + vel.Z * vel.Z)
                        rec.grounded = grounded
                    end
                end
            end
            return _abuf, n
        end
        local actorsProvider = defaultActors

        -- point vs the piece's footprint union: coarse radius reject, then per slab.
        -- Same normalised frame for both shapes — a lobe is |u,v| inside the unit
        -- circle, a tile inside the unit square — so splashes work on every surface.
        local function inPuddle(P, x, z)
            local dx, dz = x - P.cx, z - P.cz
            if dx * dx + dz * dz > P.r2 then
                return false
            end
            for _, sl in P.slabs do
                local ux, uz = x - sl.cx, z - sl.cz
                local u = (-ux * sl.cs + uz * sl.sn) * sl.ia
                local v = (ux * sl.sn + uz * sl.cs) * sl.ib
                if sl.rect then
                    if u > -1 and u < 1 and v > -1 and v < 1 then
                        return true
                    end
                elseif u * u + v * v <= 1 then
                    return true
                end
            end
            return false
        end

        -- THE FLOOD FIELD. One smooth world-space noise field decides which cells hold
        -- water; the threshold is the only thing intensity moves. It sweeps from well
        -- above the field's typical value (a handful of isolated cells) to below its
        -- theoretical MINIMUM at I = 2 — where the test cannot fail and every cell with
        -- ground under it floods. That is what makes "max = whole floor" a guarantee
        -- rather than a tuning hope.
        local function fieldAt(wx, wz)
            return math.noise(wx * NOISE_F, wz * NOISE_F, _seed)
        end
        -- knots calibrated against the MEASURED spread of math.noise (sd ≈ 0.27, observed
        -- range ±0.93 over 6e5 samples) — an assumed spread puts the whole curve out by
        -- half the field. 0.3 → scattered pools, 1.0 → ~45% of cells flooded interior,
        -- 1.6 → a flooded arena. -1.05 at I = 2 is past improved Perlin's absolute bound,
        -- so the water test cannot fail there and the whole floor floods.
        local function floodThr(I)
            if I <= 1 then
                return -0.4043 * (I - 0.3)
            end
            if I <= 1.6 then
                return -0.283 - 0.3417 * (I - 1)
            end
            -- NOT retuned. The top-end slope was re-solved against measured math.noise
            -- data; two independent Node re-implementations of Luau's noise disagree on
            -- the field's spread (sd 0.271 vs 0.365, min -0.99 vs -1.50), so any reslope
            -- here would be calibrated against a distribution nobody has actually
            -- confirmed. Coverage is already the best-behaved intensity consumer in the
            -- file. Leave it to a Studio session with a real sample.
            return -0.488 - 1.405 * (I - 1.6)
        end
        local function refreshParams()
            local I = pudIntensity()
            _int = I
            _thr = floodThr(I)
            _placeR = 46 + 20 * I
            -- heavier rain = deeper, darker, glossier standing water, not just more film.
            -- Reflectance stays under ~0.22: Roblox mirrors only the skybox, so higher
            -- turns the field into an ice rink.
            _wTr = 0.46 - 0.11 * I
            _wRf = 0.11 + 0.05 * I
        end
        -- 0 = dry, 1 = shoreline (organic pool), 2 = flooded interior (tiled).
        -- Interior means all four neighbours are water too, so a tiled cell is never
        -- the thing the player sees the flood END on — the outline is always pools.
        local function cellKind(i, j)
            local ccx, ccz = (i + 0.5) * CELL, (j + 0.5) * CELL
            if fieldAt(ccx, ccz) <= _thr then
                return 0
            end
            if fieldAt(ccx + CELL, ccz) > _thr and fieldAt(ccx - CELL, ccz) > _thr
                and fieldAt(ccx, ccz + CELL) > _thr and fieldAt(ccx, ccz - CELL) > _thr then
                return 2
            end
            return 1
        end

        local function placeCell(i, j, key, kind, by)
            local folder = _pud.folder
            if not folder then
                return false
            end
            local ccx, ccz = (i + 0.5) * CELL, (j + 0.5) * CELL
            _pfilter[1] = folder
            local ch = lp and lp.Character
            if ch then
                _pfilter[2] = ch
            else
                _pfilter[2] = folder
            end
            _prp.FilterDescendantsInstances = _pfilter
            local hit = Workspace:Raycast(Vec(ccx, by + 6, ccz), PUD_DOWN, _prp)
            if not hit or hit.Normal.Y < 0.94 then   -- flat solid ground only
                return false
            end
            local inst = hit.Instance
            if not inst.CanCollide then
                return false
            end
            if inst:IsA("Terrain") and hit.Material == Enum.Material.Water then
                return false
            end
            local cd = _cd
            cd.i, cd.j, cd.key, cd.kind = i, j, key, kind
            cd.cx, cd.cz, cd.gy = ccx, ccz, hit.Position.Y
            -- no whole-cell fit test: both constructors validate and trim PIECE BY
            -- PIECE, so a cell by a ledge keeps the supported part of its water
            if kind == 2 then
                return mkFloodCell(cd, _int)
            end
            local nslab = 5
            if _int > 1.15 then
                nslab = 4   -- flood: fewer, larger lobes keeps the overdraw sane
            end
            return mkPuddle(cd, CELL * POOL_F * (0.82 + 0.24 * math.random()), nslab, _int)
        end

        -- one grid cell: returns true when a placement was ATTEMPTED (budget spent).
        -- A cell with no ground under it is blacklisted so a void or a rooftop edge
        -- cannot burn the whole placement budget every tick.
        local function tryCell(i, j, bx, bz, by)
            local key = (i + 32768) * 65536 + j + 32768
            if _pmap[key] or _pfail[key] then
                return false
            end
            local dx = (i + 0.5) * CELL - bx
            local dz = (j + 0.5) * CELL - bz
            if dx * dx + dz * dz > _placeR * _placeR then
                return false
            end
            local kind = cellKind(i, j)
            if kind == 0 then
                return false
            end
            if not placeCell(i, j, key, kind, by) then
                _pfail[key] = true
            end
            return true
        end

        local function maintain(bx, by, bz)
            local ci, cj = math.floor(bx / CELL), math.floor(bz / CELL)
            local budget = 8
            if ci ~= _homeI or cj ~= _homeJ then
                _homeI, _homeJ = ci, cj
                table.clear(_pfail)   -- new neighbourhood: re-test what failed before
            end
            if _rebuild then
                _rebuild = false
                refreshParams()
                table.clear(_pfail)
                budget = 18
                -- retint the water that SURVIVES the re-decide, so a slider move deepens
                -- the whole field instead of only the pieces it happens to replace
                for _, P in _plist do
                    for _, d in P.model:GetChildren() do
                        if d:GetAttribute("WX_W") then
                            d.Transparency = _wTr
                            d.Reflectance = _wRf
                        end
                    end
                end
                -- the grid never moves, so a settled slider only RE-DECIDES cells: keep
                -- every piece the new field still wants and grow/shrink around them
                local n = 1
                while n <= #_plist do
                    local P = _plist[n]
                    if P.kind == cellKind(P.ci, P.cj) then
                        n = n + 1
                    else
                        _pmap[P.key] = nil
                        P.model:Destroy()
                        _plist[n] = _plist[#_plist]
                        _plist[#_plist] = nil
                    end
                end
            end
            local cull = _placeR + CELL * 0.75   -- hysteresis: a cell at the rim cannot thrash
            local cull2 = cull * cull
            local n = 1
            while n <= #_plist do
                local P = _plist[n]
                local dx, dz = P.cx - bx, P.cz - bz
                if dx * dx + dz * dz > cull2 then
                    _pmap[P.key] = nil
                    P.model:Destroy()
                    _plist[n] = _plist[#_plist]
                    _plist[#_plist] = nil
                else
                    n = n + 1
                end
            end
            -- fill nearest-first, in square rings out from the player's own cell
            local nr = math.ceil(_placeR / CELL)
            for ring = 0, nr do
                for di = -ring, ring do
                    for dj = -ring, ring do
                        if budget > 0 and #_plist < MAX_REC
                            and math.max(math.abs(di), math.abs(dj)) == ring
                            and tryCell(ci + di, cj + dj, bx, bz, by) then
                            budget = budget - 1
                        end
                    end
                end
            end
            -- a flooded floor is far more water than a scatter of pools, so the rain
            -- ring/glint load is capped in AGGREGATE: density stays even, the particle
            -- count at max intensity stays where the old field's was. Runs last so a
            -- piece placed this tick is already inside the budget.
            local ksum = 0
            for _, P in _plist do
                ksum = ksum + P.k
            end
            local damp = 1
            if ksum > K_CAP then
                damp = K_CAP / ksum
            end
            local rr = (2.1 + 4.2 * _int) * damp
            local gr = 0.8 * _int * damp
            for _, P in _plist do
                -- P.k already carries the trimmed-area scale from placement
                P.ring.Rate = rr * P.k
                P.glint.Rate = gr * P.k
            end
        end

        local function tick20(now, doMaintain)
            local bx, by, bz
            local ch = lp and lp.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if hrp then
                local p = hrp.Position
                bx, by, bz = p.X, p.Y, p.Z
            elseif Camera then
                local p = Camera.CFrame.Position
                bx, by, bz = p.X, p.Y, p.Z
            else
                return
            end
            if doMaintain then
                maintain(bx, by, bz)
            end
            local list, n = actorsProvider()
            for ai = 1, n do
                local a = list[ai]
                local st = _pstates[a.key]
                if not st then
                    st = { last = 0, wet = 0, side = 1, prevVy = 0 }
                    _pstates[a.key] = st
                end
                local sp = a.speed
                local pud = nil
                for _, P in _plist do
                    if math.abs(a.fy - P.top) < 4.5 and inPuddle(P, a.fx, a.fz) then
                        pud = P
                        break
                    end
                end
                local interval = math.clamp(3.6 / math.max(sp, 1), 0.15, 0.32)   -- stride cadence
                if pud and a.grounded and sp > 2.2 then
                    local landing = st.prevVy < -25   -- was falling last tick, grounded now
                    if landing or now - st.last >= interval then
                        st.last = now
                        st.side = -st.side
                        local fs = sp
                        if landing then
                            fs = 36
                        end
                        fireSplash(a.fx, pud.top, a.fz, fs)
                        st.wet = now + 1.7
                    end
                elseif not pud and now < st.wet and a.grounded and sp > 2.2 then
                    if now - st.last >= interval then
                        st.last = now
                        st.side = -st.side
                        dropPrint(a.fx, a.fy, a.fz, math.atan2(-a.vx, -a.vz), st.side)
                    end
                end
                st.prevVy = a.vy
            end
        end

        local function startPuddles()
            if _pud.conn then
                return
            end
            local folder = Instance.new("Folder")
            folder.Name = "_wxPuddles"
            folder:SetAttribute("WX_Custom", true)
            folder.Parent = getFolder()
            _pud.folder = folder
            _plist = {}
            _pmap = {}
            table.clear(_pfail)
            -- reseeded per session so one map never has a permanently dry corner;
            -- stable WITHIN a session, so walking away and back returns the same flood
            _seed = math.random() * 512
            _homeI, _homeJ = 1e9, 1e9
            refreshParams()
            _units, _uIdx = {}, 1
            for i = 1, 8 do
                _units[i] = mkSplashUnit(folder)
            end
            _prints, _pIdx = {}, 1
            for i = 1, 12 do
                local p = mkFlatPart(Vec(0.6, 0.02, 1.0), CFrame.new(0, -900, 0), folder)
                p.Material = Enum.Material.SmoothPlastic
                p.Color = Color3.fromRGB(14, 18, 25)
                p.Reflectance = 0.18
                _prints[i] = p
            end
            local accum = 0
            local mTick = 0
            _pud.conn = RunService.Heartbeat:Connect(function(dt)
                accum = accum + dt
                if accum < 0.05 then
                    return
                end
                accum = 0
                if not pudActive() then
                    return   -- refresh() owns teardown; just idle on stale frames
                end
                mTick = mTick + 1
                local doMaintain = false
                if mTick >= 14 then   -- ~0.7s: placement, recycle, rate sync
                    mTick = 0
                    doMaintain = true
                end
                pcall(tick20, os.clock(), doMaintain)
            end)
        end
        function stopPuddles(hard)
            if _pud.conn then
                _pud.conn:Disconnect()
                _pud.conn = nil
            end
            table.clear(_pstates)
            local folder = _pud.folder
            _pud.folder = nil
            _plist = {}
            _pmap = {}
            table.clear(_pfail)
            _units = {}
            _prints = {}
            _rebuild = false
            if not folder then
                return
            end
            if hard then
                folder:Destroy()
                return
            end
            -- soft fade: water sheets tween clear, emitters stop, live rings drain out
            for _, m in folder:GetDescendants() do
                if m:IsA("ParticleEmitter") then
                    m.Rate = 0
                elseif m:IsA("Part") and m.Transparency < 1 then
                    TweenService:Create(m, TweenInfo.new(1.4, Enum.EasingStyle.Sine), { Transparency = 1 }):Play()
                end
            end
            -- folder is detached from state above — always safe to reap after the drain
            task.delay(2.2, function()
                pcall(function() folder:Destroy() end)
            end)
        end
        function puddlesRefresh()
            if pudActive() then
                startPuddles()
            else
                stopPuddles(false)
            end
        end
        -- slider: coalesce a drag into ONE reflood on the next maintain tick
        function puddlesIntensity()
            if not _pud.conn then
                return
            end
            _fieldToken = _fieldToken + 1
            local token = _fieldToken
            task.delay(0.25, function()
                if token ~= _fieldToken then
                    return
                end
                _rebuild = true
            end)
        end
    end)()

    -- ── TIME-OF-DAY DIAL (own toggle; only drives ClockTime while the Visuals master is OFF so it
    --    never fights a lighting preset). Cheap 1Hz drift-guarded loop. ──
    local function startClock()
        if _clockConn then return end
        local accum = 0
        _clockConn = RunService.Heartbeat:Connect(function(dt)
            accum = accum + dt
            if accum < 1 then return end
            accum = 0
            if not Config.Weather or not cfg("WeatherClockDial", false) then return end
            if Config.Visuals then return end   -- don't fight a preset
            local cycle = math.max(cfg("WeatherClockCycleMin", 8), 1) * 60
            local t = ((tick() % cycle) / cycle) * 24
            if math.abs(Lighting.ClockTime - t) > 0.02 then
                Lighting.ClockTime = t
            end
        end)
    end
    local function stopClock()
        if _clockConn then _clockConn:Disconnect(); _clockConn = nil end
    end

    -- saved configs may hold a removed type name — fall back to Rain instead of a dead layer
    local function normType(name)
        if name == "Rain" or name == "BloodMoon" or PRESETS[name] then
            return name
        end
        return "Rain"
    end
    local function applyType(name)
        name = normType(name)
        local prev = _curType
        stopRain(); clearSpecial()
        if #_partLayers > 0 then
            beginLayerFade()   -- outgoing particle layers drain instead of hard-cut
        end
        _curType = name
        if name == "Rain" then
            buildRain(); startRain()
        elseif name == "BloodMoon" then
            buildBloodMoon(); startSpecialAnim()
        else
            local ramp = PRESETS[prev] ~= nil   -- particle→particle switch crossfades in
            local ir = IR[name] or IR_DEF
            for _, spec in PRESETS[name] do
                mkPartLayer(spec, ir, ramp)
            end
        end
        if name == "Fireflies" then startFireflies() else stopFireflies() end
        applyMood(name)   -- persistent CC lerps between grades (no pop)
        startAmbient(SOUND[name])
        puddlesRefresh()  -- follows the type: Rain (or Storm on) = wet ground
    end

    function Weather.setType(name)
        name = normType(name)
        Config.WeatherType = name
        if Config.Weather then applyType(name) end
    end
    local _intensityToken = 0
    -- Rate is only one of the axes now. Everything below is a LIVE property write on an
    -- already-running emitter, so a drag never rebuilds a layer; the Rate write still obeys
    -- the rateTween precedence rule, but it re-targets through L.rateMul so a slider move
    -- during a blizzard swell / gust surge / leaf-devil duck keeps the surged LEVEL instead
    -- of snapping the effect out.
    function Weather.setIntensity(v)
        Config.WeatherIntensity = math.clamp(v, 0.15, 2)
        if not Config.Weather then return end
        puddlesIntensity()   -- coverage + water depth ride the slider: one debounced reflood
        local I = Config.WeatherIntensity
        for _, L in _partLayers do
            if L.emitter then
                pcall(tuneLayer, L, I)
                if L.rateTween then L.rateTween:Cancel(); L.rateTween = nil end
                pcall(function() L.emitter.Rate = layerRate(L, I) * L.rateMul end)
            end
        end
        if _special.kind == "BloodMoon" then pcall(tuneBloodMoon, I) end
        if _rays then
            pcall(function()
                _rays.Intensity = 0.10 + 0.18 * I
                _rays.Spread = 1.1 - 0.2 * I
            end)
        end
        -- the rest is per-drag-settle work: the rain pool grows/trims (up to RAIN_MAX
        -- instances) and the mood grade re-tweens over 3s. Coalesce a drag into ONE pass.
        _intensityToken = _intensityToken + 1
        local token = _intensityToken
        task.delay(0.12, function()
            if token ~= _intensityToken then return end
            if not Config.Weather then return end
            if _curType == "Rain" then pcall(tuneRain) end
            if _curType then pcall(applyMood, _curType) end
            pcall(refreshFireflies)
        end)
    end
    function Weather.setSoundVolume(v)
        Config.WeatherSoundVolume = v
        if _ambient then pcall(function() _ambient.Volume = v end) end   -- live: no retoggle needed
    end
    function Weather.toggleStorm(on)
        Config.WeatherStorm = on
        if not Config.Weather then return end
        if on then startStorm() else stopStormLoop() end
        puddlesRefresh()   -- storm alone also wets the ground
    end
    -- Sky-event FREQUENCY setters. Each writes Config (so a save round-trips) and pulls the
    -- pending wait into the new window, so a drag is felt without re-toggling the feature.
    function Weather.setStormMin(v)
        Config.WeatherStormMin = math.clamp(v, 1, 30)
        rescheduleStorm()
    end
    function Weather.setStormVar(v)
        Config.WeatherStormVar = math.clamp(v, 0, 30)
        rescheduleStorm()
    end
    function Weather.setMeteorRate(v)
        Config.WeatherMeteorRate = math.clamp(v, 0.25, 3)
        rescheduleMeteors()
    end
    function Weather.setStarRate(v)
        Config.WeatherStarRate = math.clamp(v, 0.25, 3)
        rescheduleStars()
    end
    function Weather.togglePuddles(on)
        Config.WeatherPuddles = on
        puddlesRefresh()
    end
    function Weather.toggleMood(on)
        Config.WeatherMood = on
        if Config.Weather and _curType then
            if on then applyMood(_curType) else clearMood() end
        end
    end

    function Weather.toggleMeteors(on)
        Config.WeatherMeteors = on
        if Config.Weather then if on then startMeteors() else stopMeteors() end end
    end
    function Weather.toggleShootingStars(on)
        Config.WeatherShootingStars = on
        if Config.Weather then if on then startStars() else stopStars() end end
    end
    function Weather.toggleClock(on)
        Config.WeatherClockDial = on
        if Config.Weather then if on then startClock() else stopClock() end end
    end

    function Weather.enableWeather()
        Config.Weather = true
        getFolder(); startFollow()
        applyType(cfg("WeatherType", "Rain"))
        if cfg("WeatherStorm", false) then startStorm() end
        if cfg("WeatherMeteors", false) then startMeteors() end
        if cfg("WeatherShootingStars", false) then startStars() end
        if cfg("WeatherClockDial", false) then startClock() end
    end
    function Weather.disableWeather()
        Config.Weather = false
        stopFollow(); stopStorm(); stopRain(); clearPartLayers(); killFade(); clearMood()
        clearSpecial(); stopMeteors(); stopStars(); stopFireflies(); stopLeafDevil(); stopClock()
        stopPuddles(true)
        if _ambient then pcall(function() _ambient:Destroy() end); _ambient = nil end
        _curType = nil
    end

    -- ── SKYBOX ──────────────────────────────────────────────────────────────────
    local SKY = {
        Space     = { Bk="rbxassetid://159454299", Dn="rbxassetid://159454296", Ft="rbxassetid://159454293", Lf="rbxassetid://159454286", Rt="rbxassetid://159454300", Up="rbxassetid://159454288" },
        Sunset    = { Bk="rbxassetid://264908339", Dn="rbxassetid://264907909", Ft="rbxassetid://264909420", Lf="rbxassetid://264909758", Rt="rbxassetid://264908886", Up="rbxassetid://264907379" },
        Clouds    = { Bk="rbxassetid://570557514", Dn="rbxassetid://570557775", Ft="rbxassetid://570557559", Lf="rbxassetid://570557620", Rt="rbxassetid://570557672", Up="rbxassetid://570557727" },
        Storm     = { Bk="rbxassetid://255027929", Dn="rbxassetid://255027967", Ft="rbxassetid://255027923", Lf="rbxassetid://255027938", Rt="rbxassetid://255027946", Up="rbxassetid://255027960" },
        Winter    = { Bk="rbxassetid://402229526", Dn="rbxassetid://402229596", Ft="rbxassetid://402229293", Lf="rbxassetid://402229368", Rt="rbxassetid://402229417", Up="rbxassetid://402229564" },
        Vaporwave = { Bk="rbxassetid://1417494030", Dn="rbxassetid://1417494146", Ft="rbxassetid://1417494253", Lf="rbxassetid://1417494402", Rt="rbxassetid://1417494499", Up="rbxassetid://1417494643" },
    }
    Weather.SkyboxOrder = { "Off", "Space", "Sunset", "Clouds", "Storm", "Winter", "Vaporwave" }
    local _sky, _skyConn = nil, nil
    local _origSkies = {}

    local function hideMapSkies()
        for _, c in ipairs(Lighting:GetChildren()) do
            if c:IsA("Sky") and not c:GetAttribute("WX_Custom") then
                table.insert(_origSkies, c)
                pcall(function() c.Parent = nil end)
            end
        end
    end
    local function restoreMapSkies()
        for i = #_origSkies, 1, -1 do
            local c = _origSkies[i]
            if c and c.Parent == nil then
                pcall(function() c.Parent = Lighting end)
            end
            _origSkies[i] = nil
        end
    end

    local function buildSky(preset)
        local set = SKY[preset]; if not set then return end
        hideMapSkies()
        local s = Instance.new("Sky")
        s.Name = "_wxSky"; s:SetAttribute("WX_Custom", true)
        s.SkyboxBk, s.SkyboxDn, s.SkyboxFt = set.Bk, set.Dn, set.Ft
        s.SkyboxLf, s.SkyboxRt, s.SkyboxUp = set.Lf, set.Rt, set.Up
        if cfg("SkyboxHideCelestial", false) then
            s.SunAngularSize = 0; s.MoonAngularSize = 0; s.StarCount = 0
            s.CelestialBodiesShown = false
        else
            s.CelestialBodiesShown = true
        end
        s.Parent = Lighting
        _sky = s
    end
    local function startSkyGuard()
        if _skyConn then return end
        _skyConn = Lighting.ChildAdded:Connect(function(c)
            if c:IsA("Sky") and not c:GetAttribute("WX_Custom") and Config.SkyboxPreset and Config.SkyboxPreset ~= "Off" then
                table.insert(_origSkies, c)
                pcall(function() c.Parent = nil end)
            end
        end)
    end
    local function stopSkyGuard()
        if _skyConn then _skyConn:Disconnect(); _skyConn = nil end
    end
    local function clearSky()
        if _sky then pcall(function() _sky:Destroy() end); _sky = nil end
        restoreMapSkies()
    end
    function Weather.setSkybox(preset)
        if preset and not SKY[preset] then preset = "Off" end
        Config.SkyboxPreset = preset
        clearSky()
        if preset == "Off" or preset == nil then stopSkyGuard(); return end
        buildSky(preset); startSkyGuard()
    end
    function Weather.toggleCelestial(hide)
        Config.SkyboxHideCelestial = hide
        if _sky then
            if hide then
                _sky.SunAngularSize = 0; _sky.MoonAngularSize = 0; _sky.StarCount = 0
                _sky.CelestialBodiesShown = false
            else
                _sky.SunAngularSize = 11; _sky.MoonAngularSize = 11; _sky.StarCount = 3000
                _sky.CelestialBodiesShown = true
            end
        end
    end

    -- ── RAINBOW (independent toggle; pairs with rain). A real DOUBLE bow, Studio-verified vs
    --    the bright day sky 2026-07-14. Primary = 7 concentric ROYGBIV bands (red outermost)
    --    that all share ONE span so the leg tips CONVERGE (the old staggered spans combed the
    --    ends into frayed strands), over a soft bright-inside glow gapped INSIDE the violet
    --    band (overlapping it diluted the purples to lavender). Plus a faint SECONDARY bow
    --    above, colour order REVERSED (red faces red, real optics). Bands are UNtextured
    --    alpha-leaning beams: LOW transparency + emission 0.42 keeps the pigment saturated —
    --    the old 0.28-0.5 transp @ 0.55-0.65 emission washed to invisible pastel. Pulled to
    --    430 out / -20 up (was 500/-60: legs buried behind map geometry + hazed out).
    --    FaceCamera keeps full band width along the arch; parallax-locked + yaw-billboarded
    --    via the follow loop. ──
    local _rainbow = { host = nil, conn = nil }
    local RB_BANDS = {   -- { colour, mid transparency, width } — narrow dim violets, real-bow feel
        { Color3.fromRGB(255, 40, 40),  0.10, 24 },
        { Color3.fromRGB(255, 130, 20), 0.12, 24 },
        { Color3.fromRGB(255, 225, 40), 0.14, 24 },
        { Color3.fromRGB(60, 210, 70),  0.16, 24 },
        { Color3.fromRGB(40, 130, 255), 0.18, 24 },
        { Color3.fromRGB(85, 60, 235),  0.26, 18 },
        { Color3.fromRGB(165, 65, 230), 0.30, 16 },
    }
    local RB_DIST, RB_OY = 430, -20
    local function clearRainbow()
        if _rainbow.conn then _rainbow.conn:Disconnect(); _rainbow.conn = nil end
        if _rainbow.host then pcall(function() _rainbow.host:Destroy() end); _rainbow.host = nil end
    end
    local function buildRainbow()
        local host = Instance.new("Part")
        host.Name = "_wxRainbow"; host.Anchored = true; host.CanCollide = false; host.CanQuery = false
        host.CanTouch = false; host.CastShadow = false; host.Massless = true; host.Transparency = 1
        host.Size = Vec(1, 1, 1); host:SetAttribute("WX_Custom", true)
        local rot = CFrame.Angles(0, 0, math.rad(90))   -- turn attachment Right(+X)→+Y so CurveSize bows UP
        local function band(sp, rr, w, col, midT, emit, soft)
            local a0 = Instance.new("Attachment"); a0.CFrame = CFrame.new(-sp, 0, 0) * rot; a0.Parent = host
            local a1 = Instance.new("Attachment"); a1.CFrame = CFrame.new( sp, 0, 0) * rot; a1.Parent = host
            local b = Instance.new("Beam")
            b.Attachment0 = a0; b.Attachment1 = a1; b.Segments = 46; b.FaceCamera = true
            if soft then b.Texture = TX_SOFT; b.TextureMode = Enum.TextureMode.Stretch; b.TextureLength = 1 end
            b.Width0 = w; b.Width1 = w; b.CurveSize0 = rr; b.CurveSize1 = -rr
            b.LightEmission = emit; b.LightInfluence = 0
            b.Color = ColorSequence.new(col)
            local edge = math.min(midT + 0.25, 1)   -- legs dissolve toward the horizon
            b.Transparency = NumberSequence.new({
                NSK(0, 1), NSK(0.08, edge), NSK(0.45, midT), NSK(0.55, midT), NSK(0.92, edge), NSK(1, 1) })
            b.Parent = host
        end
        for i = 1, #RB_BANDS do
            local B = RB_BANDS[i]
            band(340, 320 - (i - 1) * 15, B[3], B[1], B[2], 0.42, false)
        end
        band(340, 165, 52, Color3.fromRGB(242, 248, 255), 0.78, 0.6, true)   -- bright-inside glow
        for i = 1, #RB_BANDS do   -- faint SECONDARY bow above, colours reversed (red faces red)
            band(400, 355 + (i - 1) * 12, 20, RB_BANDS[i][1], 0.64 + i * 0.012, 0.42, false)
        end
        host.Parent = getFolder()
        _rainbow.host = host
    end
    local function startRainbowFollow()
        if _rainbow.conn then return end
        local accum = 0
        _rainbow.conn = RunService.Heartbeat:Connect(function(dt)
            if not cfg("WeatherRainbow", false) then return end
            accum = accum + dt; if accum < 0.08 then return end   -- ~12Hz is plenty for a sky element
            accum = 0
            local cam = Camera; if not cam then return end
            local host = _rainbow.host; if not host or not host.Parent then return end
            local p = cam.CFrame.Position
            local hp = Vec(p.X, p.Y + RB_OY, p.Z - RB_DIST)        -- fixed world azimuth, XZ-parallax
            host.CFrame = CFrame.lookAt(hp, Vec(p.X, hp.Y, p.Z))   -- yaw-billboard: always a face-on arch
        end)
    end
    function Weather.toggleRainbow(on)
        Config.WeatherRainbow = on
        clearRainbow()
        if not on then return end
        buildRainbow(); startRainbowFollow()
    end

    -- ── GOD RAYS (independent toggle, skybox-style lifecycle): volumetric shafts off the sun.
    --    A single SunRaysEffect — no Atmosphere sidecar, so it never fights BloodMoon/mood. ──
    function Weather.toggleGodRays(on)
        Config.WeatherGodRays = on
        if _rays then pcall(function() _rays:Destroy() end); _rays = nil end
        if not on then return end
        local r = Instance.new("SunRaysEffect")
        r.Name = "_wxRays"; r:SetAttribute("WX_Custom", true)
        -- anchored at the approved 0.28 / 0.9 for I = 1; strong intensity = brighter and
        -- TIGHTER shafts, weak = a faint broad wash. Broad soft shafts, not a laser star.
        local I = iAmt()
        r.Intensity = 0.10 + 0.18 * I
        r.Spread = 1.1 - 0.2 * I
        r.Parent = Lighting
        _rays = r
    end

    -- ── lifecycle ──
    function Weather.init()
        if Config.Weather then pcall(Weather.enableWeather) end
        if Config.SkyboxPreset and Config.SkyboxPreset ~= "Off" then pcall(Weather.setSkybox, Config.SkyboxPreset) end
        if Config.WeatherGodRays then pcall(Weather.toggleGodRays, true) end
        if Config.WeatherRainbow then pcall(Weather.toggleRainbow, true) end
    end
    function Weather.unload()
        pcall(Weather.disableWeather)
        stopSkyGuard(); clearSky(); clearRainbow()
        if _rays then pcall(function() _rays:Destroy() end); _rays = nil end
        if _folder then pcall(function() _folder:Destroy() end); _folder = nil end
        _lightFolder = nil
    end
end)()

-- ── HUD+ · INSTRUMENT CLUSTER ───────────────────────────────────────────────
-- Tactical readouts that Rivals' own UI does NOT provide: a top-center bearing COMPASS (enemy
-- pips + off-window threat pill), a crosshair THREAT ARC pointing at the nearest enemy bearing,
-- and a nearest-enemy RANGE readout. All default-OFF, all riding the HUD master (Config.HUD) +
-- their own key. ONE 30Hz RenderStepped updater, ONE module-local pool built once (radar pattern),
-- numeric hot loops, integer-snapped writes to feed the shim skip-write. Draws on the "fx" layer.
-- Internals live in an IIFE so the block-locals never touch the main-chunk register budget.
-- (Ammo plate + session card were REMOVED: the ammo plate duped Rivals' own ammo UI, and the
--  session card duped the watermark's shots/hits/acc line.)
local HUDPlus = {}
;(function()
    local hasDrawing = screenDraw ~= nil

    -- SIGNAL palette (design §1.1). Shapes carry state; text stays neutral; gold is earned.
    local C_TEXT1  = Color3.fromRGB(243, 246, 250)  -- #F3F6FA values
    local C_TEXT2  = Color3.fromRGB(174, 185, 197)  -- #AEB9C5 labels/data
    local C_GOLD   = Color3.fromRGB(255, 194, 75)   -- #FFC24B north / accent
    local C_ENEMY  = Color3.fromRGB(255, 59, 78)    -- #FF3B4E enemy pips
    local C_EDGE   = Color3.fromRGB(155, 232, 255)  -- #9BE8FF transient motion (caret glint)
    local C_BLACK  = Color3.new(0, 0, 0)

    local PI  = math.pi
    local TAU = PI * 2
    local RAD60 = math.rad(60)

    -- ── pools (built ONCE) ──────────────────────────────────────────────────
    local _alloc = false
    local _cRail, _cRailCas = nil, nil
    local _cTicks = nil                              -- 10 tick Lines
    local _cCard  = nil                              -- 4 cardinal Texts (N/E/S/W)
    local _cCaret = nil                              -- center caret Triangle
    local _cPips  = nil                              -- 8 enemy pip Circles
    local _cPill  = nil                              -- off-window threat count "▲N"
    local _taSeg, _taSegCas = nil, nil               -- threat arc: 9 seg Lines (+ casing)
    local _rng = nil                                 -- range readout Text

    -- ── lifecycle state ─────────────────────────────────────────────────────
    local _conn = nil
    local _started = false
    local _thrT = 0                                  -- 30Hz throttle
    -- reused scratch (no per-frame alloc)
    local _pip = {}                                  -- {rel, dist} rows for compass pips

    local function nd(kind, props)
        if not hasDrawing then return nil end
        local ok, d = pcall(screenDraw, kind, "fx")
        if not ok or not d then return nil end
        d.Visible = false
        if props then for k, v in pairs(props) do pcall(function() d[k] = v end) end end
        return d
    end

    local function alloc()
        if _alloc then return end
        _alloc = true
        -- COMPASS (casing rail created before the bright rail = under)
        _cRailCas = nd("Line", { Color = C_BLACK, Thickness = 3 })
        _cRail    = nd("Line", { Color = C_TEXT2, Thickness = 1 })
        _cTicks = {}
        for i = 1, 10 do _cTicks[i] = nd("Line", { Thickness = 1 }) end
        _cCard = {}
        for i = 1, 4 do _cCard[i] = nd("Text", { Center = true, Outline = true, Font = 3, Size = 11 }) end
        _cCaret = nd("Triangle")
        _cPips = {}
        for i = 1, 8 do _cPips[i] = nd("Circle", { Filled = true, NumSides = 12 }) end
        _cPill = nd("Text", { Center = true, Outline = true, Font = 3, Size = 11, Color = C_ENEMY })
        -- THREAT ARC (casing first = under)
        _taSegCas = {}
        for i = 1, 9 do _taSegCas[i] = nd("Line", { Color = C_BLACK, Thickness = 4 }) end
        _taSeg = {}
        for i = 1, 9 do _taSeg[i] = nd("Line", { Thickness = 2 }) end
        -- RANGE readout
        _rng = nd("Text", { Center = true, Outline = true, Font = 3, Size = 13, Color = C_TEXT1 })
    end

    -- ── per-feature hide helpers (idle features cost nothing after one hide) ──
    local function hideCompass()
        if _cRail then _cRail.Visible = false; _cRailCas.Visible = false end
        if _cTicks then for i = 1, #_cTicks do _cTicks[i].Visible = false end end
        if _cCard then for i = 1, 4 do _cCard[i].Visible = false end end
        if _cCaret then _cCaret.Visible = false end
        if _cPips then for i = 1, #_cPips do _cPips[i].Visible = false end end
        if _cPill then _cPill.Visible = false end
    end
    local function hideArc()
        if _taSeg then for i = 1, 9 do _taSeg[i].Visible = false; _taSegCas[i].Visible = false end end
    end
    local function hideRange() if _rng then _rng.Visible = false end end
    local function hideAll()
        hideCompass(); hideArc(); hideRange()
    end

    local CARDINALS = {
        { "N", 0, 0, -1, true  },   -- world -Z, gold
        { "E", 1, 0,  0, false },
        { "S", 0, 0,  1, false },
        { "W", -1, 0, 0, false },
    }

    local function wrap(a)
        a = (a + PI) % TAU
        if a < 0 then a = a + TAU end
        return a - PI
    end

    -- ── COMPASS ──────────────────────────────────────────────────────────────
    -- camYaw from the flattened look heading; every element's bearing is (worldBearing - camYaw)
    -- so ticks, cardinals and pips all share ONE reference — they can never disagree.
    local function drawCompass(vp, camYaw, y)
        local railW = math.floor(math.max(Config.HUDCompassWidth or 380, 120))
        local half = railW * 0.5
        local cxp = math.floor(vp.X * 0.5)
        -- rail + casing
        local lx, rx = cxp - half, cxp + half
        _cRailCas.From = Vector2.new(lx, y); _cRailCas.To = Vector2.new(rx, y)
        _cRailCas.Transparency = 0.5; _cRailCas.Visible = true
        _cRail.From = Vector2.new(lx, y); _cRail.To = Vector2.new(rx, y)
        _cRail.Transparency = 0.85; _cRail.Visible = true
        -- 15° ticks across the window; taller at 45° multiples
        local base = math.floor(math.deg(camYaw) / 15 + 0.5) * 15
        local shown = 0
        for k = -4, 4 do
            local degA = base + k * 15
            local rel = wrap(math.rad(degA) - camYaw)
            if rel >= -RAD60 and rel <= RAD60 then
                shown = shown + 1
                local L = _cTicks[shown]
                if L then
                    local tx = math.floor(cxp + (rel / RAD60) * half)
                    local tall = (degA % 45 == 0) and 7 or 4
                    L.From = Vector2.new(tx, y - tall); L.To = Vector2.new(tx, y)
                    L.Color = C_TEXT2; L.Transparency = 0.45; L.Visible = true
                end
            end
        end
        for i = shown + 1, #_cTicks do _cTicks[i].Visible = false end
        -- cardinal labels
        for i = 1, 4 do
            local c = CARDINALS[i]
            local bearing = math.atan2(c[2], c[4])
            local rel = wrap(bearing - camYaw)
            local T = _cCard[i]
            if T then
                if rel >= -RAD60 and rel <= RAD60 then
                    local tx = math.floor(cxp + (rel / RAD60) * half)
                    T.Position = Vector2.new(tx, y - 22)
                    T.Text = c[1]; T.Color = c[5] and C_GOLD or C_TEXT2
                    T.Transparency = 1; T.Visible = true
                else T.Visible = false end
            end
        end
        -- center caret with an EDGE glint (transient accent — pulses subtly at 1.6Hz)
        if _cCaret then
            local glint = 0.5 + 0.5 * math.sin((tick()) * 1.6 * TAU)
            _cCaret.Filled = true
            _cCaret.PointA = Vector2.new(cxp, y + 7)
            _cCaret.PointB = Vector2.new(cxp - 5, y + 1)
            _cCaret.PointC = Vector2.new(cxp + 5, y + 1)
            _cCaret.Color = C_EDGE
            _cCaret.Transparency = 0.65 + 0.35 * glint
            _cCaret.Visible = true
        end
    end

    -- ── the ONE updater ──────────────────────────────────────────────────────
    local function update()
        if not (Config.HUD and hasDrawing) then hideAll(); return end
        local now = tick()
        if now - _thrT < 0.033 then return end   -- 30Hz
        _thrT = now
        local cam = Camera; if not cam then return end
        local vp = cam.ViewportSize
        local cx, cy = vp.X * 0.5, vp.Y * 0.5

        local compassOn = Config.HUDCompass
        local arcOn     = Config.HUDThreatArc
        local rangeOn   = Config.HUDRangeReadout

        -- shared enemy sweep (compass pips + nearest for arc/range) — ONE pass over players
        local myC = lp.Character
        local myR = myC and myC:FindFirstChild("HumanoidRootPart")
        local myPos = myR and myR.Position
        local camPos = cam.CFrame.Position
        local look = cam.CFrame.LookVector
        local camYaw = math.atan2(look.X, look.Z)

        local nearD, nearRel = math.huge, 0
        local pipN, offCount = 0, 0
        if compassOn or arcOn or rangeOn then
            local players = getSafePlayers()
            for i = 1, #players do
                local pl = players[i]
                if pl ~= lp and not isTeammate(pl) and isAlive(pl) then
                    local ch = pl.Character
                    local r = ch and ch:FindFirstChild("HumanoidRootPart")
                    if r then
                        local pos = r.Position
                        local dx, dz = pos.X - camPos.X, pos.Z - camPos.Z
                        local rel = wrap(math.atan2(dx, dz) - camYaw)
                        local d = myPos and (myPos - pos).Magnitude
                            or math.sqrt(dx * dx + dz * dz)
                        if d < nearD then nearD = d; nearRel = rel end
                        if rel < -RAD60 or rel > RAD60 then offCount = offCount + 1 end
                        if compassOn and pipN < 8 then
                            pipN = pipN + 1
                            local e = _pip[pipN]; if not e then e = {}; _pip[pipN] = e end
                            e.rel = rel; e.dist = d
                        end
                    end
                end
            end
        end

        -- COMPASS
        if compassOn then
            local y = 26
            drawCompass(vp, camYaw, y)
            local half = math.max(Config.HUDCompassWidth or 380, 120) * 0.5
            local cxp = math.floor(cx)
            local maxD = math.max(Config.ESPMaxDistance or 1200, 1)
            local drawPips = Config.HUDCompassPips and pipN or 0
            for i = 1, drawPips do
                local e = _pip[i]
                local P = _cPips[i]
                if P then
                    local rel = e.rel
                    local clamped = rel
                    if clamped < -RAD60 then clamped = -RAD60 elseif clamped > RAD60 then clamped = RAD60 end
                    local edge = (rel < -RAD60 or rel > RAD60)   -- behind us: edge-clamp + dim
                    local px = math.floor(cxp + (clamped / RAD60) * half)
                    local a = 1 - 0.6 * math.clamp(e.dist / maxD, 0, 1)
                    if edge then a = a * 0.4 end
                    P.Radius = 2; P.Position = Vector2.new(px, 26)
                    P.Color = C_ENEMY; P.Transparency = a; P.Visible = true
                end
            end
            for i = drawPips + 1, #_cPips do _cPips[i].Visible = false end
            -- off-window threat pill at the rail's right end
            if _cPill then
                if offCount > 0 then
                    _cPill.Text = "\226\150\178" .. offCount   -- ▲N
                    _cPill.Position = Vector2.new(math.floor(cxp + half + 16), 20)
                    _cPill.Transparency = 1; _cPill.Visible = true
                else _cPill.Visible = false end
            end
        else hideCompass() end

        -- THREAT ARC around the crosshair (nearest enemy bearing)
        if arcOn and _taSeg and nearD < math.huge then
            local R = 42
            local width = math.rad(30)
            local step = width / 9
            local th0 = nearRel - width * 0.5
            -- GOLD close -> TEXT-2 far; alpha 1 -> 0.25 with distance
            local dfrac = math.clamp((nearD - 25) / (300 - 25), 0, 1)
            local col = C_GOLD:Lerp(C_TEXT2, dfrac)
            local a = 1 - 0.75 * dfrac
            for j = 1, 9 do
                local t1 = th0 + step * (j - 1)
                local t2 = t1 + step * 0.72
                local p1 = Vector2.new(cx + math.sin(t1) * R, cy - math.cos(t1) * R)
                local p2 = Vector2.new(cx + math.sin(t2) * R, cy - math.cos(t2) * R)
                local cs = _taSegCas[j]
                if cs then cs.From = p1; cs.To = p2; cs.Transparency = a * 0.8; cs.Visible = true end
                local L = _taSeg[j]
                if L then L.From = p1; L.To = p2; L.Color = col; L.Transparency = a; L.Visible = true end
            end
        else hideArc() end

        -- RANGE readout under the crosshair (nearest enemy)
        if rangeOn and _rng then
            if nearD < math.huge then
                _rng.Text = ("%dm"):format(math.floor(nearD + 0.5))
                _rng.Position = Vector2.new(math.floor(cx), math.floor(cy + 64))
                _rng.Transparency = 1; _rng.Visible = true
            else _rng.Visible = false end
        else hideRange() end
    end

    function HUDPlus.start()
        if _started then return end
        _started = true
        alloc()
        if not _conn then
            _conn = RunService.RenderStepped:Connect(function() if _started then pcall(update) end end)
        end
    end
    function HUDPlus.stop()
        if not _started then return end
        _started = false
        if _conn then _conn:Disconnect(); _conn = nil end
        hideAll()
    end
    function HUDPlus.init()
        -- rides the HUD master: only spin up the loop when the HUD subsystem is on.
        if Config.HUD then pcall(HUDPlus.start) end
    end
    function HUDPlus.unload()
        pcall(HUDPlus.stop)
    end
end)()

-- ════════════════ PART 2 ════════════════
-- Rage · Gun Hook · Aimbot · ESP · GUI · Init
-- ══════════════════════════════════════════

-- ── RAGE INTERNALS ─────────────────────────────────────────────────────────
local Rage = {}
-- Rage internals run in their OWN function proto, not the main chunk. The executor prepends a ~25-local
-- API-shim preamble to the MAIN chunk that would push it past Luau's 200-local/proto cap, so we keep these
-- locals in a fresh IIFE proto budget. `Rage` (the export table) stays in the outer scope. This IIFE spans
-- BOTH 07a and 07b — it OPENS here (`;(function()`) and CLOSES in 07b (`end)()`); everything between is one
-- Luau proto sharing the 190-local budget. Runs immediately.
;(function()
    local _tgtConn  = nil   -- target-acquisition loop (fills RageTrueVelocityMap; sets State.Target/RageTarget)
    local _labConn  = nil   -- Lab-gated enemy-damage poll (feeds State.RageDealtTotal); only alive while RageLab

    -- per-life character token (guards the desync restore from yanking a freshly-respawned body)
    local function bump(p) State.RageCharTokens[p] = (State.RageCharTokens[p] or 0) + 1 end

    -- kill floor: the lowest Y we clamp a point-blank park to (above the fallen-parts sweep + our buffer)
    local function killFloor()
        return workspace.FallenPartsDestroyHeight + Config.RageKillPlaneBuffer
    end

    -- Clear LOS from a forged-eye position to the resolved head (private; used by flankPoint + the natural
    -- encoder). Exclude filter FAILS SAFE — a false block only skips a frame; a false clear can't happen.
    local function hasLOS(fromPos, toPos, ignore)
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = ignore
        local res = workspace:Raycast(fromPos, toPos - fromPos, rp)
        if not res then return true end
        return (res.Position - toPos).Magnitude < 3
    end

    -- ── NON-DEGENERATE LOOK CFRAME (the stray-tracer fix, 2026-07-29) ───────
    -- CFrame.new(from, to) derives its rotation as up x look with up FIXED at (0,1,0). The rage eye sits
    -- directly above the head and aims at it, so look == (0,-1,0) EXACTLY, the cross product is the zero
    -- vector, and .Unit of that is NaN -- the entire rotation matrix is NaN on every Polar shot.
    -- The POSITION component survives, which is why the server's |char0 - char2| <= 400 test still passes
    -- and the damage still lands. What does not survive is char0/char1's LookVector, and the shot pipeline
    -- projects along char1's LookVector whenever char2 fails to resolve:
    --     Gun.luau:581  v137 = v135 and (v135.CFrame * v136).Position
    --                          or (v134 * v131 * CFrame.new(0,0,-MAX_RAYCAST_DISTANCE)).Position
    -- (v135 = char2, v134 = char1). A garbage LookVector there throws the endpoint to an arbitrary point --
    -- the stray tracers into the sky/wall that carry no damage. Gun.luau:585 (`if v139 ~= v139`) is the
    -- game's OWN NaN guard on that direction, so this failure is real and known to its authors.
    -- OldLuahook.txt:1214 builds char0 the same way (eyePos = aimPt + (0, RageAboveHeadOffset, 0)), which is
    -- why this symptom predates the modular refactor and survived every timing/delivery fix aimed at it.
    -- Picking a non-parallel up when the look is near-vertical costs nothing: same position, same aim point,
    -- same hit test, only a defined roll instead of NaN. Rage power is untouched by construction.
    local function lookCF(fromPos, toPos)
        local dir = toPos - fromPos
        if dir.Magnitude < 1e-4 then dir = Vector3.new(0, -1, 0) end
        local up = Vector3.new(0, 1, 0)
        if math.abs(dir.Unit.Y) > 0.999 then up = Vector3.new(0, 0, 1) end   -- near-vertical => roll off world-Z
        return CFrame.lookAt(fromPos, fromPos + dir, up)
    end
    Rage._lookCF = lookCF   -- 07b's forged burst builds its eye/muzzle with the SAME helper

    -- ── SHARED SHOT GEOMETRY ────────────────────────────────────────────────
    -- Build the char0/char1/char3 packet fields into camData for a shot at `aimWorldPos` on `hitPart`, from
    -- eye `eyeCF` / muzzle `muzzleCF`. `jitter` (MANDATORY): when true, the char3 object-space offset is
    -- randomized within the clamp band so it varies per shot (a real Rivals shot is never char3=0 static);
    -- `clampFrac`/`jitterFrac` set the band. char2 (the live hitPart instance) is set by the caller. Returns
    -- the encoded fields via camData; the caller owns the utf8-keyed envelope.
    local function buildShotFields(camData, eyeCF, muzzleCF, hitPart, aimWorldPos, jitter, clampFrac, jitterFrac)
        local objSpace = hitPart.CFrame:PointToObjectSpace(aimWorldPos)
        local hs = hitPart.Size * (clampFrac or 0.45)
        objSpace = Vector3.new(
            math.clamp(objSpace.X, -hs.X, hs.X),
            math.clamp(objSpace.Y, -hs.Y, hs.Y),
            math.clamp(objSpace.Z, -hs.Z, hs.Z)
        )
        if jitter then
            local jf = jitterFrac or 1.0
            objSpace = Vector3.new(
                math.clamp(objSpace.X + (math.random() - 0.5) * hs.X * jf, -hs.X, hs.X),
                math.clamp(objSpace.Y + (math.random() - 0.5) * hs.Y * jf, -hs.Y, hs.Y),
                math.clamp(objSpace.Z + (math.random() - 0.5) * hs.Z * jf, -hs.Z, hs.Z)
            )
        end
        local hitWorld   = hitPart.CFrame:PointToWorldSpace(objSpace)
        local objSpaceCF = hitPart.CFrame:ToObjectSpace(CFrame.new(hitWorld))
        camData[utf8.char(0)] = Rivals.Util:EncodeCFrame(eyeCF)
        camData[utf8.char(1)] = Rivals.Util:EncodeCFrame(muzzleCF)
        camData[utf8.char(2)] = hitPart
        camData[utf8.char(3)] = Rivals.Util:EncodeCFrame(objSpaceCF)
    end
    Rage._buildShotFields = buildShotFields   -- 07b's forged burst uses the SAME builder (see below)

    -- RAGE band: tighter than silent aim's 0.45 because the rage eye is point-blank DIRECTLY ABOVE the head,
    -- so a near-vertical ray meets the top face at a shallower offset. The endpoint stays inside the part
    -- either way (so the segment must cross the surface and the shot lands), but 0.30 keeps margin for
    -- non-box hitboxes where inside-the-AABB is not inside-the-mesh.
    local RAGE_CLAMP_FRAC  = 0.30
    local RAGE_JITTER_FRAC = 1.0

    -- Shot encoder (silent-aim / aimbot path — the 08 hook calls Rage._encodeShot). Far eye => the ±45%
    -- clamp + full-half-extent jitter are sub-degree, always on the part. jitter follows Config.SilentAimJitter.
    local function encodeShot(camData, hitPart, targetChar, fromCamPos)
        if not hitPart or not camData or not Rivals.Util then return false end
        local lead      = calculateLead(targetChar, fromCamPos)
        local leadedPos = hitPart.Position + lead
        -- lookCF, not CFrame.new: a player aiming straight down at someone below hits the same degenerate
        -- rotation the rage path does (see lookCF). Rare here, free to be correct about.
        local eyeCF     = lookCF(fromCamPos, leadedPos)
        local muzzlePos = fromCamPos + (eyeCF.RightVector * 0.2) + Vector3.new(0, -Config.RageEyeMuzzleSep, 0)
        local muzzleCF  = lookCF(muzzlePos, leadedPos)
        buildShotFields(camData, eyeCF, muzzleCF, hitPart, leadedPos, Config.SilentAimJitter, 0.45, 1.0)
        return true
    end
    Rage._encodeShot = encodeShot

    -- ── WEAPON SWITCH / reload economy ──────────────────────────────────────
    local PICK_SLOT = { Primary = 1, Secondary = 2, Melee = 3 }
    ;(function()
        -- Sub-IIFE (register budget): the ~12 economy locals live in their own proto so they don't count
        -- against the shared rage-IIFE 190-cap. Exports go on the Rage table.
        local function fighterItems()
            local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
            return lf and lf.Items or nil
        end
        -- ★ FIXED 2026-08-07 — THIS RETURNED FALSE FOR EVERY MELEE ITEM, AND IT IS WHY THE KNIFE BOT
        -- NEVER LANDED A HIT. The old body asked `item:Get("Type"/"ItemType"/"Category")`, which reads the
        -- item's replicated DATA. The game puts none of those there: `add_item` (ItemLibrary L3077-3079)
        -- writes Type / Status / Class onto the **Info** table, and `add_melee` passes "Melee" for both
        -- Type and Class. `Get("Name")` returns "Knife", which contains no "melee" either.
        -- The damage: encodeRageShot's guard is
        --     if not itemIsMelee(item) then ...require ammo > 0... end
        -- so with a knife it took the GUN branch, `item:Get("Ammo")` was nil, and encodeRageShot REFUSED
        -- to redirect the camData. The swing was sent — it just went along the player's real camera at
        -- whatever they happened to be looking at, which reads exactly as "we teleport onto them and
        -- nothing happens". Same class of bug as weaponReady's ammo test: a melee predicate that only
        -- ever ran against guns.
        -- Now keyed on the game's own fields, cheapest first, with the old name sniff kept last as a
        -- fallback for anything exotic that has no Info.
        local function itemIsMelee(item)
            if not item then return false end
            local viaInfo = false
            pcall(function()
                local info = item.Info
                if info == nil then return end
                if info.Type == "Melee" or info.Class == "Melee" then viaInfo = true return end
                -- AttackReach exists on every melee and on nothing else (add_melee L3308).
                if type(info.AttackReach) == "number" and info.MaxAmmo == nil then viaInfo = true end
            end)
            if viaInfo then return true end
            local okN, nm = pcall(function() return item:Get("Name") or item.Name end)
            if okN and type(nm) == "string" and nm:lower():find("melee", 1, true) then return true end
            return false
        end
        Rage._itemIsMelee = itemIsMelee
        local function itemAmmo(item)
            if not item then return nil end
            local ok, a = pcall(function() return item:Get("Ammo") or item:Get("CurrentAmmo") end)
            if ok and type(a) == "number" then return a end
            return nil
        end
        local function slotItemByIndex(idx)
            local items = fighterItems(); if not items then return nil end
            if items[idx] then return items[idx] end
            if items[tostring(idx)] then return items[tostring(idx)] end
            for key, it in pairs(items) do
                if it and typeof(it) == "table" then
                    local okS, s = pcall(function() return tonumber(it:Get("Slot") or it:Get("Index") or it:Get("ItemSlot") or key) end)
                    if okS and s == idx then return it end
                    local okT, t = pcall(function() return it:Get("ItemType") or it:Get("Type") end)
                    if okT then
                        if idx == 1 and (t == "Primary" or t == 1 or t == "1") then return it end
                        if idx == 2 and (t == "Secondary" or t == 2 or t == "2") then return it end
                        if idx == 3 and (t == "Melee" or (type(t) == "string" and t:lower():find("melee", 1, true))) then return it end
                    end
                end
            end
            return nil
        end
        local function whichSlotNow()
            local cur = getEquippedItem(); if not cur then return nil end
            local okId, oid = pcall(function() return cur:Get("ObjectID") end)
            if okId and oid then
                for idx = 1, 3 do
                    local it = slotItemByIndex(idx)
                    if it then
                        local okI, iid = pcall(function() return it:Get("ObjectID") end)
                        if okI and iid == oid then return idx end
                    end
                end
            end
            if itemIsMelee(cur) then return 3 end
            return nil
        end
        local function slotUsable(idx)
            local it = slotItemByIndex(idx); if not it then return false end
            if itemIsMelee(it) then return Config.RageSwitchMelee == true end
            local a = itemAmmo(it)
            return a == nil or a > 0
        end
        local function slotOrder()
            local pref = PICK_SLOT[Config.RageWeaponPick] or 1
            local order = { pref }
            for _, s in ipairs({ 1, 2, 3 }) do
                if s ~= pref then order[#order + 1] = s end
            end
            if not Config.RageSwitchMelee then
                local filtered = {}
                for _, s in ipairs(order) do if s ~= 3 then filtered[#filtered + 1] = s end end
                order = filtered
            end
            return order
        end
        local function nextUsableSlot(excludeIdx)
            for _, s in ipairs(slotOrder()) do
                if s ~= excludeIdx and slotUsable(s) then return s end
            end
            return nil
        end
        -- ONE equip action per switch, delivered through the game's OWN path. The speculative
        -- {Equip,Switch,Select,EquipItem,ChangeItem} UseItem:FireServer loop is GONE: those enum names were
        -- never verified, the payload was nil where a real shot sends a table, and no legitimate client emits
        -- five item actions for one ObjectID inside a frame — pure garbage on the same replication remote our
        -- shots ride. The synthetic hotkey is now a FALLBACK ONLY (firing it alongside lf:EquipItem replicated
        -- the same equip twice at up to 16 Hz — a cadence no human input path can produce).
        local function equipSlot(idx)
            if not idx then return false end
            if whichSlotNow() == idx then return true end
            local now = tick()
            if now - (State.RageSwitchLast or 0) < (Config.RageSwitchRateLimit or 0.06) then return false end
            State.RageSwitchLast = now
            local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
            local equipped = false
            if lf and lf.EquipItem then
                equipped = pcall(function() lf:EquipItem(idx) end)
            end
            if not equipped then
                pcall(function()
                    local kc = ({ Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three })[idx]
                    if kc then
                        VirtualInputMgr:SendKeyEvent(true, kc, false, game)
                        VirtualInputMgr:SendKeyEvent(false, kc, false, game)
                    end
                end)
            end
            return true
        end
        Rage._equipSlot = equipSlot
        Rage._nextUsableSlot = nextUsableSlot
        Rage._whichSlotNow = whichSlotNow   -- APEX economy bridge (fire-then-swap slot resolution)
    end)()

    -- SHOT RE-ENCODER — the ONLY thing that redirects our fire onto the target (08 hook calls
    -- Rage._encodeRageShot on every Gun.StartShooting while Config.Rage, whether the engine asked for that shot
    -- or the player pressed M1). The engine stores THIS shot's solution in State.RageFire*; here we
    -- overwrite char0-3 of the GAME's own camData table via buildShotFields (char0 = a lookCF on-head eye,
    -- char1 = that eye lowered by RageEyeMuzzleSep so the two are DISTINCT, char2 = the live head, char3 = a
    -- clamped + re-jittered object-space offset — NEVER char0==char1 and NEVER char3=identity, which is the
    -- pair every banned build shipped and which the packetshape gate now refuses to bundle), and — because
    -- the game's StartShooting pipeline re-enters us at
    -- ITS own cadence — we RE-ENFORCE the identical ammo/reload/equip/rate gate here so a redirected shot can
    -- never resolve in an impossible weapon state or over-rate. Re-validation means a stale/deferred read can
    -- only bail (leaving the game's own camData intact), never ship a mismatched one. Increments State.Shots
    -- exactly once per redirected packet.
    local function encodeRageShot(camData)
        -- FRESHNESS FIRST (single-frame solution). The engine's ask is SYNCHRONOUS: polarFire stamps
        -- State.RageFireStamp, then drives lf:Input, and the game's Gun.StartShooting re-enters us inside that
        -- same call — so a shot the engine asked for always reads an age of ~0. Anything older is a shot the
        -- engine did NOT ask for this frame (the player's physical M1, which 08 no longer suppresses, or the
        -- game's trigger-held auto-fire) arriving against a solution the engine has since abandoned. The
        -- contents below would all still validate against it — the stale head is parented, sane, point-blank
        -- from the stale eye and has LOS — so without this test we would rewrite char0 to an on-head eye while
        -- our replicated body sits 130k studs away in the deep void. 07b clears the solution on every declining
        -- frame; this bounds the frames it cannot see (a tick the driver skipped entirely).
        if tick() - (State.RageFireStamp or 0) > 0.03 then return false end
        local hitPart = State.RageFireHitPart
        local eyePos  = State.RageFireFromPos
        local aimPos  = State.RageFireAimPos
        if not (hitPart and hitPart.Parent and eyePos and aimPos) then return false end
        if not isSanePos(eyePos) or not isSanePos(hitPart.Position) then return false end
        if (hitPart.Position - eyePos).Magnitude > (400 - 5) then return false end
        local ignore = { lp.Character }
        local t = State.RageTarget or State.Target
        if t and t.Character then ignore[2] = t.Character end
        if not hasLOS(eyePos, hitPart.Position, ignore) then return false end

        -- IMPOSSIBLE-STATE + RATE GATE (natural path is upstream of the engine choke, so gate HERE too).
        local item = getEquippedItem(); if not item then return false end
        local okE, equipping = pcall(function() return item:IsEquipping() end)
        if okE and equipping then return false end
        if not (Rage._itemIsMelee and Rage._itemIsMelee(item)) then
            local okR, reloading = pcall(function() return (item._reload_cooldown or 0) > tick() end)
            if okR and reloading then return false end
            local okA, ammo = pcall(function() return item:Get("Ammo") end)
            if not okA or type(ammo) ~= "number" or ammo <= 0 then return false end
        end
        local now = tick()
        -- Our own optional ask-spacing dial (07b fireInterval; 0 on shipped defaults = every frame). The old
        -- `or 0.07` fallback here would have silently throttled us to 14/s if the export ever went missing —
        -- and it can't: 07b runs at load inside this same IIFE.
        local interval = 0
        if Rage._fireInterval then interval = Rage._fireInterval() end
        if now - (State.RageLastFireTime or 0) < interval then return false end
        State.RageLastFireTime = now

        -- REWRITE the game's fields through the SAME builder silent aim uses. The old shape here (char0 == char1, char3 =
        -- EncodeCFrame(CFrame.new(0,0,0))) is a packet no real client can produce: char3 = identity makes the
        -- server's endpoint (char2.CFrame * char3) the hitbox CENTROID — a point INSIDE a solid part that no
        -- surface raycast can return, byte-identical on every shot from every account. Silent aim has always
        -- gone through buildShotFields and has never been detected; rage never did and always was.
        -- ★ NaN TRAP: the rage eye sits STRAIGHT ABOVE the head, so the look is exactly (0,-1,0) and
        -- CFrame.new(eyePos, aimPos) NaNs its WHOLE rotation, not just RightVector. Translating the eye CFrame
        -- cannot INTRODUCE a NaN, but it faithfully carries the one already there — which is why the muzzle
        -- must be built from lookCF, not from CFrame.new. Still do NOT copy encodeShot's `RightVector * 0.2`
        -- offset here: a near-vertical look makes RightVector meaningless even when it is finite.
        local eyeCF    = lookCF(eyePos, aimPos)
        local muzzleCF = eyeCF - Vector3.new(0, Config.RageEyeMuzzleSep, 0)
        buildShotFields(camData, eyeCF, muzzleCF, hitPart, aimPos, true, RAGE_CLAMP_FRAC, RAGE_JITTER_FRAC)

        State.Shots = State.Shots + 1
        return true
    end

    -- ── TARGET SYSTEM ───────────────────────────────────────────────────────
    local function findTarget()
        local myChar = lp.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local cands  = {}
        for _, p in ipairs(getSafePlayers()) do
            if isValidTarget(p, Config.RageVisCheck, true, true) then   -- keepDeflect + rageScope: rage flanks, and acquires THROUGH a hide
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                -- a hidden enemy's HRP can be NaN/1e5+; keep that out of the sort below and rank them last
                local d = 9999
                local sane = myRoot ~= nil and hrp ~= nil and isSanePos(hrp.Position)
                if sane then d = (hrp.Position - myRoot.Position).Magnitude end
                -- ★ RANGE CAP RESTORED 2026-08-02 — the divergence that made bundled Polar lose to Kicia.
                -- isValidTarget's rageScope skips BOTH the sanity test and MaxDistance. Skipping sanity is
                -- right (we shoot char2 from a park, so a hidden enemy must stay acquirable), but skipping
                -- MaxDistance is not: with RageHPPriority the sort is HP-first, so ANY lower-HP enemy
                -- anywhere on the map outranks the one currently shooting us, and polarTick then teleports
                -- our body onto THEIR head — thousands of studs away from the actual fight. The standalone
                -- caps candidates at MaxDistance and therefore cannot be pulled off the live threat.
                -- MEASURABLE enemies past the cap are dropped; UNMEASURABLE (hidden) ones stay candidates
                -- at d = 9999 so acquire-through-a-hide still works and they simply rank last.
                if (not sane) or d <= (Config.MaxDistance or 1200) then
                    table.insert(cands, { p = p, hp = hum.Health, d = d })
                end
            end
        end
        if #cands == 0 then return nil end
        if Config.RageHPPriority then
            table.sort(cands, function(a, b)
                if math.abs(a.hp - b.hp) > 10 then return a.hp < b.hp end
                return a.d < b.d
            end)
        else
            table.sort(cands, function(a, b) return a.d < b.d end)
        end
        return cands[1].p
    end
    Rage._findTarget = findTarget

    -- APEX scorer: findTarget + a per-candidate head-sane term + a head-sane-first sort key. Head-surfaced
    -- enemies sort ahead of voided ones unconditionally (swing to whoever we can actually hit right now), then
    -- HP/distance as usual. The head term is scoped to APEX here (isValidTarget stays the shared gate, entered
    -- with rageScope) so Polar's acquire never drifts.
    local function findTargetHeadSane()
        local myChar = lp.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local cands  = {}
        for _, p in ipairs(getSafePlayers()) do
            if isValidTarget(p, Config.RageVisCheck, true, true) then   -- keepDeflect + rageScope: rage flanks, and acquires THROUGH a hide
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hh  = p.Character:FindFirstChild("HitboxHead") or p.Character:FindFirstChild("Head")
                local headSane = false
                if hh and isSanePos(hh.Position) then headSane = true end
                local d = 9999
                if myRoot and hrp and isSanePos(hrp.Position) then d = (hrp.Position - myRoot.Position).Magnitude end
                table.insert(cands, { p = p, hp = hum.Health, d = d, s = headSane })
            end
        end
        if #cands == 0 then return nil end
        table.sort(cands, function(a, b)
            if a.s ~= b.s then return a.s end   -- head-sane candidates first, unconditionally
            if Config.RageHPPriority and math.abs(a.hp - b.hp) > 10 then return a.hp < b.hp end
            return a.d < b.d
        end)
        return cands[1].p
    end
    Rage._findTargetHeadSane = findTargetHeadSane

    -- ⛔ THE MELEE READOUT LIVES HERE, NOT IN THE POLAR DRIVER (2026-08-07, after nine failed rounds).
    -- The old one printed from the TAIL of polarTick, which made it silent in every case that mattered:
    -- each of the eight `return hide(...)` branches above it skips it, and in ORBIT 07c stops itself on its
    -- first frame so the line never appears at all. "No output and no attack" was therefore
    -- indistinguishable from "this feature does not exist in the mode you are in" — which is the literal
    -- truth in Orbit, where there is no melee bot of any kind, and our own post-knife-kill hint pushes the
    -- operator there. This loop runs in BOTH modes for as long as rage is on, so the line always appears.
    -- A nil RageKnifeStatus is the single most informative reading available: it means meleeStrike was
    -- never entered, so nothing about the packet can be the cause.
    local _meleeLogAt = 0
    local function meleeReadout()
        if Config.RageMeleeLog == false then return end
        local now = tick()
        if now - _meleeLogAt < 1 then return end
        local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
        local item = lf and lf.EquippedItem
        if not item then return end
        if not (Rage._itemIsMelee and Rage._itemIsMelee(item)) then return end
        _meleeLogAt = now
        local mode = Config.RageMode or "Polar"
        if mode ~= "Polar" then
            print("[LuaHook] melee: the knife bot is POLAR-ONLY and rage mode is " .. mode
                .. " — no melee code runs at all in this mode. Switch Rage > Mode to Polar.")
            return
        end
        local why = State.RageKnifeStatus
        if why == nil then
            why = "NEVER REACHED (rage=" .. tostring(State.RageStatus) .. ")"
        end
        print("[LuaHook] melee=" .. tostring(why)
            .. " swings=" .. tostring(State.RageKnifeSwings or 0)
            .. " rage=" .. tostring(State.RageStatus)
            .. " target=" .. tostring(State.RageTarget and State.RageTarget.Name or "none"))
    end

    -- Target-acquisition loop. KEEP: it fills State.RageTrueVelocityMap (calculateLead's fallback at
    -- 05_utils) as a side effect, so deleting it would feed stale lead data. Also maintains State.Target.
    local function startTargetLoop()
        if _tgtConn then _tgtConn:Disconnect() end
        local lastPosMap, lastTimeMap = {}, {}
        _tgtConn = RunService.Heartbeat:Connect(function()
            if not Config.Rage then return end
            pcall(meleeReadout)   -- runs in BOTH modes and past every driver early-return; see above
            local nowTime = tick()
            local safe = getSafePlayers() or {}
            for i = 1, #safe do
                local p = safe[i]
                if p ~= lp and p.Character then
                    local pRoot = p.Character:FindFirstChild("HumanoidRootPart")
                    if pRoot then
                        local currentPos = pRoot.Position
                        if lastPosMap[p] and lastTimeMap[p] then
                            local dt = nowTime - lastTimeMap[p]
                            if dt > 0 then State.RageTrueVelocityMap[p] = (currentPos - lastPosMap[p]) / dt end
                        end
                        lastPosMap[p] = currentPos
                        lastTimeMap[p] = nowTime
                    end
                end
            end
            if Config.RageFastTargetSwitch and State.Target and not isValidTarget(State.Target, false, true, true) then
                State.Target = nil
            end
            State.Target = findTarget()
        end)
    end
    Rage._startTargetLoop = startTargetLoop

    -- LAB-gated enemy-damage poll (feeds State.RageDealtTotal for the Lab trade readout). HealthChanged
    -- misses on desynced/streamed enemies, so we diff Humanoid.Health each frame. Costs nothing when the
    -- Lab is off (early return). 1v1-accurate; attributes any enemy HP loss to us.
    local function startLabPoll()
        if _labConn then return end
        local lastHP = {}
        _labConn = RunService.Heartbeat:Connect(function()
            if not Config.RageLab then return end
            local safe = getSafePlayers() or {}
            for i = 1, #safe do
                local p = safe[i]
                if p ~= lp then
                    local c = p.Character
                    local hum = c and c:FindFirstChildOfClass("Humanoid")
                    if hum then
                        local h, last = hum.Health, lastHP[p]
                        if last and h < last - 0.5 then
                            State.RageDealtTotal = (State.RageDealtTotal or 0) + (last - h)
                            if p == State.Target then State.Hits = State.Hits + 1 end
                        end
                        lastHP[p] = h
                    else
                        lastHP[p] = nil
                    end
                end
            end
        end)
    end
    Rage._startLabPoll = startLabPoll

    -- Counter-cheat detector was ripped in the clean rewrite; the Lab still reads Rage._isCheater, so keep
    -- an inert stub (never flags anyone).
    Rage._isCheater = function() return false end

    -- ── LIFECYCLE ───────────────────────────────────────────────────────────
    function Rage.init()
        for _, p in ipairs(getSafePlayers()) do bump(p) end
        Players.PlayerAdded:Connect(function(p)
            bump(p)
            p.CharacterAdded:Connect(function() bump(p) end)
        end)
        for _, p in ipairs(getSafePlayers()) do
            p.CharacterAdded:Connect(function() bump(p) end)
        end
        Players.PlayerRemoving:Connect(function(p)
            State.RageCharTokens[p] = nil
        end)
        lp.CharacterAdded:Connect(function()
            bump(lp)
            State.RageRealCF = nil; State.RageRealChar = nil
            State.RageParkDirty = false   -- disarm the latch guard with the anchor (07b: a stranded flag = rage dead)
            State.RageTarget = nil
        end)
        bump(lp)
        startLabPoll()
    end

    -- â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
    -- POLAR RAGE â€” the LIVE-PROVEN Kicia-beater (7-0, re-confirmed 5-0). ONE behavior, no modes, no fire
    -- handcuffs. Every Heartbeat: teleport the replicated body POINT-BLANK onto the enemy's live HitboxHead
    -- (no lead, no offset â€” LOS + range + eye-body consistency come free from the point-blank teleport) and
    -- ASK THE GAME for a shot at the live head; when the enemy's head is UNREACHABLE (beyond isSanePos, so the
    -- server's |eye - char2| <= 400 can never hold) we ask for NOTHING and hide â€” a shot that cannot land is pure
    -- exposure. Deep-void hide ONLY when there is nobody to shoot (no target / low HP / reloading).
    --   WHO SHOOTS: both paths exist and Config.RageDirectFire picks one. true (DEFAULT) = FORGED burst: we
    --   build RageTaps packets ourselves and FireServer them, each tap re-jittering char3 and re-checking char2
    --   is still parented. false = NATURAL: ask via lf:Input("StartShooting") and let the game's real
    --   Gun.StartShooting rule + send, with 08 -> 07a encodeRageShot rewriting char0-3 of its camData in place.
    --   Delivery is NOT the ban vector (2026-07-27 soak); the packet SHAPE was, and both paths share the same
    --   builder.
    --   PACKET SHAPE: char0 = Rage._lookCF(eye, head) and char1 = that eye lowered by RageEyeMuzzleSep, so the
    --   two are DISTINCT; char2 = the live head instance; char3 = a clamped, per-tap re-jittered object-space
    --   offset from Rage._buildShotFields. ⚠ NEVER char0 == char1 and NEVER char3 = identity — that pair is
    --   what every banned build shipped, and the packetshape build gate now refuses to bundle it. The eye sits
    --   straight above the head, which is the degenerate direction for CFrame.new(from, to), so the eye MUST
    --   come from lookCF (it rolls off world-Z there) or the whole rotation goes NaN — see the lookcf gate.
    -- MOVEMENT MODEL (path-separation): the desync is CFrame-ONLY, position-ONLY. The void/park is written at
    -- Heartbeat (post-physics, the LAST write before the engine network-samples the RootPart -> that is what
    -- replicates the desync). The real pose is restored TWICE per frame, both strictly UPSTREAM of the next
    -- Heartbeat park so neither can weaken a shot: at the Camera-1 render step (own screen renders normal
    -- every frame incl. firing) and at Stepped (pre-physics backstop â€” physics then integrates from the real
    -- spot = native movement, and a throttled/dropped render frame can never let the Heartbeat-top capture
    -- latch the park as our "real" pose). Both restores are UNCONDITIONAL: no skip-while-firing, no overlay,
    -- no input lock, no takeover. Velocity + every BodyMover + the slide-jump impulse are NEVER touched â€” we
    -- only write hrp.CFrame's position (keeping the game's rotation).
    local _rageConn, _rageCharConn = nil, nil
    local _rageStepConn = nil               -- pre-physics (Stepped) restore backstop
    local _rageRestoreName = "__lh_rage_restore"
    local _rageDiedConn = nil               -- per-life Humanoid.Died hook (knife-death -> suggest Orbit hint)
    local _rageCooldownConn = nil           -- per-frame client-cooldown defeat (mirrors OldLuahook.txt:1008-1016)

    -- FIRE INTERVAL â€” our OWN optional spacing between ASKS. It is no longer a legality gate: the GAME rules on
    -- every shot now (the fire seam only asks via lf:Input and the real Gun.StartShooting decides), and the
    -- per-frame cooldown defeat in startRage removes the weapon's client throttle. Shipped default 0 = ask once
    -- per Heartbeat (~60/s, one game-built shot each). >0 forces a minimum interval between asks â€” a hand dial
    -- for cadence experiments, never a correctness gate. Read by the fire seam and by 07a encodeRageShot on emit.
    local function fireInterval()
        return Config.RageFireRateOverride or 0
    end
    Rage._fireInterval = fireInterval

    -- ── ORBIT DESYNC PRIMITIVES (2026-08-07, ported from 07c seams S8/S14/S15) ──────────────────────
    -- Orbit was still running the design 07c retired: both restore anchors suppressed for the whole burst.
    -- That renders the vantage (the operator watches himself teleport), steps physics on the displaced
    -- body (dead movement mid-burst) and pins "home" to a stale snapshot. Kicia suppresses nothing — it
    -- re-displaces every Heartbeat and undoes it at the first render callback of the next frame, so the
    -- displaced pose exists ONLY across the frame boundary: sampled by the network, never rendered.
    -- ★ 2026-08-09 — WRITE PATH ALIGNED WITH 07c (S34). This used to use the raw `getrawmetatable(game)
    -- .__newindex`, and the header above still described that as "shared with 07c so there is ONE
    -- implementation". It was never shared — 07c has its own displace — so the two drivers had drifted
    -- into two different write mechanisms, and Orbit kept the fragile one: a metatable that can be
    -- protected, and a single throw that sets `_rawSet = nil` and silently downgrades every remaining
    -- write of the session to a bare assignment. That is the exact session-dependence removed from Polar.
    -- daydreamer's route instead (ragerewrite.lua L1382-1397): elevate thread identity to 8 around a plain
    -- assignment, restore the previous identity, fall back to a bare assignment only if the API is absent.
    -- Same intent as Kicia's raw write — do not let the write be observed or refused at script identity —
    -- with nothing that can permanently disable itself mid-session.
    local _preParkCF = nil
    local _identGet, _identSet, _identTried = nil, nil, false

    local function rawSetCFrame(hrp, cf)
        if not _identTried then
            _identTried = true
            pcall(function()
                local g = getthreadidentity or get_thread_identity
                local s = setthreadidentity or set_thread_identity or setidentity or setthreadcontext
                if type(g) == "function" and type(s) == "function" then _identGet, _identSet = g, s end
            end)
        end
        if _identSet ~= nil then
            local okPrev, prev = pcall(_identGet)
            if okPrev then
                pcall(_identSet, 8)
                local wrote = pcall(function() hrp.CFrame = cf end)
                pcall(_identSet, prev)
                if wrote then return true end
            end
        end
        return pcall(function() hrp.CFrame = cf end)
    end

    local function displace(hrp, cf)
        if _preParkCF == nil then _preParkCF = hrp.CFrame end
        return rawSetCFrame(hrp, cf)
    end
    Rage._displace = displace

    -- ORBIT PRIME. One stock physics-sender period (Kicia's own 1/15s literal) plus the anti-predictor
    -- jitter, held on the vantage rather than in the void. ORBIT_JUMP is what makes it Orbit-specific:
    -- Polar's park drifts a stud a frame so a slightly-stale replicated park still lands, but Orbit
    -- TELEPORTS to a new orbit point and a stale one is metres wrong — so the dwell is re-served on any
    -- discontinuity, not just on the exit from a hide.
    local ORBIT_PRIME_S   = 0.07
    local ORBIT_JITTER_MAX = 0.25
    local ORBIT_JUMP      = 5      -- studs of vantage movement that counts as a discontinuity
    local _orbHiding      = true
    local _orbPrimeUntil  = 0
    -- Orbit's copy of 07c seam S33. Same ceiling, same per-target reset, same fail-toward-shooting rule.
    local ORB_IMMUNE_MAX_HOLD = 6.0
    local _orbImmuneSince, _orbImmuneTgt = 0, nil
    local _orbLastDisp    = nil

    -- PRECISION-SAFE deep void (magnitude 110k-140k). Y is POSITIVE-ONLY: above FallenPartsDestroyHeight's
    -- +50000 clamp so the hidden body is never swept by the fallen-parts kill plane (underground = terrain
    -- blocks LOS = a tell). Non-sane (isSanePos false) so the sane-guard never latches it, still float32
    -- sub-stud so physics integrates cleanly (why not +-2e9). Cleared on respawn. Per-axis 110-140k => |pos|
    -- ~190-242k; Kicia's MEASURED hide is 90,072 and is undetected, so this sits outside the only envelope we
    -- know to be safe. Both radii are >>400 studs, so radius alone cannot change a fight -- only how far out we sit.
    --
    -- ★ MOVING HIDE (2026-08-02, Config.RageVoidMove). This spot used to be HELD 4-8s, and the note here argued
    -- that a per-frame re-roll would read as an impossible position-vs-velocity delta. LIVE RESULT OVERRULES IT
    -- ON POWER: re-rolling every hide frame is what makes this build destroy Kicia and very nearly beat UE. A
    -- STATIC far-out body is precisely the config UE follows and kills (MEASURED 2026-07-31: far out + static =
    -- 210 dmg / 14 hits taken; far out + moving = 0 dmg over 30s). What protects is DISPLACEMENT > 400 studs per
    -- network sample, which stales the attacker's pre-baked char0 before it arrives; standing still protects at
    -- no radius.
    -- ⚠ THE DETECTION CONCERN IS REAL AND UNMEASURED. A held spot replicates as a stationary body; this
    -- replicates as a ~200k-stud jump every sample, which is the loudest thing in the build against any
    -- JustWarped-style movement telemetry. The live test proved POWER, not undetection, and bans are delayed.
    -- Two retreats, no rebuild needed: RageVoidMove=false restores the proven-quiet 4-8s hold, and
    -- RageVoidJitterLocal keeps ONE base spot and only offsets it -- still clearing 400/sample, at ~1% of the
    -- position delta.
    local function voidAxis()
        local v = math.random(110000, 140000)
        if math.random(0, 1) == 0 then
            return -v
        end
        return v
    end

    local function rollVoid()
        return CFrame.new(voidAxis(), math.random(110000, 140000), voidAxis())
    end

    -- Consecutive draws land close whenever X and Z both keep their sign (~15% of the time), so every path
    -- below re-rolls WITH a recheck: the value returned has always cleared minStep against the previous spot.
    local function stepClears(cf, prev, minStep)
        if not prev then return true end
        return (cf.Position - prev.Position).Magnitude >= minStep
    end

    local function voidCFrame()
        local now = tick()

        if not Config.RageVoidMove then
            if (not State.RageVoidCF) or now >= (State.RageVoidNext or 0) then
                State.RageVoidCF   = rollVoid()
                State.RageVoidNext = now + 4 + math.random() * 4
            end
            return State.RageVoidCF
        end

        local prev = State.RageVoidCF
        local cf

        if Config.RageVoidJitterLocal then
            -- Hold one base spot; move only far enough to stale their char0. Each axis offset is at least
            -- 500 studs in magnitude, so the offset vector is >=866 studs -- comfortably past 400 -- while the
            -- per-sample delta stays ~2 orders of magnitude smaller than a full re-roll.
            if (not State.RageVoidBase) or now >= (State.RageVoidNext or 0) then
                State.RageVoidBase = rollVoid()
                State.RageVoidNext = now + 4 + math.random() * 4
            end
            local base = State.RageVoidBase.Position
            local span = Config.RageVoidJitterStuds or 2000
            local function offset()
                local v = 500 + math.random() * (span - 500)
                if math.random(0, 1) == 0 then
                    return -v
                end
                return v
            end
            local tries = 0
            repeat
                cf = CFrame.new(base.X + offset(), math.max(base.Y + offset(), 110000), base.Z + offset())
                tries = tries + 1
            until tries >= 8 or stepClears(cf, prev, 600)
        else
            local minStep = Config.RageVoidMinStep or 25000
            local tries = 0
            repeat
                cf = rollVoid()
                tries = tries + 1
            until tries >= 8 or stepClears(cf, prev, minStep)
        end

        State.RageVoidCF    = cf
        State.RageVoidSteps = (State.RageVoidSteps or 0) + 1
        return cf
    end

    -- RAGE PROTECTION GATE = the standalone's, exactly: ForceField only. The shared isProtected (05_utils) also
    -- scans 11 attributes and every descendant BasePart/ParticleEmitter NAME for shield/aura/guard/spawn/... â€”
    -- and Rivals parents item models ("Riot Shield", "Energy Shield", "Barrier") under the Character, so that
    -- scan latches a legitimate enemy PERMANENTLY and rage would hide forever with a live target in front of it.
    -- Aim/ESP keep the shared predicate (they only lose one candidate, not the whole engagement).
    -- ★ SPAWN PROTECTION (2026-07-28). The ForceField test above can NEVER fire — the Rivals dump
    -- contains ZERO ForceField Instances — so spawn protection was invisible to rage and we burned the
    -- opening burst into an invincible target every round. The real signal is ClientEntity:Get
    -- ("IsInvincible"), which is exactly what Elysium gates on: `if not target_entity or
    -- target_entity:Get('IsInvincible') then DesyncService:Stop() return end` (elisium src.txt:14717).
    -- Reached through the SAME handle getWeaponName already uses (05_utils:166-167): the
    -- FighterController's _player_to_fighter map -> .Entity. pcall'd and failing CLOSED-as-NOT-protected,
    -- so an API drift degrades to today's behaviour (fire anyway) instead of hiding forever.
    -- ★ BOUNDED 2026-08-02 — THE STANDALONE DIVERGENCE THAT MAKES BUNDLED POLAR LOSE TO KICIA.
    -- The standalone's gate is ForceField ONLY, and the Rivals dump contains ZERO ForceField instances, so the
    -- standalone effectively never skips anyone. This gate also reads Entity:Get("IsInvincible") — the REAL
    -- spawn-protection signal — but an unbounded belief in it is catastrophic: if that value ever reads true for
    -- a live enemy (a rival cheat flagging itself, or a stale replicated value on a desyncing entity) we return
    -- hide() every frame and emit ZERO packets. That is not "losing a fight", it is never taking one, and it is
    -- exactly the recorded symptom "bundled Polar refuses every target and emits zero packets".
    -- Spawn protection is BRIEF by definition, so bound it: once a target has read invincible continuously for
    -- longer than RageImmuneMaxHold we stop believing the flag and engage. Genuine spawn protection is still
    -- skipped; a stuck or hostile flag can never lock out an engagement again.
    -- (isProtectedRage and its bounded-immunity cache are GONE with Polar. 07c uses the standalone's gate --
    -- ForceField only -- because the Rivals dump ships zero ForceFields, so it never refuses a target; the
    -- IsInvincible term it replaced could latch true and make rage emit zero packets forever. Orbit's guard
    -- ladder never consulted either one. NOTE: that leaves the GUI's "Skip immune targets" toggle inert for
    -- both modes -- see the Orbit collateral task before deciding whether Orbit should honour it.)

    -- WEAPON READY (drives the void-vs-fire branch and pre-gates the ask). Not equipping, not reloading, and â€”
    -- for anything with a magazine â€” ammo > 0. The melee exemption sits BELOW the reload test on purpose: it
    -- used to short-circuit above it, so a melee item mid-reload-cooldown read as ready and we asked the game
    -- for a shot 07a encodeRageShot would then refuse. oldStart runs first and our camData overwrite is
    -- in-place-or-nothing, so that combination ships the GAME's own camData: a real shot from the real camera
    -- while our body is parked on an enemy head. Melee keeps the AMMO exemption only (it has no magazine, so
    -- `Ammo` reads nil and a magazine test would fail closed and never swing).
    local function weaponReady(it)
        if not it then return false end
        local okE, equipping = pcall(function() return it:IsEquipping() end)
        if okE and equipping then return false end
        if (it._reload_cooldown or 0) > tick() then return false end
        if Rage._itemIsMelee and Rage._itemIsMelee(it) then return true end
        local okA, ammo = pcall(function() return it:Get("Ammo") end)
        return okA and type(ammo) == "number" and ammo > 0
    end

    -- Behind-the-front-arc flank point vs a katana (deflect) or riot shield (block) â€” both only guard the
    -- FRONT, so we get behind them. ORBIT/APEX ONLY: Polar always parks on the head (standalone geometry).
    -- These are the ONLY remaining rage raycasts and are intentional (they protect the backstab geometry, not
    -- gate the shot). Returns a behind-target point with verified LOS to the head, or nil (=> point-blank).
    local function flankPoint(tgt, hh)
        if not tgt or not tgt.Character or not hh or not isSanePos(hh.Position) then return nil end
        local katana = Config.AvoidDeflect and isKatana(tgt)
        local shield = Config.RageShieldBackstab and isRiotShield(tgt)
        local stowed = Config.RageShieldBackstab and ownsRiotShield(tgt)
        if not (katana or shield or stowed) then return nil end
        local thrp = tgt.Character:FindFirstChild("HumanoidRootPart")
        if not thrp then return nil end
        -- the server's deflect/block arc tests the target's REPLICATED HRP CFrame (Katana:StartAiming sends
        -- no camData) = the CFrame we read here, so -LookVector is genuinely their front. Flatten to
        -- horizontal and bail on a degenerate near-vertical facing.
        local look = thrp.CFrame.LookVector
        look = Vector3.new(look.X, 0, look.Z)
        if look.Magnitude < 1e-3 then return nil end
        -- ★ 2026-08-07 — THE STOWED SHIELD INVERTS THIS. Kicia's cones (cleaned leak L139738) are:
        --   equipped Riot Shield, not attacking : 133.8 deg cone across their FRONT  -> attack from BEHIND
        --   Riot Shield merely OWNED, stowed    :  88.6 deg cone across their BACK   -> attack from the FRONT
        -- We only ever did the first, so against anyone carrying a shield they were not holding we walked
        -- our knife straight into the one arc it covers. A stowed shield only matters when nothing more
        -- urgent does: a live katana deflect REFLECTS our damage, so that still wins the tie.
        local inv    = -look.Unit
        if not katana and not shield and stowed then inv = look.Unit end
        local anchor = hh.Position   -- anchor on the LIVE head (a desyncing katana user voids HRP; head stays live)
        local kf     = killFloor()
        local dist   = shield and 2.5 or 3.0
        local ignore = { tgt.Character, lp.Character }
        local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = ignore
        local flank = anchor + inv * dist
        local wr = workspace:Raycast(anchor, inv * dist, rp)   -- don't clip through a wall behind them
        if wr then flank = wr.Position - inv * 0.5 end
        flank = Vector3.new(flank.X, math.max(flank.Y, kf + 3), flank.Z)
        if not hasLOS(flank, hh.Position, ignore) then return nil end
        return flank
    end

    -- Polar's point-blank park (and its kill-plane clamp) moved to 07c_polar_core, where the clamp is
    -- unconditional -- the proven standalone has no switch for it, and following Kicia's Y = -16k..-53k hide
    -- down parks the REPLICATED body under the fallen-parts sweep, trading a harmless miss for a death.
    -- Orbit never parks point-blank, so nothing here needs it. Config.RageKillPlaneClamp is now inert.

    -- â”€â”€ THE FIRE SEAM (Polar and Orbit both fire through here) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    -- TWO DELIVERIES, ONE PACKET SHAPE.
    -- FORGED (Config.RageDirectFire, DEFAULT): we build and FireServer the UseItem packet Config.RageTaps times.
    -- NATURAL: we store the solution in State.RageFire* and ask the game â€” lf:Input("StartShooting") on an
    -- identity-2 thread, as OldLuahook.txt:1349-1354 â€” and the 08 hook rewrites the game's own camData in place.
    -- â˜… DELIVERY IS NOT THE BAN VECTOR. A build matching OldLuahook on delivery AND suppression AND scrub was
    -- still banned (2026-07-27 soak), which killed that hypothesis outright. What every banned build shared and
    -- no clean one did is the PACKET SHAPE: char0 == char1 and char3 = EncodeCFrame(CFrame.new(0,0,0)), an
    -- endpoint at the hitbox centroid that no surface raycast can return. Silent aim, in the same build on the
    -- same remote, has always built well-formed fields via buildShotFields and has never been detected.
    -- So BOTH paths now go through buildShotFields, and forged is default again for the burst damage.
    -- Runs in an un-pcall'd Heartbeat, so every fallible call is pcall-wrapped.
    local _shootEnum

    -- rageShotLeak DELETED 2026-08-06 together with the `__namecall` hook it fed (see the long note in
    -- 01_bootstrap). It was the send-side backstop for a real shot the game fired behind our back; the
    -- fail-closed suppression in 08_gunhook already stops that UPSTREAM for every Standard gun, and the
    -- only surface it uniquely covered was the 10 subclass items with their own StartShooting — none of
    -- them a rage weapon. State.RageTracerCanary is the surviving canary for that residual.
    -- State.RageForging is still set around our taps (07c seam S3 / 07b below) and is now purely a
    -- re-entrancy marker; leave it in place, the polarcore gate pins it.

    local function polarFire(eyePos, aimPos, hh)
        -- BLANK GATE (structural) + CANARY. The server's own invariant is |eye - char2| <= MAX_RAYCAST(400): a
        -- packet that fails it CANNOT land, so asking for it is pure exposure for zero damage. 395 mirrors the
        -- margin below. Phrased as can-land so a NaN eye/head fails CLOSED. Every mode funnels through this
        -- seam, so this is also the structural enforcement of "never fire what cannot land".
        local reach = 1e9
        if hh and hh.Parent then reach = (hh.Position - eyePos).Magnitude end
        if not (reach <= 395) then
            State.RageBlankCanary = State.RageBlankCanary + 1   -- refused blanks; MUST read 0 on shipped defaults
            return
        end
        local it = getEquippedItem()
        if not it then return end

        -- (A3's one-frame surface warmup lived here and was REMOVED 2026-07-29: measured zero effect on both
        -- stray-tracer symptoms, because neither is a replication-timing problem. The real cause is the
        -- degenerate straight-down look CFrame -- see lookCF in 07a.)

        -- â”€â”€ FORGED BURST (default) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        -- Every tap is REBUILT so the packets differ: six real shots never carry byte-identical geometry, and
        -- the old code shipped one table six times. Clamp/jitter band mirrors RAGE_CLAMP_FRAC in 07a (0.30 â€”
        -- tighter than silent aim's 0.45 because this eye is point-blank directly above the head).
        if Config.RageDirectFire then
            -- OPT-IN forged-burst rate gate (Config.RageRateLimit, default OFF). The forged path is
            -- otherwise unrated and re-sends the whole burst every Heartbeat; this holds it to one burst
            -- per weapon fire interval so accepted packets stop over-draining the magazine. Written here
            -- because 07a (the natural encoder) is the only other writer of RageLastFireTime and never
            -- runs on this path.
            if Config.RageRateLimit then
                if tick() - (State.RageLastFireTime or 0) < fireInterval() then return end
                State.RageLastFireTime = tick()
            end
            pcall(function()
                it._shoot_cooldown = 0
                it._shoot_cooldown_no_ammo = 0
                it._last_shot = tick() - 1
            end)
            if not (Rivals.Ready and Rivals.Enums and Rivals.Util) then return end
            if _shootEnum == nil then
                pcall(function() _shootEnum = Rivals.Enums:ToEnum("StartShooting") end)
            end
            if _shootEnum == nil then return end
            local okId, objId = pcall(function() return it:Get("ObjectID") end)
            if not okId or not objId then return end
            -- Eye and muzzle are fixed for the burst; only char3 re-jitters per tap. The eye looks straight
            -- DOWN at the head, so eyeCF MUST come from Rage._lookCF -- CFrame.new(eyePos, aimPos) NaNs its
            -- entire rotation there, and translating it just carries that NaN into char1 (see lookCF in 07a).
            local eyeCF    = Rage._lookCF(eyePos, aimPos)
            local muzzleCF = eyeCF - Vector3.new(0, Config.RageEyeMuzzleSep, 0)
            -- ★ 2026-08-09 — follows Polar's seam S29. Kicia sends exactly ONE attack per frame
            -- (weaponAction() is called once per ragebot Update, cleaned decompile L12330-12333) and our own
            -- measurement is that accepted packets are INVARIANT to volume. RageTaps stays at its legacy 6
            -- as the ceiling; RageTapsPerFrame is the live knob and both engines read it, so a tap A/B is
            -- one config flip that moves Polar and Orbit together instead of silently only moving one.
            local taps = Config.RageTapsPerFrame
            if type(taps) ~= "number" then taps = 1 end
            taps = math.max(1, math.min(math.floor(taps), math.floor(Config.RageTaps or 6)))
            local sent     = 0
            local rayCast  = false
            pcall(function() rayCast = it.Info.IsRaycast == true end)
            State.RageForging = true    -- whitelist OUR taps at the __namecall backstop (cleared below)
            pcall(function()
                local remote = ReplicatedStorage.Remotes.Replication.Fighter.UseItem
                for _ = 1, taps do
                    -- char2 LIVENESS, per tap. The burst is one Heartbeat but the target can die/despawn
                    -- inside it, and a tap carrying a destroyed char2 makes the server fall back to
                    -- projecting along char1's LookVector (Gun.luau:581) instead of hitting the part. That
                    -- fallback is what produces a tracer with no damage, so stop feeding it: taps 2..N
                    -- re-check the part is still parented before spending a packet on it.
                    if not (hh and hh.Parent) then break end
                    local inner = {}
                    Rage._buildShotFields(inner, eyeCF, muzzleCF, hh, aimPos, true, 0.30, 1.0)
                    -- Envelope slot 2 = the ADS flag (Gun.StartShooting's 4th return, IsFullyAiming), sent
                    -- for raycast weapons only. Kicia sends it on every hitscan shot; omitting it has the
                    -- server judge us at full hipfire spread. Mirrors 07c seam S16.
                    local env = { [utf8.char(1)] = inner }
                    if rayCast then env[utf8.char(2)] = true end
                    remote:FireServer(objId, _shootEnum, env, nil)
                    sent = sent + 1
                end
            end)
            State.RageForging = false   -- pcall cannot throw past this, so the flag can never latch on
            State.Shots = State.Shots + sent   -- count what actually went out, not what we intended
            return
        end
        -- PRE-GATE UPSTREAM (single-variable hygiene): only ask when THIS shot is currently ENCODABLE, mirroring
        -- the 07a gates before the real Gun.StartShooting runs. oldStart runs first and our camData overwrite is
        -- in-place-or-nothing, so asking for a shot 07a will bail on makes the GAME ship its OWN camData (real
        -- camera pose vs the parked body = an eye-body-mismatched, likely-no-LOS packet). The blank gate above
        -- already refused any unreachable head, so this only re-checks encodability. 07a stays the backstop (it
        -- re-reads + re-gates + is the sole writer of State.RageLastFireTime).
        if not weaponReady(it) then return end
        if not hh or not hh.Parent or not isSanePos(hh.Position) then return end   -- un-pcall'd dispatch: nil-guard
        local hpos = hh.Position
        if (hpos - eyePos).Magnitude > (400 - 5) then return end
        local ignore = { lp.Character }
        local tgt = State.RageTarget or State.Target
        if tgt and tgt.Character then ignore[2] = tgt.Character end
        if not hasLOS(eyePos, hpos, ignore) then return end
        if tick() - (State.RageLastFireTime or 0) < fireInterval() then return end
        State.RageFireFromPos = eyePos
        State.RageFireAimPos  = aimPos
        State.RageFireHitPart = hh
        State.RageFireStamp   = tick()   -- freshness bound; 07a refuses any solution older than a frame
        local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
        if not lf then return end
        task.spawn(function()
            if setthreadidentity then setthreadidentity(2) elseif setidentity then setidentity(2) end
            pcall(function() lf:Input("StartShooting") end)
            if setthreadidentity then setthreadidentity(8) elseif setidentity then setidentity(8) end
        end)
    end

    -- â”€â”€ FIRE-SOLUTION LIFETIME (single-frame) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    -- State.RageFire* is written ONLY by polarFire above and is the sole input to 07a encodeRageShot, which now
    -- runs on EVERY Gun.StartShooting while Config.Rage â€” including the player's own M1, because 08 no longer
    -- suppresses it. A solution that outlives its frame would therefore redirect a manual click (or the game's
    -- trigger-held auto-fire) onto the PREVIOUS engagement's head while our replicated body sits in the deep
    -- void: a forged on-head eye from a body 130k studs away, exactly the packet this seam exists to prevent.
    -- So the engine clears the solution on every frame it declines to fire, and the stamp bounds the paths the
    -- clears cannot see (a tick the driver skipped entirely) to one frame. 07a bails on the hit part alone, but
    -- clear all of it so no stale geometry survives for anything added later to read.
    local function clearFireSolution()
        State.RageFireFromPos = nil
        State.RageFireAimPos  = nil
        State.RageFireHitPart = nil
        State.RageFireStamp   = 0
    end

    -- â”€â”€ DEEP-VOID HIDE â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    -- We deep-void ONLY when there is nobody to shoot (no/low-HP/reloading). RageVoidHide=false keeps us at our
    -- REAL position between engagements (the render restore holds us home = a normal-looking player);
    -- =true teleports to the deep void. We NEVER self-void during a live engagement.
    -- (Polar's hide() lived here. It moved to 07c_polar_core with the rest of Polar; Orbit has always used
    -- orbitVoid instead, which voids unconditionally rather than honouring RageVoidHide.)

    -- â”€â”€ MODE TICKS (register-relief sub-IIFE) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    -- The mode ticks live in their OWN proto so they do not add to the outer rage
    -- IIFE's 190-local budget. They read the shared park/fire/void helpers above as upvalues (upvalues don't
    -- count against this proto's budget) and export the dispatcher onto Rage._rageTick for the Heartbeat driver.
    -- All modes fire ONLY through polarFire, which only ASKS the game (lf:Input) â€” never a shot packet of ours.
    ;(function()
        -- â”€â”€ ORBIT (stepped side-vantage rager, effective vs normal/legit players) â”€â”€
        -- Holds one LOS-clear vantage for a short dwell so replication settles + the burst lands, then jumps a
        -- golden angle the enemy isn't pre-aiming. NEVER fires from the void; no legal vantage => deep-void hide
        -- (unhittable). Fires through polarFire (the game-asks-the-shot seam). Knife enemies push the ring out.
        local function orbitVantage(aimPos, ignore, kf, knife)
            State.OrbitAngle = ((State.OrbitAngle or 0) + 2.39996) % (math.pi * 2)   -- golden-angle advance per repick
            local base = Config.RageCombatOrbitRadius or 60
            local radii
            if knife then
                radii = { math.max(base, 75), 95 }       -- knife enemy: push the ring out past their walk-back reach
            else
                -- CAP the wide ring at 380: polarFire refuses any shot with |eye - head| > 395 (the server's own
                -- MAX_RAYCAST invariant), so an uncapped base*1.5 at a high radius setting made Orbit teleport to
                -- a vantage and then emit NOTHING â€” a silent no-fire ring that also polluted RageBlankCanary.
                radii = { base, base * 0.6, math.min(base * 1.5, 380) }
            end
            for _, r in ipairs(radii) do
                for i = 0, 5 do
                    local ang    = State.OrbitAngle + i * (math.pi / 3)
                    local jitter = 0
                    if Config.RageCombatOrbitJitter then jitter = (math.random() - 0.5) * 14 end
                    local h = (Config.RageCombatOrbitHeight or 8) + jitter
                    local pos = Vector3.new(aimPos.X + math.cos(ang) * r,
                        math.max(aimPos.Y + h, kf + 6),
                        aimPos.Z + math.sin(ang) * r)
                    if isSanePos(pos) and not posIsOOB(pos) and hasLOS(pos, aimPos, ignore) then
                        return pos
                    end
                end
            end
            return nil
        end

        -- ORBIT's void exit. Orbit voids UNCONDITIONALLY (it must never fire from a vantage it can't reach, and
        -- honoring RageVoidHide=false would leave it standing exposed mid-engagement), so it can't share hide() â€”
        -- but it MUST still clear the frame flags. A latched RageFiring permanently yields the aimbot (09_aimbot)
        -- and mis-attributes every Lab death to ATTACK; RageVoidActive never set made the Lab HIDE readout lie.
        local function orbitVoid(hrp, status)
            State.RageStatus = status
            State.OrbitVantage = nil
            State.OrbitVantageUntil = 0
            State.RageFiring = false
            State.RageVoidActive = true
            clearFireSolution()
            -- ORBIT PRIME (mirrors 07c S12+S14): hiding drops the vantage, so the replication dwell has to
            -- be served again on the way out. Roll happens on the transition OUT, not here.
            _orbHiding = true
            _orbPrimeUntil = 0
            _orbLastDisp = nil
            Rage._displace(hrp, voidCFrame())
        end

        local function orbitTick(ch, hrp, tgt)
            local kf = killFloor()
            -- guard ladder: every "can't fire" case deep-voids (unhittable), never exposes at real
            if not tgt or not tgt.Character then
                return orbitVoid(hrp, "No target")
            end
            local tc   = tgt.Character
            local thrp = tc:FindFirstChild("HumanoidRootPart")
            local hh   = tc:FindFirstChild("HitboxHead") or tc:FindFirstChild("Head")
            if not hh or not isSanePos(hh.Position) then
                return orbitVoid(hrp, "Hiding")
            end
            if not weaponReady(getEquippedItem()) then
                return orbitVoid(hrp, "Reloading")
            end
            local aimPos = hh.Position
            if posIsOOB(aimPos) or aimPos.Y < kf + 1 then   -- kill-plane bait guard
                return orbitVoid(hrp, "Hiding")
            end
            local ignore = { tc, lp.Character }
            local vantage, status = nil, nil

            -- melee flank (katana/riot-shield) or our-knife backstab
            local flank = flankPoint(tgt, hh)
            if not flank and thrp and Config.RageKnifeBackstab and isLocalKnife() then
                local inv = -thrp.CFrame.LookVector
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                rp.FilterDescendantsInstances = ignore
                local f  = thrp.Position + inv * 3.0
                local wr = workspace:Raycast(thrp.Position, inv * 3.0, rp)
                if wr then f = wr.Position - inv * 0.5 end
                local cand = Vector3.new(f.X, math.max(f.Y, kf + 3), f.Z)
                if isSanePos(cand) and not posIsOOB(cand) and hasLOS(cand, hh.Position, ignore) then
                    flank = cand
                end
            end

            if flank then
                vantage = flank
                State.OrbitVantage = nil
                if isRiotShield(tgt) then
                    status = "Anti-riot"
                elseif isKatana(tgt) then
                    status = "Katana flank"
                else
                    status = "Backstab"
                end
            else
                local knife = isEnemyKnife(tgt)
                local held  = State.OrbitVantage
                if (not held) or tick() >= (State.OrbitVantageUntil or 0) or not hasLOS(held, aimPos, ignore) then
                    local v = orbitVantage(aimPos, ignore, kf, knife)
                    if v then
                        State.OrbitVantage = v
                        State.OrbitVantageUntil = tick() + (Config.RageOrbitDwell or 0.09)
                        held = v
                    elseif held and hasLOS(held, aimPos, ignore) then
                        State.OrbitVantageUntil = tick() + (Config.RageOrbitDwell or 0.09)
                    else
                        held = nil
                    end
                end
                if held then
                    vantage = held
                    if knife then status = "Orbit (kept dist)" else status = "Orbit" end
                end
            end

            if not vantage or not isSanePos(vantage) or posIsOOB(vantage) then
                return orbitVoid(hrp, "Orbit (hiding)")
            end
            State.RageStatus = status or "Orbit"
            State.RageVoidActive = false

            -- ★ ORBIT PRIME (2026-08-07). Orbit had the SAME first-shot defect Polar did, and worse: Polar's
            -- park tracks a head and drifts a stud a frame, so a slightly-stale replicated park still lands.
            -- Orbit JUMPS to a new orbit point every RageOrbitDwell, and a stale position there is metres
            -- wrong. Kicia holds a fresh position 1/15s (one stock physics-sender period) before its first
            -- shot; at the old 0.09s dwell Orbit was firing from an unreplicated vantage for most of every
            -- dwell. So: re-serve the dwell on any DISCONTINUITY in the replicated pose, which covers both
            -- the exit from a hide and every vantage jump, and is the honest statement of the requirement
            -- (the server must have received where we are now).
            local jumped = _orbLastDisp == nil or (vantage - _orbLastDisp).Magnitude > ORBIT_JUMP
            _orbLastDisp = vantage
            if _orbHiding or jumped then
                _orbHiding = false
                local extra = 0
                if Config.RageHideJitter ~= false then extra = math.random() * ORBIT_JITTER_MAX end
                _orbPrimeUntil = tick() + ORBIT_PRIME_S + extra
            end

            Rage._displace(hrp, CFrame.new(vantage))

            -- SPAWN PROTECTION (mirrors 07c S6): hold fire, do NOT hide. Packets are rejected by
            -- construction while IsInvincible is set, and un-parking would cost the whole re-approach the
            -- moment it clears -- the operator MEASURED that engaging protected targets wins. Fails open.
            -- ★ 2026-08-09 — BOUNDED, mirroring 07c seam S33. This was unbounded: if the IsInvincible
            -- mirror ever latched true (it could, before the isSpawnProtected subscribe-latch fix in
            -- 05_utils), Orbit held the vantage and emitted ZERO packets for the rest of that player's
            -- life, silently. Spawn protection is a few seconds and ends the moment the player acts, so
            -- past the ceiling the mirror is wrong, not the player. Fails toward SHOOTING: engaging a
            -- genuinely invincible target only wastes ammo (packets are rejected by construction), while
            -- holding fire on a killable one costs the round.
            local holdFire = false
            if Config.RageSkipImmune ~= false then holdFire = isSpawnProtected(tgt) end
            if not holdFire then
                _orbImmuneSince, _orbImmuneTgt = 0, nil
            else
                local nowI = tick()
                if _orbImmuneTgt ~= tgt then
                    _orbImmuneSince, _orbImmuneTgt = nowI, tgt
                end
                if nowI - _orbImmuneSince > ORB_IMMUNE_MAX_HOLD then
                    holdFire = false
                    State.RageImmuneOverride = (State.RageImmuneOverride or 0) + 1
                end
            end

            if holdFire then
                State.RageFiring = false
                State.RageStatus = "Protected — vantage held, holding fire"
            elseif tick() < _orbPrimeUntil then
                State.RageFiring = false
                State.RageStatus = "Priming"
            else
                State.RageFiring = true
                local eye = vantage + Vector3.new(0, Config.RagePBEyeUp or 3, 0)
                polarFire(eye, aimPos, hh)
            end
            pcall(Visuals.notifyTarget, tgt)
        end

        -- â”€â”€ DISPATCH â”€â”€
        -- ORBIT ONLY. Polar lives in 07c_polar_core.lua as a verbatim copy of the proven standalone and
        -- runs on its OWN anchors, so this driver never sees it: Rage.enable starts exactly one of the two,
        -- and each self-tears-down if it is no longer the selected mode. A Polar tick reaching here would
        -- mean the mode dispatch broke, so fail loud in the Lab readout rather than silently raging with
        -- the reimplementation this file was built to retire.
        local function rageTick(ch, hrp, tgt)
            if (Config.RageMode or "Polar") ~= "Orbit" then
                State.RageStatus = "Mode error"
                return
            end
            orbitTick(ch, hrp, tgt)
        end
        Rage._rageTick = rageTick
    end)()

    -- KNIFE-DEATH HINT: on our own death, if a knife/melee player killed us, suggest switching to Orbit (our
    -- knife counter). No attacker handle exists, so infer: engaged RageTarget is a knifer, else a knifer sits
    -- within melee range of our death pose. Rate-limited (>=90s) + skipped when already in Orbit. The whole body
    -- is pcall'd â€” it runs off Humanoid.Died (an un-pcall'd Roblox signal), and it FindFirstChilds into a
    -- possibly-dying character.
    local function onLocalDied()
        pcall(function()
            -- clamp-removal risk readout: did we die within a few frames of parking below the fallen-parts plane?
            -- Measured ABOVE the knife-hint early-returns so a hint gate can never swallow the measurement.
            if tick() - State.RageBelowPlaneLast < 0.5 then
                State.RageBelowPlaneDeaths = State.RageBelowPlaneDeaths + 1
                State.RageBelowPlaneLast = 0   -- latch: one attribution per loss (also blocks a double-count below)
            end
            if not Config.Rage then
                return
            end
            if Config.RageMode == "Orbit" then   -- already using our knife counter
                return
            end
            if tick() - (State.RageKnifeHintLast or 0) < 90 then
                return
            end
            local knifed = false
            local tgt = State.RageTarget
            if tgt and tgt.Parent and isEnemyKnife(tgt) then
                knifed = true
            else
                -- prefer the captured real pose (RageRealCF): the live HRP may be parked on the enemy this frame
                local dpos = nil
                local real = State.RageRealCF
                if real then
                    dpos = real.Position
                else
                    local ch = lp.Character
                    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        dpos = hrp.Position
                    end
                end
                if dpos then
                    for _, plr in ipairs(getSafePlayers()) do
                        if plr ~= lp and not (Config.TeamCheck and isTeammate(plr)) then
                            local r = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            if r and (r.Position - dpos).Magnitude <= 18 and isEnemyKnife(plr) then
                                knifed = true
                                break
                            end
                        end
                    end
                end
            end
            if not knifed then
                return
            end
            State.RageKnifeHintLast = tick()
            local lib = _G["\76\72"]   -- the Linoria Library, published at load (13_gui)
            if lib and lib.Notify then
                pcall(function() lib:Notify("Knifed by a melee player â€” switch Rage mode to Orbit (our knife counter)", 5) end)
            end
        end)
    end

    local function hookDied(char)
        if _rageDiedConn then
            _rageDiedConn:Disconnect()
            _rageDiedConn = nil
        end
        if not char then
            return
        end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            _rageDiedConn = hum.Died:Connect(onLocalDied)
        end
    end

    -- â”€â”€ THE ONE RESTORE PRIMITIVE â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    -- Position-only homing write, shared by the render bind, the Stepped backstop and EVERY teardown path.
    -- CFrame ONLY: the game applies slide-jump as a BodyVelocity impulse, so writing AssemblyLinearVelocity /
    -- Velocity / RotVelocity (or touching a BodyMover) eats that impulse â€” a real shipped movement bug. The
    -- per-life token (RageRealChar) stops a freshly respawned body being yanked to a dead body's pose.
    -- Rotation is the game's, never ours. `pin` un-sticks a GROUNDED Freefall so jump/slide state can't churn.
    local function restoreHome(pin)
        -- ORDER CANARY (Goal B(2), machine-check): the Heartbeat park must be the LAST hrp write before the engine
        -- network-samples us. Both real anchors are downstream phases and clear this marker before calling in, so
        -- a non-zero count means a future edit put a restore/teardown/guard AFTER the park inside one dispatch.
        if State.RagePostPark then State.RageOrderCanary = State.RageOrderCanary + 1 end
        local ch = lp.Character
        if not ch then return end
        local hrp = ch:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then return end
        -- ★ 2026-08-07: put the body back exactly where the game left it before WE displaced it, not at the
        -- stale RageRealCF snapshot. Returning the live pre-displacement pose is what keeps movement native
        -- during a burst; RageRealCF survives only as the teardown / stranded-body fallback below.
        local back = _preParkCF
        _preParkCF = nil
        if back == nil then
            -- Fall back to the snapshot only for the teardown paths, and NEVER `return` here: RenderStep
            -- runs first and clears the saved pose, so bailing would mean the Stepped anchor -- the only
            -- caller that passes pin -- could never reach the humanoid pin and a displacement would leave
            -- us stuck in Freefall. Same defect 07c hit; same fix.
            local real = State.RageRealCF
            if real and State.RageRealChar == ch then
                back = CFrame.new(real.Position) * hrp.CFrame.Rotation
            end
        end
        pcall(function()
            if back then hrp.CFrame = back end
            -- WITNESS (Goal B(3)): a restore write actually LANDED, so the live pose is ours again and the capture
            -- may adopt it. Inside the pcall and AFTER the assignment on purpose â€” if the write ever throws, the
            -- guard stays armed and the capture stays refused instead of silently adopting the park.
            State.RageParkDirty = false
            if pin then
                local hu = ch:FindFirstChildOfClass("Humanoid")
                if hu and hu:GetState() == Enum.HumanoidStateType.Freefall and hu.FloorMaterial ~= Enum.Material.Air then
                    hu:ChangeState(Enum.HumanoidStateType.Running)
                end
            end
        end)
    end

    local function startRage()
        if _rageConn then return end
        -- Kicia's four physics flags (sender rate 15->120 etc). Shared implementation in 07c so the two
        -- drivers cannot half-apply or half-restore a global between them; nil-checked because 07b loads
        -- first. Raising the send rate is what lets ORBIT_PRIME_S be one period instead of four.
        if Rage._setPhysicsFlags then pcall(Rage._setPhysicsFlags, true) end
        hookDied(lp.Character)   -- knife-death Orbit hint (per-life; re-hooked on respawn below)
        -- CLEAR-ON-RESPAWN: drop the captured pose (+ its per-life token) so a freshly-spawned body is never
        -- yanked to a stale pre-death pose. The no-anchor guard in the driver holds us until this life
        -- re-captures a sane pose at the top of the next Heartbeat.
        if not _rageCharConn then
            _rageCharConn = lp.CharacterAdded:Connect(function()
                State.RageRealCF = nil; State.RageRealChar = nil
                State.RageVoidCF = nil; State.RageVoidBase = nil
                -- the latch guard MUST be disarmed wherever the anchor is dropped: a dirty flag stranded across a
                -- respawn would refuse every capture, leaving RageRealCF nil and rage stuck in "Waiting" forever.
                State.RageParkDirty = false; State.RageLastParkPos = nil
                -- PHANTOM: null the stale weld cache (new body has fresh welds; the old joints died with the old
                hookDied(lp.Character)   -- re-hook the knife-death Orbit hint on the fresh Humanoid
            end)
        end
        -- CLIENT-CLEAN RESTORE (ALL modes), purely client-side and UNCONDITIONAL on both anchors: no
        -- skip-while-firing, no overlay, no input lock, no takeover. The Heartbeat park is the last write
        -- before the network sample, so it always re-parks after these â€” they cannot cost a single shot.
        -- ★ SKIP-WHILE-FIRING RESTORED 2026-08-02 — THE STANDALONE DIVERGENCE THAT LOSES THE KICIA FIGHT.
        -- Both anchors used to run UNCONDITIONALLY, on the claim that "the Heartbeat park is the last write
        -- before the network sample, so they cannot cost a shot". That claim is an ASSUMPTION about when the
        -- engine samples the RootPart, and it was never measured. Trace one firing frame under it:
        --      RenderStep -> real | Stepped -> real | PHYSICS -> real | Heartbeat -> park
        -- The proven standalone skips both anchors while firing, so its body sits at the PARK through the
        -- physics step. If replication samples with physics rather than after Heartbeat, the unconditional
        -- version replicates our REAL body while char0 claims the enemy's head — and PARKLESS_TEST proved the
        -- server resolves a shot from the REPLICATED BODY (no-park landed only with line of sight, else it
        -- registered a wall impact). That is precisely the observed symptom: identical packets, identical
        -- park, and bundled Polar loses a fight the standalone wins.
        -- Cost of the fix: movement is not native during a burst (physics runs at the park) — exactly the
        -- trade the standalone makes, and the standalone wins. Power first.
        -- Set RageRestoreWhileFiring = true to A/B the old unconditional behaviour without a rebuild.
        -- ★ SKIP-WHILE-FIRING DELETED 2026-08-07 — the note above is now history and the conclusion it
        -- reached has been overturned by the leak. Kicia suppresses NOTHING (leak L144633-144688): it
        -- re-displaces every Heartbeat and undoes it at RenderPriority.First, unconditionally. The
        -- "replication might sample with physics" worry that motivated the skip is answered — the sender
        -- runs in the end-of-frame networking phase, which is INSIDE the Heartbeat->next-render window, so
        -- every send that happens at all happens while the displaced pose is standing. The skip bought
        -- nothing and cost a rendered teleport plus dead movement for the whole burst. Polar dropped it
        -- first (07c seam S8) and the fight got better, not worse.
        local function rageRestoreActive()
            if not Config.Rage then return false end
            if not State.RageInMatch then return false end
            if State.RageRealChar ~= lp.Character then return false end
            return true
        end
        -- (1) RENDER, at Camera-1 so the camera update at Camera reads the RESTORED pose (binding after Camera
        -- would show a one-frame snap to the park). The fixed bind name lets a re-executed script kill a stale
        -- bind from a previous instance by name â€” do NOT randomize it.
        pcall(function() RunService:UnbindFromRenderStep(_rageRestoreName) end)
        -- First.Value - 1000, matching 07c and strictly earlier than Kicia's First.Value: we are back on
        -- the real pose before ANY other render-step consumer (including the camera at 200) reads it.
        RunService:BindToRenderStep(_rageRestoreName, Enum.RenderPriority.First.Value - 1000, function()
            State.RagePostPark = false   -- downstream of the sample: this restore is legitimate, not an order violation
            if rageRestoreActive() then restoreHome(true) end
        end)
        -- (2) PRE-PHYSICS BACKSTOP. Stepped is 1:1 with Heartbeat; RENDER is the one phase that can be
        -- throttled or dropped, and a single skipped render frame would let the Heartbeat-top capture latch
        -- the PARK as our real pose (a park on a head IS sane, so the sane-guard would not catch it) and
        -- "real" would permanently become the enemy. Restoring here also guarantees physics integrates from
        -- the real pose = native movement. Strictly UPSTREAM of the same frame's Heartbeat park.
        if not _rageStepConn then
            _rageStepConn = RunService.Stepped:Connect(function()
                State.RagePostPark = false   -- ditto: pre-physics of the NEXT frame, never inside the park's dispatch
                if rageRestoreActive() then restoreHome(true) end
            end)
        end
        -- (3) COOLDOWN DEFEAT â€” behaviour-mirrored from OldLuahook.txt:1008-1016. The game is the only shot
        -- authority now, and its PER-INSTANCE client cooldowns would cap us at the weapon's legal rate, so zero
        -- them at the top of every frame: one ask per Heartbeat then yields one real, game-built shot (~60/s).
        -- Connected BEFORE the driver so it runs FIRST in Heartbeat order and this frame's Input already sees
        -- zeroes. _last_shot is repaired ONLY when it sits more than a second in the FUTURE (a corrupt/desynced
        -- stamp) â€” never pushed backwards, which is what the deleted forged burst did unconditionally. The
        -- SHARED Info table is NEVER touched: no nukeInfo port, so there is no restore-on-unload bookkeeping to
        -- get wrong (rewriting these per-instance fields every frame is why OldLuahook needs none either).
        local function defeatCooldowns()
            if not Config.Rage then return end
            local it = getEquippedItem()
            if not it then return end
            it._shoot_cooldown = 0
            it._shoot_cooldown_no_ammo = 0
            if (it._last_shot or 0) > tick() + 1 then it._last_shot = tick() - 1 end
            if it._shot_but_ammo_hasnt_updated then it._shot_but_ammo_hasnt_updated = false end
        end
        if not _rageCooldownConn then
            _rageCooldownConn = RunService.Heartbeat:Connect(function()
                pcall(defeatCooldowns)   -- un-pcall'd dispatch: one nil-index here would kill the loop silently
            end)
        end
        -- HEARTBEAT DRIVER (post-physics: this is what the engine network-samples -> what replicates).
        _rageConn = RunService.Heartbeat:Connect(function()
            -- ...or the mode switched to Polar, which 07c drives on its own anchors. Same teardown either
            -- way: home the body first, then drop every anchor -- never hand over while parked or voided.
            if not Config.Rage or (Config.RageMode or "Polar") ~= "Orbit" then
                -- restore-before-teardown (a direct Config.Rage=false that skips Rage.disable): home the
                -- body, THEN drop every anchor -- never strand at a park or in the void.
                if Rage._setPhysicsFlags then pcall(Rage._setPhysicsFlags, false) end
                restoreHome(false)
                pcall(function() RunService:UnbindFromRenderStep(_rageRestoreName) end)
                if _rageConn then _rageConn:Disconnect(); _rageConn = nil end
                if _rageStepConn then _rageStepConn:Disconnect(); _rageStepConn = nil end
                if _rageCooldownConn then _rageCooldownConn:Disconnect(); _rageCooldownConn = nil end
                if _rageCharConn then _rageCharConn:Disconnect(); _rageCharConn = nil end
                if _rageDiedConn then _rageDiedConn:Disconnect(); _rageDiedConn = nil end
                State.RageRealCF = nil; State.RageRealChar = nil
                State.RageTarget = nil; State.RageVoidCF = nil; State.RageVoidBase = nil
                State.RageParkDirty = false; State.RageLastParkPos = nil   -- disarm with the anchor (see CharacterAdded)
                State.RageInMatch = false
                State.OrbitVantage = nil; State.OrbitVantageUntil = 0
                clearFireSolution()
                return
            end
            local ch  = lp.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not hrp or not hrp.Parent then
                -- the fallen-parts sweep DESTROYS parts (no Humanoid.Died), so a Died-only counter would read 0
                -- while we lose every life. This is the second attribution edge; the latch keeps it one-per-loss.
                if tick() - State.RageBelowPlaneLast < 0.5 then
                    State.RageBelowPlaneDeaths = State.RageBelowPlaneDeaths + 1
                    State.RageBelowPlaneLast = 0
                end
                clearFireSolution()
                return
            end
            -- capture the real pose (adopts WASD/dash/legit teleports) every sane frame. This runs at the TOP of
            -- the Heartbeat, BEFORE rageTick parks the body, so capture reads the real pose the client restore
            -- last wrote â€” never the park. Position only; velocity is never captured or restored.
            -- PARK-LATCH GUARD (Goal B(3), machine-check). A park sits ON an enemy head, which IS a sane position,
            -- so isSanePos alone cannot tell a park from our real pose. If NO restore write landed since the last
            -- displacing write, the live pose may BE the park: refuse the capture (fail closed â€” keep the last
            -- known-good real pose) and count it. RageParkLatchCanary MUST read 0 forever. The RageRealChar test
            -- keeps a dirty flag stranded by a respawn from deadlocking the capture (which would strand rage in
            -- "Waiting" for the session); a real latch always happens inside one life, where the chars match.
            if State.RageParkDirty and State.RageRealChar == ch then
                State.RageParkLatchCanary = State.RageParkLatchCanary + 1
                if State.RageLastParkPos then
                    State.RageLatchStuds = (hrp.Position - State.RageLastParkPos).Magnitude
                end
            elseif isSanePos(hrp.Position) then
                State.RageRealCF = hrp.CFrame
                State.RageRealChar = ch
            end
            -- lobby gate: do nothing outside a match (no teleport onto people in the hub). Home ONLY from a
            -- non-sane pose â€” that can only be our own void write, so this can never fight a legitimate
            -- game-side teleport to the lobby.
            State.RageInMatch = inMatch()
            if not State.RageInMatch then
                if not isSanePos(hrp.Position) then restoreHome(false) end
                State.RageTarget = nil
                State.RageStatus = "Lobby"
                State.RageFiring = false
                clearFireSolution()
                return
            end
            -- no-anchor guard: never displace unless THIS life has a captured real pose to restore from.
            if not State.RageRealCF or State.RageRealChar ~= ch then
                State.RageStatus = "Waiting"
                State.RageFiring = false
                clearFireSolution()
                return
            end
            -- corpse guard: never park/void/fire while dead. A dead fighter cannot legally send UseItem and a
            -- point-blank teleport of a ragdolling body replicates as impossible movement. Home from the void.
            local hum0 = ch:FindFirstChildOfClass("Humanoid")
            if hum0 and hum0.Health <= 0 then
                if not isSanePos(hrp.Position) then restoreHome(false) end
                State.RageFiring = false
                State.RageVoidActive = false
                State.RageStatus = "Dead"
                clearFireSolution()
                return
            end
            -- ACQUIRE: the sticky path, unchanged from the proven Polar behaviour. startTargetLoop still fills
            -- RageTrueVelocityMap + State.Target (the silent-aim lead fallback) regardless.
            local tgt = State.RageTarget
            do
                if tgt and (not tgt.Parent or not tgt.Character or not isAlive(tgt)
                    or (Config.TeamCheck and isTeammate(tgt))) then
                    tgt = nil
                end
                if not tgt then tgt = Rage._findTarget() end
                State.RageTarget = tgt
            end
            -- SCOPE MARKER for the order canary: from here to the end of this dispatch we are downstream of the
            -- park and upstream of the network sample, so ANY restore in that window breaks Goal B(2). Both
            -- anchors clear it (they run in later phases, where restoring is exactly the point).
            State.RagePostPark = true
            Rage._rageTick(ch, hrp, tgt)   -- writes park/void at Heartbeat; the client restore renders between bursts
            -- ARM THE LATCH GUARD. rageTick may have displaced the body (park / vantage / void); until a restore
            -- write lands, the live pose is NOT our real pose. Derived from the ACTUAL displacement so a frame that
            -- wrote nothing (hide with RageVoidHide off) can never raise the canary. Reading hrp.Position here
            -- returns the value just written â€” physics does not run inside a dispatch.
            local anchor    = State.RageRealCF   -- non-nil (no-anchor guard above); nil-checked so a nil-index can't kill the driver
            local displaced = false
            if anchor then displaced = (hrp.Position - anchor.Position).Magnitude > 0.001 end
            State.RageParkDirty = displaced
            if displaced then State.RageLastParkPos = hrp.Position end
        end)
    end

    -- EXACTLY ONE DRIVER RUNS. Polar is 07c_polar_core (the verbatim standalone, own anchors); Orbit is this
    -- file. Both self-tear-down from their own Heartbeat when they are no longer the selected mode, so a
    -- live RageMode switch needs no GUI cooperation: the outgoing driver homes the body and drops its
    -- anchors on its next frame, and this call starts the incoming one.
    function Rage.enable()
        Config.Rage = true
        if Rage._startTargetLoop then Rage._startTargetLoop() end
        if (Config.RageMode or "Polar") ~= "Orbit" then
            if Rage._polarCoreStart then Rage._polarCoreStart() end
            return
        end
        startRage()
    end

    function Rage.disable()
        Config.Rage = false
        if Rage._polarCoreStop then Rage._polarCoreStop() end   -- 07c owns its own anchors and its own home write
        -- a GUI-thread disable can land between the Heartbeat park and the next render anchor; its restore below is
        -- legitimate (post-sample), so clear the marker first or it would count a spurious order violation.
        State.RagePostPark = false
        pcall(function() RunService:UnbindFromRenderStep(_rageRestoreName) end)
        if _rageConn then _rageConn:Disconnect(); _rageConn = nil end
        if _rageStepConn then _rageStepConn:Disconnect(); _rageStepConn = nil end
        if _rageCooldownConn then _rageCooldownConn:Disconnect(); _rageCooldownConn = nil end
        if _rageCharConn then _rageCharConn:Disconnect(); _rageCharConn = nil end
        if _rageDiedConn then _rageDiedConn:Disconnect(); _rageDiedConn = nil end
        restoreHome(false)   -- home on EVERY exit (per-life token gated), never stranded at a park or in the void
        State.RageRealCF = nil; State.RageRealChar = nil
        State.RageTarget = nil; State.RageVoidCF = nil; State.RageVoidBase = nil
        State.RageParkDirty = false; State.RageLastParkPos = nil   -- disarm with the anchor (see CharacterAdded)
        State.RageInMatch = false
        State.OrbitVantage = nil; State.OrbitVantageUntil = 0
        State.RageFiring = false
        State.RageVoidActive = false
        State.RageStatus = "Idle"
        clearFireSolution()
    end

    function Rage.unload()
        Rage.disable()
        -- _tgtConn / _labConn are 07a locals (same IIFE) â€” tear them down here so no standing loop survives.
        if _tgtConn then pcall(function() _tgtConn:Disconnect() end); _tgtConn = nil end
        if _labConn then pcall(function() _labConn:Disconnect() end); _labConn = nil end
    end

    Rage._encodeRageShot = encodeRageShot
end)()

-- ============================================================================
-- 07c_polar_core.lua — POLAR, TRANSPLANTED VERBATIM
--
-- This file IS C:/Kernaled/polar_movinghide.lua — the standalone that beats Kicia and very nearly
-- beats UE — copied function for function, not reimplemented. It deliberately shares NOTHING with
-- 07b: its own locals, its own Heartbeat/Stepped/RenderStep anchors, its own findTarget, isProtected,
-- voidCFrame, hide, polarTick and restore.
--
-- WHY A COPY INSTEAD OF A PORT (2026-08-03). Bundled Polar was a REIMPLEMENTATION of the standalone,
-- and it lost the fight the standalone wins. Four separate divergences were found by hand — restore
-- running while firing, a missing MaxDistance cap, an unbounded IsInvincible, an unclamped park —
-- each after the previous "fix" failed live. Every one of them was a shared 07b/05_utils helper that
-- had drifted from its standalone counterpart. Enumerating divergences cannot terminate: it only ever
-- finds the ones someone thinks to look for. Using ZERO shared helpers kills the entire class at once.
--
-- TWELVE THINGS DIFFER FROM THE STANDALONE, each marked @polarcore-seam. S1-S4 are forced by the bundle
-- or the build gates. S5-S12 are deliberate additions and are the first things to disable if a live A/B
-- ever regresses against the standalone (all but S5 and S10 have a config flag; S5 must be deleted):
--
-- S8-S12 were added 2026-08-07 after reading Kicia's ragebot end to end. Summary; details at each site.
--   S8  TRUE DESYNC  — displace at Heartbeat, restore UNCONDITIONALLY at RenderPriority.First. Replaces
--                      the standalone's suppress-restore-while-firing, which rendered the park (operator
--                      watched himself teleport) and ran physics on the parked body (dead movement).
--   S9  PHYSICS FLAGS— Kicia's four: sender rate 15->120, unbounded assembly history,
--                      FallenPartsDestroyHeight = NaN. NOT a compensation for S8 (that claim was wrong and
--                      is corrected at the site) — it raises how OFTEN a fresh park reaches the server,
--                      which is what makes S10's one priming frame sufficient. Flag: Config.RagePhysicsFlags.
--   S10 FIRE ORDER   — build the shot from the PREVIOUS frame's park. FireServer runs synchronously
--                      inside the Heartbeat that writes the park, so the shot always overtakes the
--                      position update and the first volley resolves from our real pose — into a wall.
--                      ⚠ Its ONE frame of prime is only enough while S9 is actually live; at the stock
--                      send rate a fresh park needs ~4. Read State.RagePhysRate before trusting it.
--   S11 THREAT FIRST — tag cheats (insane coordinate, or sustained impossible speed) and sort them above
--                      the HP order. Flag: Config.RagePrioritizeHackers.
--   S12 HIDE JITTER  — 0-250ms random extra dwell, so our cycle length stops being a learnable constant.
--                      Flag: Config.RageHideJitter. MERGED with S14 2026-08-07 — see next line.
--   S14 PRIME        — hold the park PRIME_S (one stock physics-sender period, Kicia's own 1/15s constant)
--                      before the first shot of a burst, and spend S12's jitter parked instead of hidden.
--                      This is the wall-bullet fix: S10's one frame was a 4x under-lead. Not a settle
--                      timer — it runs only in the dead time where the magazine was empty anyway.
--                      (S13 was the force-crouch investigation. Rejected, never became a seam.)
--   S27 PARITY      — ⚠ READ THIS FIRST IF POLAR UNDERPERFORMS. Operator-measured 2026-08-09: the live
--                      bundle's hitscan is SIGNIFICANTLY weaker than the standalone, AR vs AR. S8, S10 and
--                      S14 are the three things on the hit path that the winner does not do, and S8 is a
--                      multiplicative loss while the other two are additive:
--                        · the standalone suppresses BOTH restore anchors while _firing (polar_movinghide
--                          L375, L384), so the park is the body's pose for 100% of every frame. Under S8
--                          the park exists only from the tail of Heartbeat to the next frame's first render
--                          callback. S8's neutrality argument assumes the physics sender ALWAYS runs inside
--                          that window; the sender is a separate scheduler job with its own cadence, so it
--                          does not. Partial capture => proportionally fewer parks reach the server =>
--                          proportionally fewer accepted packets. S8's own falsification test ("if the
--                          sampler read any other phase we would land NOTHING") is a false dichotomy: it
--                          only rules out zero capture, not the partial capture we actually observe.
--                        · WHY COPYING KICIA HERE WAS WRONG: Kicia's ragebot does not need its park to
--                          replicate at all. It glues PhysicsRepRootPart to the enemy's own hitbox, so the
--                          server resolves us from a part we never have to move. Its unconditional restore
--                          is free BECAUSE of the glue. We took the restore without the glue — the same
--                          cross-contamination as S21 (the -9e37 sentinels) and S25 (the melee cooldown).
--                        · S10 and S14 then spent a frame plus 70-320ms of every burst not shooting, to fix
--                          a first-bullet-into-a-wall symptom the winning artifact ALSO has and wins with.
--                      Config.RagePolarParity (DEFAULT TRUE) runs the standalone's rule: restores suppressed
--                      while firing, fire from THIS frame's park, no prime. Set it false to get S8/S10/S14
--                      back for an A/B. The honest cost of parity is the standalone's cost, and the operator
--                      has already run with it: the park RENDERS (you watch yourself teleport) and physics
--                      steps the parked body (movement is dead for the ~83ms a magazine lasts).
--                      Config.RageParkLift also ships FALSE now — S19's 12-stud lift is a third geometry
--                      change the winner does not make, and it is reasoned-neutral, not measured-neutral.
--
-- S28-S29 were added 2026-08-09 after re-reading Kicia's ragebot to answer ONE question: why is ITS restore
-- free? The answer is not the part glue (that was the S27 hypothesis and it is WRONG), and it is not a
-- scheduler-phase argument. It is two FFlags, and we already ship them.
--   S28 PERFECT      — the physics sender does not transmit "the pose at sample time". It transmits a HISTORY
--       RESTORE       of assembly poses since the last packet, and stock settings DECIMATE that history:
--                     DFIntAssemblyHistorySkipSize = 8 keeps roughly one entry in eight, capped at
--                     DFIntAssemblyHistoryBufferSize = 15. A park that exists only from Heartbeat to the next
--                     RenderStep is exactly the short-lived pose a decimator discards — sometimes. THAT is
--                     the partial capture S27 diagnosed, and it is why the loss was BIMODAL rather than
--                     constant. Kicia sets SkipSize = 0 and BufferSize = 2^31 the moment its ragebot enables
--                     (cleaned decompile L62801-62829), so every pose the body held goes on the wire and the
--                     restore cannot take the park away. Its unconditional restore is free BECAUSE of the
--                     flags. We shipped the restore (S8) with the flags unverified, and then in the S27 sweep
--                     we turned the flags OFF and kept the suppression — two different halves of the same
--                     answer, never both. This seam runs Kicia's actual configuration: flags on, restore
--                     unconditional, movement and render preserved. It is SELF-VERIFYING — every flag is
--                     written back and read back, and if any one of them does not take, the restore falls
--                     back to the standalone's suppress-while-firing on its own. That auto-fallback is also
--                     the structural cure for S9's session-dependence: instead of one more seam that behaves
--                     differently depending on how the session loaded, it is a measured branch.
--                     Flag: Config.RagePerfectRestore (true / "force" / false). FLIP THIS FIRST if power
--                     regresses — false restores exactly the S27 behaviour the operator confirmed working.
--   S29 ONE TAP      — Kicia's ragebot Update calls weaponAction() exactly ONCE per frame (L12330-12333) and
--                     its Plan returns a single AttackEncoded/ShootEncoded thunk. POLAR_TAPS_SANE = 6 spends
--                     the magazine six times faster for no extra acceptance: our own measurement is that
--                     accepted packets are INVARIANT to volume (67x swing, same 6 accepted), which S28
--                     finally explains — one park pose reaches the server per frame, so extra taps in that
--                     frame have nothing new to resolve against. The magazine is the budget either way (30
--                     rounds), so the only question is whether it is spent across 5 frames or 30. Strictly
--                     dominant, under both the per-frame and per-packet acceptance models.
--                     The CONSTANT stays 6 — the polarcore gate pins it to the standalone and it is now the
--                     upper clamp. Flag: Config.RageTapsPerFrame (default 1).
--   S17 UN-GATED     — the resurface predictor comes back ON under parity. It is not a Kicia port that needs
--                     the glue; it is a strict superset of Kicia's SpatialLimitGate (median of 5 vs its
--                     last-value overwrite, any absence vs its 2^22 threshold, bounded wrongness vs its
--                     unbounded belief) and it is the only thing here that shortens reaction time.
--                     Kicia's one remaining trick, gating the learn on the TARGET's ammo state, is subsumed
--                     by our median: it exists to stop one anomalous absence poisoning a last-value model.
--                     Flag: Config.RagePredictResurface. Second thing to flip if power regresses.
-- NOT ported, and the reasons are on record so they do not get re-proposed:
--   Kicia's ShootLock latch (L64986-65001, Ragebot.ShootFrames = 1) commits to the attack for one frame
--   after its gate closes. It exists because its gate is a bare threshold test with no predictor; ours has
--   S17. Adding both would put a second, dumber horizon in the hottest branch of the tick.
--   Kicia's InputSpammingEnabled zeroing (L24957-24970) is a NO-OP for guns — ItemLibrary.luau:3448 already
--   defaults StartShooting to 0, and Gun.luau:97 only queues a deferred real shot when that field is FALSY.
--
-- NOT ported, deliberately: Kicia's force-crouch. It feeds GetSpread, but only along the GetCameraData
-- path; we forge char0-char3 directly so our packets already carry zero spread. All it would buy us is
-- MechanicsController's 0.5x walkspeed during every burst.
--   S1 LIFECYCLE   — driven by Config.Rage + Config.RageMode instead of a load-time bind and
--                    shared._PR_teardown; fixed render-bind name so a re-executed script kills a
--                    stale bind by name.
--   S2 ENCODER     — the packet is built with Rage._lookCF + Rage._buildShotFields. The standalone's
--                    own shape (char0 == char1, char3 = identity, NaN rotation from the straight-down
--                    CFrame.new) is the DETECTION VECTOR; the packetshape and lookcf gates refuse it.
--                    This is the one seam whose live equivalence is assumed rather than measured.
--   S3 BUNDLE      — State.RageForging (MANDATORY: rageShotLeak in 07b DROPS any StartShooting UseItem
--      CONTRACT      that is not flagged as ours, so an unflagged verbatim burst would be eaten by our
--                    own backstop), plus RageFiring/RageStatus/Shots which 09_aimbot and 11_lab read.
--   S4 DEAD BRANCH — the standalone's fire-at-a-voided-head path is unreachable (HIDE_WHEN_UNREACHABLE
--                    is a constant true) and is the only fire site that reads our own body, which the
--                    hrpwrite gate forbids. Deleted, not disabled.
--   S5 CORPSE GUARD— NOT forced, and NOT in the standalone: we home a dead body instead of deep-voiding
--                    it. Undetection reasoning only, no damage cost. See the site for why, and delete it
--                    before suspecting anything else if this build underperforms the standalone.
--   S6 SPAWN PROT. — the standalone's ForceField test can never fire (Rivals ships none; its invincibility
--                    visual is a particle Attachment), so it has NO protection skip. We add the game's own
--                    replicated IsInvincible, mirrored off its change signal = one table index, no TTL.
--                    Flag: Config.RageSkipImmune. Fails OPEN.
--   S7 ANTI-KATANA — the standalone has none. A live deflect REFLECTS our damage (DeflectDamageMultiplier
--                    = 1) for 1s out of every 5, and Polar parks inside the katana's 6-stud reach, so we
--                    hide for that window instead of feeding it. Signal is the game's own
--                    Katana._StartDeflecting. Flag: Config.AvoidDeflect. Fails OPEN.
--
-- The `polarcore` build gate re-reads polar_movinghide.lua on every build and fails if the constants
-- or the load-bearing structure here drift from it. Keep it that way: this file's whole value is that
-- it is not an independent implementation.
-- ============================================================================

;(function()

    -- Services, lp and the game modules all come from 01_bootstrap. These are the SAME objects the
    -- standalone requires directly (Utility / EnumLibrary / FighterController) — reached through the
    -- load-guarded accessor instead of a bare require, which is a robustness change, not a behavioural one.
    local PolarCore = {}

    local _realCF, _realChar = nil, nil
    local _voidCF     = nil
    local _target     = nil
    local _firing     = false
    local _inMatch    = false
    local _reloadLast = 0
    local _deflectSince = 0
    local _shots      = 0
    local _voidSteps  = 0
    local _shootEnum  = nil
    local _useItem    = nil
    local _notified   = nil

    local _conn, _stepConn, _charConn = nil, nil, nil
    local RENDER_NAME = "LuaHook_PolarCore_Restore"   -- @polarcore-seam:S1 fixed, never randomized
    local CAMERA_NAME = "LuaHook_PolarCore_CamAnchor" -- @polarcore-seam:S35, same fixed-name rule

    local SANE_POS_LIMIT  = 100000
    local MAX_DISTANCE    = 1200
    local VOID_HIDE       = true
    local POLAR_TAPS_SANE = 6
    local EYE_UP_SANE     = 2.5
    local KILL_PLANE_BUF  = 200
    -- @polarcore-seam:S41 — studs a park may drift before we count a physics-ejection frame. 1.5 is above
    -- the couple of studs a head legitimately moves between two Heartbeats and well below the 12-stud S19
    -- lift, so a lift regression and a solver ejection are both visible without alarming on aim drift.
    local PARK_DRIFT_STUDS = 1.5

    -- THE PERFECTED HIDE. A new far coordinate EVERY hide frame: measured 2026-07-31, far-out-and-STATIC
    -- took 210 damage over 14 hits (UE follows us out and kills us there), far-out-and-MOVING took 0 over
    -- 30s. Because forged packets consume ammo, Polar empties a mag in ~3-4 Heartbeats and then hides for
    -- the whole ~2-3s reload, so the hide is ~95% of the fight rather than an edge case.
    local VOID_MOVE       = true
    local VOID_MIN_STEP   = 25000    -- min studs between consecutive hide points (needs > 400; huge margin)
    local VOID_R_MIN      = 110000   -- band kept EXACTLY as the standalone: proven in this game, and always
    local VOID_R_MAX      = 140000   -- > SANE_POS_LIMIT so the void can never be captured as our real pose
    local HIDE_WHEN_UNREACHABLE = true

    -- @polarcore-seam:S7 — game constant: Katana Info.DeflectDuration = 1s, DeflectCooldown = 4s, so a
    -- deflect can never legitimately be live longer than this. Past it, the signal is stuck, not deflecting.
    local DEFLECT_MAX_HOLD = 1.5

    -- @polarcore-seam:S33 — THE SAME BOUND, FOR INVINCIBILITY. Added 2026-08-09: the S6 hold-fire had no
    -- ceiling at all, which is the exact failure the old IsInvincible gate was killed for — a signal stuck
    -- true is a permanent lockout that emits ZERO packets, silently. Spawn protection in Rivals is a few
    -- seconds and ends the instant the player acts, so past this the mirror is wrong, not the player.
    -- Engaging a genuinely invincible target costs only ammo (the packets are rejected by construction);
    -- holding fire on a killable one costs the round. So the bound fails toward shooting, deliberately.
    local IMMUNE_MAX_HOLD = 6.0
    local _immuneSince = 0
    local _immuneTgt   = nil

    -- @polarcore-seam:S2 — vertical eye->muzzle separation so char0 ~= char1 (packetshape gate).
    local EYE_MUZZLE_SEP  = 0.07
    local RAGE_CLAMP_FRAC = 0.30

    -- @polarcore-seam:S27 STANDALONE PARITY. One predicate, read at three sites, and it is the difference
    -- between this file being the transplant it claims to be and being a variant of it. See the header.
    -- Read live (not latched) so an A/B is a config flip, not a rebuild.
    local function parity()
        return Config.RagePolarParity ~= false
    end

    -- @polarcore-seam:S8 TRUE DESYNC — displace at Heartbeat, put the body back at the FIRST render
    -- callback of the next frame. Ported from Kicia's characterController (leak L144633-144688), which is
    -- a genuinely different design from what this file used to do and is why Kicia has no visible teleport:
    --
    --      Heartbeat        _preParkCF = hrp.CFrame ; hrp.CFrame = displaced
    --      RenderStep(First) hrp.CFrame = _preParkCF ; _preParkCF = nil
    --
    -- The displaced pose therefore exists ONLY between Heartbeat and the next frame's first render
    -- callback — a window the network sampler sees and the renderer never does. Kicia binds exactly one
    -- restore, at Enum.RenderPriority.First, and it runs UNCONDITIONALLY: there is no "skip while firing"
    -- anywhere in its ragebot. It does not need one, because it re-displaces every single Heartbeat.
    --
    -- What this replaces, and why it was wrong: the old code suppressed BOTH restore anchors for the whole
    -- burst (`if _firing then return false end`). That leaves the body parked on the enemy's head across
    -- render, so the player watches themselves teleport — operator-observed, and the reason this changed.
    -- It also pinned "home" to a stale snapshot captured on the last non-firing frame, which is why
    -- movement went dead during a burst. Saving the LIVE CFrame each Heartbeat fixes both at once: the
    -- restore always returns the body to where the game itself just put it, never to a stale anchor.
    local _preParkCF = nil

    -- @polarcore-seam:S9 PHYSICS REPLICATION FLAGS — ported verbatim from Kicia's ragebot SetEnabled
    -- (leak L73914-73946 / L268399-268431). The decompiler renders the calls as `f10501(f10491, name,
    -- value)`; the binding table at L161674-161675 resolves those to `pcall(setfflag, name, value)` — so
    -- the values really are STRINGS, not numbers.
    --
    -- ★ CORRECTED 2026-08-07. This block used to call itself "the compensating half of S8", the claim being
    -- that S8's narrow window would be MISSED at the stock send rate. That is wrong, and believing it aimed
    -- three separate fixes at the wrong thing. See the neutrality argument at the anchors below: every send
    -- that happens at all happens inside S8's window, so S8 transmits the park exactly as often as the
    -- standalone's hold-it-all-frame design, at any rate.
    --
    -- What S9 actually buys is RATE, and rate governs exactly one thing: how long a FRESH park must be held
    -- before a shot fired from it can land. At the stock 15 Hz the server learns a new park about once every
    -- four frames, so S10's single priming frame is right only about a quarter of the time and the opening
    -- rounds of a burst resolve from wherever we were before it. At 120 Hz the park goes out about twice a
    -- frame and one frame of prime is always enough. So S10's correctness is CONDITIONAL ON THIS BEING
    -- LIVE — which is why the resolver below publishes whether it actually took.
    --   FallenPartsDestroyHeight = NaN   every comparison against NaN is false, so nothing is ever culled
    --                                    for falling — this is what protects an extreme-coordinate hide.
    --   AssemblyHistoryBufferSize/SkipSize  retain every physics state and skip none.
    -- Kicia restores the three DFInts to hard-coded stock values rather than captured ones; only
    -- FallenPartsDestroyHeight is captured. Kept faithful.
    --
    -- ⚠ TRADE, not a free win: 8x the position update rate also means 8x the evidence of a body that
    -- teleports. Kicia ships it and is undetected per operator ground truth, which is the whole basis for
    -- doing it. Config.RagePhysicsFlags exists so it can be A/B'd against S8 alone.
    local FFLAGS_ON  = { DFIntS2PhysicsSenderRate = "120", DFIntAssemblyHistoryBufferSize = "2147483648", DFIntAssemblyHistorySkipSize = "0" }
    local FFLAGS_OFF = { DFIntS2PhysicsSenderRate = "15",  DFIntAssemblyHistoryBufferSize = "15",         DFIntAssemblyHistorySkipSize = "8" }
    local _fpdhOriginal = nil
    local _flagsOn = false
    -- @polarcore-seam:S28 — the two outcomes S28's auto-fallback keys on. _physSet: a setter resolved and no
    -- write threw. _physLive: every write ALSO read back equal, and FallenPartsDestroyHeight really is NaN.
    -- Only _physLive proves the history decimation is off, which is the precondition for the restore to be
    -- free. Kept separate rather than collapsed into one flag precisely because "set, unreadable" is the
    -- ambiguous case, and hiding an ambiguity behind a boolean is how S9 became session-dependent.
    local _physSet  = false
    local _physLive = false

    -- The setter is NOT universally named `setfflag`, and the old code gave up silently when that exact
    -- global was missing. That silence is expensive: it is the difference between the server learning our
    -- park every ~8ms and every ~66ms, which sets how many frames of park the first shot of a burst needs
    -- before it can land. Resolve whatever this executor exposes, read the value back where a getter
    -- exists, and PUBLISH the outcome so "is S9 actually on?" is a readout instead of an assumption.
    local function fflagApi()
        local set, get, name = nil, nil, "none"
        pcall(function()
            if type(setfflag) == "function" then
                set, name = setfflag, "setfflag"
            elseif type(setfastflag) == "function" then
                set, name = setfastflag, "setfastflag"
            elseif type(set_fflag) == "function" then
                set, name = set_fflag, "set_fflag"
            end
            if type(getfflag) == "function" then
                get = getfflag
            elseif type(getfastflag) == "function" then
                get = getfastflag
            end
        end)
        return set, get, name
    end

    -- @polarcore-seam:S28 — nil means "no getter, cannot tell", which is NOT the same as false and must not
    -- be collapsed into one. Compared as strings because the setters take strings and the getters variously
    -- return strings or numbers.
    -- ★ 2026-08-09, operator: "i dont see restore working". The first version compared tostring(v) == want,
    -- which FALSE-NEGATIVES on the one flag most likely to be clamped: DFInts are int32 on the engine side
    -- and we ask for DFIntAssemblyHistoryBufferSize = 2147483648, which is 2^31 — one past int32 max. A
    -- clamp to 2147483647 is a SUCCESS (the intent is "unbounded") and was being read as a refusal, which
    -- marked the whole set REFUSED and pinned the restore off. Kicia asks for the same value and never
    -- checks, so it never notices. Compare numerically, and treat any saturating value as satisfying 2^31.
    local function readsBack(get, name, want)
        if get == nil then return nil end
        local ok, v = pcall(get, name)
        if not ok or v == nil then return nil end
        if tostring(v) == want then return true end
        local got, req = tonumber(v), tonumber(want)
        if got == nil or req == nil then return false end
        if req >= 2147483647 then return got >= 2147483646 end
        return got == req
    end

    local function setPhysicsFlags(on)
        if on == _flagsOn then return end
        if on and Config.RagePhysicsFlags == false then return end
        _flagsOn = on
        -- @polarcore-seam:S28 — never latch a NaN as "the original". S27 left the flags off under parity, so
        -- this could not happen; now that they are raised unconditionally, a re-execute over a session that
        -- never ran stop() would capture our OWN NaN as the value to restore, permanently. killFloor() would
        -- then return NaN, the park's Y clamp would produce a NaN park, isSanePos would reject it and Polar
        -- would hide forever. Roblox's own default is -500.
        if _fpdhOriginal == nil then
            local prev = workspace.FallenPartsDestroyHeight
            if prev ~= prev then prev = -500 end
            _fpdhOriginal = prev
        end
        -- @polarcore-seam:S28 — read the property straight back. NaN is the only value that fails self-
        -- equality, so this is a direct proof the write took rather than a hope that it did.
        local fpdhOk = false
        pcall(function()
            if on then
                workspace.FallenPartsDestroyHeight = 0 / 0
            else
                workspace.FallenPartsDestroyHeight = _fpdhOriginal
            end
            local v = workspace.FallenPartsDestroyHeight
            fpdhOk = v ~= v
        end)
        local set, get, setName = fflagApi()
        if set == nil then
            _physSet, _physLive = false, false
            State.RagePhysVerified = false
            State.RagePhysRate = "no fflag setter — history decimation stays stock"
            return
        end
        local want = FFLAGS_OFF
        if on then want = FFLAGS_ON end
        -- ★ 2026-08-09 — report PER FLAG, not one aggregate word. The first version said only "REFUSED" and
        -- left us guessing which of three writes failed, which is exactly the position this seam was built
        -- to get us out of. State.RagePhysDetail is what Rage._physDiag() prints.
        local threw, detail = false, ""
        local keyOk = false
        for name, value in want do
            local wrote = pcall(set, name, value)
            if not wrote then threw = true end
            local seen = readsBack(get, name, value)
            local tag = "?"
            if seen == true then tag = "ok" end
            if seen == false then tag = "REFUSED" end
            if not wrote then tag = "THREW" end
            -- @polarcore-seam:S28 — DFIntAssemblyHistorySkipSize is the ONLY load-bearing one: it is the
            -- decimation itself. The buffer size and the send rate are enhancements, so a "?" on either of
            -- them must not veto the restore. Gating on all three is what made verification unachievable.
            if name == "DFIntAssemblyHistorySkipSize" and seen == true then keyOk = true end
            detail = detail .. string.sub(name, 5) .. "=" .. tag .. " "
        end
        _physSet  = on and not threw
        _physLive = _physSet and keyOk and fpdhOk
        State.RagePhysVerified = _physLive
        State.RagePhysSet = _physSet   -- 11_lab derives the RESTORE readout from these two plus the config
        State.RagePhysDetail = detail .. "FPDH=" .. tostring(fpdhOk)
        local how = "verified"
        if not on then
            how = "off"
        elseif threw then
            how = "THREW"
        elseif not fpdhOk then
            how = "FPDH refused"
        elseif not keyOk then
            how = "SkipSize unproven"
        end
        State.RagePhysRate = setName .. " " .. how
    end

    -- ════════════════════════════════════════════════════════════════════════════════════════════════
    -- THE RESTORE. Read this whole block before changing any of it — it is the single most re-litigated
    -- mechanism in the project and every past change here was made on a theory that later broke.
    --
    -- ★ WHAT AN INDEPENDENT AUDIT OF THE LEAK ESTABLISHED (2026-08-09, both decompiles, 3 emissions each).
    -- CONFIRMED, no longer inference:
    --   · rootDesync (cleaned L143877-143954): `new` stores `_oldCFrame = rootPart.CFrame`; `_Initialize`
    --     binds `_RenderStepUpdate` at RenderPriority.First; `HeartbeatUpdate` saves the live pose then
    --     writes the park through the RAW `getrawmetatable(game).__newindex` (traced: L161687 -> clonefunction
    --     L184923 -> L184954 -> the call at L143945); `_RenderStepUpdate` restores with a PLAIN assignment
    --     (L143936). The raw-write / plain-restore asymmetry is real and consistent across all 6 sites.
    --   · `SetServerCFrame(cf)` ONLY stores into `_cframe` (L143910-143912). It never touches the part.
    --   · There is EXACTLY ONE park write and ONE restore per frame. Exhaustive search: no second
    --     BindToRenderStep, no PreSimulation/PreRender write, no task.defer, nothing.
    --   · `_replica` is a cosmetic ghost — a cloned model with Humanoid.Health = math.huge and the Entity
    --     tag stripped (L137284-137299). Not load-bearing. Do not port it.
    --   · The 66.7 ms dwell is PER-TARGET, not per-frame: `_attackStart` is set when the attack on this
    --     target begins and Plan returns a park with a nil weaponAction until it elapses (L13589).
    --
    -- ⛔ WHAT IS **NOT** ESTABLISHED, and what I previously asserted as fact:
    --   1. **The frame ordering is UNRECOVERABLE.** All four GameLoop callbacks
    --      (SetPreCameraRender/SetPreRender/SetPreSimulation/SetHeartbeat, L131478-131489) decompile to
    --      EMPTY STUBS in every emission of both files, and the ragebot controller module's factory is
    --      stubbed to `return nil` outright. Whether ragebot:Update runs before or after
    --      rootDesync:HeartbeatUpdate CANNOT BE READ. My "there is only one ordering it can have" was a
    --      guess dressed as a reading, and "Kicia fires from the previous frame's park" follows from it,
    --      so that is a guess too.
    --   2. **The park may not be what replicates for Kicia AT ALL.** Kicia sets
    --      `sethiddenproperty(ourPart, "PhysicsRepRootPart", enemyHeadHitbox)` at thread identity 8
    --      (L66278-66282 / L241257-241261) and drags that hitbox to a Y=100,000 rendezvous. If the physics
    --      sender replicates from PhysicsRepRootPart, then rootDesync's park is a purely LOCAL effect and
    --      Kicia's restore is free for the reason I originally proposed and then wrongly retracted: the
    --      park was never load-bearing for it. That depends on Roblox engine internals we cannot read.
    --
    -- So there are now TWO live explanations for why Kicia's restore is free — undecimated assembly history
    -- (Config.RagePhysicsFlags) and the part glue — and the evidence does not separate them. The hide is
    -- also still unexplained by the first one: during a hide `_firing` is false, so the void pose lives in
    -- exactly the sliver-window S8 gave the park, and the moving hide measurably takes ZERO damage over 30s.
    -- If a sliver-window pose replicates well enough to keep us unhittable, the same sliver should have
    -- carried the park. It did not.
    --
    -- ★★ SETTLED BY A SECOND INDEPENDENT ARTIFACT (2026-08-09). Operator: "i cant even move in restore".
    -- Read daydreamer's `ragerewrite.lua` L1381-1460 — its desync class is Kicia's, function for function:
    --      desync.new()            BindToRenderStep(guid, RenderPriority.First, renderstepupdate)
    --      heartbeatupdate()       oldcframe = part.CFrame ; write the park
    --      renderstepupdate()      write oldcframe back ; oldcframe = nil
    -- and CRUCIALLY **there is no Stepped re-park anywhere in it**, exactly as there is none in Kicia.
    -- Two independent shipped cheats, one shape. The park exists only from Heartbeat to the next render
    -- callback, and the body is at its REAL pose for render AND physics — which is precisely why movement
    -- stays native in both of them.
    --
    -- ⚠ SO "render" WAS MY INVENTION, AND IT IS THE THING THAT FROZE MOVEMENT. Re-parking at Stepped puts
    -- the park in front of the physics step every frame, so the character is simulated at the enemy's head
    -- instead of where the player is walking. That is not a variant of the rivals' design, it is a third
    -- design nobody proved, and [[operating-rules]] says do not reimplement a proven artifact. Demoted.
    --
    -- The S8 objection is noted and deliberately overruled: S8 measured weaker, but S8 ran this shape with
    -- the physics fflags UNVERIFIED, with 6 taps per frame, and firing from the current frame's park. All
    -- three are now different. And whatever the true explanation is (undecimated history vs the part glue),
    -- two artifacts that beat us both ship exactly this and both keep their movement.
    --
    -- ★★★ MEASURED, AND IT ENDS THE ARGUMENT (operator, 2026-08-09). Running Kicia on a second account and
    -- watching US through ITS esp: **in the live build the enemy sees us standing at our RESTORE point.**
    -- In the standalone they do not. That is a direct observation of the thing three sessions of theory
    -- could not settle: **the restore REPLICATES.** The physics sender does not confine itself to the
    -- Heartbeat->next-render window; it samples the restored pose, so every frame we restore while firing
    -- we hand the server our real body instead of the park, and the shot resolves from there.
    --
    -- ⛔ AND daydreamer IS NOT A SECOND WITNESS. `grep -rn PhysicsRepRootPart "daydreamer scirpt/"` returns
    -- NOTHING. It copied Kicia's desync class verbatim and did NOT copy the part glue that makes it safe —
    -- the same cross-contamination error we have now made four times, except daydreamer shipped it. So the
    -- previous entry's "two independent artifacts, one shape" was WRONG: it is one artifact and one copy of
    -- it. Kicia's restore is free because `sethiddenproperty(ourPart,"PhysicsRepRootPart",enemyHitbox)`
    -- means its root part's CFrame is not what replicates at all. Take the restore without the glue and the
    -- restore is simply a leak. That was my original hypothesis, I retracted it for the decimation theory,
    -- and the ESP observation restores it.
    --
    -- **For a NO-GLUE build the restore MUST be suppressed while firing.** That is the standalone, it is
    -- what the operator confirmed working, and it is the default again. The cost stands and is real:
    -- movement is dead for the ~83 ms a magazine lasts, and the park renders. The ONLY way to buy both is
    -- the glue (task #160) — not another restore variant.
    --
    --   "none"   (DEFAULT) the standalone / S27: neither anchor restores while firing, so the park is the
    --            body's pose for 100% of every frame and nothing can leak. Movement dead during a burst.
    --   "kicia"  park at Heartbeat, unconditional restore at RenderPriority.First, fire from the previous
    --            frame's park. ⚠ LEAKS WITHOUT THE GLUE — measured, see above. Keeps movement. Only useful
    --            as the A/B, or once #160 lands and the glue makes it correct.
    --   "render" restore for the render pass, re-park at Stepped. Movement still dead (physics steps the
    --            parked body), but the renderer never shows the park. Costs power for cosmetics; A/B only.
    -- @polarcore-seam:S37 — the glue FORCES "kicia" for as long as it is live, and this is not a preference.
    -- With the glue installed the park is the rendezvous, 100k studs out. Under "none" the body is left
    -- there for the whole burst, which does not desync us, it removes us from the match. Kicia's own pair is
    -- Heartbeat-park + RenderPriority.First-restore, i.e. exactly "kicia" — and the restore is free precisely
    -- because the glue is what replicates. Neither half works without the other, so they are chosen together.
    -- Declared before restoreMode purely for ordering; glueActive is defined with the rest of the glue.
    local glueActive
    -- ⛔ @polarcore-seam:S43 ZERO CYCLE WAS HERE AND IS REVERTED (2026-08-12, same day). Full tombstone in
    -- 02_config. Short version: the operator measured the build WEAKER THAN BASELINE WITH THE TOGGLE OFF,
    -- in a matchup we had been winning. Nothing in S43 should have executed with it off, which is exactly
    -- why the whole seam came out rather than being patched — an unexplained regression is not something to
    -- narrow down while it sits on the attack path.
    local function restoreMode()
        if glueActive ~= nil and glueActive() then return "kicia" end
        local m = Config.RageRestoreMode
        if m == "kicia" or m == "render" or m == "none" then return m end
        return "none"
    end

    -- @polarcore-seam:S15 — THE ASYMMETRY IN KICIA'S RESTORE. Re-read 2026-08-07 after four failed fixes,
    -- and it is the one structural difference left between its desync and ours.
    --
    -- Kicia does NOT write the displacement with a plain assignment. Both `t201:HeartbeatUpdate` and its
    -- flat duplicate `f9579` write it as a THREE-ARG call, `up0(rootPart, "CFrame", cframe)`, while
    -- `_RenderStepUpdate` restores with a plain `rootPart.CFrame = old`. The same 3-arg shape appears
    -- again in the ragebot's SetEnabled for `FallenPartsDestroyHeight`, and the binding block that
    -- resolves setfflag/pcall/sethiddenproperty (leak L161674-161693) captures, in the same breath,
    -- `getrawmetatable(game).__newindex` and `.__index`. So: displacement through the RAW Instance
    -- __newindex, restore through the normal one. Deliberate, and only in that direction.
    --
    -- Why it can cost us the first bullet: anything that has hooked Instance __newindex sees ONLY our
    -- restore — the legitimate in-map pose — and never the park. Rivals ships movement telemetry on that
    -- surface (JustWarped). If the game observes and corrects a character CFrame write it does not like,
    -- a plainly-assigned park can be undone before it replicates, while Kicia's never is. That produces
    -- exactly what the operator sees: an opening volley the server resolves from the real body, into a
    -- wall, with the rest of the magazine landing once the park sticks.
    --
    -- Fails back to a plain assignment if the metatable is protected or the call throws, so this is
    -- strictly no worse than the previous behaviour. The RESTORE stays a plain assignment on purpose —
    -- that is the write Kicia lets the game see, and the one that should look ordinary.
    -- @polarcore-seam:S34 — resolved once, cached. `_identTried` starts false so the resolve runs on the
    -- first write of the session and never again.
    local _identGet, _identSet = nil, nil
    local _identTried = false

    -- @polarcore-seam:S27 — the standalone writes the park with a PLAIN ASSIGNMENT (polar_movinghide L356)
    -- and beats Kicia doing it. Whether `getrawmetatable(game).__newindex` resolves at all is executor- and
    -- session-dependent, and one throw disables it permanently mid-session — so S15 makes the single most
    -- load-bearing write in the engine take one of two different code paths depending on how the session
    -- started. That is a textbook source of "sometimes it performs like the standalone, sometimes it does
    -- not". Under parity there is exactly one write path, the proven one.
    -- @polarcore-seam:S34 — BOTH rivals ELEVATE THREAD IDENTITY FOR THE PARK WRITE; we were the only one
    -- doing a bare assignment. daydreamer's `writecframe` (ragerewrite.lua L1382-1397) sets identity 8,
    -- writes, restores the previous identity, and falls back to a plain assignment if any of that fails.
    -- Kicia reaches the same place differently (the raw `getrawmetatable(game).__newindex`, itself captured
    -- alongside its identity-8 `sethiddenproperty` helper). Two artifacts, one intent: do not let the write
    -- be observed or refused at script identity.
    -- Identity 8 is chosen over S15's raw metamethod because it is strictly less fragile — no metatable to
    -- be protected, nothing to permanently disable on one throw — and because daydreamer proves it in this
    -- exact game. Every step is individually pcall'd and the plain assignment remains the final fallback,
    -- so on an executor with no identity API this is byte-for-byte the standalone's write.
    -- Resolved once per session. Split out of rawSetCFrame because seam S36's redirect needs the same API
    -- and must be able to ask for it without pretending to write a CFrame.
    local function identEnsure()
        if _identTried then return _identSet ~= nil end
        _identTried = true
        pcall(function()
            local g = getthreadidentity or get_thread_identity
            local s = setthreadidentity or set_thread_identity or setidentity or setthreadcontext
            if type(g) == "function" and type(s) == "function" then
                _identGet, _identSet = g, s
            end
        end)
        State.RageRawSet = _identSet ~= nil
        return _identSet ~= nil
    end

    local function rawSetCFrame(hrp, cf)
        identEnsure()
        if _identSet ~= nil then
            local okPrev, prev = pcall(_identGet)
            if okPrev then
                pcall(_identSet, 8)
                local wrote = pcall(function() hrp.CFrame = cf end)
                pcall(_identSet, prev)
                if wrote then return true end
            end
        end
        return pcall(function() hrp.CFrame = cf end)
    end

    -- ════════════════════════════════════════════════════════════════════════════════════════════════
    -- @polarcore-seam:S37  THE PART GLUE — KICIA'S MECHANISM, TRANSPLANTED EXACTLY.
    -- PhysicsGlue: cleaned decompile L149574-149679. Caller chain: L136883-136932.
    --
    -- Everything before this seam tried to solve one problem: the park has to be on the wire, but the body
    -- has to be here. S8 / "render" / "kicia" / S35 are four different compromises between those, and every
    -- one either leaked the restore (measured on enemy esp) or froze movement or was cosmetic. They are all
    -- the wrong shape, because they all accept the premise that OUR BODY is what replicates.
    --
    -- ⛔ S36 REJECTED THAT PREMISE AND STILL GOT IT WRONG, AND THE REASON MATTERS. It pointed the redirect
    -- at a part we made with `Instance.new` — and a part created on the client has NO NETWORK IDENTITY. The
    -- server has never heard of it, so when the physics sender resolves our assembly through
    -- PhysicsRepRootPart there is nothing it can serialize. `gethiddenproperty` reading the anchor back only
    -- ever proved the LOCAL property write took, which is not the same claim. The source says the same thing
    -- by omission and says it loudly: all ten `Instance.new("Part")` sites in Kicia are cosmetic (effects
    -- anchor, LightningExplosion, WeatherEmitter). Eight developers took on breaking a WeldConstraint,
    -- anchoring another player's hitbox and a per-session rendezvous when three lines of Instance.new would
    -- have done. Nobody pays that price when the cheap version works. That absence IS the experiment.
    --
    -- So this is the real one. Per frame, with a target:
    --   1. sethiddenproperty(ourRoot, "PhysicsRepRootPart", theirHitboxHead) at threadidentity 8
    --   2. break that hitbox's WeldConstraint.Part1 and anchor it — so dragging it does not drag their rig,
    --      and their rig does not drag it back
    --   3. write the hitbox to a per-session RENDEZVOUS ~100k studs out
    --   4. park our own root at rendezvous + (0,-0.7,0.05). Kicia STILL spends this body write every frame
    --   5. restore the body before the render pass, which is free now: the server resolves us from the
    --      hitbox, so the restored pose is not what replicates. That is why Kicia's restore costs nothing
    --      and ours leaked.
    --
    -- ★ THE RENDEZVOUS IS A CO-LOCATION POINT, NOT A HIDING PLACE — and that resolves the |char0 - char2|
    -- <= 400 contradiction this task was blocked on. BOTH endpoints land there, 0.7 studs apart, so the
    -- range model passes trivially while the pair sits 100k studs from every other player's geometry. It is
    -- also why step 4 is not redundant with step 1: the park is what keeps us next to char2.
    --
    -- ⚠ THIS MUTATES ANOTHER PLAYER'S CHARACTER — a write class nothing else in this bundle performs. Local
    -- writes only (we do not own those parts, so none of it replicates), and every field is saved before the
    -- first write and restored on release. BURNER ONLY.
    --
    -- FALLS BACK COMPLETELY: no sethiddenproperty, no identity API, no weld, a refused redirect or a throw
    -- anywhere and `glueActive()` stays false, the hitbox is put back, and Polar runs the body-park path
    -- exactly as it does today under RageRestoreMode. The worst case is the build already measured beating
    -- Kicia.
    --
    -- Kicia's exact distribution, rolled once per session (L149575-149579). Deliberately NOT re-rolled per
    -- target: a rendezvous that moves is a second teleport on the wire for no benefit.
    local _rvCF = nil
    -- Kicia's normal-stance park offset (L136943). It also carries a -3.85 variant for a "Below" fighter
    -- state we have no way to read, so we ship the standing case only rather than guess at the other.
    local GLUE_PARK_OFF = Vector3.new(0, -0.7, 0.05)
    -- @polarcore-seam:S38  THE GLUE-PATH WIRE FORMAT. Shipping S37 without this is why the first live run
    -- landed nothing: with the glue installed, Kicia does NOT send the park as char0/char1. It sends fixed
    -- constants (cleaned L136945-136977, forwarded to ShootEncoded at L136924-136932), because the glue is
    -- what places us — the packet has no business also claiming a position, and ours claimed the rendezvous
    -- 100k studs out, so the server threw every shot away.
    -- ★ THE SAME CROSS-CONTAMINATION ERROR AS S21/S25, IN THE OTHER DIRECTION. S21 took these sentinels
    -- WITHOUT the glue and failed; S37 took the glue WITHOUT the sentinels and failed. They are ONE unit.
    -- `-9e37` is not a coordinate and was never meant to be read as one — it is the marker that says the
    -- position fields are dead on this packet.
    -- Kicia also carries +pi/2 variants for a "Below" fighter state we cannot read; the standing pair is
    -- shipped alone rather than guessing at the other, exactly as with GLUE_PARK_OFF.
    -- Shape matches Rivals.Util:EncodeCFrame's own output — six keys, x/y/z then pitch/yaw/roll — so these
    -- drop straight into the camData slots the proven builder fills.
    local GLUE_CHAR0 = {
        [utf8.char(0)] = -9e37,
        [utf8.char(1)] = 0,
        [utf8.char(2)] = 0,
        [utf8.char(3)] = -math.pi / 2,
        [utf8.char(4)] = math.pi,
        [utf8.char(5)] = math.pi,
    }
    local GLUE_CHAR1 = {
        [utf8.char(0)] = 0,
        [utf8.char(1)] = -90000000,
        [utf8.char(2)] = 0,
        [utf8.char(3)] = -math.pi / 2,
        [utf8.char(4)] = math.pi,
        [utf8.char(5)] = math.pi,
    }
    local GLUE_CHAR3 = {
        [utf8.char(0)] = 0,
        [utf8.char(1)] = 1,
        [utf8.char(2)] = 0,
        [utf8.char(3)] = 0,
        [utf8.char(4)] = 0,
        [utf8.char(5)] = 0,
    }
    local _glueHit       = nil    -- the enemy hitbox the server currently resolves us from
    local _glueWeld      = nil    -- its WeldConstraint, when it had one
    local _glueWeldPart1 = nil    -- that weld's original Part1
    local _glueAnchored  = nil    -- the hitbox's original Anchored
    -- Our root's PhysicsRepRootPart before we ever wrote it. Kicia gives NO precedent for a release value:
    -- PhysicsGlue:Free (L149617-149624) and :Destroy (L149663-149679) restore only the hitbox's weld and
    -- Anchored, and never un-set the property at all. Writing the root part back to itself was a guess;
    -- reading the engine's own default and restoring exactly that is not.
    local _gluePrev   = nil
    local _gluePrevOk = false
    -- @polarcore-seam:S44 GUM — "off" | "lite" | "on". Written so NO config key can be inert, because an
    -- inert toggle has burned this project twice (RageRestoreMode "auto" -> "none" made the whole
    -- translocate seam dead code; a parity veto above a config read made three ON-by-default GUI toggles do
    -- nothing). Precedence: RageGumMode wins when it names one of the three modes; failing that the legacy
    -- RageGlueMode is read and its "full" maps to "on"; failing that the older boolean RagePartGlue can
    -- still promote to "on" — so neither an operator who only knows RagePartGlue nor a config saved before
    -- the 2026-08-14 rename is silently ignored. Rage._gumDiag() prints whatever this resolves to.
    local function gumMode()
        local m = Config.RageGumMode
        if m ~= "off" and m ~= "lite" and m ~= "on" then
            -- legacy RageGlueMode, whose third mode was spelled "full"
            local g = Config.RageGlueMode
            if g == "lite" or g == "off" then
                m = g
            elseif g == "full" then
                m = "on"
            else
                m = "off"
            end
        end
        if m == "off" and Config.RagePartGlue == true then return "on" end
        return m
    end
    -- @polarcore-seam:S44 — the LITE binding is tracked SEPARATELY from _glueHit, and that separation is
    -- load-bearing in three places rather than a style choice:
    --   1. glueActive() (_glueHit ~= nil) is what forces restoreMode() to "kicia". Lite parks normally, so
    --      it must NOT force the transport — keeping _glueHit full-only leaves that line alone.
    --   2. The same predicate picks the WIRE FORMAT at the fire site. Lite must keep sending the proven
    --      buildShotFields packet: the S38 -9e37 sentinels are only correct WITH the rendezvous park, and
    --      under lite our body really is on the target's head, so real geometry is the truthful thing.
    --   3. The full-glue path's `else glueRelease() end` runs on every lite frame. glueRelease() guards on
    --      _glueHit, so with a separate handle it is a free no-op instead of tearing lite down and forcing a
    --      release-plus-reacquire — two wasted hidden-property writes every frame.
    local _liteHit    = nil
    local _liteDriven = false
    -- Set on every frame something actually drives the glue. The watchdog in the Heartbeat reads it.
    local _glueDriven = false
    local TRANSLOCATE_PULSES_PER_BURST = 2
    -- @polarcore-seam:S42 — shooting frames to spend before the FIRST poison pulse of a burst. ~12 frames
    -- is ~0.2s at 60fps: the payload is a corrupted velocity sample, so it is only worth spending once an
    -- enemy is actually tracking us and has a history to corrupt. Counted in frames rather than seconds
    -- because what matters is how many position samples of ours they have taken, and that is per-frame.
    -- ⚠ A DWELL WAS TRIED AND REMOVED (2026-08-12). Holding the volume 0.22s was built on a misreading —
    -- that a pursuer had to follow us in and die there. The operator corrected it: "if kicia in translocate
    -- even we can attack it, its not that being in translocate is unhittable, thats not the mechanism."
    -- The volume is not cover, so a dwell buys nothing and costs exposure plus fire time. One frame is the
    -- correct dose: at DFIntS2PhysicsSenderRate = 120 the displaced position goes out about twice in a
    -- single frame (see S10), so the poisoned sample reaches every enemy without us lingering anywhere.
    local TRANSLOCATE_ARM_FRAMES = 12
    local _translocateFireFrames = 0
    local _translocateNext = false
    local _translocateBurstPulses = 0
    local _translocatePart = nil

    -- Kicia's exact call shape: identity 8 around the sethiddenproperty, previous identity restored.
    -- READ IT BACK. `pcall` returning true only means the setter did not throw, and this is the one write
    -- in the bundle whose silent failure is invisible — a redirect that did not take looks exactly like a
    -- redirect that did, right up until every shot resolves from our real body. Where gethiddenproperty
    -- exists we compare identity; where it does not we report "unverified" rather than pretending.
    local function setRepRoot(part, target)
        if _identSet == nil then return false end
        local ok, seen = false, nil
        pcall(function()
            local prev = _identGet()
            _identSet(8)
            local wrote = pcall(sethiddenproperty, part, "PhysicsRepRootPart", target)
            if wrote and type(gethiddenproperty) == "function" then
                local okR, v = pcall(gethiddenproperty, part, "PhysicsRepRootPart")
                if okR then seen = v end
            end
            _identSet(prev)
            ok = wrote
        end)
        if not ok then return false end
        if seen == nil then
            State.RageGlueVerified = "unverified (no gethiddenproperty)"
            return true
        end
        if seen ~= target then
            State.RageGlueVerified = "REFUSED (read back " .. tostring(seen) .. ")"
            return false
        end
        State.RageGlueVerified = "verified"
        return true
    end

    -- @polarcore-seam:S44 LITE GLUE — UE's shape. Hand replication back to our own root and forget the
    -- binding. Deliberately does NOT touch _glueHit, _glueWeld, _glueAnchored or the rendezvous: lite never
    -- creates any of them, so there is nothing on the victim's character to reassemble. That is the entire
    -- safety argument for this mode — the only thing it ever changed is one hidden property on OUR OWN root.
    local function liteRelease()
        if _liteHit == nil then return end
        _liteHit    = nil
        _liteDriven = false
        State.RageGlueBound = false
        local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then return end
        local back = hrp
        if _gluePrevOk then back = _gluePrev end
        setRepRoot(hrp, back)
        State.RageGlueVerified = "released"
    end

    -- @polarcore-seam:S44 — the redirect and NOTHING ELSE, which is what the UE dump shows and what makes
    -- this the single-variable experiment that "full" can never be. Same target as Kicia and full: the
    -- enemy's own hitbox, the only part in play the server has ever heard of (that was the whole S36
    -- correction and it applies identically here). Same exclusions as full, for the same reasons:
    --   predicting — S17 is parked on a REMEMBERED head because the real one is in the void, so redirecting
    --                at that hitbox would put us on the wire wherever the void put it, and we are holding
    --                fire anyway.
    --   melee      — a melee swing is validated against a ~7-stud reach from our replicated body, so moving
    --                that body away from the target rejects every swing. Same trap S21/S25 fell into.
    -- Returns true only when the redirect is live AND read back as ours.
    local function liteAcquire(hit, predicting, melee)
        if gumMode() ~= "lite" or predicting or melee then
            liteRelease()
            return false
        end
        -- Every early exit releases. The full path can rely on its caller's `else glueRelease() end`; lite has
        -- no such branch, so the only other backstop is the Heartbeat watchdog a frame later — and "a
        -- half-installed redirect must never survive a frame" is the rule this whole seam is built around.
        if type(sethiddenproperty) ~= "function" then
            liteRelease()
            return false
        end
        if not identEnsure() then
            liteRelease()
            return false
        end
        if hit == nil or hit.Parent == nil then
            liteRelease()
            return false
        end
        local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then
            liteRelease()
            return false
        end
        -- Read the engine's own default BEFORE the first write, while it is still the engine's value.
        -- Shared with the full path on purpose: both write the same property on the same root part, and
        -- whichever gets there first captures the same truthful default.
        if not _gluePrevOk and type(gethiddenproperty) == "function" then
            local okP, v = pcall(gethiddenproperty, hrp, "PhysicsRepRootPart")
            if okP then
                _gluePrev   = v
                _gluePrevOk = true
            end
        end
        -- Unconditional, every frame, exactly Kicia's ordering (L149600 calls the setter before the binding
        -- check). A redirect that silently stopped taking looks identical to one that took.
        if not setRepRoot(hrp, hit) then
            liteRelease()
            return false
        end
        _liteHit    = hit
        _liteDriven = true
        State.RageGlueBound = true
        return true
    end

    -- "Is the body currently parked at a rendezvous?" — which is the question the restore coupling actually
    -- needs, and it is true from the moment we bind until glueRelease clears it. Deliberately NOT
    -- `and _glueHit.Parent ~= nil`: a target dying mid-burst nils the hitbox's Parent between our Heartbeat
    -- park and the next render, which would flip restoreMode() back to "none" for exactly one frame and
    -- leave the body stranded 100k studs out with the restore switched off. Only release clears this.
    -- Assignment, not `local function`: restoreMode above forward-declares it and a second `local` there
    -- would shadow that one and leave the restore coupling reading a permanent nil.
    glueActive = function()
        return _glueHit ~= nil
    end

    -- Kicia's _SetupGlue (L149626-149644). It only anchors when the part HAS a WeldConstraint, and that
    -- condition is kept: a hitbox with no weld is left exactly as found. The decompile's finder is a
    -- two-arg `up0(part, "WeldConstraint")` which reads as either a class or a name lookup, so try both.
    local function glueSetup(hit)
        local weld = hit:FindFirstChildOfClass("WeldConstraint")
        if weld == nil then weld = hit:FindFirstChild("WeldConstraint") end
        if weld == nil then return end
        _glueWeld      = weld
        _glueWeldPart1 = weld.Part1
        _glueAnchored  = hit.Anchored
        pcall(function()
            if _glueWeldPart1 ~= nil then weld.Part1 = nil end
            hit.Anchored = true
        end)
    end

    -- Put the victim's character back exactly as found.
    -- ⚠ DELIBERATE DIVERGENCE FROM KICIA, and it is a bug fix, not a preference. Its _ReleaseGlue
    -- (L149646-149661) un-anchors `originalPart1` — the part the weld USED to point at — while _SetupGlue
    -- anchored the HITBOX. So Kicia leaves every hitbox it ever touched anchored for the rest of the round
    -- and anchors a part it never touched, and :Destroy (L149663-149679) does not restore Anchored at all.
    -- Nothing downstream in Kicia reads either flag so it never surfaces there. We restore what we changed.
    local function glueTeardown()
        local weld, part1, hit, anch = _glueWeld, _glueWeldPart1, _glueHit, _glueAnchored
        _glueWeld, _glueWeldPart1, _glueAnchored = nil, nil, nil
        pcall(function()
            if weld ~= nil and weld.Parent ~= nil and part1 ~= nil then weld.Part1 = part1 end
            if hit ~= nil and hit.Parent ~= nil and anch ~= nil then hit.Anchored = anch end
        end)
    end

    -- Hand replication back to our real body and reassemble the victim. MUST run on teardown, death,
    -- character change, and any frame nothing drove the glue: the server resolving us from a part nobody
    -- updates means frozen on the wire, at the last rendezvous, with the cheat switched off.
    local function glueRelease()
        State.RageTranslocating = false
        if _glueHit == nil then return end
        glueTeardown()
        _glueHit    = nil
        _glueDriven = false
        State.RageGlueBound = false
        local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then return end
        local back = hrp
        if _gluePrevOk then
            back = _gluePrev
        end
        setRepRoot(hrp, back)
        -- setRepRoot leaves its own verdict behind; it describes the RESTORE write, not a live redirect.
        State.RageGlueVerified = "released"
    end

    -- Kicia's Acquire (L149599-149615), minus the refcount: we have exactly one root part, so at most one
    -- binding can exist and the count could only ever be 1. Returns the rendezvous POSITION to park beside,
    -- or nil when the glue could not be installed — every caller then falls back to the body-park path.
    local function glueAcquire(hit)
        -- @polarcore-seam:S44 — was `Config.RagePartGlue == false`. Now the mode resolver, so "lite" cannot
        -- reach the rendezvous path and RagePartGlue = true still means "full" for anyone who only knows
        -- that key. Returning nil is what routes the caller onto the ordinary body-park path.
        if gumMode() ~= "on" then return nil end
        if type(sethiddenproperty) ~= "function" then return nil end
        if not identEnsure() then return nil end
        if hit == nil or hit.Parent == nil then return nil end
        local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then return nil end
        -- Read the engine's own default BEFORE the first write, while it is still the engine's value.
        if not _gluePrevOk and type(gethiddenproperty) == "function" then
            local okP, v = pcall(gethiddenproperty, hrp, "PhysicsRepRootPart")
            if okP then
                _gluePrev   = v
                _gluePrevOk = true
            end
        end
        -- Unconditional, every frame, BEFORE the binding check — Kicia's exact ordering (L149600).
        if not setRepRoot(hrp, hit) then
            glueRelease()
            return nil
        end
        if _glueHit ~= hit then
            glueTeardown()          -- reads the OLD _glueHit, so it must run before the reassignment
            _glueHit = hit
            glueSetup(hit)
        end
        if _rvCF == nil then
            _rvCF = CFrame.new(math.random(-100000, -10000), 100000, math.random(-100000, 10000))
        end
        local rv = _rvCF.Position
        -- Kicia writes POSITION ONLY here (L149609): `CFrame.new(v188.Position)`, rotation preserved only
        -- when its third arg is passed, and the ragebot call site passes two args.
        local moved = pcall(function() hit.CFrame = CFrame.new(rv) end)
        if not moved then
            -- Half-installed is the one state that must never survive a frame: the redirect is live and
            -- pointing at a hitbox we are not driving.
            glueRelease()
            return nil
        end
        _glueDriven = true
        State.RageGlueBound = true
        return rv
    end

    -- Every displacement goes through here so exactly one place is responsible for remembering the real
    -- pose. Guarded against double-save: two writes in one frame must not overwrite the true CFrame with
    -- an already-displaced one.
    -- Returns whether the write actually went through. The caller needs that: latching "we were parked
    -- here" after a write that threw is how a burst ends up firing from a park the body never reached.
    local function displace(hrp, cf)
        if _preParkCF == nil then _preParkCF = hrp.CFrame end
        return rawSetCFrame(hrp, cf)
    end

    -- @polarcore-seam:S10 FIRE FROM THE PREVIOUS FRAME'S PARK.
    -- Operator-observed: the first shot of every burst hits a wall, the rest of the mag hits the head.
    -- Cause is ordering, not latency. FireServer runs synchronously inside the same Heartbeat that writes
    -- the park, so the shot leaves the client BEFORE the engine's replication sender has sent the new
    -- position — at every ping, every time. The server resolves that first volley from THE LAST DISPLACED
    -- POSE IT WAS SENT, and on the opening frame of a burst that is still the hide. (It is NOT our real
    -- in-map pose: the restore is invisible to the sender — see the neutrality argument at the anchors —
    -- so the sender never carries the restored body. An earlier version of this note said otherwise.)
    -- Fix: build the shot's eye/muzzle from the park we wrote LAST frame — a position the server has
    -- already received — while still aiming at the target's CURRENT head. One frame of target movement is
    -- far inside both the range cap and LOS at point-blank, so the stale eye costs nothing.
    -- This is NOT the reverted settle timer: nothing waits on a clock and no latency is estimated. We
    -- simply stop firing on the one frame whose rounds are guaranteed to be wasted.
    local _prevPark    = nil
    local _prevParkTgt = nil
    -- @polarcore-seam:S30 — the pose the Stepped anchor re-parks to under the "render" policy. Written only
    -- where a park write actually LANDED, so a throw can never leave us re-parking to a stale coordinate.
    local _lastPark    = nil

    -- @polarcore-seam:S12+S14 — ONE MECHANISM: the dwell between "ready to attack" and "first shot", spent
    -- PARKED rather than hidden. It does two jobs that used to be separate and that fought each other.
    --
    -- S14 PRIME (the wall-bullet fix, and the reason this was reworked). Kicia holds the park for a hard
    -- 1/15 s before the first shot of every attack window — literal `0.06666666666666667` in BOTH its
    -- HitscanStrategy:Plan and MeleeStrategy:Plan (leak L268165 / L268281). That constant is exactly one
    -- period of the stock DFIntS2PhysicsSenderRate = 15, the same 15 it writes back on disable. So it is a
    -- replication dwell, not a reaction time. S10's single frame (~16ms) is a 4x UNDER-LEAD at the stock
    -- rate: the server learns a fresh park only about once every four frames, so the opening rounds of a
    -- burst resolve from the hide and go into a wall. PRIME_S covers one stock period with margin.
    --   ⚠ This is NOT the reverted ping-derived settle timer. That one was keyed to RTT, which is the wrong
    --   quantity entirely — the round trip has nothing to do with it; the LOCAL sender period does. And it
    --   waited while we were able to shoot. This waits only in time the magazine was empty anyway.
    --
    -- S12 JITTER (unchanged purpose). Kicia's SpatialLimitGate learns how long each enemy stays voided and
    -- opens fire Stability = 0.15s BEFORE their predicted resurface — that is how it eats UE's fixed
    -- 620/140ms cycle. Our hide length is the reload, a game constant, so we are exactly as learnable. Only
    -- the DURATION is observable (the predictor times from the threshold crossing and never sees our
    -- phase), and the spread has to exceed the 0.15s lead or it just moves the mean. Hence 0-250ms.
    --
    -- WHY THEY MERGE: the old S12 spent its extension in the VOID, so the park was thrown away and rebuilt
    -- from scratch afterwards — it would have cancelled a reload-tail pre-park every single time. Spending
    -- the same milliseconds on the head instead makes the jitter double as the prime, and the first shot
    -- after it fires from a park that has been standing for 70-320ms. Net new no-fire time is PRIME_S
    -- alone, ~3% of a ~2.5s cycle, against ~6 rounds of a 30-round magazine recovered.
    -- The cost is honest and real: those 70-320ms are now exposed at the enemy's head instead of hidden.
    -- Kicia pays the same exposure and does not even get the jitter for it.
    local PRIME_S         = 0.07   -- >= 1/15s, the stock physics-sender period. Kicia's number, rounded up.
    local HIDE_JITTER_MAX = 0.25
    local _hiding     = false
    local _primeUntil = 0

    -- @polarcore-seam:S11 HACKER TAGGING. Kicia's own classifier is stubbed in BOTH emissions of the leak
    -- (`function Update() end`, L96466 and L240385), so the heuristic is unrecoverable. What survives is
    -- its SHAPE: the classifier holds `_speedTimers` and `_notified` per fighter and the tag is sticky
    -- (`_playerTags:Add` returns false if already present, and it is only ever cleared when the fighter
    -- leaves). So: sustained impossible speed, latched once tripped. Reconstructed here, plus a second
    -- signal Kicia cannot use but we can — a body outside the sane coordinate box is voided, and no
    -- legitimate mechanic in Rivals puts a player there. That one is instant and has no false positives.
    local HACK_SPEED = 120     -- studs/s. Base walkspeed plus every boost stays far below this.
    local HACK_ACCUM = 0.15    -- seconds of sustained anomaly before the tag latches
    local _hackTag   = {}
    local _lastSeen  = {}
    local _hackAccum = {}

    local function tickHackers(dt)
        if dt <= 0 or dt > 0.5 then return end   -- a hitch would fake an enormous speed
        for _, p in Players:GetPlayers() do
            if p ~= lp and not _hackTag[p] then
                local c = p.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local pos = hrp.Position
                    if not isSanePos(pos) then
                        _hackTag[p] = true
                    else
                        local last = _lastSeen[p]
                        if last then
                            if (pos - last).Magnitude / dt > HACK_SPEED then
                                local a = (_hackAccum[p] or 0) + dt
                                _hackAccum[p] = a
                                if a >= HACK_ACCUM then _hackTag[p] = true end
                            else
                                _hackAccum[p] = 0
                            end
                        end
                        _lastSeen[p] = pos
                    end
                end
            end
        end
    end

    -- @polarcore-seam:S17 RESURFACE PREDICTOR — our answer to Kicia's SpatialLimitGate (leak L142216).
    -- Kicia times how long each enemy stays past 2^22 studs and opens fire Stability = 0.15s BEFORE the
    -- learned resurface, so it is already parked and mid-dwell when a periodic, open-loop rager (UE's
    -- 620ms void / 120-160ms surface) materialises. Without it the surface window plays out as: notice
    -- (1 frame) -> leave the void (1 frame) -> park (1 frame) -> serve PRIME_S (~70ms) -> fire with
    -- whatever is left of ~140ms. With it we spend the whole window firing.
    --
    -- THREE DELIBERATE IMPROVEMENTS ON KICIA:
    --  1. MEDIAN of the last 5, not its last-value overwrite. Kicia recomputes expectedDuration from the
    --     single most recent cycle, so one anomalous absence (a death, a lag spike, a reload-extended
    --     hide) destroys its next prediction outright. A median of 5 shrugs that off.
    --  2. Reachability is "is their head at a SANE coordinate", not "past 2^22". Kicia's threshold only
    --     sees a deep voider; ours sees any absence, at any depth, including a body that simply despawned.
    --     It is also independent of OUR position, which matters because we are in the void half the time.
    --  3. Bounded wrongness: once elapsed exceeds median + LEAD the model has missed for this cycle and we
    --     stop believing it and hide, so a bad prediction costs at most 2*LEAD of exposure, once.
    --
    -- ⚠ WHERE we pre-park is the honest weak point. We use their LAST KNOWN head, which is right for a
    -- normal player and for anything that resurfaces where it left. UE is measured to park ~4.7 studs from
    -- ITS target, so if it resurfaces onto us instead this pre-park is simply wrong -- and costs one frame
    -- to re-park, i.e. exactly today's behaviour. Never worse, so it ships; but this is the term to
    -- revisit with live data, not the timing.
    local PRED_LEAD    = 0.15   -- Kicia's Ragebot.Stability, verbatim
    local PRED_MIN     = 0.05   -- shorter absences are noise (one frame of a missing character model)
    local PRED_MAX     = 10.0   -- longer ones are a death or a leave, not a combat cycle
    local PRED_SAMPLES = 5
    local PRED_NEEDED  = 3      -- refuse to predict from fewer than this; Kicia guesses from 1 (seeded 1.0s)
    local _predHidden  = {}     -- player -> os.clock() when their head stopped being sane
    local _predDur     = {}     -- player -> ring buffer of absence durations
    local _predLast    = {}     -- player -> last sane head position

    local function isSanePos(p)
        return p == p
            and math.abs(p.X) < SANE_POS_LIMIT
            and math.abs(p.Y) < SANE_POS_LIMIT
            and math.abs(p.Z) < SANE_POS_LIMIT
    end

    -- @polarcore-seam:S17 — one pass per Heartbeat, before every early return, so a cycle is still learned
    -- while we are reloading, hiding or dead. Allocation-free in the steady state.
    local function tickPredict()
        local now = os.clock()
        for _, p in Players:GetPlayers() do
            if p ~= lp then
                local c = p.Character
                local hh = nil
                if c then hh = c:FindFirstChild("HitboxHead") or c:FindFirstChild("Head") end
                -- PRE-WARM THE PROTECTION MIRROR (2026-08-09, operator asked for faster detection).
                -- isSpawnProtected is O(1) once subscribed, but the FIRST call for a new entity does the
                -- :Get() and the GetDataChangedSignal hookup inline. Paying that on the frame we acquire a
                -- target is the one moment it can cost a decision. This loop already walks every player
                -- every Heartbeat, so warming it here means the mirror is always live before the target
                -- path asks, and a respawn re-subscribes on the same frame the new entity appears.
                isSpawnProtected(p)
                -- @polarcore-seam:S37 identified the right hazard — "OUR OWN GLUE has this hitbox 100k studs
                -- out right now, so both branches below would learn a lie" — and then took the wrong cure:
                -- it SKIPPED the player. That starved the model. While glued we stopped clearing _predHidden,
                -- stopped learning durations and stopped refreshing _predLast, so aboutToResurface — the one
                -- gate S45's void prefire depends on — had nothing to work with and mostly answered "no",
                -- which resolves to hide. The glue put us in the void branch and simultaneously blinded the
                -- only thing that could get us out of it.
                -- @polarcore-seam:S46 — the cure is to MEASURE A PART WE NEVER MOVE, exactly as Kicia
                -- (aliveState.rootPart, cleaned :141530) and daydreamer (entry.root = ent.RootPart) both do.
                -- HumanoidRootPart is untouched by the glue — no weld break, no anchor, no CFrame write — so
                -- it keeps carrying the target's real replicated position even mid-drag. Learning is now
                -- CONTINUOUS through a glue instead of suspended, which is strictly more samples than the
                -- rivals get and is what makes our median-of-5 better than their last-value overwrite.
                local rp   = c and c:FindFirstChild("HumanoidRootPart") or nil
                local mine = hh ~= nil and hh == _glueHit
                -- Fall back to the head ONLY when it is not ours to lie with.
                local ref  = rp
                if ref == nil and not mine then ref = hh end
                if ref ~= nil and isSanePos(ref.Position) then
                    -- Remember a HEAD position (that is what the pre-park wants), but never one we dragged.
                    if hh ~= nil and not mine then _predLast[p] = hh.Position end
                    local since = _predHidden[p]
                    if since ~= nil then
                        _predHidden[p] = nil
                        local d = now - since
                        if d >= PRED_MIN and d <= PRED_MAX then
                            local r = _predDur[p]
                            if r == nil then
                                r = {}
                                _predDur[p] = r
                            end
                            r[#r + 1] = d
                            if #r > PRED_SAMPLES then table.remove(r, 1) end
                        end
                    end
                elseif ref ~= nil and _predHidden[p] == nil then
                    _predHidden[p] = now
                end
            end
        end
    end

    -- Median of the ring. Copied by hand rather than table.clone/table.sort on the live ring: sorting the
    -- ring in place would destroy the arrival order that makes it a sliding window.
    local function predMedian(p)
        local r = _predDur[p]
        if r == nil or #r < PRED_NEEDED then return nil end
        local s = {}
        for i = 1, #r do s[i] = r[i] end
        table.sort(s)
        return s[math.floor(#s / 2) + 1]
    end

    -- True only inside [median - LEAD, median + LEAD] of the current absence. Past that the model has
    -- missed for this cycle, so we stop believing it and go back to hiding — a wrong prediction can never
    -- cost more than 2*PRED_LEAD of exposure, once, and never repeats within the same absence.
    local function aboutToResurface(p)
        local since = _predHidden[p]
        if since == nil then return false end
        local m = predMedian(p)
        if m == nil then return false end
        local elapsed = os.clock() - since
        if elapsed > m + PRED_LEAD then return false end
        return elapsed >= m - PRED_LEAD
    end

    local function posInPart(pos, part)
        if not part or not part.Parent then return false end
        local lpv = part.CFrame:PointToObjectSpace(pos)
        local s = part.Size * 0.5
        return math.abs(lpv.X) <= s.X and math.abs(lpv.Y) <= s.Y and math.abs(lpv.Z) <= s.Z
    end

    local function posIsOOB(pos)
        local ok, result = pcall(function()
            for _, p in CollectionService:GetTagged("OutOfBoundsSafePart") do
                if posInPart(pos, p) then return false end
            end
            for _, p in CollectionService:GetTagged("OutOfBoundsPart") do
                if posInPart(pos, p) then return true end
            end
            return false
        end)
        return ok and result == true
    end

    local function killFloor()
        local ok, val = pcall(function() return Workspace.FallenPartsDestroyHeight end)
        -- @polarcore-seam:S28 — NaN is a number, and S9 deliberately writes one here, so the type test alone
        -- lets a NaN through into the park's Y clamp and every park becomes insane. Second line of defence:
        -- setPhysicsFlags also refuses to latch a NaN as the restore value.
        if ok and type(val) == "number" and val == val then return val + KILL_PLANE_BUF end
        return -400
    end

    local function isTeammate(player)
        if player == lp then return true end
        local a = lp:GetAttribute("TeamID")
        local b = player:GetAttribute("TeamID")
        if a and b then return a == b end
        if lp.Team and player.Team and lp.Team == player.Team then return true end
        return false
    end

    local function isAlive(player)
        local c = player.Character
        local h = c and c:FindFirstChildOfClass("Humanoid")
        return h ~= nil and h.Health > 0
    end

    -- @polarcore-seam:S6 SPAWN PROTECTION — the standalone tests ForceField only, which can NEVER fire:
    -- Rivals ships no ForceField anywhere, and its invincibility visual is an Attachment of particles
    -- (ClientEntity._UpdateInvincibilityVisual). So the standalone has no spawn-protection skip at all.
    -- The game's real signal is the replicated entity key IsInvincible; isSpawnProtected (05_utils) mirrors
    -- it off GetDataChangedSignal, so this is ONE TABLE INDEX with no allocation and no TTL staleness.
    -- The ForceField test is kept as a free superset.
    -- FAILS OPEN: isSpawnProtected returns false whenever the entity/fighter map is unavailable, so a
    -- module-shape change degrades to the standalone's behaviour (engage anyway) rather than to the
    -- catastrophe the old unbounded gate caused — hiding every frame and emitting ZERO packets.
    local function isProtected(player)
        if not player or not player.Character then return false end
        if player.Character:FindFirstChildOfClass("ForceField") then return true end
        -- @polarcore-seam:S32 — THE SHIPPED LIE, found by the operator 2026-08-09: "the protected spawn
        -- protection players dont even work". A parity veto stood HERE, ABOVE the config read, so the GUI
        -- toggle "Hold fire on immune targets" displayed ON and did precisely nothing. Same bug killed
        -- 'Target cheaters first' and 'Avoid katana deflect'. THE RULE: the parity predicate may choose a
        -- DEFAULT in 02_config; it must never stand between a user-facing control and its effect.
        --
        -- Why enabling it is also correct on the merits: the old measurement ("engaging protected targets
        -- WINS, skipping LOSES") was taken against an implementation that HID on a protected target, which
        -- un-parked us and forced a re-acquire. This one parks on the head exactly as it would on a killable
        -- target and withholds only the packets — which are rejected by construction while IsInvincible is
        -- set. Same position, same timing, no wasted ammo: strictly better than either side of that test.
        --
        -- ⚠ The gate invariant for this asserts there is no parity call between this function's signature
        -- and the config read below, and it reads TEXT — so do not write that call's name, with parens,
        -- anywhere in this comment. It will fail the build. (It just did.)
        if not Config.RageSkipImmune then return false end
        return isSpawnProtected(player)
    end

    local function inMatch()
        if lp:GetAttribute("TeamID") ~= nil then return true end
        if lp.Team ~= nil then return true end
        return false
    end

    local function getEquippedItem()
        local ok, result = pcall(function()
            local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
            if lf and lf.EquippedItem then return lf.EquippedItem end
            return nil
        end)
        if ok then return result end
        return nil
    end

    local function weaponReady(it)
        if not it then return false end
        local okE, equipping = pcall(function() return it:IsEquipping() end)
        if okE and equipping then return false end
        if (it._reload_cooldown or 0) > tick() then return false end
        -- @polarcore-seam:S20 MAGAZINELESS ITEMS — THE REASON THE KNIFE BOT DID NOTHING.
        -- The standalone only ever held an AR, so this ended with an unconditional `ammo > 0`. A melee item
        -- has no magazine: ItemLibrary registers no MaxAmmo for it, so `it:Get("Ammo")` is nil, the test
        -- failed, and polarTick took the `hide(hrp, "Reloading")` branch EVERY FRAME — Polar hid forever
        -- with a knife equipped and never reached the fire branch at all. (07b has carried the melee
        -- exemption for months; 07c never did, because it is a transplant of the AR-only standalone.)
        -- The predicate is the GAME's own: Gun.StartShooting gates its auto-reload on `Info.MaxAmmo`
        -- being non-nil, so "no MaxAmmo" is exactly how Rivals itself says "this thing has no magazine".
        -- Preferred over the name/type sniffing in Rage._itemIsMelee, which reads Type off the item DATA
        -- while ItemLibrary puts it on Info.
        local magazine = true
        pcall(function() magazine = it.Info.MaxAmmo ~= nil end)
        if not magazine then return true end
        local okA, ammo = pcall(function() return it:Get("Ammo") end)
        return okA and type(ammo) == "number" and ammo > 0
    end

    -- Sticky, HP-first, RANGE-CAPPED. The cap is load-bearing: without it the HP-first sort locks the
    -- lowest-HP enemy anywhere on the map and parks us on their head, across the level, mid-fight.
    --
    -- @polarcore-seam:S6 — a spawn-protected enemy is NO LONGER excluded here, it is DEMOTED. Excluding them
    -- meant that while the whole lobby was invincible we had no target at all, so we sat in the void and only
    -- began the acquire-and-teleport once the protection dropped. That travel time is the entire HvH margin
    -- (operator, MEASURED: skip ON = we lose, skip OFF = we win). Now they stay selectable so we can already
    -- be parked on the head when IsInvincible clears — but they sort strictly BELOW every killable enemy, so
    -- a protected target can never starve us of a real one.
    local function findTarget()
        local myChar = lp.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local cands = {}
        for _, p in Players:GetPlayers() do
            if p ~= lp and not isTeammate(p) and isAlive(p) then
                local c = p.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                if hrp and isSanePos(hrp.Position) then
                    local d = 9999
                    if myRoot then d = (hrp.Position - myRoot.Position).Magnitude end
                    if d <= MAX_DISTANCE then
                        local hum = c:FindFirstChildOfClass("Humanoid")
                        local health = 9999
                        if hum then health = hum.Health end
                        table.insert(cands, { p = p, hp = health, d = d, prot = isProtected(p),
                                              hack = _hackTag[p] == true })
                    end
                end
            end
        end
        if #cands == 0 then return nil end
        table.sort(cands, function(a, b)
            -- @polarcore-seam:S11 — threat first. In an HvH lobby a pure HP sort happily empties the mag
            -- into a bot while the one player who can actually kill us does so. Ranked ABOVE the protected
            -- demotion on purpose: a spawn-protected cheat is still the thing to be parked on when its
            -- invincibility drops. Below that the original order is untouched.
            -- @polarcore-seam:S27 — off under parity. _hackTag is STICKY and depends on whether we happened
            -- to observe a teleport, so the target order differs between rounds against the same lobby.
            -- The standalone sorts on HP then distance, full stop.
            -- @polarcore-seam:S32 — un-vetoed. 'Target cheaters first' is a GUI toggle shipped ON; parity
            -- was silently discarding it.
            if Config.RagePrioritizeHackers ~= false and a.hack ~= b.hack then return a.hack end
            if a.prot ~= b.prot then return b.prot end   -- killable first, protected only as fallback
            if math.abs(a.hp - b.hp) > 10 then return a.hp < b.hp end
            return a.d < b.d
        end)
        return cands[1].p
    end

    -- Y is always POSITIVE so the hide can never drop us through the kill plane; X/Z carry a random sign,
    -- which is what makes consecutive steps enormous.
    local function voidAxis()
        local v = math.random(VOID_R_MIN, VOID_R_MAX)
        if math.random(0, 1) == 0 then return -v end
        return v
    end

    local function rollVoid()
        return CFrame.new(voidAxis(), math.random(VOID_R_MIN, VOID_R_MAX), voidAxis())
    end

    local function voidCFrame()
        local prev = _voidCF
        local cf = rollVoid()
        if VOID_MOVE and prev then
            -- Two draws can land close when both X and Z keep their sign (~15% of the time). Loop with a
            -- recheck so the value returned has always passed the test.
            local tries = 0
            while tries < 8 and (cf.Position - prev.Position).Magnitude < VOID_MIN_STEP do
                cf = rollVoid()
                tries = tries + 1
            end
        end
        _voidCF = cf
        _voidSteps = _voidSteps + 1
        return cf
    end

    -- Kicia's target-present Translocate destination: five studs below the first zero-delay kill volume.
    -- Cache the tagged part, but revalidate both its tag and KillDelay so a map swap cannot retain it.
    local TRANSLOCATE_OFFSET = -5

    -- ⛔ S43's translocateSafe() fall-cull guard and Kicia's third compute branch (no zero-delay part -> a
    -- random far point, cleaned L141593-141594) were added here and REVERTED with the rest of S43. Both are
    -- real and both are worth re-adding on their own merits later; they came out only because the operator
    -- measured an unexplained regression and the correct response to that is a whole revert, not a partial
    -- one. Details in 02_config's S43 tombstone.
    local function attackTranslocateCFrame()
        local ok, result = pcall(function()
            local part = _translocatePart
            if part == nil or part.Parent == nil
               or not CollectionService:HasTag(part, "OutOfBoundsPart")
               or part:GetAttribute("KillDelay") ~= 0 then
                part = nil
                for _, candidate in CollectionService:GetTagged("OutOfBoundsPart") do
                    if candidate:GetAttribute("KillDelay") == 0 then
                        part = candidate
                        break
                    end
                end
                _translocatePart = part
            end
            if part == nil then
                return nil
            end
            return part.CFrame * CFrame.new(0, -part.Size.Y / 2 + TRANSLOCATE_OFFSET, 0)
        end)
        if not ok then
            _translocatePart = nil
            return nil
        end
        return result
    end

    -- @polarcore-seam:S19 ANTI-BACKSTAB PARK HEIGHT. Operator-observed, Polar only: a NORMAL player can
    -- walk up and knife-backstab us mid-rage, because pointBlank puts our replicated body exactly ON the
    -- enemy head -- inside every melee reach in the game (Knife HeavyAttackReach = 7 is the largest;
    -- Katana / Riot Shield / Chainsaw / Battle Axe are all 6). Orbit never had this because it parks at a
    -- 60-stud vantage. Kicia does NOT solve this either -- its hitscan park is headPos + 0.5 studs, just as
    -- backstabbable -- so this is ours, not a port.
    -- NEUTRAL TO RAGE POWER BY CONSTRUCTION: the server resolves a shot from our REPLICATED body and needs
    -- line of sight to the hitbox, so the lift is applied ONLY when the lifted park still has LOS to the
    -- head. Indoors, under a ceiling, or through any geometry it silently keeps today's point-blank park.
    -- Skipped entirely while WE hold a knife -- seam S18 needs to be inside reach, not outside it.
    local PARK_UP_STUDS = 12
    local _parkRP = nil

    local function parkHasLOS(from, to, ourChar, tgtChar)
        if _parkRP == nil then
            _parkRP = RaycastParams.new()          -- hoisted: one instance, never per-frame
            _parkRP.FilterType = Enum.RaycastFilterType.Exclude
        end
        _parkRP.FilterDescendantsInstances = { ourChar, tgtChar }
        local res = Workspace:Raycast(from, to - from, _parkRP)
        if not res then return true end
        return (res.Position - to).Magnitude < 3
    end

    -- @polarcore-seam:S18 KNIFE BACKSTAB BOT. Kicia's ragebotPlanner:Plan (cleaned leak L39952-40040) and
    -- its Item:HeavyAttackEncoded (L196846). Three things here are not guessable and all three are from
    -- source:
    --   1. A heavy attack is NOT StartShooting. It rides the **StartAiming** enum, with the envelope's
    --      second slot carrying the encoded animation name "HeavyAttackAnimation1" (a light attack is
    --      StartShooting + "AttackAnimation1"). Slot 2 is the item action's 4th return in both cases --
    --      IsFullyAiming for a Gun, the animation for a melee -- which is also why seam S16 is right.
    --   2. The BACKSTAB IS FORGED IN THE PACKET, not by standing behind anyone. char0/char1 keep Kicia's
    --      usual sentinel positions but their ORIENTATION slots are overwritten with the VICTIM'S OWN
    --      rootPart:ToOrientation() yaw and roll, with pitch pinned to -pi/2. Kicia parks ON the head,
    --      where no positional test could tell front from back, so the server's backstab check has to be
    --      angular -- and Kicia satisfies it by claiming to be facing exactly where the victim faces.
    --   3. The cadence is a RETRY WINDOW, not a spray. On a swing it sets a 0.625 s window during which it
    --      re-sends every frame (bypassing its own lock and cooldown) in case the first was rejected, then
    --      goes silent until 1.25 s -- the Knife's real Info.HeavyAttackCooldown. Half the cooldown, so the
    --      retries can never bleed into the next legitimate swing.
    -- Why it is worth having at all: Knife HeavyAttack carries CriticalDamage = 150 = a full fighter's HP,
    -- and the game's own statistics text calls a backstab "an instant elimination". One accepted packet is
    -- one kill, so none of the magazine/duty-cycle arithmetic that bounds the AR applies here.
    -- NOT ported: Kicia's camera-rotation forge. It drives SendViewAngles through a priority-slot system
    -- that HOOKS the game's own camera replication loop to keep our real angle from overwriting the lie.
    -- We do not add hooks for this. The packet already carries the victim's yaw, which is what the server
    -- judges the attack from; the camera half would only matter if the check reads the replicated angle
    -- instead, and that would be visible as backstabs that never crit.
    -- Kicia's 0.625 / 1.25 is exactly half of, and all of, the Knife's Info.HeavyAttackCooldown. Keep the
    -- RATIO and take the period from the weapon (@polarcore-seam:S22) so this is right for every melee.
    -- @polarcore-seam:S25 — the ONLY timing in Kicia's no-glue MeleeStrategy is this dwell. 1/15 s, the
    -- same constant its hitscan strategy uses and the same one PRIME_S is: one stock physics-sender
    -- period, so the park has certainly replicated before the first swing. After it, attack every frame.
    local MELEE_DWELL_S    = 0.07
    local _meleeDwellStart = nil


    -- Takes a POSITION, not the part: @polarcore-seam:S17 needs to build a park from a predicted head
    -- position for a target whose live hitbox is currently voided.
    -- @polarcore-seam:S41 — this math.max is the ONE deterministic upward force in the whole park path, so
    -- it is a named suspect for "we tp to them but end up above them" and it gets counted rather than
    -- argued about. It only bites a target below killFloor() + 3, and that floor is FallenPartsDestroyHeight
    -- + KILL_PLANE_BUF (200) — with S9's NaN write forcing the -400 fallback the clamp sits near Y = -397,
    -- far below a player standing a few studs under a map floor. So this is EXPECTED to read 0 for the
    -- ordinary underground case and non-zero only for a deeply buried one; a non-zero reading would move the
    -- diagnosis here and away from the physics story below. The clamp itself is pinned by build.js:316
    -- (divergence #4) and must not be touched on the strength of this counter alone.
    local function pointBlank(hp)
        local y = math.max(hp.Y, killFloor() + 3)
        if y > hp.Y + 0.001 then
            State.RageParkClampFrames = (State.RageParkClampFrames or 0) + 1
        end
        return Vector3.new(hp.X, y, hp.Z)
    end

    -- @polarcore-seam:S22 MELEE PROFILE — read the weapon out of the GAME, never off its name.
    -- ItemLibrary's add_melee (dump L3300) shows what a melee item really carries, and the name tells you
    -- nothing useful. Three items declare `{"StartAiming"}` as an input and they mean three DIFFERENT
    -- things by it:
    --     Knife / Glast Shard : HeavyAttack, HeavyAttackReach 7, CriticalDamage 150  -> the backstab
    --     Battle Axe          : SpinCooldown / SpinRadius / SpinDamage               -> a spin attack
    --     Katana class        : StartDeflecting                                      -> a DEFLECT
    -- So sending StartAiming because the item is "an axe" makes us spin, and on a katana it makes us
    -- deflect instead of attacking. `isLocalKnife` is a name-substring list and matches "axe" — it is fine
    -- for 07b's flank geometry and completely wrong for choosing an action.
    -- The only honest predicate is the one the game itself keys the backstab on: an item can heavy-attack
    -- iff it declares BOTH CriticalDamage and HeavyAttackCooldown. In this build that is exactly the Knife
    -- (all skins share one Info) and the Glast Shard.
    -- Returns nil for anything that is not a melee weapon at all.
    local function meleeProfile(it)
        local prof = nil
        pcall(function()
            local info = it.Info
            if info == nil then return end
            if info.MaxAmmo ~= nil then return end            -- has a magazine => a gun, not melee
            -- @polarcore-seam:S25 — the cooldown is NOT read any more (Kicia's no-glue melee has none;
            -- see meleeStrike). HeavyAttackCooldown survives only as the capability marker: an item that
            -- declares it AND CriticalDamage is the one that can backstab-crit.
            local heavy = info.CriticalDamage ~= nil and type(info.HeavyAttackCooldown) == "number"
            prof = { heavy = heavy }
        end)
        return prof
    end

    -- @polarcore-seam:S18/S22 — one swing, then a retry window, then silence until the weapon's REAL
    -- cooldown. Handles every melee item, not just the knife: a heavy-capable weapon backstabs, everything
    -- else (Fists, Riot Shield, Battle Axe, katanas...) sends the ordinary light attack.
    -- Returns true if a packet went out this frame, false if we are inside the quiet part of the cycle.
    local function meleeStrike(firePark, hpos, hh, tgt)
        local it = getEquippedItem()
        if it == nil then State.RageKnifeStatus = "no item" return false end
        local prof = meleeProfile(it)
        if prof == nil then State.RageKnifeStatus = "not a melee item" return false end
        -- @polarcore-seam:S25 NO COOLDOWN — Kicia's no-glue MeleeStrategy has NONE, and mine was imported
        -- from the wrong planner for the second time. Read `MeleeStrategy:Plan` end to end (cleaned leak
        -- L51631-51690): ShootLock, then a 1/15 s dwell from _attackStart, and after that it calls
        -- `item:HeavyAttack(...)` on EVERY FRAME — ~60/s — with no rate limit anywhere in the function.
        -- The 0.625 s retry window and 1.25 s cooldown belong to `ragebotPlanner` (leak L40031), the PART
        -- GLUE planner, exactly like the -9e37 sentinels did. Applying them here meant we sent ONE packet
        -- per 1.25 s and then sat in "cooldown"; if that single packet was refused for any reason, or our
        -- tick() phase drifted from the server's, we landed nothing and waited a second and a quarter to
        -- try again. Kicia hammers it and lets the server accept whichever swing lands.
        -- Only the DWELL survives, and it is the same replication dwell as the gun's PRIME_S: hold the
        -- park still long enough for the server to have received it before the first swing.
        local now = tick()
        if _meleeDwellStart == nil then _meleeDwellStart = now end
        if now - _meleeDwellStart < MELEE_DWELL_S then
            State.RageKnifeStatus = "dwell"
            return false
        end

        local actionName, animName = "StartShooting", "Attack1"
        if prof.heavy then
            actionName, animName = "StartAiming", "HeavyAttack1"
        end

        local actionEnum, animEnum = nil, nil
        pcall(function() actionEnum = Rivals.Enums:ToEnum(actionName) end)
        pcall(function() animEnum = Rivals.Enums:ToEnum(animName) end)

        local tc = tgt.Character
        local trp = tc and tc:FindFirstChild("HumanoidRootPart")
        if trp == nil then State.RageKnifeStatus = "target has no root" return false end

        local vp, vy = trp.CFrame:ToOrientation()
        if prof.heavy and Config.RageKnifeCamForge ~= false then
            ViewAngle.forge(vp, vy)
        end

        local eyePos   = firePark + Vector3.new(0, EYE_UP_SANE, 0)
        pcall(function()
            if _parkRP == nil then
                _parkRP = RaycastParams.new()
                _parkRP.FilterType = Enum.RaycastFilterType.Exclude
            end
            local ign = { lp.Character }
            if tgt and tgt.Character then ign[#ign + 1] = tgt.Character end
            _parkRP.FilterDescendantsInstances = ign
            local ures = Workspace:Raycast(hpos, Vector3.new(0, 8, 0), _parkRP)
            if ures and ures.Instance then
                eyePos = hpos - Vector3.new(0, 0.7, 0)
            end
        end)
        local eyeCF    = Rage._lookCF(eyePos, hpos)
        local muzzleCF = eyeCF - Vector3.new(0, EYE_MUZZLE_SEP, 0)
        local sent = false

        State.RageFireFromPos = eyePos
        State.RageFireAimPos  = hpos
        State.RageFireHitPart = hh
        State.RageFireStamp   = tick()

        pcall(function()
            it._attack_cooldown = 0
            it._last_attack = tick() - 1
        end)

        local function atId2(fn)
            local prev = nil
            if getthreadidentity ~= nil then pcall(function() prev = getthreadidentity() end) end
            local s = setthreadidentity or set_thread_identity or setidentity or setthreadcontext
            if s ~= nil then pcall(s, 2) end
            local ok, res = pcall(fn)
            if s ~= nil and prev ~= nil then pcall(s, prev) end
            return ok, res
        end

        -- Primary delivery: Direct method call on the item (Kicia MeleeStrategy standard)
        local hitData = { part = hh }
        if prof.heavy and type(it.HeavyAttack) == "function" then
            local ok = atId2(function() it:HeavyAttack(eyeCF, eyeCF, hitData) end)
            if ok then sent = true end
        elseif (not prof.heavy) and type(it.Attack) == "function" then
            local ok = atId2(function() it:Attack(eyeCF, eyeCF, hitData) end)
            if ok then sent = true end
        end

        local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
        if not sent then
            if Config.RageMeleeAsk ~= false then
                if lf == nil then State.RageKnifeStatus = "no LocalFighter" return false end
                local prev = nil
                if getthreadidentity ~= nil then pcall(function() prev = getthreadidentity() end) end
                local s = setthreadidentity or set_thread_identity or setidentity or setthreadcontext
                if s ~= nil then pcall(s, 2) end
                local ok, err = pcall(function() lf:Input(actionName) end)
                if s ~= nil and prev ~= nil then pcall(s, prev) end
                local ran = false
                pcall(function() ran = (it._attack_cooldown or 0) > 0 end)
                sent = ok and ran
                if not ok then
                    State.RageKnifeStatus = "Input failed: " .. tostring(err)
                elseif not ran then
                    State.RageKnifeStatus = "item refused " .. actionName
                end
            else
                if _useItem == nil then
                    pcall(function() _useItem = ReplicatedStorage.Remotes.Replication.Fighter.UseItem end)
                end
                local okId, objId = pcall(function() return it:Get("ObjectID") end)
                if not okId or objId == nil then
                    pcall(function() objId = it.Info.ObjectID end)
                end
                if _useItem == nil then State.RageKnifeStatus = "no UseItem remote" return false end
                if objId == nil then State.RageKnifeStatus = "no ObjectID" return false end
                if actionEnum == nil then
                    State.RageKnifeStatus = "no " .. actionName .. " enum"
                    return false
                end
                State.RageForging = true
                local ferr = nil
                local fok = atId2(function()
                    local inner = {}
                    Rage._buildShotFields(inner, eyeCF, muzzleCF, hh, hpos, true, RAGE_CLAMP_FRAC, 1.0)
                    local env = { [utf8.char(1)] = inner }
                    if animEnum ~= nil then env[utf8.char(2)] = animEnum end
                    _useItem:FireServer(objId, actionEnum, env, nil)
                    sent = true
                end)
                State.RageForging = false
                if not fok then State.RageKnifeStatus = "FireServer failed: " .. tostring(ferr) end
            end
        end

        if sent then
            _shots = _shots + 1
            State.Shots = State.Shots + 1
            State.RageKnifeSwings = (State.RageKnifeSwings or 0) + 1
            State.RageKnifeStatus = "swinging " .. actionName
        else
            State.RageKnifeStatus = "send failed"
        end
        return sent
    end

    -- @polarcore-seam:S2 + S3. Geometry, taps and cooldown-zeroing are the standalone's; only the bytes
    -- of the packet differ (lookCF eye/muzzle + per-tap jittered object-space char3 instead of
    -- char0 == char1 with an identity char3).
    local function polarFire(eyePos, aimPos, hh, taps)
        local it = getEquippedItem()
        if not it then return 0 end
        pcall(function()
            it._shoot_cooldown = 0
            it._shoot_cooldown_no_ammo = 0
            it._last_shot = tick() - 1
        end)
        if _shootEnum == nil then
            pcall(function() _shootEnum = Rivals.Enums:ToEnum("StartShooting") end)
        end
        if _shootEnum == nil then return 0 end
        if _useItem == nil then
            pcall(function() _useItem = ReplicatedStorage.Remotes.Replication.Fighter.UseItem end)
        end
        if _useItem == nil then return 0 end
        local okId, objId = pcall(function() return it:Get("ObjectID") end)
        if not okId or not objId then return 0 end
        local fireEyePos = eyePos
        pcall(function()
            if _parkRP == nil then
                _parkRP = RaycastParams.new()
                _parkRP.FilterType = Enum.RaycastFilterType.Exclude
            end
            local ign = { lp.Character }
            local tgt = State.RageTarget or State.Target
            if tgt and tgt.Character then ign[#ign + 1] = tgt.Character end
            _parkRP.FilterDescendantsInstances = ign
            local ures = Workspace:Raycast(aimPos, Vector3.new(0, 8, 0), _parkRP)
            if ures and ures.Instance then
                fireEyePos = aimPos - Vector3.new(0, 0.7, 0)
            end
        end)
        local eyeCF    = Rage._lookCF(fireEyePos, aimPos)
        local muzzleCF = eyeCF - Vector3.new(0, EYE_MUZZLE_SEP, 0)
        local sent     = 0
        -- @polarcore-seam:S16 THE ENVELOPE'S SECOND FIELD. Kicia's ShootEncoded (cleaned leak L196645 /
        -- L72718, identical in both emissions) sends
        --     if isRaycast then { ["\1"] = camData, ["\2"] = true } else { ["\1"] = camData } end
        -- and we have only ever sent the first field. Reading the game back: Gun.StartShooting returns
        -- (true, "StartShooting", camData, IsFullyAiming(), isQuickShot), so envelope slot 2 is the ADS
        -- flag — and Kicia's emptied `if self.name == "Revolver" then end` branch, the revolver being the
        -- quick-shot weapon, is where slot 3 went. Claiming fully-aimed is what shrinks the server's
        -- spread cone by Info.AimSpreadMultiplier (Gun.luau:571 GetSpread), so an omitted flag is a shot
        -- judged at full hipfire spread. Only for raycast weapons, exactly as Kicia gates it: a projectile
        -- item resolves down _ProjectileEffect and has no business claiming an ADS hitscan.
        local rayCast = false
        pcall(function() rayCast = it.Info.IsRaycast == true end)
        -- @polarcore-seam:S38 — resolved ONCE for the whole burst, not per tap: a glue that released between
        -- taps would otherwise send half a burst in each format.
        local glued = glueActive()
        State.RageForging = true    -- @polarcore-seam:S3 whitelist our taps past the 07b __namecall backstop
        pcall(function()
            for _ = 1, taps do
                local inner = {}
                if glued then
                    -- The constants are shared, not rebuilt per tap. Kicia sends the identical table every
                    -- frame and nothing downstream mutates it; per-tap jitter is meaningless here anyway,
                    -- because these fields are not read as a position.
                    inner[utf8.char(0)] = GLUE_CHAR0
                    inner[utf8.char(1)] = GLUE_CHAR1
                    inner[utf8.char(2)] = hh
                    inner[utf8.char(3)] = GLUE_CHAR3
                else
                    Rage._buildShotFields(inner, eyeCF, muzzleCF, hh, aimPos, true, RAGE_CLAMP_FRAC, 1.0)
                end
                local env = { [utf8.char(1)] = inner }
                    -- @polarcore-seam:S16, S27 — the standalone sends NO envelope slot 2 and beats Kicia, so
                -- under parity the wire format is byte-for-byte the winner's shape minus the two fields
                -- the packetshape/lookcf gates forbid restoring.
                if rayCast and not parity() then env[utf8.char(2)] = true end
                _useItem:FireServer(objId, _shootEnum, env, nil)
                sent = sent + 1
            end
        end)
        State.RageForging = false   -- pcall cannot throw past this, so the flag can never latch on
        _shots = _shots + sent
        State.Shots = State.Shots + sent
        return sent
    end

    -- @polarcore-seam:S29 ONE TAP PER FRAME. POLAR_TAPS_SANE stays 6 because the polarcore gate pins it to
    -- the standalone and it is now the CLAMP; what changes is how many of those taps we actually spend.
    -- Kicia sends exactly one attack per frame and wins, and our own measurement says accepted packets do
    -- not scale with volume — so taps 2..6 are magazine spent for nothing. The magazine is the real budget
    -- (30 rounds either way), so this only decides whether it is spent over 5 frames or 30.
    local function tapsPerFrame()
        local n = Config.RageTapsPerFrame
        if type(n) ~= "number" then return 1 end
        if n < 1 then return 1 end
        if n > POLAR_TAPS_SANE then return POLAR_TAPS_SANE end
        return math.floor(n)
    end

    local ATTACK_GAP_HOLD = 0.30
    local _attackGapTgt = nil
    local _attackGapUntil = 0
    local _attackReadyTgt = nil

    local function clearAttackGap()
        _attackGapTgt = nil
        _attackGapUntil = 0
    end

    local function resetAttackContinuity()
        clearAttackGap()
        _attackReadyTgt = nil
    end

    -- An invalid target pose is not a new combat state until it outlives a human-scale mode switch.
    -- Keep the moving hide defensive, but retain the last proven attack metadata for the return edge.
    local function holdAttackGap(hrp, tgt, status)
        if Config.RageAttackContinuity == false then return false end
        local now = os.clock()
        if _attackGapTgt ~= tgt then
            if _attackReadyTgt ~= tgt or _prevPark == nil or _prevParkTgt ~= tgt then
                return false
            end
            _attackGapTgt = tgt
            _attackGapUntil = now + ATTACK_GAP_HOLD
        elseif now > _attackGapUntil then
            clearAttackGap()
            return false
        end

        _firing = false
        State.RageFiring = false
        State.RageStatus = status
        State.RageVoidActive = VOID_HIDE
        _lastPark = nil
        _meleeDwellStart = nil
        _translocateNext = false
        _translocateBurstPulses = 0
        _translocateFireFrames = 0
        liteRelease()   -- @polarcore-seam:S44 before glueRelease, which must stay adjacent to the void hide
        glueRelease()
        if VOID_HIDE then
            displace(hrp, voidCFrame())
        end
        return true
    end

    local function hide(hrp, status)
        resetAttackContinuity()
        _firing = false
        State.RageFiring = false
        State.RageStatus = status
        State.RageVoidActive = VOID_HIDE
        _prevPark    = nil    -- @polarcore-seam:S10 a park from before a hide is far too stale to fire from
        _prevParkTgt = nil
        -- @polarcore-seam:S30 — a hide sets _firing false, so the anchors restore normally and there is
        -- nothing to re-park to. Leaving this set would have the Stepped anchor drag us back onto a dead
        -- target's head on the frame a burst ends.
        _lastPark    = nil
        -- @polarcore-seam:S12+S14 — hiding drops the park, so the prime must be served again on the way
        -- out. Idempotent: the roll happens on the transition OUT of hiding, not here.
        _hiding     = true
        _primeUntil = 0
        -- @polarcore-seam:S25 — hiding drops the park, so the melee dwell has to be served again on the
        -- way out. Kicia clears its _attackStart on exactly the same condition (its ShootLock closing).
        _meleeDwellStart = nil
        _translocateNext = false
        _translocateBurstPulses = 0
        _translocateFireFrames = 0
        -- @polarcore-seam:S37 — a hide means there is no target worth shooting, so there is no hitbox we
        -- have any business being glued to. Release FIRST: that hands replication back to our own body and
        -- reassembles the victim, so the void displacement below is the measured moving-hide operating on
        -- our own root exactly as it does in the build that beats Kicia. The alternative — leaving the glue
        -- installed and stopping driving it — parks us frozen at a fixed rendezvous for the whole hide,
        -- which is both a learnable constant and someone else's character left broken.
        -- @polarcore-seam:S44 — lite first, for the same reason and a stronger one: under lite the redirect
        -- is the ONLY thing making the server resolve us from the target, so leaving it installed across a
        -- hide would replicate us at a hitbox we have stopped driving instead of at the moving void point
        -- the hide is built on. glueRelease stays adjacent to the displace below.
        liteRelease()
        glueRelease()
        if VOID_HIDE then
            displace(hrp, voidCFrame())
        end
    end

    local function polarTick(ch, hrp)
        local tgt = _target
        -- A protected target also drops stickiness so findTarget re-runs and its killable-first sort can
        -- promote anyone better. If it is still the only option, findTarget simply returns it again.
        if tgt and (not tgt.Parent or not tgt.Character or not isAlive(tgt) or isTeammate(tgt)
                    or isProtected(tgt)) then
            tgt = nil
        end
        if not tgt then tgt = findTarget() end
        _target = tgt
        State.RageTarget = tgt

        if not tgt or not tgt.Character then return hide(hrp, "No target") end

        -- @polarcore-seam:S6 SPAWN PROTECTION — HOLD FIRE, DO NOT HIDE.
        -- This used to `hide()`, which also UN-PARKED us: the moment the invincibility cleared we were
        -- 110-140k studs away and had to re-acquire, re-teleport, and wait a network sample before the first
        -- packet could be judged from the head. That travel time is the entire HvH margin — the operator
        -- MEASURED that turning the skip OFF (engage protected targets anyway) WINS and turning it ON loses.
        -- So we now do exactly what the winning config does — target them and park on the head — and withhold
        -- only the packets, which are rejected by construction while IsInvincible is set. Strictly better than
        -- the config that already wins: same position, same timing, no wasted ammo, no wasted exposure.
        -- Note this is deliberately NOT the deflect branch's behaviour below: a deflect REFLECTS our damage
        -- from inside melee reach, so that one must still pull the body out. Invincibility only absorbs.
        -- @polarcore-seam:S33 — bounded, per target. The timer restarts on a target change so a long fight
        -- against several protected players cannot accumulate into a false expiry.
        local holdFire = isProtected(tgt)
        if not holdFire then
            _immuneSince, _immuneTgt = 0, nil
        else
            local now = tick()
            if _immuneTgt ~= tgt then
                _immuneSince, _immuneTgt = now, tgt
            end
            if now - _immuneSince > IMMUNE_MAX_HOLD then
                holdFire = false
                State.RageImmuneOverride = (State.RageImmuneOverride or 0) + 1
            end
        end

        -- @polarcore-seam:S7 ANTI-KATANA. Game constants (ItemLibrary "Katana"): DeflectDuration = 1,
        -- DeflectCooldown = 4, DeflectDamageMultiplier = 1 — a deflect is live for 1s out of every 5, and
        -- it REFLECTS our damage back at full rate. Polar parks point-blank ON the head, which is inside
        -- the katana's 6-stud AttackReach (45 dmg / 0.7s), so firing 6 taps a frame into a live deflect is
        -- the single worst thing this engine can do: zero damage dealt, full damage taken, at melee range.
        -- isDeflecting is the game's OWN signal — 05_utils wraps the shared Katana._StartDeflecting, which
        -- runs for every fighter and gives the exact Info.DeflectDuration window — so this is an O(1)
        -- UserId index with no allocation and no polling. Hiding (not just holding fire) is strictly
        -- better: the moving hide takes 0 damage and pulls us out of melee reach for the 1s window.
        -- FAILS OPEN: no hook and no anim match => false => engage exactly as the standalone does.
        -- BOUNDED, for the same reason the old IsInvincible gate had to be: a signal stuck true is a
        -- permanent lockout that emits ZERO packets. The module hook self-clears on a generation token, but
        -- the animation fallback (used only if the hook could not install) could in principle latch on a
        -- lingering deflect_idle track. The game says a deflect is live for DeflectDuration = 1s and cannot
        -- repeat for another 4, so past DEFLECT_MAX_HOLD we stop believing the signal and engage.
        -- @polarcore-seam:S27 — off under parity. The standalone has no deflect branch at all. Ours can hide
        -- for up to 1.5s per detection, and when the Katana module hook fails to install (a per-session
        -- outcome) the signal degrades to an ANIMATION SCAN that can false-positive — so this branch can
        -- silently eat whole seconds of a round, or none, depending on how the session loaded.
        -- @polarcore-seam:S32 — un-vetoed. 'Avoid katana deflect' is a GUI toggle shipped ON (twice), and
        -- parity was discarding it. Still bounded by DEFLECT_MAX_HOLD so a stuck signal cannot lock us out.
        if Config.AvoidDeflect and isDeflecting(tgt) then
            local now = tick()
            if _deflectSince == 0 then _deflectSince = now end
            if now - _deflectSince < DEFLECT_MAX_HOLD then return hide(hrp, "Deflecting") end
        else
            _deflectSince = 0
        end

        local it = getEquippedItem()
        if not weaponReady(it) then
            local now = tick()
            if now - _reloadLast > 0.5 then
                _reloadLast = now
                pcall(function()
                    local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
                    if lf then lf:Input("StartReloading") end
                end)
            end
            return hide(hrp, "Reloading")
        end

        local hh = tgt.Character:FindFirstChild("HitboxHead") or tgt.Character:FindFirstChild("Head")
        if not hh then return hide(hrp, "Hiding") end

        -- @polarcore-seam:S12+S14 — everything needed to attack is now true, so THIS is the instant the
        -- hide would naturally have ended. Roll the dwell ONCE here and fall through to the park: we hold
        -- position on the head for it rather than returning to the void, which is what makes the same
        -- milliseconds serve as both the replication prime and the anti-predictor jitter.
        -- Placed after the reload and deflect branches so their hides are not double-counted.
        if _hiding then
            _hiding = false
            local extra = 0
            if Config.RageHideJitter ~= false then
                extra = math.random() * HIDE_JITTER_MAX
            end
            _primeUntil = tick() + PRIME_S + extra
        end

        -- @polarcore-seam:S46 — NEVER REASON ABOUT A COORDINATE WE MOVED OURSELVES.
        -- This one line was a ~50% duty-cycle bug that predates S45 and is why the glue never read as more
        -- than "a little better". glueAcquire DRAGS hh to _rvCF, whose Y is exactly 100000, and isSanePos is
        -- a strict `< SANE_POS_LIMIT` (100000) — so the rendezvous is, by our own test, an INSANE position.
        -- hh is re-read from the Character every frame, so from the frame after the glue binds `hh.Position`
        -- IS the rendezvous: we took the "target voided" branch every frame, on a target we had voided
        -- ourselves, and that branch can only pre-park, hold fire, or hide. The glue then got released by
        -- holdAttackGap/hide, the head snapped back, the next frame read sane, and we attacked once — so the
        -- engine alternated attack/hide forever instead of holding the head.
        -- THE RULE, from BOTH winners independently: measure presence from the part you never touch.
        --   Kicia      ragebotPlanner:Tick -> f9425(p64.aliveState.rootPart.Position)   (cleaned :141530)
        --   daydreamer astarget(f) -> root = ent.RootPart; gate():tick(key, entry.root.Position, hasammo)
        -- Both drag ONLY HitboxHead. HumanoidRootPart is never welded, anchored or moved by the glue, so it
        -- keeps replicating the target's REAL position straight from the server — which is exactly the
        -- signal "are they hiding" needs, and the only one the glue cannot corrupt.
        -- Scope: `mine` is false whenever we do not own the drag (gum off, gum lite — lite writes no CFrame),
        -- so for every existing configuration this is byte-identical to the proven build. When we DO own it,
        -- park and aimPos are both overridden by the glue block below anyway, so the only thing this changes
        -- is the VALIDITY decision — which is the entire point.
        local trp  = tgt.Character:FindFirstChild("HumanoidRootPart")
        local mine = (hh == _glueHit)
        local hpos = hh.Position
        if mine and trp ~= nil then hpos = trp.Position end

        -- Target voided/unreachable: its hitbox is far past the server's MAX_RAYCAST from any char0 we
        -- could claim, so every packet aimed at it is REJECTED BY CONSTRUCTION. Firing anyway drains the
        -- magazine into blanks AND holds _firing true, which suppresses both restores — so across the ~80%
        -- of UE's cycle that it is hidden we would neither hide nor land anything, and the reload would
        -- land mid-hide leaving us empty for the one window that can score. Hiding is the only branch that
        -- can help here. (@polarcore-seam:S4 — the standalone's fire-from-void alternative was unreachable
        -- dead code and the only fire site reading our own body; deleted.)
        -- @polarcore-seam:S17 — the target is unreachable, but if their own cycle says they are about to
        -- come back, park on their LAST KNOWN head now and serve the prime during the absence, so the
        -- first frame they exist we are already parked and already replicated. Fire is withheld the whole
        -- time: their hitbox is in the void, so char2 is unreachable and every packet is rejected by
        -- construction. If they come back somewhere else we lose one frame re-parking — today's cost.
        -- @polarcore-seam:S45 VOID PREFIRE. ⛔ THE COMMENT ABOVE IS HALF WRONG AND IT COST US EVERY MATCH
        -- AGAINST UE. "char2 is unreachable and every packet is rejected by construction" is FALSE: the
        -- game's own SHARED source (ReplicatedStorage, run by the server too) makes target validity
        -- `IsAlive() + enemy TeamID + same EnvironmentID` — EntityLookupParams:17 and GameplayUtility:441 —
        -- with NO positional term at all, so a voided enemy is still in the raycast whitelist. Hiding only
        -- defeats the 400-stud ray, and GameplayUtility:379's from-point pass bypasses that ray entirely
        -- and PREPENDS its hit. Kicia and daydreamer both fire at voided hitboxes; both beat UE; we did not.
        -- The discriminator was SANE_POS_LIMIT = 100000 against UE's 2.1e9 void: every UE hide tripped the
        -- bail below, which sits ABOVE the glue, so we never even tried.
        -- THE RULE: when a coordinate is unusable, stop trusting COORDINATES and use IDENTITY. glueAcquire
        -- takes the HitboxHead *instance* and drags it to our rendezvous at ~1e5 — inside the 2^22 spatial
        -- limit — so a 2.1e9 target is pulled back into sane coordinate space before anything reads a
        -- number. That drag is exactly why this needs "on" and cannot use "lite": lite has no drag, so our
        -- replication root would sit at 2.1e9 and blow that limit. daydreamer's partglue:acquire drags for
        -- the same reason, and Kicia's PhysicsGlue is where both of them got it.
        -- BOUNDED: gated on the SAME aboutToResurface() window S17 already computes — [median - PRED_LEAD,
        -- median + PRED_LEAD] of a learned absence, never below PRED_NEEDED samples — so a wrong prediction
        -- still costs at most 2*PRED_LEAD once per absence. This is not "fire through the whole hide".
        local predicting = false
        local voidFire   = false
        local rv         = nil
        if not isSanePos(hpos) then
            local pre = nil
            -- @polarcore-seam:S27 — off under parity. The standalone HIDES whenever the head is unreachable
            -- (polar_movinghide L339-342); it never pre-parks and never stands exposed on a stale head.
            -- @polarcore-seam:S28 — un-gated from parity. S17 is not a Kicia port that needs the glue; it is
            -- a strict superset of Kicia's own SpatialLimitGate and the only thing in this file that
            -- shortens reaction time. Its cost is bounded by construction (aboutToResurface stops believing
            -- the model past median + PRED_LEAD, so a wrong prediction is at most 2*PRED_LEAD of exposure,
            -- once per absence) and it never fires below PRED_NEEDED samples.
            if Config.RagePredictResurface ~= false and aboutToResurface(tgt) then pre = _predLast[tgt] end
            if pre == nil or not isSanePos(pre) then
                if holdAttackGap(hrp, tgt, "Holding target swap") then
                    return nil
                end
                return hide(hrp, "Head voided")
            end
            hpos = pre
            predicting = true
            -- @polarcore-seam:S45 — S17 has now put us on a REMEMBERED, sane head position, which is what
            -- every intermediate check below (park, OOB, park-lift LOS) is written to reason about. The
            -- ONLY thing S45 adds is: also take the hitbox by IDENTITY, and if that lands, stop holding
            -- fire. rv is carried to the glue block below, which overrides the park to the rendezvous
            -- exactly as it does on the normal path — so validation still happens on real geometry and the
            -- rendezvous is still never sanity-tested, which matters because _rvCF's Y is exactly 100000
            -- and isSanePos is a strict `< SANE_POS_LIMIT`. Setting hpos = rv here instead would fail the
            -- park check one screen down and hide, which is the bug this shape exists to avoid.
            -- predicting is cleared on success: the two are mutually exclusive by construction, and every
            -- downstream `not predicting` gate (fire, translocate, lite) reads the pair that way.
            -- ⚠ meleeProfile(it), NOT the `melee` local — that one is not declared until the park-lift
            -- section far below, so testing it here would read nil and let a knife glue, which is exactly
            -- the S38 cross-contamination the melee gate exists to prevent (Kicia forges a THIRD wire
            -- format for melee: char0/char1 from the target's own orientation with a +-pi/2 pitch).
            if Config.RageGumVoidFire ~= false and gumMode() == "on"
               and meleeProfile(it) == nil then
                rv = glueAcquire(hh)
                if rv ~= nil then
                    predicting = false
                    voidFire   = true
                end
            end
        end

        -- _firing is the RESTORE authority, not "are we shooting": it must be true whenever the park is the
        -- pose we want replicated, so the anchors stay off and the body stays on the head. It is therefore
        -- set even while holding fire at a protected target. State.RageFiring is the honest external signal
        -- (09_aimbot / 11_lab read it) and follows whether packets are actually leaving.
        _firing = true
        State.RageFiring = not holdFire
        State.RageVoidActive = false

        local melee = meleeProfile(it) ~= nil
        local park
        if melee then
            local tc = tgt.Character
            local trp = tc and tc:FindFirstChild("HumanoidRootPart")
            if trp and (it.name == "Knife" or (meleeProfile(it) and meleeProfile(it).heavy)) then
                park = trp.Position - (trp.CFrame.LookVector * 1.2) + Vector3.new(0, 0.6, 0)
            else
                park = hpos + (trp and (trp.CFrame.LookVector * -0.8) or Vector3.new(0, -0.5, 0))
            end
        else
            park = pointBlank(hpos)
        end
        if posIsOOB(hpos) or posIsOOB(park) or not isSanePos(park) then
            if holdAttackGap(hrp, tgt, "Holding target swap") then
                return nil
            end
            return hide(hrp, "Hiding")
        end
        clearAttackGap()
        -- @polarcore-seam:S19 — lift out of every melee reach, but ONLY while the lifted park keeps line
        -- of sight to the head, which is the exact condition the server needs to resolve our shot from the
        -- replicated body. No LOS => keep the point-blank park => identical to before.
        -- @polarcore-seam:S22 — and never while WE hold a melee weapon of any kind: our own swing has to
        -- reach too. The test used to be isLocalKnife(), a name-substring list, so Fists or a Riot Shield
        -- lifted us 12 studs out of our own range while we kept trying to attack.
        if Config.RageParkLift ~= false and not melee then
            local lifted = park + Vector3.new(0, PARK_UP_STUDS, 0)
            if isSanePos(lifted) and not posIsOOB(lifted)
               and parkHasLOS(lifted, hpos, ch, tgt.Character) then
                park = lifted
            end
        end

        -- @polarcore-seam:S37 — THE GLUE. Everything above validated the target on its REAL geometry, which
        -- is the only place those checks mean anything; from here the pair lives at the rendezvous.
        -- glueAcquire redirects our replication root at the target's hitbox, detaches and drags that hitbox
        -- ~100k studs out, and hands back the point to park beside it. char0 and char2 are then 0.7 studs
        -- apart, alone in that corner of the world.
        -- ⚠ NOT while predicting: S17 parks on a REMEMBERED head position because the real one is
        -- unreachable, and dragging a hitbox we are not actually shooting at would corrupt the resurface
        -- model for a target we are holding fire on anyway.
        -- @polarcore-seam:S45 — `rv == nil` first, because the void-prefire path already acquired this frame
        -- and glueAcquire must run exactly once per frame: it rewrites the redirect and re-drags the hitbox
        -- every call, so a second one is a wasted hidden-property write on the hot path. predicting and
        -- voidFire are mutually exclusive by construction (the branch above sets one or the other, never
        -- both), so this stays a strict superset of the old condition and nothing that used to glue stops.
        -- The body write below is NOT optional and NOT a fallback — Kicia spends it every frame too
        -- (SetServerCFrame -> HeartbeatUpdate), because the park is what keeps us adjacent to char2.
        -- ⚠ NOT WHILE HOLDING A MELEE WEAPON. Kicia's melee glue planner (ragebotPlanner:Plan, cleaned
        -- L39996-39997) forges char0/char1 from the TARGET's own orientation with a +-pi/2 pitch — a third
        -- wire format, different again from the hitscan constants in S38. Gluing with our proven melee
        -- packet would repeat the exact S37 mistake one weapon class over. Melee keeps the body park.
        local aimPos = hpos
        if rv == nil and not predicting and not melee then rv = glueAcquire(hh) end
        -- @polarcore-seam:S44 — LITE binds here, BEFORE the full path's park override, and deliberately not
        -- after it: the `else glueRelease() end` branch below runs on every lite frame, and putting this
        -- after it would sit inside a distance-bounded gate pin for no reason. Ordering is safe because the
        -- two handles are disjoint — glueRelease() cannot touch _liteHit, and gumMode() returns exactly one
        -- mode so the two paths are mutually exclusive by construction. A stale binding left by a mid-round
        -- mode flip is collected by whichever watchdog owns it on the next Heartbeat.
        if rv == nil then liteAcquire(hh, predicting, melee) end
        -- The hitbox is AT the rendezvous now, so read its position back rather than assuming ours.
        if rv ~= nil then
            park   = rv + GLUE_PARK_OFF
            aimPos = hh.Position
        else
            glueRelease()
        end

        -- @polarcore-seam:S10 — fire from the park the server already has, aim at the head as it is NOW.
        -- Requires the same target, so a switch re-primes for one frame instead of shooting from a park
        -- that belonged to somebody else. The latch is conditional on the write having LANDED: latching a
        -- park the body never reached is the one way this seam can hand the next frame a fire origin the
        -- server was never told about, which is the exact failure it exists to prevent.
        local firePark = nil
        if _prevPark ~= nil and _prevParkTgt == tgt then firePark = _prevPark end
        -- @polarcore-seam:S27 — the standalone fires from THIS frame's park, on this frame, with nothing
        -- withheld (polar_movinghide L364). It is a measured winner while doing that, so the first volley
        -- landing in a wall is a cost it already pays and already beats Kicia through. S10 traded a whole
        -- frame of every burst to avoid it; under parity we take the wall bullet and keep the frame.
        -- @polarcore-seam:S31 — the fire ordering is COUPLED to the restore mode, because it is coupled in
        -- Kicia. Kicia's shot leaves inside ragebot:Update, before rootDesync:HeartbeatUpdate writes this
        -- frame's park, so every Kicia round resolves from the previous frame's park. Only "kicia" mode
        -- reproduces that; "render" and "none" keep the body parked across physics, so they fire from THIS
        -- frame's park exactly as the standalone does (polar_movinghide L364).
        if restoreMode() ~= "kicia" then firePark = park end
        -- @polarcore-seam:S39/S42 THE PREDICTOR POISON. Operator ground truth: the manual Random ->
        -- Translocate -> Random swap mid-attack makes Kicia's TRADE insane — it hits more AND takes less —
        -- and the gain PERSISTS after returning to Random. Being in the volume is not itself protection
        -- (a Kicia sitting in Translocate is shootable), so the payload cannot be the destination. It is
        -- the DISPLACEMENT: a one-frame jump of ~1e5 studs makes every enemy's finite-difference velocity
        -- estimate — (pos - lastPos)/dt — return an astronomical number. We defend against exactly this
        -- and it is written in our own code: 05_utils rejects >500 studs/s samples and zeroes lead above
        -- 120 studs/s, with the comment "a void-flickering enemy pollutes the estimate". Kicia INFLICTS
        -- that: their aim goes wrong (or their lead collapses to zero) and stays wrong while the poisoned
        -- sample lives in their history, which is why one or two flips carry the whole fight. Ours never
        -- degrades. One frame is not a compromise here — it is the correct dose, since the poison is
        -- delivered the moment the position replicates and every extra frame only exposes us.
        -- Do NOT re-gate on glueActive(): Kicia uses no glue here. Full derivation: 02_config.
        -- ⚠ restoreMode() ~= "none" is REQUIRED: under "none" both anchors early-return mid-burst, so the
        -- park is our REAL body across the physics step and the bait would walk us into the kill volume.
        -- ⚠ NOTE FOR WHOEVER REOPENS THIS (2026-08-12): that claim is now known to be half wrong — under
        -- "render" the Stepped anchor calls reparkAfterRender(), so the body is at the park across physics
        -- there too and this clause only ever chose between two equally exposed transports. It is left
        -- exactly as it was because S43, which acted on that finding, was reverted after an unexplained
        -- live regression. Re-derive before touching it; do not take this comment as licence.
        -- @polarcore-seam:S45 — `not voidFire` too. The bait's payload is a velocity-estimate poison
        -- delivered to an enemy who is CURRENTLY TRACKING US; a target in its own void is tracking nothing,
        -- so a pulse there buys no poison and spends a frame of exposure and a frame of fire for nothing.
        local translocateReady = Config.RageAttackTranslocate ~= false
            and restoreMode() ~= "none"
            and not predicting and not holdFire and not melee and firePark ~= nil
            and not voidFire
            and (parity() or tick() >= _primeUntil)
        local startingTranslocate = translocateReady
            and _translocateNext
            and _translocateBurstPulses < TRANSLOCATE_PULSES_PER_BURST
        local translocateCF = nil
        -- @polarcore-seam:S42 — ONE FRAME, NEVER HELD. Operator, correcting a dwell version I shipped:
        -- "staying in translocate for that long makes us exposed, cuz if kicia in translocate even we can
        -- attack it — its not that being in translocate is unhittable, thats not the mechanism." Correct:
        -- the volume is not cover, so every extra frame there is a frame we are shootable and not shooting.
        -- The payload is the DISPLACEMENT ITSELF, not the destination, and it is delivered the instant the
        -- position replicates. See the poison note at translocateReady.
        if startingTranslocate then
            translocateCF = attackTranslocateCFrame()
        end

        local desiredCFrame = CFrame.new(park)
        if translocateCF ~= nil then
            desiredCFrame = translocateCF
        end
        local parked = displace(hrp, desiredCFrame)

        -- A Translocate frame is never a shot origin. Preserve the last attack park so the return frame
        -- can use S38 immediately instead of paying another prime.
        if parked and translocateCF == nil then
            _prevPark, _prevParkTgt = park, tgt
            _lastPark = CFrame.new(park)   -- @polarcore-seam:S30 only on a write that LANDED
        elseif not parked then
            _prevPark, _prevParkTgt = nil, nil
            _lastPark = nil
        end

        if translocateCF ~= nil then
            _translocateNext = false
            -- @polarcore-seam:S42 — spend a pulse ONLY on the opening edge. Counting every held frame would
            -- consume both allowances inside the first dwell and reduce this straight back to a blip.
            if startingTranslocate then
                _translocateBurstPulses = _translocateBurstPulses + 1
                State.RageTranslocateBaits = (State.RageTranslocateBaits or 0) + 1
                -- SPACE THE TWO BAITS. Zeroing the arm counter makes the second bait wait another
                -- TRANSLOCATE_ARM_FRAMES of actual shooting, which is the human cadence — bait, shoot,
                -- bait — instead of re-arming on the very next frame and firing both back to back.
                _translocateFireFrames = 0
            end
            State.RageFiring = false
            State.RageTranslocating = parked
            if parked then
                State.RageStatus = "Translocating"
            else
                -- The write failed, so our body is NOT at the volume and holding the clock open would
                -- suppress fire for the whole dwell for nothing. Close it and return to the park.
                State.RageStatus = "Translocate failed"
            end
        elseif predicting then
            _translocateNext = false
            -- @polarcore-seam:S17 parked and priming on a target that has not materialised yet
            State.RageFiring = false
            State.RageStatus = "Predicting resurface"
        elseif holdFire then
            _translocateNext = false
            State.RageStatus = "Protected — parked, holding fire"
        elseif firePark == nil then
            _translocateNext = false
            -- @polarcore-seam:S31 — "kicia" mode has no park from last frame on the opening frame of a
            -- burst (or after a target switch). Spend this frame parking. One frame, no clock.
            State.RageFiring = false
            State.RageStatus = "Priming"
            _meleeDwellStart = nil
        elseif (not parity()) and (tick() < _primeUntil) then
            _translocateNext = false
            -- @polarcore-seam:S27 — PRIME_S + the jitter are 70-320ms of parked, exposed, non-firing time
            -- per burst that the standalone does not spend. They are S8's compensation, not an independent
            -- win, so they go with S8.
            State.RageFiring = false
            State.RageStatus = "Priming"
            -- @polarcore-seam:S25 — no replicated park yet, so the melee dwell has not started. Without
            -- this a target switch would carry a stale dwell across and swing a frame early, from a park
            -- the server has not been told about.
            _meleeDwellStart = nil
        elseif melee and Config.RageKnifeBot ~= false then
            _translocateNext = false
            -- @polarcore-seam:S18/S22 — a melee item has no magazine and a real per-swing cooldown, so
            -- this path never tap-sprays. A heavy-capable weapon backstabs for 150 (a whole fighter);
            -- everything else lands its ordinary light attack on the weapon's own cadence.
            if meleeStrike(firePark, aimPos, hh, tgt) then
                _attackReadyTgt = tgt
                State.RageStatus = "Melee"
            else
                State.RageFiring = false
                State.RageStatus = "Melee (cooldown)"
            end
        else
            -- @polarcore-seam:S37 — aimPos, not hpos. Under the glue the hitbox IS the rendezvous, and char0
            -- (built from firePark, also at the rendezvous) has to point at where char2 actually is or every
            -- packet is a 100k-stud miss. Unglued the two are the same value.
            local sent = polarFire(firePark + Vector3.new(0, EYE_UP_SANE, 0), aimPos, hh, tapsPerFrame())
            -- @polarcore-seam:S42 — _translocateFireFrames counts frames we have actually been SHOOTING this
            -- burst, and the first bait is withheld until TRANSLOCATE_ARM_FRAMES of them pass. The one-frame
            -- version armed on the very first packet and spent both allowances in the opening ~50ms, before
            -- an opposing ragebot had converged on our park — baiting a hook not yet on the line. The
            -- operator's manual flip lands MID-burst, once they are already tracking us.
            -- Folded into the existing `sent > 0` block rather than adding a second one: two identical
            -- conditionals here made the gate's fire-site pin ambiguous, and one is simply better code.
            if sent > 0 then
                _attackReadyTgt = tgt
                _translocateFireFrames = _translocateFireFrames + 1
            end
            -- @polarcore-seam:S45 — count and name the void prefire separately. Without this the lab shows
            -- a plain "Attacking" and there is no way to tell a normal burst from the one thing that is
            -- supposed to be new, which is exactly how S39's bait sat at zero executions for two days.
            if voidFire and sent > 0 then
                State.RageVoidFires = (State.RageVoidFires or 0) + 1
            end
            _translocateNext = sent > 0 and parked and not melee
                and _translocateFireFrames >= TRANSLOCATE_ARM_FRAMES
                and _translocateBurstPulses < TRANSLOCATE_PULSES_PER_BURST
                and Config.RageAttackTranslocate ~= false
            State.RageStatus = "Attacking"
            if voidFire then State.RageStatus = "Attacking (gum void prefire)" end
        end
        -- The per-second melee readout used to sit HERE and that made it useless: every `return hide(...)`
        -- above skips this line, and in Orbit this whole driver stops on its first frame. It now lives in
        -- 07a's target loop, which runs in both modes and past every early return.
        if _notified ~= tgt then
            _notified = tgt
            pcall(Visuals.notifyTarget, tgt)   -- @polarcore-seam:S3 on target CHANGE only, not per frame
        end
    end

    -- @polarcore-seam:S8 — put the body back exactly where the game left it before we displaced it, then
    -- forget it. Returning the LIVE pre-displacement pose (not the stale _realCF snapshot) is what keeps
    -- movement native during a burst. _realCF survives only as the teardown/stranded-body fallback.
    local function restoreHome(pin)
        local ch = lp.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then return end
        local back = _preParkCF
        _preParkCF = nil
        pcall(function()
            if back then hrp.CFrame = back end
            -- The pin runs even when there was nothing to restore. RenderStep fires first and clears the
            -- saved pose, so gating the pin on `back` would mean the Stepped anchor — the only caller that
            -- passes pin — never reached it, and a displacement would leave us stuck in Freefall.
            if pin then
                local hu = ch:FindFirstChildOfClass("Humanoid")
                if hu and hu:GetState() == Enum.HumanoidStateType.Freefall
                   and hu.FloorMaterial ~= Enum.Material.Air then
                    hu:ChangeState(Enum.HumanoidStateType.Running)
                end
            end
        end)
    end

    -- @polarcore-seam:S35 CAMERA ANCHOR — the visible teleport, fixed WITHOUT touching the body.
    -- Operator, 2026-08-09: `"none"` destroys Kicia (power is back) *"but it doesnt restore like i see the
    -- teleport and us attacking"*. Every previous attempt at that complaint moved the ROOT PART back, and
    -- every one of them leaked the restore to the server. This solves it one layer up instead.
    --
    -- What is actually wrong is not the body — it is the CAMERA. CameraController binds at
    -- Enum.RenderPriority.Camera (200) and writes `Camera.CFrame = CFrame.new(subjectPos) * Rotation`
    -- ABSOLUTELY every frame (CameraController/init.luau:412), and the subject is our HumanoidRootPart. Park
    -- the root on the enemy's head and the camera flies there with it. That is the whole visual.
    --
    -- So: bind AFTER the controller and add back the displacement it just applied. Our write is the last one
    -- before the draw, and because we re-apply it every frame we never need it to persist — which is exactly
    -- why the "camera writes are discarded" note in the camera ground-truth file does not apply here. That
    -- note is about trying to make a ROTATION change stick across frames; this is a per-frame positional
    -- correction, recomputed from live values each time.
    --
    -- ★ THE POINT: this touches Camera.CFrame and NOTHING else. The root part stays parked for 100% of the
    -- frame, so the sender still only ever sees the park, and the power measured under "none" is unchanged
    -- by construction. It cannot leak, because there is nothing new on the wire — the camera is not
    -- replicated (only the look ANGLE is, via UpdateCameraRotation, and we do not touch rotation).
    -- It does NOT give movement back. Movement needs the park to not be the mechanism, i.e. the glue (#160).
    local function cameraAnchor()
        if Config.RageCameraAnchor == false then return end
        -- @polarcore-seam:S37 — no glue-specific guard is needed here and adding one would be wrong. The
        -- glue forces "kicia", so RenderStep(First-1000) has already restored the body and cleared
        -- _preParkCF by the time this runs at Camera+5, and the nil test below turns the correction off on
        -- its own. Under the fallback path the body IS parked and the correction is still required.
        local back = _preParkCF
        if back == nil then return end          -- not displaced right now: nothing to correct
        local ch = lp.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then return end
        local delta = back.Position - hrp.Position
        -- A hide is 110-140k studs away; correcting the camera by that much is right for the park but the
        -- hide has no meaningful "real" pose to show either, and a vector that large is where float error
        -- starts to matter. isSanePos on the DELTA keeps the correction to the point-blank park case.
        if not isSanePos(delta) then return end
        Camera.CFrame = Camera.CFrame + delta
    end

    -- @polarcore-seam:S30 — the second half of the "render" policy. The render anchor has just put the body
    -- back on its real pose so the frame draws correctly; this runs at Stepped, immediately after render and
    -- before physics, and puts the park back. displace() re-saves the (real) pose it finds, so the next
    -- render restore is still correct. Silent when there is no park to return to — a burst that has not
    -- written one yet, or a write that threw.
    local function reparkAfterRender()
        local cf = _lastPark
        if cf == nil then return end
        local ch = lp.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        if not hrp or not hrp.Parent then return end
        displace(hrp, cf)
    end

    -- @polarcore-seam:S8 — THE FRAME TRACE, superseding the standalone's suppress-while-firing rule.
    -- The standalone skipped both anchors during a burst so the park survived the physics step. That does
    -- replicate, but it also renders: the operator can watch himself teleport onto every target, and
    -- physics steps the parked body, which is where "movement is not native during a burst" came from.
    -- Kicia does not suppress anything (leak L144633-144688) — it re-displaces EVERY Heartbeat and undoes
    -- it at RenderPriority.First. Per frame we now get:
    --      RenderStep(First-1000) -> REAL | Stepped -> REAL | PHYSICS -> REAL | Heartbeat -> DISPLACED
    -- so the displaced pose lives only across the frame boundary — a window the network sampler sees and
    -- the renderer never does — while render and physics always get the true body.
    -- ★ SETTLED 2026-08-07 — THE RESTORE IS NEUTRAL TO RAGE POWER. Writing the argument down because it
    -- keeps being re-opened and each re-opening has cost a wrong fix:
    --   1. The server's view of us is, and is only, whatever the physics sender last transmitted
    --      (PARKLESS_TEST: the shot resolves from the REPLICATED body, never from char0).
    --   2. The sender runs in the end-of-frame networking phase — after Heartbeat, before the next frame's
    --      render callbacks — which is precisely the window above. So the displaced pose is the ONLY pose
    --      the sender can ever observe. Not "usually": every send that happens at all happens in there.
    --   3. Therefore S8 transmits the same parks, at the same times, as the standalone's hold-it-all-frame
    --      rule. The standalone merely ALSO shows the park to the renderer and steps physics on it, and the
    --      server reads neither.
    -- Point 2 is confirmed by behaviour, not only by reasoning: if the sampler read any other phase, S8
    -- would transmit nothing at all and the magazine would land nothing — and the rest of the magazine
    -- lands. If a burst ever stops landing, suspect the SEND RATE (S9) or target selection, not this.

    -- @polarcore-seam:S11 — drop per-player tracking when a player leaves, so the tables cannot grow
    -- across a session. The hacker TAG itself is intentionally sticky for as long as the player is here:
    -- Kicia never untags either, and a cheat that stops teleporting for a moment is still a cheat.
    Players.PlayerRemoving:Connect(function(p)
        _hackTag[p]   = nil
        _lastSeen[p]  = nil
        _hackAccum[p] = nil
        _predHidden[p] = nil   -- @polarcore-seam:S17
        _predDur[p]    = nil
        _predLast[p]   = nil
    end)

    function PolarCore.start()
        if _conn then return end
        _firing = false
        resetAttackContinuity()
        -- @polarcore-seam:S9, S27 — the standalone touches NO fflags and wins, so stock is proven
        -- sufficient. Under parity we leave the engine alone: whether the setter resolves and whether each
        -- value takes is executor- and session-dependent (that is exactly why S9 had to publish a readout),
        -- and FallenPartsDestroyHeight = NaN feeds killFloor() -> the park's own Y clamp. One less global
        -- that can differ between two runs of the same build. Gated here, not inside setPhysicsFlags,
        -- because 07b's Orbit shares that function and parity is a Polar concept.
        -- @polarcore-seam:S28 — un-gated from parity. The S27 sweep switched these OFF because "whether each
        -- value takes is session-dependent", which was true and was the right call while the effect of the
        -- flags was unknown. It is now known: DFIntAssemblyHistorySkipSize = 0 is precisely what makes a
        -- restore safe, so turning the flags off is what FORCED the suppression. The session-dependence is
        -- handled where it belongs — setPhysicsFlags reads every value back, and restoreDuringFire() refuses
        -- to trust an unverified set — rather than by declining to try.
        setPhysicsFlags(true)
        _notified = nil

        pcall(function() RunService:UnbindFromRenderStep(RENDER_NAME) end)
        -- @polarcore-seam:S35 — Camera + 5, i.e. after the game's controller (200), after 09_aimbot (+1) and
        -- after 09b_trigger (+2), so the correction is the last thing to touch Camera.CFrame before the draw
        -- and cannot be undone by one of our own binds. Fixed name so a re-execute kills the stale bind.
        pcall(function() RunService:UnbindFromRenderStep(CAMERA_NAME) end)
        RunService:BindToRenderStep(CAMERA_NAME, Enum.RenderPriority.Camera.Value + 5, function()
            pcall(cameraAnchor)
        end)
        -- @polarcore-seam:S8 — BOTH anchors fire UNCONDITIONALLY, every frame, firing or not. restoreHome
        -- is self-guarding (no saved pose => it only runs the humanoid pin). The previous version gated
        -- both on `not _firing`, which is what rendered the park and killed movement for the whole burst.
        -- First.Value - 1000 rather than Kicia's First.Value: strictly earlier, so we are back on the real
        -- pose before ANY other render-step consumer can read the CFrame.
        -- @polarcore-seam:S27 — under parity BOTH anchors go quiet for the whole burst, exactly as
        -- polar_movinghide L375/L384 does, so the park is the body's pose for every phase of every frame
        -- and no scheduler-timing assumption stands between us and the server. `_preParkCF == nil` stays
        -- the correct home-capture test under both rules: with the anchors suppressed it is non-nil for
        -- the whole burst, which is precisely what the standalone's `not _firing` proxy meant.
        -- @polarcore-seam:S28 — the guard is no longer parity(); it is restoreDuringFire(), which is the
        -- actual precondition. Under S27 the rule was "suppress while firing", which is correct only while
        -- the assembly history is decimated. Under S28, when every pose reaches the server anyway, the park
        -- is already sent by the time this runs and putting the body back costs nothing — which is Kicia's
        -- configuration, and the reason it has no visible teleport and keeps its movement. Both anchors take
        -- the SAME predicate: split them and the void and the park are undone by different rules again.
        RunService:BindToRenderStep(RENDER_NAME, Enum.RenderPriority.First.Value - 1000, function()
            if _firing and restoreMode() == "none" then return end
            restoreHome(false)
        end)

        -- @polarcore-seam:S30 — the Stepped anchor is where the three policies actually differ. "full"
        -- leaves the body restored (Kicia). "render" puts the park straight back, so only the render pass
        -- ever saw the real pose. "none" never restored in the first place.
        _stepConn = RunService.Stepped:Connect(function()
            if _firing then
                local pol = restoreMode()
                if pol == "render" then return reparkAfterRender() end
                if pol ~= "kicia" then return end
            end
            restoreHome(true)
        end)

        _charConn = lp.CharacterAdded:Connect(function()
            -- @polarcore-seam:S37 — the redirect is a property ON THE OLD ROOT PART. That part is gone, so
            -- the binding died with it; clear our belief in it or every park would silently fall through to
            -- the body path (or worse, we would think we were glued and skip the fallback). The captured
            -- default died with that part too and must be re-read off the new one. But the VICTIM is still
            -- holding a broken weld and an anchored hitbox, and nothing else will ever put those back, so
            -- tear that down for real rather than just forgetting it. No setRepRoot here: the new root part
            -- has its own untouched default and writing our old one onto it would be the actual corruption.
            pcall(glueTeardown)
            _glueHit = nil
            _gluePrevOk = false
            _glueDriven = false
            -- @polarcore-seam:S44 — FORGET, do not release. The redirect lived on the OLD root part, which
            -- no longer exists; writing our captured default onto the NEW root would be the actual
            -- corruption (same reasoning as the full path two lines up). Lite touched nothing on the
            -- victim, so there is nothing to reassemble either.
            _liteHit = nil
            _liteDriven = false
            _translocateNext = false
            _translocateBurstPulses = 0
            _translocateFireFrames = 0
            _translocatePart = nil
            State.RageGlueBound = false
            State.RageTranslocating = false
            _realCF = nil
            _realChar = nil
            _voidCF = nil
            _target = nil
            _notified = nil
            _firing = false   -- dying mid-burst would otherwise block the first home capture forever
            resetAttackContinuity()
            _preParkCF = nil  -- a pose saved off the OLD character must never be written to the new one
            _prevPark, _prevParkTgt = nil, nil   -- @polarcore-seam:S10
            _lastPark = nil                      -- @polarcore-seam:S30 never re-park a NEW body onto an old park
            -- @polarcore-seam:S12+S14 — _hiding TRUE, not false: a new body has never had a park
            -- replicated, so the first burst of a new life must serve the prime like any other.
            _hiding, _primeUntil = true, 0
        end)

        _conn = RunService.Heartbeat:Connect(function(dt)
            State.RageTranslocating = false
            tickHackers(dt or 0)   -- @polarcore-seam:S11 runs before any early return: a cheat must still
            tickPredict()          -- @polarcore-seam:S17 ditto: a hide/surface cycle must be learned even
                                   -- while we are reloading or dead, or the model only ever sees our fights
                                   -- be classified while we are in the lobby, dead, or hiding

            -- @polarcore-seam:S37 WATCHDOG. The glue is only safe while SOMETHING re-drives it every frame:
            -- the server resolves us from a hitbox that stops being written the moment we stop, so any
            -- frame bailing out before the park leaves us frozen on the wire at the last rendezvous — with
            -- the cheat switched off and a victim's character still in pieces. In-match every polarTick
            -- exit funnels through hide(), which releases; the returns BELOW this do not — end of round
            -- drops us to `not _inMatch` and every lobby frame returns early. Releasing on "nothing drove
            -- the glue last frame" covers all of them with one rule instead of a release call at each exit
            -- that someone has to remember to add.
            if _glueHit ~= nil and not _glueDriven then
                pcall(glueRelease)
            end
            _glueDriven = false
            -- @polarcore-seam:S44 — the same watchdog for the lite binding, and it is needed for the same
            -- reason: under lite the redirect is the ONLY thing placing us on the wire, so a frame that
            -- returns before the attack path (end of round, lobby, dead, mode switch) would otherwise leave
            -- the server resolving us from a hitbox nobody drives. One rule beats a release call at every
            -- exit somebody has to remember to add.
            if _liteHit ~= nil and not _liteDriven then
                pcall(liteRelease)
            end
            _liteDriven = false
            -- Published for 11_lab: BOUND alone cannot say whether the restore is being forced, because
            -- only "full" parks at the rendezvous and only "full" flips restoreMode() to "kicia".
            State.RageGumMode = gumMode()

            if not Config.Rage or (Config.RageMode or "Polar") ~= "Polar" then
                PolarCore.stop()
                return
            end
            local ch  = lp.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not hrp or not hrp.Parent then return end

            -- Capture home ONLY on frames where the body is genuinely at the player's own position —
            -- otherwise home drifts onto the enemy and both the hide-restore and the teardown put the
            -- player there. @polarcore-seam:S8 — the standalone expresses that test as `not _firing`,
            -- which is a PROXY that was exact only while the anchors were suppressed for the whole burst.
            -- Under S8 they never are: the body is back on its real pose from RenderStep onward and is only
            -- displaced at the very end of this dispatch, so `not _firing` no longer means "not displaced"
            -- — it just freezes home at the pre-burst pose for as long as a burst lasts, and a burst can
            -- last the whole fight. `_preParkCF == nil` is the exact statement of the same intent: nothing
            -- is currently displaced, so whatever the body reads is genuinely ours.
            if _preParkCF == nil and isSanePos(hrp.Position) then
                _realCF   = hrp.CFrame
                _realChar = ch
            end

            -- @polarcore-seam:S41 PARK DRIFT CANARY — the underground measurement, and ONLY a measurement.
            -- Operator-reported: against an enemy standing under the map "when we tp to them we above them
            -- so we cant hit them". Root cause, from this file's own frame trace at the anchors: under the
            -- default restoreMode() == "none" BOTH anchors return early while _firing, so the park is the
            -- body's pose across the physics step. Parking on a head that is inside rock hands Roblox's
            -- solver a body embedded in geometry, and it does the one thing it always does — ejects it
            -- along the shortest exit, which for a thin floor is UP. Next frame we re-park, get ejected
            -- again, and the operator watches himself hover above a target he cannot hit.
            -- ⚠ Kicia does not have this problem and does not solve it either — the question is malformed.
            -- SetServerCFrame is replication-only: HeartbeatUpdate writes the root and _RenderStepUpdate
            -- puts it back at RenderPriority.First, BEFORE physics runs. Its real body is never in the rock,
            -- so nothing ever ejects it. Kicia can park inside solid geometry precisely because its park is
            -- never a physical object. Ours is, for exactly as long as the restore stays suppressed.
            -- ⚠ NO FIX IS SHIPPED HERE ON PURPOSE. The proven standalone steps physics on its park too and
            -- wins, so the property is not fatal in general — it bites only when the park is inside
            -- geometry, and every candidate remedy is a divergence from the winner:
            --   · anchoring the body → an anchored assembly generates no physics history, and S28 says
            --     history IS what the sender transmits, so it risks silently killing park replication;
            --   · zeroing velocity every frame → a second writer on the assembly, unmeasured;
            --   · restoreMode "kicia" → measured to LEAK without the glue;
            --   · lifting the park → S19, already shipped OFF for exactly this class of reasoning.
            -- Four speculative fixes have already been spent on this file (S8/S9/S10/S14, all failed), so
            -- this seam buys the number first: drift is the studs between the park we wrote last Heartbeat
            -- and where the body actually is now. Physics is the only thing that can move it in that
            -- window. Read RageParkDrift in the lab against an underground target; if it climbs, the
            -- diagnosis is confirmed and the glue (which removes the body from the equation entirely) is
            -- the answer rather than any of the four above.
            -- ⚠ SCOPED TO "none" ON PURPOSE. That claim — "nothing but physics can have moved it" — is only
            -- true where BOTH anchors early-return while _firing. Under "render" the Stepped anchor calls
            -- reparkAfterRender and under "kicia" restoreHome runs, so the same subtraction would be
            -- measuring OUR OWN restore against the park and would read large and meaningless. A canary
            -- that reports a huge number for a healthy build is worse than no canary.
            if _lastPark ~= nil and _firing and restoreMode() == "none" then
                local ok, d, dy = pcall(function()
                    local off = hrp.Position - _lastPark.Position
                    return off.Magnitude, off.Y
                end)
                if ok and d == d and d > PARK_DRIFT_STUDS then
                    State.RageParkDriftFrames = (State.RageParkDriftFrames or 0) + 1
                    State.RageParkDrift = math.floor(d)
                    -- SIGNED, because the symptom is specifically "we above them". A solver ejection through
                    -- a thin floor is POSITIVE and persistent; gravity on a park the write missed is
                    -- negative. Magnitude alone cannot tell those apart, and they have opposite fixes.
                    State.RageParkDriftY = math.floor(dy or 0)
                end
            end


            -- ⚠ LOAD-BEARING, AND I DELETED IT ONCE (2026-08-11). Without this assignment _inMatch stays
            -- false forever, the guard below returns every single Heartbeat as "Lobby", and rage never
            -- attacks at all — with no error, in any mode, whatever else is configured. It was lost while
            -- inserting the S41 canary above; the standalone has it in this exact position
            -- (polar_movinghide.lua:427). Never separate it from the guard it feeds.
            _inMatch = inMatch()
            State.RageInMatch = _inMatch
            if not _inMatch then
                _target = nil
                _firing = false
                resetAttackContinuity()
                _translocateNext = false
                _translocateBurstPulses = 0
                _translocateFireFrames = 0
                State.RageFiring = false
                State.RageTarget = nil
                State.RageStatus = "Lobby"
                if not isSanePos(hrp.Position) then restoreHome(false) end
                return
            end

            if not _realCF or _realChar ~= ch then
                _firing = false
                resetAttackContinuity()
                _translocateNext = false
                _translocateBurstPulses = 0
                _translocateFireFrames = 0
                State.RageFiring = false
                State.RageStatus = "Waiting"
                return
            end

            -- @polarcore-seam:S5 CORPSE GUARD — the ONE behaviour here the standalone does not have, and the
            -- only place this file makes a judgement call. The standalone keeps ticking while dead, so it
            -- deep-voids its own corpse; we home it instead. Kept because a point-blank teleport of a
            -- ragdolling body replicates as impossible movement and a dead fighter cannot legally send
            -- UseItem, so this is an undetection guard that costs no damage (nothing can be hit while dead).
            -- If the live A/B ever comes back worse than the standalone, DELETE THIS FIRST: it is the only
            -- untested deviation left, and adding guards the winner does not have is exactly what produced
            -- the four divergences this file exists to retire.
            local hum = ch:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health <= 0 then
                _firing = false
                resetAttackContinuity()
                _translocateNext = false
                _translocateBurstPulses = 0
                _translocateFireFrames = 0
                State.RageFiring = false
                State.RageVoidActive = false
                State.RageStatus = "Dead"
                -- @polarcore-seam:S37 — a corpse must replicate as a corpse where it fell. Holding the glue
                -- through death would leave the ragdoll resolving from the last rendezvous.
                pcall(glueRelease)
                pcall(liteRelease)   -- @polarcore-seam:S44 after, so "Dead" stays adjacent to glueRelease
                if not isSanePos(hrp.Position) then restoreHome(false) end
                return
            end

            polarTick(ch, hrp)
        end)
    end

    function PolarCore.stop()
        -- @polarcore-seam:S37 FIRST, before anything else can throw. Leaving the glue installed after
        -- teardown means the server keeps resolving us from a hitbox nothing updates any more — the player
        -- would be frozen on the wire at the last rendezvous, permanently, with the cheat switched off, and
        -- a victim would keep a broken weld for the rest of the round.
        pcall(liteRelease)   -- @polarcore-seam:S44 before, so glueRelease stays adjacent to setPhysicsFlags
        pcall(glueRelease)
        setPhysicsFlags(false)   -- @polarcore-seam:S9 restore before anything else can fail
        pcall(ViewAngle.restore)  -- @polarcore-seam:S18 never leave the player's look angle frozen
        if _conn then _conn:Disconnect(); _conn = nil end
        if _stepConn then _stepConn:Disconnect(); _stepConn = nil end
        if _charConn then _charConn:Disconnect(); _charConn = nil end
        pcall(function() RunService:UnbindFromRenderStep(RENDER_NAME) end)
        pcall(function() RunService:UnbindFromRenderStep(CAMERA_NAME) end)   -- @polarcore-seam:S35
        _firing = false
        resetAttackContinuity()
        local hrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        if hrp and hrp.Parent then
            if _realCF and _realChar == lp.Character then
                pcall(function() hrp.CFrame = CFrame.new(_realCF.Position) * hrp.CFrame.Rotation end)
            elseif not isSanePos(hrp.Position) then
                -- never leave the body stranded in the void with no home to go back to
                pcall(function() hrp.CFrame = CFrame.new(0, 100, 0) end)
            end
        end
        _realCF = nil; _realChar = nil; _target = nil; _voidCF = nil; _notified = nil
        _translocateNext = false
        _translocateBurstPulses = 0
        _translocateFireFrames = 0
        _translocatePart = nil
        State.RageFiring = false
        State.RageVoidActive = false
        State.RageTranslocating = false
        State.RageTarget = nil
        State.RageInMatch = false
        State.RageStatus = "Idle"
    end

    PolarCore.shots     = function() return _shots end
    PolarCore.voidSteps = function() return _voidSteps end

    Rage._polarCoreStart = PolarCore.start
    Rage._polarCoreStop  = PolarCore.stop
    -- @polarcore-seam:S9 — shared with Orbit rather than duplicated. One implementation, one _flagsOn
    -- latch, so the two drivers can never half-apply or half-restore a GLOBAL between them. 07b loads
    -- first so it must nil-check this at call time, not at load.
    Rage._setPhysicsFlags = setPhysicsFlags

    -- @polarcore-seam:S28/S30 — one console call that answers "why is the restore off?" without a rebuild.
    -- Prints which fflag setter/getter resolved, the per-flag write+read-back result, and the policy that
    -- came out of it. Run it IN A MATCH with rage on: the flags are only raised in PolarCore.start().
    function Rage._physDiag()
        local set, get, setName = fflagApi()
        print("[LuaHook] fflag api: setter=" .. setName .. "  getter=" .. tostring(get ~= nil))
        print("[LuaHook] flags:  " .. tostring(State.RagePhysDetail or "(never set — is rage on?)"))
        print("[LuaHook] summary: " .. tostring(State.RagePhysRate or "off")
              .. "   set=" .. tostring(_physSet) .. "  verified=" .. tostring(_physLive))
        -- @polarcore-seam:S33 — a non-zero count means the IsInvincible mirror said "protected" for longer
        -- than spawn protection can legitimately last, i.e. the signal latched and the bound saved us.
        -- Expected to be 0. If it climbs, isSpawnProtected is the thing to look at, not the rage engine.
        print("[LuaHook] immune-hold overrides: " .. tostring(State.RageImmuneOverride or 0))
        -- @polarcore-seam:S37 — the question that decides everything else. BOUND=true means the server is
        -- resolving us from the target's hitbox at the rendezvous; false means we are on the body-park path
        -- and RageRestoreMode still governs. readback only proves the PROPERTY took, never that the engine
        -- honours it — that part is closed-source C++ and only a live A/B can answer it.
        -- @polarcore-seam:S44 — print the RESOLVED mode, never the raw keys. THREE config keys feed gumMode()
        -- and an operator reading "RagePartGlue = false" while RageGumMode = "lite" would draw exactly the
        -- wrong conclusion from a soak. This line is the one that says what actually ran.
        print("[LuaHook] gum: mode=" .. tostring(gumMode())
              .. "  (RageGumMode=" .. tostring(Config.RageGumMode)
              .. ", legacy RageGlueMode=" .. tostring(Config.RageGlueMode)
              .. ", RagePartGlue=" .. tostring(Config.RagePartGlue)
              .. ", voidFire=" .. tostring(Config.RageGumVoidFire ~= false) .. ")"
              .. "  liteBound=" .. tostring(_liteHit ~= nil)
              .. "  BOUND=" .. tostring(State.RageGlueBound == true)
              .. "  readback=" .. tostring(State.RageGlueVerified or "n/a")
              .. "  (sethiddenproperty=" .. tostring(type(sethiddenproperty) == "function")
              .. ", gethiddenproperty=" .. tostring(type(gethiddenproperty) == "function")
              .. ", identity=" .. tostring(_identSet ~= nil) .. ")")
        local rvTxt = "unrolled"
        if _rvCF ~= nil then rvTxt = tostring(_rvCF.Position) end
        -- The rendezvous is a FULL-mode artifact; under lite it stays "unrolled" forever and that is correct,
        -- not a fault. `glued to` reports whichever handle owns the redirect.
        print("[LuaHook] rendezvous: " .. rvTxt
              .. "   glued to: " .. tostring(_glueHit or _liteHit)
              .. "   (full=" .. tostring(_glueHit ~= nil) .. ", lite=" .. tostring(_liteHit ~= nil) .. ")")
        print("[LuaHook] attack translocate: enabled=" .. tostring(Config.RageAttackTranslocate ~= false)
              .. "  active=" .. tostring(State.RageTranslocating == true)
              .. "  next=" .. tostring(_translocateNext)
              .. "  burst=" .. tostring(_translocateBurstPulses)
              .. "/" .. tostring(TRANSLOCATE_PULSES_PER_BURST)
              .. "  part=" .. tostring(_translocatePart))
        print("[LuaHook] restore mode: " .. restoreMode()
              .. "   (Config.RageRestoreMode=" .. tostring(Config.RageRestoreMode)
              .. ", glue forces kicia=" .. tostring(glueActive())
              .. ", fires from " .. tostring(restoreMode() == "kicia") .. "=prev-frame park)")
        print("[LuaHook] gum void prefire (S45): allowed=" .. tostring(Config.RageGumVoidFire ~= false
                  and gumMode() == "on")
              .. "   shots sent through a hide=" .. tostring(State.RageVoidFires or 0)
              .. "   (0 against a deep-voider means the seam never ran — check the gum mode above first)")
        return restoreMode()
    end
    -- @polarcore-seam:S44 — the gum/glue readout lives inside _physDiag rather than a function of its own,
    -- and several comments used to point at a `Rage._gumDiag()` that has never existed. Alias rather than
    -- move: the physics flags and the glue are read together in practice, and splitting them would mean
    -- running two commands to answer one question.
    Rage._gumDiag = Rage._physDiag
end)()

-- ── GUN HOOK ───────────────────────────────────────────────────────────────

-- SILENT-AIM MULTIPOINT + TORSO FALLBACK: the server re-raycasts eye(camPos)->head, so a
-- head with no clear LOS silently misses. Instead of encoding a single clamped point, probe
-- a ring of candidate points around the chosen part; if none of the head's points are visible,
-- fall back to the other head hitboxes, then (optionally) the torso parts. Returns the first
-- BasePart the server should accept, or the primary (closest-to-crosshair) part as a last resort.
-- Reuses isVisible + HEAD_PARTS/TORSO_PARTS from 05_utils; the actual shot is still encoded by
-- Rage._encodeShot (which clamps + jitters within whichever part we return here).
local function silentPartVisible(part)
    if not part or not part:IsA("BasePart") then return false end
    if not Config.SilentAimMultipoint then return isVisible(part.Position) end
    if isVisible(part.Position) then return true end
    local n = math.max(1, math.floor(Config.SilentAimMultipointCount or 5))
    local r = math.min(part.Size.X, part.Size.Y, part.Size.Z) * 0.4
    for i = 1, n do
        local a   = (i / n) * math.pi * 2
        local off = Vector3.new(math.cos(a) * r, ((i % 2 == 0) and 0.5 or -0.5) * r, math.sin(a) * r)
        if isVisible(part.Position + off) then return true end
    end
    return false
end
local function pickSilentPart(char, primary)
    if not char then return primary end
    if silentPartVisible(primary) then return primary end
    for _, name in ipairs(HEAD_PARTS) do
        local p = char:FindFirstChild(name)
        if p and p ~= primary and silentPartVisible(p) then return p end
    end
    if Config.SilentAimTorsoFallback then
        for _, name in ipairs(TORSO_PARTS) do
            local p = char:FindFirstChild(name)
            if p and silentPartVisible(p) then return p end
        end
    end
    return primary   -- nothing clearly visible; fire the crosshair-closest part anyway
end

-- ── GUN HOOK ───────────────────────────────────────────────────────────────
-- NOTE: assigns the `local hookGunModule` forward-declared in 01_bootstrap.lua (do NOT re-`local` it,
-- or the CharacterAdded respawn re-hook there would capture a separate nil upvalue).
function hookGunModule()
    if not Rivals.Ready or not Rivals.Gun then return end
    -- ★ 2026-08-07 — THE GUARD USED TO BE `or shared._gunHooked == game then return end`, AND IT SILENTLY
    -- DISABLED EVERY HOOK ADDED AFTER THE FIRST EXECUTION OF A SESSION.
    -- `shared` survives across script executions; only rejoining clears it. So the second and every later
    -- run of the bundle in one Roblox session returned right here and installed NOTHING — including hooks
    -- a NEWER build had just added. That is how the melee camData redirect and the shot oracle could be
    -- "shipped and gated green" and still never exist at runtime, and it is the most likely reason the
    -- knife bot appeared dead through repeated re-executes while gun rage (which needs no new hook) kept
    -- working. Re-executing is the normal way this build is tested, so the guard had to go.
    -- Idempotence is now achieved properly instead: restore every original we previously saved BEFORE
    -- re-wrapping, so a re-execute replaces its own hooks rather than nesting them.
    if shared._LH_GunOrig then pcall(function() Rivals.Gun.StartShooting = shared._LH_GunOrig end) end
    if shared._LH_TracerOrig then pcall(function() Rivals.Gun._LocalTracers = shared._LH_TracerOrig end) end
    if shared._LH_ShootEffectOrig then pcall(function() Rivals.Gun._ShootEffect = shared._LH_ShootEffectOrig end) end
    if shared._LH_MeleeOrig and Rivals.Melee then
        pcall(function() Rivals.Melee.StartShooting = shared._LH_MeleeOrig end)
    end
    if shared._LH_KnifeOrig and Rivals.Knife then
        pcall(function() Rivals.Knife.StartAiming = shared._LH_KnifeOrig end)
    end
    shared._gunHooked = game
    
    local oldStart = Rivals.Gun.StartShooting
    shared._LH_GunOrig = oldStart   -- save the TRUE original so Unload can restore it (prevents a stale hook
                                    -- from a re-executed/unloaded instance from breaking guns)
    local hookWrapper = function(self, ...)
        -- FORGED-RAGE M1 SUPPRESSION. While the engine is delivering the burst itself (07b polarFire), the
        -- player's physical trigger must be INERT: running oldStart would fire a REAL shot along the frozen
        -- camera direction while our body is parked on the enemy's head — a server-visible shot with mismatched
        -- geometry, plus a client tracer and impact decals on the wall. We short-circuit BEFORE oldStart and
        -- return `false`, the game's own "no shot fired" value, emitted every frame by its cooldown/no-ammo
        -- paths, so nothing is mutated. On the NATURAL path (RageDirectFire=false) this does not apply — there
        -- oldStart IS the shot — and rage off restores the trigger instantly. pcall'd so it can never brick guns.
        -- ★ FAIL CLOSED (2026-07-29). The old test was `Config.Rage and Config.RageDirectFire and
        -- self.ClientFighter and self.ClientFighter.IsLocalPlayer`, evaluated inside a pcall with
        -- `suppress` defaulting to FALSE. So ANY of: ClientFighter transiently nil (respawn, equip swap,
        -- the reload transition), or indexing it throwing, made the whole condition fall through and ran
        -- the REAL oldStart -- a live shot along the player's ACTUAL camera. Gun.luau:143 then drew a
        -- LOCAL tracer for it before anything was even sent, which is exactly the reported first-bullet-
        -- into-the-wall and the stray skyward tracers (skyward because the body is parked in the void at
        -- Y=110000..140000 through the reload). Our forged burst cannot produce either: polarFire gates
        -- every packet on |eye - char2| <= 395 and derives the eye from the TARGET's head, never from us.
        -- Now: while rage-forged is active the local gun is inert by DEFAULT, and we only re-enable it on
        -- POSITIVE proof this call belongs to a remote fighter.
        local suppress = (Config.Rage == true and Config.RageDirectFire == true)
        if suppress then
            pcall(function()
                local cf = self.ClientFighter
                if cf and cf.IsLocalPlayer == false then suppress = false end
            end)
        end
        if suppress then return false end
        local results = { oldStart(self, ...) }   -- ALWAYS run the real fire first and keep its results
        -- Our shot logic must NEVER break the game's firing. Run it in pcall and always return the original
        -- results, so ANY error here (or a stale hook left behind by a re-execute) can't stop guns working.
        pcall(function()
            if not self.ClientFighter or not self.ClientFighter.IsLocalPlayer then return end
            local camData = results[3]
            if not camData or typeof(camData) ~= "table" then return end

            local camPos = Camera.CFrame.Position
            State.CamPos = camPos

            -- Rage path — the ONLY thing that redirects this game-built shot onto the parked target. 07a
            -- re-gates and rewrites char0-3 of the game's own camData in place, or bails and leaves it untouched.
            if Config.Rage then
                if Rage._encodeRageShot(camData) then results[4] = true end
                return
            end

            -- Silent aim path
            if Config.SilentAim then
                local tgt, part = selectTarget({
                    fov        = Config.SilentAimFOV,
                    checkVis   = Config.SilentAimVisCheck,
                    partMode   = Config.SilentAimTargetPart,
                    stickyTarget = State.SilentLastTarget,
                    stickyBonus  = Config.SilentAimStickiness or 0.05,
                })
                if tgt and part then
                    State.SilentLastTarget = tgt
                    Visuals.notifyTarget(tgt)
                    local hitPart = pickSilentPart(tgt.Character, part)
                    if Rage._encodeShot(camData, hitPart, tgt.Character, camPos) then
                        results[4] = true
                        State.Shots = State.Shots + 1
                        State.Hits  = State.Hits  + 1
                    end
                    return
                end
            end

            -- Aimbot shot-override path
            if Config.Aimbot and Config.AimbotShotOverride
                and State.AimbotTarget and State.AimbotPart and State.AimbotKeyHeld then
                local tgt = State.AimbotTarget
                if tgt and tgt.Character and isValidTarget(tgt, false) then
                    Visuals.notifyTarget(tgt)
                    if Rage._encodeShot(camData, State.AimbotPart, tgt.Character, camPos) then
                        results[4] = true
                        State.Shots = State.Shots + 1
                        State.Hits  = State.Hits  + 1
                    end
                end
            end

            -- MANUAL fire (no assist target resolved above): still hologram whoever is under the crosshair,
            -- so the dot works on every shot at a target regardless of which features are on — gated only by
            -- the hologram toggle. (Rage returns earlier and shows its own dot from the engine.)
            if Config.HUD or Config.VisualsHolograms then
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                rp.FilterDescendantsInstances = { lp.Character }
                local res = workspace:Raycast(camPos, Camera.CFrame.LookVector * (Config.MaxDistance or 1000), rp)
                if res and res.Instance then
                    local m  = res.Instance:FindFirstAncestorOfClass("Model")
                    local pl = m and Players:GetPlayerFromCharacter(m)
                    if pl and pl ~= lp then Visuals.notifyTarget(pl) end
                end
            end
        end)
        return unpack(results)
    end

    -- Give hookWrapper the GAME env so getfenv(Rivals.Gun.StartShooting).hookfunction == nil (closes a
    -- latent leak — no known probe scans StartShooting today, but cheap). NOT newcclosure: that would flip
    -- iscclosure false→true, anomalous for a module method. Upvalues are unaffected by setfenv; only free
    -- globals (typeof/pcall/unpack/Enum/RaycastParams) rebind, all present in the original method's env.
    if setfenv then pcall(setfenv, hookWrapper, getfenv(oldStart)) end
    if setreadonly then pcall(setreadonly, Rivals.Gun, false) end
    Rivals.Gun.StartShooting = hookWrapper

    -- ── LOCAL-TRACER KILL (belt to the fail-closed brace above) ─────────────────────────────────────
    -- Gun.luau:143 calls _LocalTracers INSIDE StartShooting, BEFORE the packet is sent, so a shot that
    -- slips past the wrapper has already drawn its tracer by the time any send-side gate could see it.
    -- Suppressing the send cannot unpaint that line. This is also the only place that covers subclass
    -- items (Modules/Items/Minigun, Revolver, Gunblade, ...) which define their OWN StartShooting and so
    -- never reach our base-class wrapper at all -- they still INHERIT _LocalTracers from Gun.
    -- Gun.luau:143 already gates the call on ClientFighter.IsLocalPlayer, so every call reaching us is
    -- ours and an unconditional skip is correct. Downstream is safe: _local_tracers simply stays empty,
    -- which is the state the forged path already runs in, so _ShootEffect (Gun.luau:679) keeps drawing
    -- the honest server-result tracer for our real shots, and _CorrectLocalTracers no-ops on an empty
    -- list (Gun.luau:625 `if v148 then`).
    local oldLocalTracers = Rivals.Gun._LocalTracers
    if type(oldLocalTracers) == "function" then
        shared._LH_TracerOrig = oldLocalTracers
        Rivals.Gun._LocalTracers = function(selfItem, ...)
            if Config.Rage == true and Config.RageDirectFire == true then
                State.RageTracerCanary = (State.RageTracerCanary or 0) + 1   -- >0 proves the leak was real
                return
            end
            return oldLocalTracers(selfItem, ...)
        end
    end

    -- ── MELEE CAMDATA REDIRECT (2026-08-07) ─────────────────────────────────────────────────────────
    -- The melee equivalent of the Gun hook above, and the reason it exists: four attempts at FORGING a
    -- melee UseItem packet all landed nothing, while the "ask the game" delivery has been landing gun
    -- damage for months. Both melee entry points return camData built from the player's REAL camera:
    --     Melee.StartShooting -> (true, "StartShooting", GetCameraData(), ToEnum(anim))   [light, shared]
    --     Knife.StartAiming   -> (true, "StartAiming",   GetCameraData(), ToEnum(anim))   [heavy, subclass]
    -- so redirecting a melee swing onto the rage target is the SAME one-line camData rewrite the gun path
    -- uses -- Rage._encodeRageShot re-gates and rewrites char0-char3 in place, or refuses and leaves the
    -- table untouched. It refuses anything older than one frame, so a swing the engine did not ask for
    -- (the player's own click) is never redirected.
    -- Both are class-table replacements, the same idiom as the two Gun hooks; no hookfunction.
    local function wrapMeleeAttack(cls, method, saveKey)
        if type(cls) ~= "table" then return end
        local orig = rawget(cls, method)
        if type(orig) ~= "function" then return end
        -- Save the TRUE original so a re-execute can restore it above instead of nesting a wrapper inside
        -- a wrapper, and so Unload puts the game back the way it found it.
        shared[saveKey] = shared[saveKey] or orig
        if setreadonly then pcall(setreadonly, cls, false) end
        cls[method] = function(selfItem, ...)
            local prev = nil
            if getthreadidentity ~= nil then pcall(function() prev = getthreadidentity() end) end
            local s = setthreadidentity or set_thread_identity or setidentity or setthreadcontext
            if s ~= nil then pcall(s, 2) end
            local results = { orig(selfItem, ...) }
            if s ~= nil and prev ~= nil then pcall(s, prev) end
            pcall(function()
                if not Config.Rage then return end
                if not selfItem.ClientFighter or not selfItem.ClientFighter.IsLocalPlayer then return end
                local camData = results[3]
                if typeof(camData) ~= "table" then return end
                Rage._encodeRageShot(camData)
            end)
            return unpack(results)
        end
    end
    wrapMeleeAttack(Rivals.Melee, "StartShooting", "_LH_MeleeOrig")
    wrapMeleeAttack(Rivals.Knife, "StartAiming",  "_LH_KnifeOrig")

    -- ── SHOT ORACLE (2026-08-07) ────────────────────────────────────────────────────────────────────
    -- Four theory-driven fixes for "the first bullet of every burst hits a wall" have now failed live.
    -- That is the signal to stop theorising and measure, and Gun.ReplicateFromServer("ShootEffect")
    -- hands us exactly the missing fact: the SERVER's own answer for where each of our shots ended up.
    -- Gun.luau:651 decodes the payload as { [char0] = Position, [char1] = Instance, ... } per pellet.
    -- So per shot we learn whether the server put the round on the target or somewhere else, and — the
    -- decisive part — how far that somewhere else was from OUR REAL BODY. A stray resolved from a stale
    -- pose lands a few studs from wherever the server still thought we were, so:
    --     off-target hits clustered a few studs from our own root  => the server used our REAL pose,
    --                                                                 i.e. the park had not replicated
    --     off-target hits far from us AND far from the target      => something else entirely
    --     no off-target hits at all                                => the visible wall round is not a
    --                                                                 packet of ours and never was
    -- Read-only, allocation-free, no send-path involvement, and inert unless rage is actually forging.
    local oldShootEffect = Rivals.Gun._ShootEffect
    if type(oldShootEffect) == "function" then
        shared._LH_ShootEffectOrig = oldShootEffect
        Rivals.Gun._ShootEffect = function(selfItem, results, ...)
            pcall(function()
                if Config.Rage ~= true or Config.RageDirectFire ~= true then return end
                if type(results) ~= "table" then return end
                local cf = selfItem.ClientFighter
                if not cf or not cf.IsLocalPlayer then return end
                local tgt = State.RageTarget
                local tchar = tgt and tgt.Character
                local myRoot = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
                for _, entry in results do
                    local hitPart = entry[utf8.char(1)]
                    local hitPos  = entry[utf8.char(0)]
                    local onTarget = false
                    if hitPart and tchar and hitPart:IsDescendantOf(tchar) then onTarget = true end
                    if onTarget then
                        State.RageHitsOn = (State.RageHitsOn or 0) + 1
                    else
                        State.RageHitsOff = (State.RageHitsOff or 0) + 1
                        if typeof(hitPos) == "Vector3" then
                            if myRoot then
                                State.RageOffFromSelf = (hitPos - myRoot.Position).Magnitude
                            end
                            local th = tchar and (tchar:FindFirstChild("HitboxHead") or tchar:FindFirstChild("Head"))
                            if th then
                                State.RageOffFromTarget = (hitPos - th.Position).Magnitude
                            end
                        end
                    end
                end
            end)
            return oldShootEffect(selfItem, results, ...)
        end
    end
end

hookGunModule()

-- ============================================================================
-- 08c_viewangle.lua — FORGED LOOK ANGLE (Kicia's ViewAngleDriver, all three surfaces)
--
-- WHAT THE SERVER RECEIVES ABOUT WHERE WE LOOK, from the game's own
-- FighterController._CameraReplicationLoop (dump L227-247):
--
--     while true do
--         wait(0.1)                                              -- 10 Hz, nothing faster
--         local enc = Util:EncodeCameraRotation(CameraController.Rotation)
--         if self._replication_stopped or enc ~= self._last_encoded_camera_rotation then
--             Remotes.Replication.Fighter.UpdateCameraRotation:FireServer(enc, nil)
--         end
--         self._last_encoded_camera_rotation = enc
--         self._replication_stopped = false
--     end
--
-- ONE remote, 10 Hz, send-on-change only. Kicia forges against it on three surfaces and we now do all
-- three. NONE of them is a hookfunction — its whole technique layer is modification without hooking
-- (debug.setconstant / debug.setupvalue / plain table-field replacement), which is why "this needs a
-- hook" was the wrong reason to skip it twice.
--
-- (1) SEND — `UpdateCameraRotation:FireServer(encoded, nil)`. Kicia's SendRawCameraRotation is literally
--     that line (cleaned leak L25317). An ordinary remote; no surface, nothing to restore.
--
-- (2) SUPPRESS — walk debug.getupvalues(_CameraReplicationLoop), find the Utility upvalue (a table whose
--     metatable.__index carries EncodeCameraRotation) and debug.setupvalue a shim over it (L25217-25283).
--     The shim returns `_last_encoded_camera_rotation` UNCHANGED, so `enc ~= _last_encoded` is false and
--     `_replication_stopped` is forced false — the branch never fires and the loop sends NOTHING. It is a
--     suppressor, not a liar: the lie is (1). Without it the loop overwrites our claim within 100 ms.
--
-- (3) LOCAL STATE — replace ClientFighterCharacterJoints.Update and rewrite `data.CameraRotationRaw` for
--     the local player (L25194-25213). That function only drives a camera-rotation spring and waist /
--     neck / root joint C0-C1 (game Joints.luau:24), so it reaches no remote and cannot add damage. What
--     it buys is CONSISTENCY, and Kicia's detail here is the tell that this is deliberate: f1902
--     (L25159) round-trips the angle through encodeSingle -> decodeSingle before writing it, i.e. it
--     stores the QUANTIZED value the wire actually carries, not the raw float. Anything on this client
--     that compares "the angle I replicated" against "the angle my character data holds" therefore sees
--     no discrepancy. We reproduce the round trip with the game's own Encode/DecodeCameraRotation.
--
-- ⚠ FOOTPRINT, plainly: one reversible upvalue write into a live game closure, plus one game-module
-- method replacement (the same idiom 08_gunhook already uses for Gun.StartShooting and Gun._LocalTracers).
-- Inert until the knife bot actually forges. The `viewangle` build gate refuses to build unless the
-- originals are kept AND restored both on rage stop and on unload — a shim left installed would freeze
-- the player's replicated look angle for the rest of the session.
-- ============================================================================

-- ★ ASSIGNED, NOT DECLARED. The name is forward-declared in 03_camera_aa.lua because build.js
-- concatenates src/*.lua in SORTED order, which puts this file AFTER 07c_polar_core.lua — and 07c's two
-- S18 seams call ViewAngle.forge / ViewAngle.restore. A `local` here would be invisible to them, so they
-- read a nil global and PolarCore.stop() threw "attempt to index nil with 'restore'" on every teardown.
ViewAngle = {}

;(function()
    local _remote     = nil
    local _forged     = nil     -- quantized Vector2(pitch, yaw) currently being claimed, or nil
    -- (2) suppression
    local _loopFn, _utilIdx, _utilOrig = nil, nil, nil
    local _suppressed = false
    -- (3) joints
    local _joints, _jointsOrig = nil, nil

    local function remote()
        if _remote == nil then
            pcall(function()
                _remote = ReplicatedStorage.Remotes.Replication.Fighter.UpdateCameraRotation
            end)
        end
        return _remote
    end

    -- ── (2) SUPPRESS ────────────────────────────────────────────────────────────────────────────────
    -- Kicia reaches the loop through getmetatable(FighterController).__index; our handle is the required
    -- module rather than an instance, so try it directly first and fall back to Kicia's path.
    local function resolveLoop()
        if _loopFn ~= nil then return true end
        if type(debug) ~= "table" or type(debug.getupvalues) ~= "function"
           or type(debug.setupvalue) ~= "function" then
            return false
        end
        pcall(function()
            local F = Rivals.Fighter
            if F == nil then return end
            local fn = rawget(F, "_CameraReplicationLoop")
            if type(fn) ~= "function" then
                local mt = getmetatable(F)
                local proto = mt and rawget(mt, "__index")
                if type(proto) == "table" then fn = rawget(proto, "_CameraReplicationLoop") end
            end
            if type(fn) ~= "function" then return end
            for i, v in debug.getupvalues(fn) do
                if type(v) == "table" then
                    local vmt = getmetatable(v)
                    local vidx = vmt and rawget(vmt, "__index")
                    if type(vidx) == "table" and rawget(vidx, "EncodeCameraRotation") ~= nil then
                        _loopFn, _utilIdx, _utilOrig = fn, i, v
                        return
                    end
                end
            end
        end)
        return _loopFn ~= nil
    end

    -- Every index other than EncodeCameraRotation forwards to the real Utility, so the loop cannot break
    -- on a field we did not anticipate.
    local function makeShim()
        local shim = {}
        shim.EncodeCameraRotation = function(_, rot)
            local last = nil
            pcall(function()
                local F = Rivals.Fighter
                if F ~= nil then
                    F._replication_stopped = false
                    last = F._last_encoded_camera_rotation
                end
            end)
            if last ~= nil then return last end
            return _utilOrig:EncodeCameraRotation(rot)
        end
        return setmetatable(shim, { __index = _utilOrig })
    end

    local function suppress(on)
        if on == _suppressed then return end
        if on then
            if not resolveLoop() then return end
            if pcall(debug.setupvalue, _loopFn, _utilIdx, makeShim()) then
                _suppressed = true
                State.ViewAngleForged = true
            end
            return
        end
        if _loopFn ~= nil and _utilOrig ~= nil then
            pcall(debug.setupvalue, _loopFn, _utilIdx, _utilOrig)
        end
        _suppressed = false
        State.ViewAngleForged = false
    end

    -- ── (3) LOCAL STATE ─────────────────────────────────────────────────────────────────────────────
    local function patchJoints(on)
        if on then
            if _jointsOrig ~= nil then return end
            pcall(function()
                _joints = loadGameModule(lp.PlayerScripts,
                    {"Modules", "ClientReplicatedClasses", "ClientFighter", "ClientFighterCharacter", "Joints"})
                if type(_joints) ~= "table" then
                    _joints = nil
                    return
                end
                local orig = rawget(_joints, "Update")
                if type(orig) ~= "function" then
                    _joints = nil
                    return
                end
                _jointsOrig = orig
                if setreadonly then pcall(setreadonly, _joints, false) end
                _joints.Update = function(selfJoints, dt, data)
                    -- The IsLocalPlayer guard is load-bearing: Update runs for EVERY fighter's joints, and
                    -- rewriting a remote player's camera data would visibly break their animation on our
                    -- screen for no gain at all.
                    if _forged ~= nil and type(data) == "table" then
                        pcall(function()
                            local cfc = selfJoints.ClientFighterCharacter
                            local cf = cfc and cfc.ClientFighter
                            if cf and cf.IsLocalPlayer == true then
                                data.CameraRotationRaw = _forged
                            end
                        end)
                    end
                    return orig(selfJoints, dt, data)
                end
            end)
            return
        end
        if _joints ~= nil and _jointsOrig ~= nil then
            pcall(function()
                if setreadonly then pcall(setreadonly, _joints, false) end
                _joints.Update = _jointsOrig
            end)
        end
        _jointsOrig = nil
    end

    -- ── PUBLIC ──────────────────────────────────────────────────────────────────────────────────────
    -- Claim a look angle, in RADIANS. Axis order is the game's own: CameraController.Rotation is
    -- Vector2(pitch, yaw) — GetRotationCFrame composes Angles(0, Y, 0) * Angles(X, 0, 0) — which is the
    -- same order CFrame:ToOrientation() returns, so a victim's orientation drops straight in.
    function ViewAngle.forge(pitch, yaw)
        local r = remote()
        if r == nil or not Rivals.Util then return false end
        local ok = pcall(function()
            -- ONE encode serves both the wire and the local state, which is exactly what makes them
            -- agree: DecodeCameraRotation returns the byte-quantized angle the server actually got.
            local enc = Rivals.Util:EncodeCameraRotation(Vector2.new(pitch, yaw))
            _forged = Rivals.Util:DecodeCameraRotation(enc)
            r:FireServer(enc, nil)
        end)
        if not ok then return false end
        suppress(true)
        patchJoints(true)
        return true
    end

    -- MANDATORY wherever the forge stops. An upvalue left swapped outlives our chunk and would freeze the
    -- player's look-angle replication for the rest of the session — they would stare in one direction to
    -- everyone else, which is both a broken game and the loudest anomaly this bundle could emit.
    function ViewAngle.restore()
        _forged = nil
        suppress(false)
        patchJoints(false)
    end

    ViewAngle.isForging = function() return _forged ~= nil end
end)()

-- ── AIMBOT ─────────────────────────────────────────────────────────────────
-- ANGULAR CONTROL LOOP. Everything here is yaw/pitch radians, never screen pixels. The old build
-- worked in pixels and assumed 1 unit of mousemoverel == 1 pixel; the game dump says otherwise
-- (Controllers/CameraController/init.luau):
--
--   L29   local v_u_22 = Enum.RenderPriority.Camera.Value            -- the controller binds at 200
--   L30   local v_u_23 = Vector2.new(0.77, 1) * math.rad(0.5)        -- base scale (pitch, yaw)
--   L31   local v_u_24 = { MouseKeyboard = 1, Touch = 0.875, Gamepad = 0.75 }
--   L457  self:ApplyRotationDelta(Vector2.new(input.Delta.Y, input.Delta.X)
--                                 * v_u_23 * v_u_24[scheme] * self:_GetFOVMultiplier() * -1)
--   L216  ApplyRotationDelta(d): Rotation += d * _inverted_identity_vector * GetCameraSensitivity()
--                                            * Vector2(_camera_sensitivity_y, _camera_sensitivity_x)
--   L146  GetRotationCFrame(): CFrame.Angles(0, Rotation.Y, 0) * CFrame.Angles(Rotation.X, 0, 0)
--   L412  workspace.CurrentCamera.CFrame = CFrame.new(v144) * v143.Rotation   -- ABSOLUTE write
--
-- Four consequences, and this whole file is built on them:
--
--  1. THE GAIN IS A PRODUCT OF SIX LIVE FACTORS, one of which (_GetFOVMultiplier) changes the
--     instant you ADS. A single hand-tuned AimbotSensMultiplier could never be right in both
--     hipfire and ADS, which is why the old aimbot felt different in each. We MEASURE the gain
--     off our own camera instead (calibrate() below) and re-converge when FieldOfView moves.
--     The dump's analytic values are used only as SEEDS and as a sanity band -- baked in as
--     constants, never read live, so this file executes no game code (see the note in 3).
--
--  2. THE DEAD TIME IS EXACTLY ONE FRAME, AND THE CONTROL LAW MUST NOT COMPENSATE FOR IT.
--     The controller binds at priority 200; we bind at 201. A mousemoverel issued at 201 is
--     queued, drained at the start of the NEXT frame, applied by the controller at 200 of that
--     frame, and read by us at 201 of that frame. So by the time we compute frame N's error, the
--     frame N-1 send has ALREADY landed and is ALREADY in the error. There is never a command
--     in flight at decision time, so there is nothing to subtract.
--     ★ THE 2026-08-04 REGRESSION, kept here because it is not obvious: the first version of this
--     file "compensated" by subtracting the previous send. With e(n+1) = e(n) - p(n) and
--     p(n) = a*(e(n) - p(n-1)), the characteristic equation is z^2 - (1-2a)z - a = 0, whose root
--     hits -1 at a = 2/3. At a = 1 the roots are the golden ratio: the command grows 1, -1, 2,
--     -3, 5, -8 ... Fibonacci, flipping sign every frame. The aimbot snapped on and then flew off
--     the target, faster each frame. a = 1 - exp(-dt/tau) exceeds 2/3 for any smoothness below
--     ~5, so the shipped default (0 = hard lock) diverged every time. _sx/_sy still record the
--     last send, but ONLY the gain estimator reads them. The control law uses the raw error, for
--     which e(n+1) = (1-a)*e(n) -- deadbeat at a = 1, unconditionally stable for 0 < a < 2.
--
--  3. WRITING Camera.CFrame IS DISCARDED. L412 builds the camera from internal state every frame
--     and never reads the live CFrame, so the old mobile fallback was dead code. The working
--     replacement is CameraController:ApplyRotationDelta -- but that needs a require, so it is
--     OFF by default behind AimbotDirectCamera and only engages when mousemoverel is genuinely
--     absent. ApplyRotationDelta and NOT SetRotation, deliberately: it fires RotationDeltaApplied
--     exactly as real input does, whereas SetRotation moves the camera with no matching rotation
--     signal -- precisely the internal inconsistency an opaque CameraSecurity could key on.
--
--  4. OUR LOOK ANGLE IS ON THE WIRE. FighterController sends Util:EncodeCameraRotation(camRot) ->
--     UpdateCameraRotation:FireServer on change, so the server already has our look-angle series.
--     Nothing else this file does is server-visible: it hooks NOTHING (no getmouse, no
--     UserInputService, no hookfunction/hookmetamethod anywhere), writes no game state, calls no
--     game function, and in the default path does not even require a game module. Its entire
--     interface is: read Camera.CFrame/FieldOfView/ViewportSize, read character parts, one LOS
--     raycast, and mousemoverel -- which produces a genuine InputChanged the game consumes
--     through its own path. The ONLY exposure is behavioural, and AimbotMaxSpeed (deg/s) is the
--     knob that governs it. Human ceiling is ~1080 deg/s; 0 means uncapped.
--
-- The error is measured on the RENDERED Camera.CFrame.LookVector, because that is what the gun's
-- camData is built from. Free bonus: the loop therefore also cancels the game's own idle sway,
-- jump spring, slide lean and shake instead of shooting through them.
local Aimbot = {}
;(function()

    local TAU = math.pi * 2
    local D2R = math.pi / 180
    local R2D = 180 / math.pi

    -- ── tuning constants ───────────────────────────────────────────────────
    local MAX_TAU     = 0.30    -- s; the time constant at AimbotSmoothness = 100
    local RETAIN_MUL  = 1.6     -- retention cone = FOV * this (acquire narrow, hold wide)
    local STICKY_MEM  = 2.0     -- s a dropped target stays preferred
    local FF_TAU      = 0.06    -- s; EMA on the target's angular rate (feed-forward)
    local FF_MAX      = 12      -- rad/s (~690 deg/s). Above this it is a teleport artifact, not
                                -- tracking -- and in HvH the enemy IS a rage user whose hitbox
                                -- flickers to the void, so an unclamped rate would yank the aim
                                -- off a perfectly good target for several frames afterwards.
    local UNIT_MAX    = 2000    -- hard ceiling on one frame's mouse units (a 180 deg turn at the
                                -- default gain is ~360), so a near-zero gain estimate can never
                                -- produce an astronomical jump.
    local RAMP_TIME   = 0.15    -- s; overshoot ramp after acquire
    local PITCH_LIMIT = 1.5690509975429023   -- the game's own SetRotation clamp (dump L157)
    local CAL_MIN     = 1.5     -- min |units| sent last frame before a gain sample is trusted
    local CAL_FAST_N  = 8       -- samples of fast adaptation before switching to the slow EMA
    -- The true gain is seed * scheme * fovMultiplier * sensitivity * perAxisSensitivity. On PC
    -- scheme is 1 and the FOV multiplier is <= 1, so only the player's sensitivity setting can
    -- push it up. A 6x band covers any plausible setting while still rejecting garbage samples;
    -- the old 20x band was loose enough to let a mis-timed observation poison the estimate.
    local BAND_LO     = 0.05    -- accept a sample only within [|seed|*LO, |seed|*HI]
    local BAND_HI     = 6
    local OSC_ERR     = 0.02    -- rad (~1.15 deg): the |error| floor above which ringing counts
    local RUNAWAY_ERR = 1.0     -- rad (~57 deg) of SMOOTHED error while actively driving = broken
    -- Analytic seeds from the dump: yaw rad per mouse-X unit = -rad(0.5); pitch adds the 0.77.
    local SEED_MX     = -0.008726646259971648
    local SEED_MY     = -0.006719517620178168
    -- ApplyRotationDelta takes pre-sensitivity units, so at default settings its gain is 1:1.
    local SEED_DX     = 1
    local SEED_DY     = 1

    -- ── state ──────────────────────────────────────────────────────────────
    local _bound     = false
    local _mouseMove = mousemoverel
    local _fovC, _lockC, _dbgT = nil, nil, nil

    local _tgt, _part  = nil, nil
    local _prevTgt     = nil
    local _notified    = nil
    local _acquireAt   = 0
    local _ramp        = 0

    local _gx, _gy     = SEED_MX, SEED_MY   -- measured gain: radians per sent unit (signed)
    local _sdx, _sdy   = SEED_MX, SEED_MY   -- the seed the band is judged against
    local _nx, _ny     = 0, 0               -- accepted calibration samples per axis
    local _sx, _sy     = 0, 0               -- units sent LAST frame (the one-frame dead time)
    local _fx, _fy     = 0, 0               -- sub-unit send remainder (mousemoverel quantizes)
    local _lyaw, _lpit = 0, 0               -- camera angles last frame
    local _haveCam     = false

    local _ffy, _ffp   = 0, 0               -- feed-forward angular rates (rad/s)
    local _lty, _ltp   = 0, 0               -- required aim angles last frame
    local _haveTgt     = false
    local _lastPartRef = nil                -- aim part last frame (a swap is not target motion)

    -- Oscillation guard. _auth starts BELOW 1 so the very first flick is safe even if the
    -- player's sensitivity makes our seeded gain badly wrong; it ramps to full within ~1s of
    -- active aiming, which is far faster than anyone can notice.
    local _auth        = 0.6
    local _flips       = 0                  -- decaying count of error sign changes
    local _errEma      = 0                  -- smoothed |error|, so quantization noise can't trip
    local _lastSign    = nil
    local _drive       = 0                  -- seconds of continuous active commanding
    local _trips       = 0                  -- runaway tripwire fires
    local _calOff      = false              -- estimator retired; run on the dump's constants

    local _lastFOV     = 0
    local _errDeg      = 0
    local _path        = "none"
    local _ctl, _ctlTried = nil, false

    -- ── angle helpers (valid for ANY direction, including behind the camera) ──
    local function wrapPi(a) return (a + math.pi) % TAU - math.pi end
    local function yawOf(v)   return math.atan2(-v.X, -v.Z) end
    local function pitchOf(v) return math.asin(math.clamp(v.Y, -1, 1)) end

    -- Angle between the camera's look and a world point, in radians.
    local function angTo(cf, pos)
        local d = pos - cf.Position
        local m = d.Magnitude
        if m < 1e-4 then return 0 end
        return math.acos(math.clamp(cf.LookVector:Dot(d) / m, -1, 1))
    end

    -- Half-cone degrees -> on-screen pixel radius, for the FOV ring only.
    local function fovPixels(deg)
        local vp = Camera.ViewportSize
        local lim = math.max(vp.X, vp.Y)
        if deg >= 89 then return lim end
        local half = math.tan(math.rad(Camera.FieldOfView) * 0.5)
        if half <= 0 then return lim end
        return math.clamp(math.tan(deg * D2R) / half * (vp.Y * 0.5), 4, lim)
    end

    -- ── targeting ──────────────────────────────────────────────────────────
    -- isValidTarget gates on isProtected, the legacy ForceField heuristic -- and Rivals ships no
    -- ForceField at all, so it can never fire. isSpawnProtected is the game's real signal (the
    -- replicated IsInvincible key + its change signal) and costs a table index once subscribed.
    local function validFor(pl)
        if not isValidTarget(pl, false) then return false end
        if Config.AimbotSkipImmune and isSpawnProtected(pl) then return false end
        return true
    end

    local function firstVisible(char, list, skip)
        for _, n in ipairs(list) do
            local p = char:FindFirstChild(n)
            if p and p ~= skip and p:IsA("BasePart") and isVisible(p.Position) then return p end
        end
        return nil
    end

    -- "Best": head hitboxes -> other head parts -> torso, each LOS-probed. The occlusion-aware
    -- part fallback the visible aimbot never had (silent aim has had it since pickSilentPart).
    local function resolveBest(char, primary)
        if not char then return primary end
        if primary and isVisible(primary.Position) then return primary end
        return firstVisible(char, HEAD_PARTS, primary)
            or firstVisible(char, TORSO_PARTS, primary)
            or primary
    end

    -- One angular pass over the player list. Scores in RADIANS, not pixels, so an off-screen or
    -- behind-us enemy is a perfectly ordinary candidate instead of an early return.
    local function acquire(cf, fovR, retainR, cur)
        local mode = Config.AimbotTargetPart or "Best"
        local pick = (mode == "Best") and "Head" or mode
        local prio = Config.AimbotPriority or "Crosshair"
        local vis  = Config.AimbotVisCheck
        local myRoot = nil
        if prio == "Distance" then
            local mc = lp.Character
            myRoot = mc and mc:FindFirstChild("HumanoidRootPart")
        end
        local bP, bPart, bAng, bScore = nil, nil, math.huge, math.huge
        local cPart, cAng, cOK = nil, math.huge, false
        for _, pl in ipairs(getSafePlayers()) do
            if pl ~= lp and validFor(pl) then
                local char = pl.Character
                local part = pickPart(char, pick)
                if part then
                    local ang    = angTo(cf, part.Position)
                    local isCur  = (pl == cur)
                    if ang <= (isCur and retainR or fovR) then
                        if (not vis) or isVisible(part.Position) then
                            local score = ang
                            if prio == "Health" then
                                local hp = getHealth(pl)
                                score = hp * 100 + ang
                            elseif prio == "Distance" and myRoot then
                                score = (part.Position - myRoot.Position).Magnitude * 100 + ang
                            end
                            if isCur then
                                cPart, cAng, cOK = part, ang, true
                                score = score * (1 - (Config.AimbotStickiness or 0))
                            end
                            if score < bScore then bScore, bP, bPart, bAng = score, pl, part, ang end
                        end
                    end
                end
            end
        end
        -- Switch hysteresis: hold a still-valid lock unless the challenger is meaningfully closer
        -- to the crosshair. Stops the flicker between two enemies at similar angles.
        -- Crosshair priority ONLY: under Health/Distance the ordering is deliberately not angular,
        -- so an angular guard here would veto exactly the switches the priority was chosen to
        -- make (a 10 HP enemy one degree further out would never be taken). Those modes get their
        -- hysteresis from AimbotStickiness instead.
        if prio == "Crosshair" and cOK and bP and bP ~= cur then
            if bAng > cAng - (Config.AimbotSwitchDeg or 0) * D2R then
                return cur, cPart, cAng
            end
        end
        return bP, bPart, bAng
    end

    -- ── drawings ───────────────────────────────────────────────────────────
    local function ensureDraw()
        pcall(function()
            if not _fovC then
                local c = screenDraw("Circle")
                if c then
                    c.Thickness = 1; c.NumSides = 64
                    c.Color = Color3.fromRGB(180, 180, 180)
                    c.Transparency = 0.6; c.Filled = false; c.Visible = false
                    _fovC = c
                end
            end
            if not _lockC then
                local c = screenDraw("Circle")
                if c then
                    c.Thickness = 2; c.NumSides = 32
                    c.Color = Color3.fromRGB(255, 80, 100)
                    c.Transparency = 0.9; c.Filled = false; c.Radius = 6; c.Visible = false
                    _lockC = c
                end
            end
            if not _dbgT then
                local t = screenDraw("Text")
                if t then
                    t.Font = 3; t.Size = 13; t.Outline = true
                    t.Color = Color3.fromRGB(0, 230, 160)
                    t.Position = Vector2.new(14, 330); t.Visible = false
                    _dbgT = t
                end
            end
        end)
    end

    local function diagText()
        -- auth < 1 means the oscillation guard is backing the loop off: either it is still
        -- ramping in after acquire, or the measured gain is wrong enough to overshoot.
        return string.format(
            "AIMBOT  path=%s%s\ngain  x=%.6f (n%d)   y=%.6f (n%d)\nerr %.2f deg   sent %d,%d   auth %.2f   trips %d\ntarget %s",
            _path, _calOff and "  [gain PINNED]" or "",
            _gx, _nx, _gy, _ny, _errDeg, _sx, _sy, _auth, _trips,
            _tgt and _tgt.Name or "-")
    end

    local function updateDraw()
        local wantFov  = Config.Aimbot and Config.AimbotShowFOV
        local wantLock = Config.Aimbot and Config.AimbotShowLock and _part
        local wantDbg  = Config.Aimbot and Config.AimbotDebug
        if not (wantFov or wantLock or wantDbg) then
            if _fovC  and _fovC.Visible  then _fovC.Visible  = false end
            if _lockC and _lockC.Visible then _lockC.Visible = false end
            if _dbgT  and _dbgT.Visible  then _dbgT.Visible  = false end
            return
        end
        ensureDraw()
        if _fovC then
            if wantFov then
                local vp = Camera.ViewportSize
                _fovC.Position = Vector2.new(vp.X * 0.5, vp.Y * 0.5)
                _fovC.Radius   = fovPixels(Config.AimbotFOVDeg or 20)
                _fovC.Visible  = true
            else
                _fovC.Visible = false
            end
        end
        if _lockC then
            local on = false
            if wantLock then
                local sp, vis = Camera:WorldToViewportPoint(_part.Position)
                if vis and sp.Z > 0 then
                    _lockC.Position = Vector2.new(sp.X, sp.Y)
                    on = true
                end
            end
            _lockC.Visible = on
        end
        if _dbgT then
            if wantDbg then
                _dbgT.Text = diagText(); _dbgT.Visible = true
            else
                _dbgT.Visible = false
            end
        end
    end

    -- ── the aim path ───────────────────────────────────────────────────────
    -- Resolved once, reported in the debug line so a dead path is visible rather than mysterious.
    local function resolvePath()
        if _mouseMove then return "mouse" end
        if Config.AimbotDirectCamera then
            if not _ctlTried then
                _ctlTried = true
                -- loadGameModule blocks for up to 15s, so it can never run inline in a renderstep.
                task.spawn(function()
                    local ok, m = pcall(loadGameModule, lp.PlayerScripts, { "Controllers", "CameraController" })
                    -- Only the LIVE singleton is usable. Never call _new(): a second camera
                    -- controller would be a real anomaly, not a workaround.
                    if ok and type(m) == "table" and typeof(m.Rotation) == "Vector2"
                       and type(m.ApplyRotationDelta) == "function" then
                        _ctl = m
                        _gx, _gy   = SEED_DX, SEED_DY
                        _sdx, _sdy = SEED_DX, SEED_DY
                        _nx, _ny   = 0, 0
                    end
                end)
            end
            if _ctl then return "direct" end
        end
        return "none"
    end

    -- Quantize to whole units (mousemoverel truncates) while carrying the remainder, so slow
    -- tracking at high smoothness is never silently rounded away to nothing.
    local function quant(v, frac)
        local w = v + frac
        local n = (w >= 0) and math.floor(w) or math.ceil(w)
        return n, w - n
    end

    local function emit(ux, uy)
        if _path == "mouse" then
            pcall(_mouseMove, ux, uy)
        elseif _path == "direct" and _ctl then
            -- ApplyRotationDelta takes Vector2(pitch, yaw) -- component order per the dump.
            pcall(function() _ctl:ApplyRotationDelta(Vector2.new(uy, ux)) end)
        end
    end

    -- One calibration sample per axis per frame: what the camera actually did, divided by what we
    -- asked for last frame. Band-rejected so the player's own mouse can't poison it; snapped
    -- outright on a sign flip so an inverted-axis setting is corrected in a single frame.
    local function calibrate(obs, sent, gain, n, seed)
        if math.abs(sent) < CAL_MIN then return gain, n end
        local s  = obs / sent
        local a  = math.abs(s)
        local lo = math.abs(seed) * BAND_LO
        local hi = math.abs(seed) * BAND_HI
        if a < lo or a > hi then return gain, n end
        if n < CAL_FAST_N or (s < 0) ~= (gain < 0) then return s, n + 1 end
        -- Once converged, refuse samples wildly inconsistent with the running estimate: those are
        -- frames where the player's own mouse (or a mis-timed observation) dominated ours.
        local r = math.abs(s / gain)
        if r < 0.34 or r > 3 then return gain, n end
        return gain + (s - gain) * 0.05, n + 1
    end

    local function clearTarget()
        _tgt, _part = nil, nil
        _prevTgt    = nil
        _notified   = nil   -- so a re-acquire re-fires the target dot
        _haveTgt    = false
        _lastPartRef = nil
        _ffy, _ffp  = 0, 0
        _errDeg     = 0
        _flips, _errEma, _lastSign, _drive = 0, 0, nil, 0
        State.AimbotTarget = nil
        State.AimbotPart   = nil
    end

    local function step(dt)
        dt = math.clamp(dt or (1 / 60), 1 / 1000, 0.1)

        local cf     = Camera.CFrame
        local look   = cf.LookVector
        local curYaw, curPit = yawOf(look), pitchOf(look)

        -- CALIBRATION must run before anything can return, and always against LAST frame's send.
        if _haveCam and not _calOff then
            _gx, _nx = calibrate(wrapPi(curYaw - _lyaw), _sx, _gx, _nx, _sdx)
            _gy, _ny = calibrate(curPit - _lpit,         _sy, _gy, _ny, _sdy)
        end
        _lyaw, _lpit, _haveCam = curYaw, curPit, true

        -- ADS changes the FOV multiplier inside the game's own sensitivity chain, so the gain
        -- genuinely changes. Drop back to fast adaptation instead of dragging the old value.
        local fov = Camera.FieldOfView
        if math.abs(fov - _lastFOV) > 0.5 then
            _lastFOV = fov
            _nx, _ny = 0, 0
        end

        -- _sx/_sy have now been consumed by the gain estimator above, which is their ONLY reader
        -- (see note 2 in the header -- the control law must NOT subtract them). Clearing here
        -- means every early return below correctly reports "nothing was sent this frame".
        _sx, _sy = 0, 0
        updateDraw()

        if not Config.Aimbot then
            State.AimbotKeyHeld = false
            clearTarget()
            return
        end
        -- Rage owns the camera and the trigger while it is on.
        if State.RageFiring then clearTarget(); return end

        local keyDown = aimbotKeyDown()
        State.AimbotKeyHeld = keyDown
        if not keyDown then
            -- State.AimbotLastTarget is deliberately NOT cleared here: it is the STICKY_MEM
            -- memory, so re-pressing the aim key within 2s prefers the enemy you were already
            -- on. The old build nil'd it on every release, which made that memory dead.
            clearTarget()
            return
        end

        _path = resolvePath()
        if _path == "none" then clearTarget(); return end

        -- ── acquire ────────────────────────────────────────────────────────
        local fovR    = math.clamp(Config.AimbotFOVDeg or 20, 0.1, 180) * D2R
        local retainR = math.min(fovR * RETAIN_MUL, math.pi)
        local sticky  = _tgt
        if not sticky then
            local last = State.AimbotLastTarget
            if last and (tick() - (State.AimbotLastTargetTime or 0)) <= STICKY_MEM then sticky = last end
        end

        local tgt, part = acquire(cf, fovR, retainR, sticky)
        if not tgt or not part then clearTarget(); return end
        if (Config.AimbotTargetPart or "Best") == "Best" then
            part = resolveBest(tgt.Character, part) or part
        end

        if tgt ~= _prevTgt then
            _acquireAt = tick()
            _ramp      = 0
            _haveTgt   = false
            _ffy, _ffp = 0, 0
            _prevTgt   = tgt
        end
        _tgt, _part = tgt, part
        State.AimbotTarget         = tgt
        State.AimbotPart           = part
        State.AimbotLastTarget     = tgt
        State.AimbotLastTargetTime = tick()
        if _notified ~= tgt then
            _notified = tgt
            pcall(Visuals.notifyTarget, tgt)
        end

        -- ── error, in angles ───────────────────────────────────────────────
        local aimPos = part.Position + calculateLead(tgt.Character, cf.Position, Config.AimbotPrediction)
        local d = aimPos - cf.Position
        if d.Magnitude < 1e-3 then return end
        local u      = d.Unit
        local tYaw   = yawOf(u)
        local tPit   = math.clamp(pitchOf(u), -PITCH_LIMIT, PITCH_LIMIT)
        local errYaw = wrapPi(tYaw - curYaw)
        local errPit = tPit - curPit
        _errDeg = math.sqrt(errYaw * errYaw + errPit * errPit) * R2D

        -- FEED-FORWARD: the rate at which the REQUIRED aim angle is changing. It folds in both
        -- the target's motion and our own strafing, which is exactly the quantity a proportional
        -- controller lags by (err = rate * tau). Without this the crosshair trails a strafing
        -- enemy forever and raising smoothness only makes it worse.
        -- Skip the differentiation on the frame the aim PART changes (Best mode flipping head ->
        -- torso when LOS breaks is a step in the aim point, not target motion), and clamp the
        -- rate so a void-flicker cannot inject a huge phantom velocity into the EMA.
        if _haveTgt and part == _lastPartRef then
            local k = math.clamp(dt / FF_TAU, 0, 1)
            local ry = math.clamp(wrapPi(tYaw - _lty) / dt, -FF_MAX, FF_MAX)
            local rp = math.clamp((tPit - _ltp) / dt,       -FF_MAX, FF_MAX)
            _ffy = _ffy + (ry - _ffy) * k
            _ffp = _ffp + (rp - _ffp) * k
        end
        _lty, _ltp, _haveTgt, _lastPartRef = tYaw, tPit, true, part

        -- Reaction delay applies per NEWLY ACQUIRED target, not per frame.
        if (Config.AimbotReactionMs or 0) > 0
           and (tick() - _acquireAt) * 1000 < Config.AimbotReactionMs then return end

        -- ── the control law ────────────────────────────────────────────────
        -- The RAW error, deliberately. See note 2 in the header: the previous send has already
        -- landed and is already inside errYaw/errPit, so discounting it double-counts and the
        -- loop diverges.
        if (Config.AimbotDeadzoneDeg or 0) > 0 then
            local m = math.sqrt(errYaw * errYaw + errPit * errPit)
            if m < Config.AimbotDeadzoneDeg * D2R then return end
        end

        -- Read before the guards: the runaway window below is scaled by the requested smoothness.
        local s = math.clamp(Config.AimbotSmoothness or 0, 0, 100)

        -- OSCILLATION GUARD -- the safety net that the shipped-and-diverged version did not have.
        -- Stability rests on two things being true: the input lag is one frame, and the measured
        -- gain is right. Both are load-bearing and neither is measured on THIS machine. If the
        -- gain underestimates by >2x, or the lag is ever 2 frames, the executed move overshoots
        -- the command and the loop rings. Rather than trust the analysis, DETECT it: rapid
        -- sign-flipping of the error while the error is large is an unambiguous signature of a
        -- loop fighting itself. Legitimate tracking keeps the error mostly one-sided, and a
        -- correctly settled hard lock sits well under the OSC_ERR floor (its residual is bounded
        -- by mouse quantization, ~0.25 deg), so neither trips this.
        local aErr = math.sqrt(errYaw * errYaw + errPit * errPit)
        _errEma = _errEma + (aErr - _errEma) * math.clamp(dt / 0.15, 0, 1)
        _drive  = _drive + dt
        local sPos = (errYaw >= 0)
        if _lastSign ~= nil and sPos ~= _lastSign then _flips = _flips + 1 end
        _lastSign = sPos
        _flips = _flips * math.exp(-dt / 0.25)      -- ~quarter-second memory
        if _flips >= 4 and _errEma > OSC_ERR then
            _auth  = math.max(0.15, _auth * 0.5)    -- halve authority; converges for any lag <= 3
            _flips = 0
        else
            _auth = math.min(1, _auth + dt * 0.3)   -- recover slowly, so it cannot pump
        end

        -- RUNAWAY TRIPWIRE. The guard above only catches failure that LOOKS like ringing. A gain
        -- estimate corrupted the other way -- wrong sign, or correlated against the wrong frame if
        -- the input lag is ever 2 -- drives the aim away monotonically, which never flips sign and
        -- so slips straight past it. This catches failure by its OUTCOME instead of its shape: if
        -- we have been actively driving at a target for half a second and the smoothed error is
        -- still enormous, the loop is not working, whatever the mechanism. At hard lock that gap
        -- would close in a single frame, so there is no legitimate way to sit here.
        -- Response: cut authority, and PIN THE GAIN BACK TO THE ANALYTIC SEED, since the estimator
        -- is the only adaptive part and therefore the likeliest culprit. If it happens twice, stop
        -- estimating for the rest of the session and run purely on the dump's constants, which are
        -- exact at default settings and within the band for any plausible sensitivity. Reduced
        -- authority plus a known-good gain converges for any input lag up to 3 frames.
        -- The window scales with the configured smoothness, because "still far off after N
        -- seconds" only means failure relative to how fast the user ASKED it to converge: a
        -- hard lock closes any gap in one frame (0.15s is already 9 frames of grace), while at
        -- smoothness 100 a legitimate 90-degree flick genuinely takes ~3 tau to arrive.
        if _errEma > RUNAWAY_ERR and _drive > (0.15 + (s / 100) * MAX_TAU * 3) then
            _auth    = math.max(0.08, _auth * 0.5)
            _gx, _gy = _sdx, _sdy
            _nx, _ny = 0, 0
            _drive   = 0
            _trips   = _trips + 1
            if _trips >= 2 then _calOff = true end
        end

        local alpha = 1
        if s > 0 then alpha = 1 - math.exp(-dt / (s / 100 * MAX_TAU)) end
        alpha = alpha * _auth

        local cy = errYaw * alpha
        local cp = errPit * alpha

        -- Overshoot-and-settle: a transient over-correction on the approach, decaying to 0.
        local os = Config.AimbotOvershoot or 0
        if os > 0 then
            _ramp = math.min(1, _ramp + dt / RAMP_TIME)
            local k = 1 + math.sin(_ramp * math.pi) * os
            cy, cp = cy * k, cp * k
        end

        local ff = (Config.AimbotTrackAssist or 0) / 100
        if ff > 0 then
            cy = cy + _ffy * dt * ff
            cp = cp + _ffp * dt * ff
        end

        local nz = Config.AimbotNoiseDeg or 0
        if nz > 0 then
            local n = nz * D2R * dt
            cy = cy + (math.random() - 0.5) * 2 * n
            cp = cp + (math.random() - 0.5) * 2 * n
        end

        -- THE undetection knob: a hard cap on angular rate, in a unit that means the same thing
        -- on every machine. Our look angle is replicated on change, so this is the shape of the
        -- only server-visible signal the aimbot produces. ~1080 deg/s is the human ceiling.
        local cap = Config.AimbotMaxSpeed or 0
        if cap > 0 then
            local m   = math.sqrt(cy * cy + cp * cp)
            local lim = cap * D2R * dt
            if m > lim then local k = lim / m; cy, cp = cy * k, cp * k end
        end

        -- Never command past the game's own pitch clamp; it would silently eat the command.
        cp = math.clamp(curPit + cp, -PITCH_LIMIT, PITCH_LIMIT) - curPit

        -- ── emit ───────────────────────────────────────────────────────────
        if _gx == 0 or _gy == 0 then return end
        local ux, uy = cy / _gx, cp / _gy
        local um = math.max(math.abs(ux), math.abs(uy))
        if um > UNIT_MAX then local k = UNIT_MAX / um; ux, uy = ux * k, uy * k end
        if _path == "mouse" then
            ux, _fx = quant(ux, _fx)
            uy, _fy = quant(uy, _fy)
        else
            _fx, _fy = 0, 0
        end
        if ux == 0 and uy == 0 then return end
        emit(ux, uy)
        _sx, _sy = ux, uy
    end

    -- ── public API ─────────────────────────────────────────────────────────
    -- Bound ONLY while enabled: literally zero per-frame cost when off. Camera+1 is load-bearing
    -- twice over -- it reads the camera after the game's controller (priority 200) has produced
    -- it, and 09b_trigger deliberately binds at +2 so it evaluates AFTER this frame's aim.
    function Aimbot.enable()
        Config.Aimbot = true
        if _bound then return end
        RunService:BindToRenderStep("LuaHook_Aimbot", Enum.RenderPriority.Camera.Value + 1, function(dt)
            pcall(step, dt)   -- a destroyed part mid-frame must never kill the bind silently
        end)
        _bound = true
    end

    function Aimbot.disable()
        Config.Aimbot = false
        State.AimbotKeyHeld = false
        clearTarget()
        _sx, _sy, _fx, _fy = 0, 0, 0, 0
        _haveCam, _ramp, _notified = false, 0, nil
        _auth = 0.6   -- re-arm the safe ramp on the next engage
        if _bound then
            pcall(function() RunService:UnbindFromRenderStep("LuaHook_Aimbot") end)
            _bound = false
        end
        if _fovC  then _fovC.Visible  = false end
        if _lockC then _lockC.Visible = false end
        if _dbgT  then _dbgT.Visible  = false end
    end

    function Aimbot.init()
        if Config.Aimbot then Aimbot.enable() end
    end

    function Aimbot.unload()
        Aimbot.disable()
        -- The shared velocity tracker (05_utils) is torn down here and nowhere else.
        if shared._LH_velConn then
            pcall(function() shared._LH_velConn:Disconnect() end)
            shared._LH_velConn = nil
        end
        if _fovC  then pcall(function() _fovC:Remove()  end); _fovC  = nil end
        if _lockC then pcall(function() _lockC:Remove() end); _lockC = nil end
        if _dbgT  then pcall(function() _dbgT:Remove()  end); _dbgT  = nil end
    end

    function Aimbot.hasMouseMove() return _mouseMove ~= nil end
    function Aimbot._diag() return diagText() end

end)()

-- ── TRIGGER BOT ─────────────────────────────────────────────────────────────
-- Fires when the crosshair is genuinely ON an enemy. It NEVER emits a shot packet: it asks the game
-- to shoot (lf:Input on an identity-2 thread) and lets the game apply its own legality gates and
-- build + send the shot. That distinction is load-bearing — see the header of polarFire in
-- 07b_rage_engine.lua. Target detection is one camera raycast, so the ray itself is the wall check:
-- if anything is between us and them we hit the wall and do nothing, which is exactly the semantics
-- a trigger wants (no separate LOS pass, no stale visibility cache).
local Trigger = {}
do
    local _bound    = false
    local _lastFire = 0
    local _onTgtAt  = 0      -- tick() the crosshair first landed on the CURRENT character
    local _lastChar = nil

    -- Hoisted: one RaycastParams reused every frame, filter refreshed only on respawn.
    local trigParams = RaycastParams.new()
    trigParams.FilterType = Enum.RaycastFilterType.Exclude
    local _filterChar = nil

    local function isHeadHit(part)
        if not part then return false end
        local n = part.Name
        for _, h in ipairs(HEAD_PARTS) do
            if n == h then return true end
        end
        return false
    end

    -- Ask the game to fire. Identity 2 mirrors the rage engine and OldLuahook: the game's own
    -- Gun.StartShooting runs, decides, and sends. We contribute nothing to the wire.
    local function askToShoot()
        local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
        if not lf then return end
        task.spawn(function()
            if setthreadidentity then setthreadidentity(2) elseif setidentity then setidentity(2) end
            pcall(function() lf:Input("StartShooting") end)
            if setthreadidentity then setthreadidentity(8) elseif setidentity then setidentity(8) end
        end)
    end

    -- Whoever is directly under the crosshair, plus the part we hit. nil when the ray hits geometry,
    -- nothing, ourselves, or a non-player model.
    local function underCrosshair()
        local c = lp.Character
        if c ~= _filterChar then
            trigParams.FilterDescendantsInstances = { c }
            _filterChar = c
        end
        local cf   = Camera.CFrame
        local dist = math.clamp(Config.TriggerMaxDist or 400, 1, 400)   -- server MAX_RAYCAST is 400
        local res  = Workspace:Raycast(cf.Position, cf.LookVector * dist, trigParams)
        if not res or not res.Instance then return nil end
        local model = res.Instance:FindFirstAncestorOfClass("Model")
        if not model then return nil end
        local pl = Players:GetPlayerFromCharacter(model)
        if not pl or pl == lp then return nil end
        return pl, res.Instance
    end

    local function step()
        if not Config.Trigger then return end
        -- Rage owns the trigger while it is on: it already asks every frame, and a second driver
        -- would double-ask and fight its target selection.
        if Config.Rage then
            _lastChar = nil
            return
        end
        if not isInputActive(Config.TriggerKey) then
            _lastChar = nil
            return
        end

        local pl, hit = underCrosshair()
        if not pl then
            _lastChar = nil
            return
        end
        if not isValidTarget(pl, false) then
            _lastChar = nil
            return
        end
        if Config.TriggerHeadOnly and not isHeadHit(hit) then
            _lastChar = nil
            return
        end

        -- Reaction delay is per NEW target, not per shot, so holding the crosshair on one enemy
        -- keeps firing instead of re-paying the delay every bullet.
        local now = tick()
        if pl.Character ~= _lastChar then
            _lastChar = pl.Character
            _onTgtAt  = now
        end
        if (now - _onTgtAt) * 1000 < (Config.TriggerDelayMs or 0) then return end
        if (now - _lastFire) * 1000 < (Config.TriggerRefireMs or 0) then return end

        _lastFire = now
        askToShoot()
    end

    -- Camera+2 so we evaluate AFTER the aimbot (Camera+1) has moved the crosshair this frame —
    -- otherwise the trigger reads last frame's aim and lags a shot behind on a fast flick.
    -- Bound only while enabled: literally zero per-frame cost when off.
    function Trigger.enable()
        Config.Trigger = true
        if _bound then return end
        RunService:BindToRenderStep("LuaHook_Trigger", Enum.RenderPriority.Camera.Value + 2, function()
            pcall(step)   -- un-pcall'd dispatch: one nil-index here would kill the bind silently
        end)
        _bound = true
    end

    function Trigger.disable()
        Config.Trigger = false
        _lastChar = nil
        _lastFire = 0
        _onTgtAt  = 0
        if not _bound then return end
        pcall(function() RunService:UnbindFromRenderStep("LuaHook_Trigger") end)
        _bound = false
    end

    function Trigger.init()
        if Config.Trigger then Trigger.enable() end
    end

    function Trigger.unload()
        Trigger.disable()
    end
end

-- ── ESP ────────────────────────────────────────────────────────────────────
local ESP = {}
do
    local hasDrawing  = screenDraw ~= nil
    local _renderConn = nil
    local _espFrame   = 0
    local _lastRenderT = 0
    local _dcLastT    = 0                                 -- declutter throttle timestamp (E2.4)
    local _bboxCache  = {}
    local _bboxFrameN = {}
    local _pts = {}; for _i = 1, 8 do _pts[_i] = {} end   -- reused bracket buffer (no per-frame alloc)
    local _ctx = {}                                       -- reused per-frame shared context (no per-player alloc)
    local _renderArr = {}                                 -- reused nearest-N cap buffer
    local _dcArr     = {}                                 -- reused declutter overlap buffer
    local _radarO    = { drawings = {} }                  -- module-local radar drawing pool
    local _module    = { drawings = {} }                  -- module-local HUD drawing pool (threat count)

    local BLACK = Color3.new(0, 0, 0)
    local WHITE = Color3.new(1, 1, 1)   -- gradient-box base (UIGradient shows true against white)
    local HPBG  = Color3.fromRGB(11, 15, 22)   -- SIGNAL v3 · HP track token (#0B0F16, esp-v3 §04)
    local cam   = Camera

    -- Drawing font name -> id
    local FONTS = { UI = 0, System = 1, Plex = 2, Monospace = 3, GothamBold = 4, SourceSansBold = 5 }

    -- Custom health gradient or 5-stop ramp
    local function resolveHealthColor(frac, dyn)
        if dyn then return dyn end
        if Config.ESPHealthGradientCustom and Config.ESPHealthGradientHigh and Config.ESPHealthGradientLow then
            return Config.ESPHealthGradientLow:Lerp(Config.ESPHealthGradientHigh, math.clamp(frac or 1, 0, 1))
        end
        if Config.ESPHealthGradient and hpRamp then
            return hpRamp(frac)
        end
        return Config.ESPHealthColor or Color3.fromRGB(61, 224, 122)
    end

    -- SIGNAL v2 · animated gradient outline color (rank 1). Triangle-wave ping-pong A<->B so the
    -- drift reads as one continuous sweep; offset gives each corner a distinct phase. nil => caller falls back.
    local function boxGradColor(now, offset)
        local a, b = Config.ESPBoxGradientA, Config.ESPBoxGradientB
        if not a or not b then return nil end
        local spd = Config.ESPBoxGradientSpeed or 0.12
        local t = ((now or 0) * spd + (offset or 0)) % 1
        if t > 0.5 then t = 1 - t end
        return a:Lerp(b, math.clamp(t * 2, 0, 1))
    end

    -- SIGNAL v3 · full-box gradient outline: a real UIStroke UIGradient (esp-v3 §02) whose Rotation the
    -- caller spins per frame. The A->B->A ColorSequence is cached (rebuilt only when the config colors
    -- change) so no ColorSequence is allocated per frame — the gradient write skip-writes after frame 1.
    local _boxGradSeq, _boxSeqA, _boxSeqB = nil, nil, nil
    local function boxGradSeq()
        local a, b = Config.ESPBoxGradientA, Config.ESPBoxGradientB
        if not a or not b then return nil end
        if _boxGradSeq and a == _boxSeqA and b == _boxSeqB then return _boxGradSeq end
        _boxSeqA, _boxSeqB = a, b
        _boxGradSeq = ColorSequence.new({
            ColorSequenceKeypoint.new(0, a),
            ColorSequenceKeypoint.new(0.5, b),
            ColorSequenceKeypoint.new(1, a),
        })
        return _boxGradSeq
    end

    -- SIGNAL v2 · target-lock hysteresis (rank 4). A challenger must be >=10% closer AND held 0.5s
    -- before the lock switches; identical target keeps the lock. Prevents flicker between equidistant players.
    local _lock = { obj = nil, cand = nil, candT = 0 }
    local function resolveLock(bestO, bestD, lockO, lockD, now)
        local lk = _lock
        if bestO == nil then lk.obj = nil; lk.cand = nil; return nil end
        local prev = lk.obj
        if lk.obj == nil or lockO == nil then
            lk.obj = bestO; lk.cand = nil
        elseif bestO == lk.obj then
            lk.cand = nil
        elseif bestD <= (lockD or math.huge) * 0.9 then
            if lk.cand == bestO then
                if (now - (lk.candT or now)) >= 0.5 then lk.obj = bestO; lk.cand = nil end
            else
                lk.cand = bestO; lk.candT = now
            end
        else
            lk.cand = nil
        end
        if lk.obj and lk.obj ~= prev then lk.obj._primT = now end
        return lk.obj
    end

    -- Rig-aware bone maps (name pairs). R15 = default; R6 detected at build.
    local SKEL_R15 = {
        {"Head","UpperTorso"},{"UpperTorso","LowerTorso"},
        {"UpperTorso","LeftUpperArm"},{"LeftUpperArm","LeftLowerArm"},{"LeftLowerArm","LeftHand"},
        {"UpperTorso","RightUpperArm"},{"RightUpperArm","RightLowerArm"},{"RightLowerArm","RightHand"},
        {"LowerTorso","LeftUpperLeg"},{"LeftUpperLeg","LeftLowerLeg"},{"LeftLowerLeg","LeftFoot"},
        {"LowerTorso","RightUpperLeg"},{"RightUpperLeg","RightLowerLeg"},{"RightLowerLeg","RightFoot"},
    }
    local SKEL_R6 = {
        {"Head","Torso"},
        {"Torso","Left Arm"},{"Torso","Right Arm"},
        {"Torso","Left Leg"},{"Torso","Right Leg"},
    }

    -- 3D Bounding Box Wireframe Edges (pairs of vertex indices 1..8)
    local BOX_3D_EDGES = {
        {1,2}, {2,4}, {4,3}, {3,1}, -- Top face
        {5,6}, {6,8}, {8,7}, {7,5}, -- Bottom face
        {1,5}, {2,6}, {3,7}, {4,8}  -- Vertical pillars
    }

    -- Budgeted primitive creation per frame to prevent allocation spikes
    local _createBudget = 0
    local CREATE_BUDGET_PER_FRAME = 32

    local function newDraw(t)
        if not hasDrawing then return nil end
        local ok, d = pcall(screenDraw, t)
        if not ok then return nil end
        d.Visible = false; return d
    end

    -- Lazy single-primitive: create on first use, cache after (false = create failed).
    local function nd(o, key, dtype)
        local d = o[key]
        if d == nil then
            if _createBudget <= 0 then return nil end   -- defer to a later frame; leave uncached so it retries
            _createBudget = _createBudget - 1
            d = newDraw(dtype) or false
            o[key] = d
            if d then o.drawings[#o.drawings + 1] = d end
        end
        return d or nil
    end

    -- Lazy array of primitives grown to n on demand.
    local function ndArr(o, key, dtype, n)
        local arr = o[key]
        if not arr then arr = {}; o[key] = arr end
        for i = #arr + 1, n do
            if _createBudget <= 0 then break end        -- defer remaining elements to a later frame
            local d = newDraw(dtype)
            if not d then break end
            _createBudget = _createBudget - 1
            arr[i] = d
            o.drawings[#o.drawings + 1] = d
        end
        return arr
    end

    -- Square setter (filled or outlined).
    local function sq(d, x, y, w, h, filled, color, transp, thick)
        d.Filled = filled
        if not filled then d.Thickness = thick or 1 end
        d.Position = Vector2.new(x, y)
        d.Size     = Vector2.new(w, h)
        d.Color    = color
        d.Transparency = transp
        d.Visible  = true
    end

    local function ensureCham(o, char)
        local hl = o.cham
        if hl == nil then
            hl = Instance.new("Highlight")
            hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            hl.Enabled   = false
            hl.Parent    = char
            o.cham = hl
        elseif hl and hl.Parent ~= char then
            pcall(function() hl.Parent = char end)
        end
        return o.cham
    end

    local function cleanESP(p)
        local o = State.ESPObjects[p]; if not o then return end
        for _, d in ipairs(o.drawings or {}) do
            pcall(function() if d.Remove then d:Remove() end end)
        end
        if o.cham and o.cham.Parent then pcall(function() o.cham:Destroy() end) end
        _bboxCache[p]  = nil
        _bboxFrameN[p] = nil
        State.ESPObjects[p] = nil
    end

    local function buildESP(player)
        if player == lp then return end
        cleanESP(player)
        local char = player.Character; if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart"); if not root then return end

        local hum  = char:FindFirstChildOfClass("Humanoid")
        local isR6 = (hum and hum.RigType == Enum.HumanoidRigType.R6) or (char:FindFirstChild("Torso") ~= nil)
        local rig  = isR6 and SKEL_R6 or SKEL_R15
        local bones = {}
        for i, pair in ipairs(rig) do
            bones[i] = { a = char:FindFirstChild(pair[1]), b = char:FindFirstChild(pair[2]) }
        end

        local o = { drawings = {}, root = root, rig = rig, bones = bones, _fadeT = tick() }
        State.ESPObjects[player] = o
    end

    -- Robust Bounding Box Projection with strict range and scale clamping (resolves 1000m+ distortion bug)
    local function bbox(char, player)
        local frame = _bboxFrameN[player] or -999
        if (_espFrame - frame) < 1 then
            local c = _bboxCache[player]
            if c then return c[1], c[2], c[3], c[4] end
            return nil
        end
        local minX, minY, maxX, maxY
        local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso")
            or char:FindFirstChild("Torso")
        local head = char:FindFirstChild("Head")
        if not root or not root.Parent then
            _bboxFrameN[player] = _espFrame; _bboxCache[player] = nil; return nil
        end

        local rootPos = root.Position
        local headPos = head and head.Position or (rootPos + Vector3.new(0, 1.5, 0))

        if Config.ESPBoxMode == "Dynamic" then
            local ok, cf, sz = pcall(function() return char:GetBoundingBox() end)
            if ok and cf and sz then
                local anyPt = false
                minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
                local hx, hy, hz = sz.X * 0.5, sz.Y * 0.5, sz.Z * 0.5
                for x = -1, 1, 2 do for y = -1, 1, 2 do for z = -1, 1, 2 do
                    local pt = (cf * Vector3.new(hx * x, hy * y, hz * z))
                    local sp = cam:WorldToViewportPoint(pt)
                    if sp.Z > 0 then
                        anyPt = true
                        if sp.X < minX then minX = sp.X end
                        if sp.Y < minY then minY = sp.Y end
                        if sp.X > maxX then maxX = sp.X end
                        if sp.Y > maxY then maxY = sp.Y end
                    end
                end end end
                if not anyPt then
                    _bboxFrameN[player] = _espFrame; _bboxCache[player] = nil; return nil
                end
            end
        end

        if not minX or minX >= maxX or minY >= maxY then
            -- Stabilized humanoid projection (aspect-ratio preserved across all distances)
            local topPos = headPos + Vector3.new(0, 0.85, 0)
            local botPos = rootPos - Vector3.new(0, 2.9, 0)
            local topSp, v1 = cam:WorldToViewportPoint(topPos)
            local botSp, v2 = cam:WorldToViewportPoint(botPos)

            if not (v1 or v2) or (topSp.Z <= 0 and botSp.Z <= 0) then
                _bboxFrameN[player] = _espFrame; _bboxCache[player] = nil; return nil
            end

            local h = math.abs(topSp.Y - botSp.Y)
            -- Distance-invariant aspect ratio 0.54 (standard Roblox humanoid ratio)
            local w = h * 0.54
            local cx = (topSp.X + botSp.X) * 0.5

            minX = cx - w * 0.5
            maxX = cx + w * 0.5
            minY = math.min(topSp.Y, botSp.Y)
            maxY = math.max(topSp.Y, botSp.Y)
        end

        local bw = maxX - minX
        local bh = maxY - minY

        -- SANITY & DISTANCE CLAMPING: Cull degenerate boxes (< 3px) or crazy offscreen sizes (> 2500px)
        if bw < 2 or bh < 3 or bw > 2500 or bh > 3500 then
            _bboxFrameN[player] = _espFrame; _bboxCache[player] = nil; return nil
        end

        _bboxFrameN[player] = _espFrame
        _bboxCache[player] = { minX, minY, maxX, maxY }
        return minX, minY, maxX, maxY
    end

    local function hideDrawings(o)
        for _, d in ipairs(o.drawings) do d.Visible = false end
    end

    local function hide2D(o)
        for _, d in ipairs(o.drawings) do
            if d ~= o.arrow and d ~= o.arrowOutline and d ~= o.arrowDist then d.Visible = false end
        end
    end

    local function hideAll(o, force)
        if o._allHidden and not force then return end
        o._allHidden = true
        hideDrawings(o)
        if o.cham then o.cham.Enabled = false end
    end

    function ESP.rebuildAll()
        for p in pairs(State.ESPObjects) do cleanESP(p) end
        if not Config.ESP then return end
        for _, p in ipairs(getSafePlayers()) do
            if p ~= lp and p.Character then buildESP(p) end
        end
    end

    -- Weapon name with a small TTL cache
    local function espWeapon(o, player)
        local now = tick()
        if not o._wepT or (now - o._wepT) > 0.5 then
            o._wep  = getWeaponName(player)
            o._wepT = now
        end
        return o._wep or "?"
    end

    -- Per-player render body
    local function renderPlayer(player, o)
        local ctx  = _ctx
        local char = player.Character
        if not char or not o.root or not o.root.Parent then cleanESP(player); return end
        if not o.root:IsA("BasePart") then cleanESP(player); return end
        local rootPos = o.root.Position
        if not rootPos then cleanESP(player); return end

        local vp     = ctx.vp
        local myRoot = ctx.myRoot
        local dist   = o._dist
        if not dist then
            dist = (myRoot and myRoot.Position and rootPos)
                and (myRoot.Position - rootPos).Magnitude or 0
        end
        local oor = dist > Config.ESPMaxDistance

        if (Config.ESPTeamCheck and isTeammate(player)) or (not isAlive(player)) then
            hideAll(o); return
        end

        local vis = o._vis or false
        if (Config.ESPColorMode == "Visibility" or Config.ESPRadar or Config.ESPChamsVisSplit or Config.ESPPeekAlert
                or (Config.ESPChams and Config.ESPChamsStyle == "Ghost"))
            and not oor and (_espFrame - (o._visFrame or -99)) >= 3 then
            pcall(function() o._vis = isVisible(rootPos) end)
            o._visFrame = _espFrame
            vis = o._vis or false
        end

        local dyn
        local cmode = Config.ESPColorMode
        if cmode == "Rainbow" then dyn = ctx.rb
        elseif cmode == "Visibility" then dyn = vis and Config.ColorVisible or Config.ColorEnemy
        elseif cmode == "Team" then dyn = isTeammate(player) and Config.ColorTeam or Config.ColorEnemy
        elseif cmode == "Distance" then
            dyn = Config.ESPDistNearColor:Lerp(Config.ESPDistFarColor,
                math.clamp(dist / math.max(Config.ESPMaxDistance, 1), 0, 1))
        end

        if oor or not ctx.hasDrawing then
            if o.cham then o.cham.Enabled = false end
            hideDrawings(o); o._allHidden = true
            return
        end

        if o._allHidden and Config.ESPFadeIn then o._fadeT = ctx.now end
        o._allHidden = false
        local fadeMul = 1
        if Config.ESPFadeIn and o._fadeT then
            fadeMul = math.clamp((ctx.now - o._fadeT) / 0.18, 0, 1)
        end

        local outline = ctx.outline
        local textOutline = ctx.textOutline
        if textOutline == nil then textOutline = true end
        local oAlpha  = ctx.outlineAlpha
        local tscale  = 1
        if Config.ESPTextScaling then
            tscale = math.clamp(1 - (dist / math.max(Config.ESPMaxDistance, 1)) * 0.5, 0.55, 1)
        end
        local tfloor = Config.ESPTextMinSize or 11
        local font = FONTS[Config.ESPFont] or 2

        local minX, minY, maxX, maxY = bbox(char, player)
        if minX then
            if Config.ESPSmoothing then
                local sb = o._sbox
                local ccx, ccy = (minX + maxX) * 0.5, (minY + maxY) * 0.5
                local chx, chy = (maxX - minX) * 0.5, (maxY - minY) * 0.5
                if not sb then
                    sb = { ccx, ccy, chx, chy }; o._sbox = sb
                else
                    local dcx = ccx - sb[1]
                    local dcy = ccy - sb[2]
                    if (dcx * dcx + dcy * dcy) > (150 * 150) then
                        sb[1] = ccx; sb[2] = ccy; sb[3] = chx; sb[4] = chy
                    else
                        local dt = ctx.dt or 0
                        local aC = 1 - math.exp(-22 * dt)   -- center half-life ~31ms
                        local aS = 1 - math.exp(-12 * dt)   -- size half-life ~58ms
                        sb[1] = sb[1] + (ccx - sb[1]) * aC
                        sb[2] = sb[2] + (ccy - sb[2]) * aC
                        sb[3] = sb[3] + (chx - sb[3]) * aS
                        sb[4] = sb[4] + (chy - sb[4]) * aS
                    end
                end
                minX, maxX = sb[1] - sb[3], sb[1] + sb[3]
                minY, maxY = sb[2] - sb[4], sb[2] + sb[4]
            end

            minX = math.floor(minX); minY = math.floor(minY)
            maxX = math.floor(maxX); maxY = math.floor(maxY)
            local w, h = maxX - minX, maxY - minY

            local minH = Config.ESPMinBoxHeight or 0
            if minH > 0 and h > 0 and h < minH then
                local cx = (minX + maxX) * 0.5
                local cy = (minY + maxY) * 0.5
                local fw = math.floor(minH * 0.54)
                minX = math.floor(cx - fw * 0.5)
                maxX = math.floor(cx + fw * 0.5)
                minY = math.floor(cy - minH * 0.5)
                maxY = math.floor(cy + minH * 0.5)
                w, h = maxX - minX, maxY - minY
            end

            local _prevHP = o._lastHP
            local _curHP, _curMH, _curFrac
            if Config.ESPHealth or Config.ESPHealthGhost or Config.ESPHealTick then
                pcall(function() _curHP, _curMH = getHealth(player) end)
                if _curHP ~= nil then
                    _curFrac = math.clamp((_curMH or 0) > 0 and _curHP / _curMH or 0, 0, 1)
                end
            end
            if Config.ESPHealthGhost and _prevHP and _curFrac and _curFrac < _prevHP - 0.005 then
                if not o._ghostT or (ctx.now - o._ghostT) >= 0.35 then
                    o._ghostFrac = _prevHP
                else
                    o._ghostFrac = math.max(o._ghostFrac or _prevHP, _prevHP)
                end
                o._ghostT = ctx.now
            end

            -- ── BOX RENDERING (3-Layer Razor Outline / Corner Brackets / 3D Box) ──
            if Config.ESPBox then
                local bc     = dyn or Config.ESPBoxColor
                local bAlpha = (1 - Config.ESPBoxTransparency) * fadeMul
                local thick  = Config.ESPBoxThickness or 1
                local cornerMul = 1
                if Config.ESPPrimaryEmphasis and o._primary then
                    thick = thick + 1; bAlpha = fadeMul
                    local pt = o._primT and math.clamp((ctx.now - o._primT) / 0.14, 0, 1) or 1
                    local e  = 1 - (1 - pt) * (1 - pt)
                    cornerMul = 1 + 0.3 * e
                end

                local grad = Config.ESPBoxGradient and boxGradColor(ctx.now, 0) ~= nil

                if Config.ESPBoxFill then
                    local bf = nd(o, "boxFill", "Square")
                    if bf then
                        sq(bf, minX, minY, w, h, true, dyn or Config.ESPBoxFillColor, 1 - Config.ESPBoxFillTransparency)
                        bf.Thickness = 0
                    end
                elseif o.boxFill then o.boxFill.Visible = false end

                local isCorners = Config.ESPBoxBrackets or (Config.ESPBoxStyle == "Corner Brackets")
                local is3D = (Config.ESPBoxStyle == "3D Box")

                if isCorners then
                    if o.box then o.box.Visible = false end
                    if o.boxOut then o.boxOut.Visible = false end
                    if o.boxIn then o.boxIn.Visible = false end
                    if o.box3D then for _, l in ipairs(o.box3D) do l.Visible = false end end
                    if o.box3DShadow then for _, l in ipairs(o.box3DShadow) do l.Visible = false end end

                    local cLen = math.clamp(math.floor(w * (Config.ESPCornerLength or 0.25) * cornerMul), 4, math.max(math.floor(w * 0.48), 6))
                    local lines = ndArr(o, "boxCorners", "Line", 8)
                    local shadows = outline and ndArr(o, "boxCornerShadows", "Line", 8) or o.boxCornerShadows

                    local pts = _pts
                    pts[1].f = Vector2.new(minX, minY); pts[1].t = Vector2.new(minX + cLen, minY)
                    pts[2].f = Vector2.new(minX, minY); pts[2].t = Vector2.new(minX, minY + cLen)
                    pts[3].f = Vector2.new(maxX, minY); pts[3].t = Vector2.new(maxX - cLen, minY)
                    pts[4].f = Vector2.new(maxX, minY); pts[4].t = Vector2.new(maxX, minY + cLen)
                    pts[5].f = Vector2.new(minX, maxY); pts[5].t = Vector2.new(minX + cLen, maxY)
                    pts[6].f = Vector2.new(minX, maxY); pts[6].t = Vector2.new(minX, maxY - cLen)
                    pts[7].f = Vector2.new(maxX, maxY); pts[7].t = Vector2.new(maxX - cLen, maxY)
                    pts[8].f = Vector2.new(maxX, maxY); pts[8].t = Vector2.new(maxX, maxY - cLen)

                    for i = 1, 8 do
                        local L = lines[i]
                        local p = pts[i]
                        local cCol = grad and boxGradColor(ctx.now, i * 0.12) or bc
                        if shadows then
                            local S = shadows[i]
                            if S then
                                if outline then
                                    S.From = p.f; S.To = p.t; S.Thickness = thick + 2; S.Color = BLACK
                                    S.Transparency = oAlpha; S.Visible = true
                                else S.Visible = false end
                            end
                        end
                        if L then
                            L.From = p.f; L.To = p.t; L.Thickness = thick; L.Color = cCol
                            L.Transparency = bAlpha; L.Visible = true
                        end
                    end
                elseif is3D then
                    if o.box then o.box.Visible = false end
                    if o.boxOut then o.boxOut.Visible = false end
                    if o.boxIn then o.boxIn.Visible = false end
                    if o.boxCorners then for _, l in ipairs(o.boxCorners) do l.Visible = false end end
                    if o.boxCornerShadows then for _, l in ipairs(o.boxCornerShadows) do l.Visible = false end end

                    local rootCF = o.root.CFrame
                    local sz = Vector3.new(3.6, 5.4, 3.6)
                    local hx, hy, hz = sz.X * 0.5, sz.Y * 0.5, sz.Z * 0.5
                    local v3d = {}
                    local allOn = true
                    local idx3 = 1
                    for y = 1, -1, -2 do for x = -1, 1, 2 do for z = -1, 1, 2 do
                        local pt = rootCF * Vector3.new(hx * x, hy * y, hz * z)
                        local sp, onS = cam:WorldToViewportPoint(pt)
                        if not onS or sp.Z <= 0 then allOn = false break end
                        v3d[idx3] = Vector2.new(sp.X, sp.Y)
                        idx3 = idx3 + 1
                    end end end

                    if allOn and #v3d == 8 then
                        local l3d = ndArr(o, "box3D", "Line", 12)
                        local s3d = outline and ndArr(o, "box3DShadow", "Line", 12) or o.box3DShadow
                        for i = 1, 12 do
                            local e = BOX_3D_EDGES[i]
                            local pA, pB = v3d[e[1]], v3d[e[2]]
                            if s3d and s3d[i] then
                                if outline then
                                    s3d[i].From = pA; s3d[i].To = pB; s3d[i].Thickness = thick + 2
                                    s3d[i].Color = BLACK; s3d[i].Transparency = oAlpha; s3d[i].Visible = true
                                else s3d[i].Visible = false end
                            end
                            if l3d[i] then
                                l3d[i].From = pA; l3d[i].To = pB; l3d[i].Thickness = thick
                                l3d[i].Color = bc; l3d[i].Transparency = bAlpha; l3d[i].Visible = true
                            end
                        end
                    else
                        if o.box3D then for _, l in ipairs(o.box3D) do l.Visible = false end end
                        if o.box3DShadow then for _, l in ipairs(o.box3DShadow) do l.Visible = false end end
                    end
                else
                    if o.boxCorners then for _, l in ipairs(o.boxCorners) do l.Visible = false end end
                    if o.boxCornerShadows then for _, l in ipairs(o.boxCornerShadows) do l.Visible = false end end
                    if o.box3D then for _, l in ipairs(o.box3D) do l.Visible = false end end
                    if o.box3DShadow then for _, l in ipairs(o.box3DShadow) do l.Visible = false end end

                    if outline then
                        local bOut = nd(o, "boxOut", "Square")
                        if bOut then
                            sq(bOut, minX - 1, minY - 1, w + 2, h + 2, false, BLACK, oAlpha, 1)
                        end
                    elseif o.boxOut then o.boxOut.Visible = false end

                    local b = nd(o, "box", "Square")
                    if b then
                        sq(b, minX, minY, w, h, false, bc, bAlpha, thick)
                        if Config.ESPBoxGradient and hasDrawing then
                            b.Gradient = boxGradSeq()
                            b.GradientRotation = ((ctx.now or 0) * (Config.ESPBoxGradientSpeed or 0.12) * 360) % 360
                        else
                            b.Gradient = nil
                        end
                    end

                    if outline and thick >= 1 and w > 4 and h > 4 then
                        local bIn = nd(o, "boxIn", "Square")
                        if bIn then
                            sq(bIn, minX + thick, minY + thick, w - thick * 2, h - thick * 2, false, BLACK, oAlpha, 1)
                        end
                    elseif o.boxIn then o.boxIn.Visible = false end
                end
            else
                if o.box then o.box.Visible = false end
                if o.boxOut then o.boxOut.Visible = false end
                if o.boxIn then o.boxIn.Visible = false end
                if o.boxFill then o.boxFill.Visible = false end
                if o.boxCorners then for _, l in ipairs(o.boxCorners) do l.Visible = false end end
                if o.boxCornerShadows then for _, l in ipairs(o.boxCornerShadows) do l.Visible = false end end
                if o.box3D then for _, l in ipairs(o.box3D) do l.Visible = false end end
                if o.box3DShadow then for _, l in ipairs(o.box3DShadow) do l.Visible = false end end
            end

            -- ── SKELETON ─────────────────────────────────────────────────────
            if Config.ESPSkeleton then
                local skelLines = ndArr(o, "skeleton", "Line", #o.bones)
                local skelShad  = outline and ndArr(o, "skeletonShadow", "Line", #o.bones) or o.skeletonShadow
                local sc        = dyn or Config.ESPSkeletonColor
                local sAlpha    = (1 - Config.ESPSkeletonTransparency) * fadeMul
                local thick     = Config.ESPSkeletonThickness or 1

                if (not o._skelPts) or (_espFrame - (o._skelFrame or -9)) >= 2 then
                    o._skelFrame = _espFrame
                    local pts = o._skelPts; if not pts then pts = {}; o._skelPts = pts end
                    for i, pair in ipairs(o.bones) do
                        local pa, pb = pair.a, pair.b
                        if pa and pb and pa.Parent and pb.Parent then
                            local s1, v1 = cam:WorldToViewportPoint(pa.Position)
                            local s2, v2 = cam:WorldToViewportPoint(pb.Position)
                            if v1 and v2 and s1.Z > 0 and s2.Z > 0 then
                                pts[i] = { f = Vector2.new(s1.X, s1.Y), t = Vector2.new(s2.X, s2.Y), ok = true }
                            else
                                pts[i] = { ok = false }
                            end
                        else
                            pts[i] = { ok = false }
                        end
                    end
                end

                local pts = o._skelPts
                for i = 1, #o.bones do
                    local L = skelLines[i]
                    local S = skelShad and skelShad[i]
                    if L then
                        local p = pts and pts[i]
                        if p and p.ok then
                            local f, t = p.f, p.t
                            if S then
                                if outline then
                                    S.From = f; S.To = t; S.Thickness = thick + 2; S.Color = BLACK
                                    S.Transparency = oAlpha; S.Visible = true
                                else S.Visible = false end
                            end
                            L.From = f; L.To = t; L.Color = sc; L.Thickness = thick; L.Transparency = sAlpha; L.Visible = true
                        else
                            L.Visible = false; if S then S.Visible = false end
                        end
                    end
                end
            else
                if o.skeleton then for _, l in ipairs(o.skeleton) do l.Visible = false end end
                if o.skeletonShadow then for _, l in ipairs(o.skeletonShadow) do l.Visible = false end end
            end

            -- ── HEALTH BAR (Vertical Docked / Horizontal with Lerp & Ghost Animation) ──
            local infoY = maxY + 3
            if Config.ESPHealth then
                local hp, mh = _curHP, _curMH
                if hp == nil then pcall(function() hp, mh = getHealth(player) end) end
                local pct = _curFrac or math.clamp((mh or 0) > 0 and hp / mh or 0, 0, 1)
                local fillPct = pct
                if Config.ESPHealthSmooth then
                    local s = o._sHP
                    if s == nil then s = pct
                    else s = s + (pct - s) * math.clamp((ctx.dt or 0) * 16, 0, 1) end
                    o._sHP = s; fillPct = s
                end

                local barCol = resolveHealthColor(fillPct, dyn)
                local hAlpha = (1 - Config.ESPHealthTransparency) * fadeMul
                local horizontal = Config.ESPHealthOrientation == "Horizontal"
                local fillTop

                if h > 2 then
                    if horizontal then
                        local barH = 3.5
                        local by   = maxY + 4
                        local bw   = w
                        if outline and nd(o, "hpOutline", "Square") then
                            sq(o.hpOutline, minX - 1, by - 1, bw + 2, barH + 2, false, BLACK, oAlpha, 1)
                        elseif o.hpOutline then o.hpOutline.Visible = false end
                        if nd(o, "hpBg", "Square") then sq(o.hpBg, minX, by, bw, barH, true, HPBG, 0.88) end
                        local fw = math.max(bw * fillPct, 1)
                        if nd(o, "hpFill", "Square") then sq(o.hpFill, minX, by, fw, barH, true, barCol, hAlpha) end
                        if Config.ESPHealthGhost then
                            local g = nd(o, "hpGhost", "Square")
                            if g and o._ghostT and o._ghostFrac and o._ghostFrac > fillPct and (ctx.now - o._ghostT) < 0.35 then
                                local gx = minX + bw * fillPct
                                local gw = math.max(bw * (o._ghostFrac - fillPct), 1)
                                local gt = 0.65 * (1 - math.clamp((ctx.now - o._ghostT) / 0.35, 0, 1))
                                sq(g, gx, by, gw, barH, true, WHITE, gt)
                            elseif g then g.Visible = false end
                        elseif o.hpGhost then o.hpGhost.Visible = false end
                        if o.hpTicks then for _, l in ipairs(o.hpTicks) do l.Visible = false end end
                        infoY   = by + barH + 3
                        fillTop = by
                    else
                        local barW = 3.5
                        local bx   = minX - 6
                        local by   = minY
                        local bh   = h
                        if outline and nd(o, "hpOutline", "Square") then
                            sq(o.hpOutline, bx - 1, by - 1, barW + 2, bh + 2, false, BLACK, oAlpha, 1)
                        elseif o.hpOutline then o.hpOutline.Visible = false end
                        if nd(o, "hpBg", "Square") then sq(o.hpBg, bx, by, barW, bh, true, HPBG, 0.88) end
                        local fh = math.max(bh * fillPct, 1)
                        fillTop  = by + (bh - fh)
                        if nd(o, "hpFill", "Square") then sq(o.hpFill, bx, fillTop, barW, fh, true, barCol, hAlpha) end

                        if Config.ESPHealthSegTicks then
                            local tk = ndArr(o, "hpTicks", "Line", 3)
                            for ti = 1, 3 do
                                local L = tk[ti]
                                if L then
                                    local ty = by + bh * (ti * 0.25)
                                    L.From = Vector2.new(bx, ty); L.To = Vector2.new(bx + barW, ty)
                                    L.Thickness = 1; L.Color = BLACK; L.Transparency = 0.6; L.Visible = true
                                end
                            end
                        elseif o.hpTicks then for _, l in ipairs(o.hpTicks) do l.Visible = false end end

                        if Config.ESPHealthGhost then
                            local g = nd(o, "hpGhost", "Square")
                            if g and o._ghostT and o._ghostFrac and o._ghostFrac > fillPct and (ctx.now - o._ghostT) < 0.35 then
                                local gTop = by + (bh - bh * o._ghostFrac)
                                local gh   = math.max(fillTop - gTop, 1)
                                local gt   = 0.65 * (1 - math.clamp((ctx.now - o._ghostT) / 0.35, 0, 1))
                                sq(g, bx, gTop, barW, gh, true, WHITE, gt)
                            elseif g then g.Visible = false end
                        elseif o.hpGhost then o.hpGhost.Visible = false end
                    end

                    local numMode = Config.ESPHealthNumberMode
                    local showNum = numMode == "Always" or (numMode == "OnDamage" and pct < 1)
                        or (Config.ESPHealthGhost and _curFrac ~= nil and _curFrac <= 0.25)
                    if showNum then
                        local ht = nd(o, "hpText", "Text")
                        if ht then
                            ht.Font = font
                            ht.Size = math.max(math.min(tfloor, Config.ESPHealthTextSize), math.floor(Config.ESPHealthTextSize * tscale))
                            ht.Outline = textOutline
                            ht.Color = barCol
                            ht.Transparency = hAlpha
                            ht.Text = tostring(math.floor(hp or 0))
                            if horizontal then
                                ht.Center = false
                                ht.Position = Vector2.new(math.floor(minX + w + 4), math.floor(fillTop - 1))
                            else
                                ht.Center = false; ht.RightAlign = true
                                ht.Position = Vector2.new(math.floor(minX - 8), math.floor(fillTop - ht.Size * 0.5))
                            end
                            ht.Visible = true
                        end
                    elseif o.hpText then o.hpText.Visible = false end
                else
                    if o.hpOutline then o.hpOutline.Visible = false end
                    if o.hpBg then o.hpBg.Visible = false end
                    if o.hpFill then o.hpFill.Visible = false end
                    if o.hpGhost then o.hpGhost.Visible = false end
                    if o.hpText then o.hpText.Visible = false end
                    if o.hpTicks then for ti = 1, #o.hpTicks do o.hpTicks[ti].Visible = false end end
                end
            else
                if o.hpOutline then o.hpOutline.Visible = false end
                if o.hpBg then o.hpBg.Visible = false end
                if o.hpFill then o.hpFill.Visible = false end
                if o.hpGhost then o.hpGhost.Visible = false end
                if o.hpText then o.hpText.Visible = false end
                if o.hpTicks then for ti = 1, #o.hpTicks do o.hpTicks[ti].Visible = false end end
            end

            -- ── NAME (Top Pane) ──────────────────────────────────────────────
            if Config.ESPName and not (Config.ESPDeclutter and o._declutter) then
                local nt = nd(o, "nameText", "Text")
                if nt then
                    nt.Font = font
                    nt.Size = math.max(math.min(tfloor, Config.ESPTextSize), math.floor(Config.ESPTextSize * tscale))
                    nt.Center = true; nt.Outline = textOutline
                    nt.Position = Vector2.new(math.floor(minX + w * 0.5), math.floor(minY - nt.Size - 3))
                    nt.Text  = (Config.ESPNameMode == "Username") and player.Name or player.DisplayName
                    nt.Color = Config.ESPNameColor
                    nt.Transparency = (1 - Config.ESPNameTransparency) * fadeMul
                    nt.Visible = true

                    if Config.ESPNameHealthUnderline then
                        pcall(function()
                            local frac = o._sHP or _curFrac
                            if frac == nil then
                                local hp2, mh2; pcall(function() hp2, mh2 = getHealth(player) end)
                                if hp2 then frac = math.clamp((mh2 or 0) > 0 and hp2 / mh2 or 0, 0, 1) end
                            end
                            local un = nd(o, "nameUnder", "Line")
                            if un and frac then
                                local tb    = nt.TextBounds
                                local fullW = (tb and tb.X) or 0
                                local uy    = nt.Position.Y + nt.Size + 2
                                local lx    = nt.Position.X - fullW * 0.5
                                local uw    = fullW * math.clamp(frac, 0, 1)
                                local unS   = outline and nd(o, "nameUnderShadow", "Line") or o.nameUnderShadow
                                if unS then
                                    if outline then
                                        unS.From = Vector2.new(lx - 1, uy); unS.To = Vector2.new(lx + uw + 1, uy)
                                        unS.Thickness = 3; unS.Color = BLACK; unS.Transparency = oAlpha; unS.Visible = true
                                    else unS.Visible = false end
                                end
                                un.From = Vector2.new(lx, uy); un.To = Vector2.new(lx + uw, uy)
                                un.Thickness = 2; un.Color = resolveHealthColor(frac, dyn); un.Transparency = 1; un.Visible = uw > 0.5
                            elseif un then un.Visible = false end
                        end)
                    elseif o.nameUnder then
                        o.nameUnder.Visible = false
                        if o.nameUnderShadow then o.nameUnderShadow.Visible = false end
                    end
                end
            elseif o.nameText then
                o.nameText.Visible = false
                if o.nameUnder then o.nameUnder.Visible = false end
                if o.nameUnderShadow then o.nameUnderShadow.Visible = false end
            end

            -- ── AMMO BAR (Bottom Pane under box) ─────────────────────────────
            local botY = infoY
            if Config.ESPAmmoBar and not (Config.ESPDeclutter and o._declutter) then
                pcall(function()
                    local abBg   = nd(o, "ammoBg", "Square")
                    local abFill = nd(o, "ammoFill", "Square")
                    local abOut  = outline and nd(o, "ammoOutline", "Square") or o.ammoOutline
                    local item   = Rivals.Fighter and Rivals.Fighter:Get(player)
                    local eq     = item and (item.EquippedItem or item.GetEquippedItem and item:GetEquippedItem())
                    local ammo, maxAmmo = 30, 30
                    if eq and eq.Data then
                        ammo = eq.Data.Ammo or 30
                        maxAmmo = eq.Data.MaxAmmo or 30
                    end
                    local aPct = math.clamp(maxAmmo > 0 and (ammo / maxAmmo) or 1, 0, 1)
                    local barY = botY + 1
                    local barH = 2.5
                    if abOut then
                        if outline then sq(abOut, minX - 1, barY - 1, w + 2, barH + 2, false, BLACK, oAlpha, 1)
                        else abOut.Visible = false end
                    end
                    if abBg then sq(abBg, minX, barY, w, barH, true, HPBG, 0.88) end
                    if abFill then sq(abFill, minX, barY, math.max(w * aPct, 1), barH, true, Color3.fromRGB(255, 194, 75), fadeMul) end
                    botY = barY + barH + 3
                end)
            else
                if o.ammoBg then o.ammoBg.Visible = false end
                if o.ammoFill then o.ammoFill.Visible = false end
                if o.ammoOutline then o.ammoOutline.Visible = false end
            end

            -- ── INFO: Distance & Weapon (Bottom Pane) ────────────────────────
            if (Config.ESPDistance or Config.ESPWeapon) and not (Config.ESPDeclutter and o._declutter) then
                local it = nd(o, "infoText", "Text")
                if it then
                    local txt
                    if Config.ESPWeapon then
                        local wep = espWeapon(o, player)
                        txt = wep
                    end
                    if Config.ESPDistance then
                        local dTxt = ("%dm"):format(dist)
                        txt = txt and (txt .. " · " .. dTxt) or dTxt
                    end
                    it.Font = font
                    it.Size = math.max(math.min(tfloor, Config.ESPInfoTextSize), math.floor(Config.ESPInfoTextSize * tscale))
                    it.Center = true; it.Outline = textOutline
                    it.Position = Vector2.new(math.floor(minX + w * 0.5), math.floor(botY))
                    it.Text  = txt or ""
                    it.Color = Config.ESPDistanceColor or Config.ESPInfoColor
                    it.Transparency = (1 - Config.ESPNameTransparency) * fadeMul
                    it.Visible = txt ~= nil
                end
            elseif o.infoText then o.infoText.Visible = false end

            -- ── TRACER SNAPLINES ─────────────────────────────────────────────
            if Config.ESPTracers then
                local origin = Vector2.new(vp.X * 0.5, vp.Y)
                local m = Config.ESPTracerOrigin
                if m == "Top" then origin = Vector2.new(vp.X * 0.5, 0)
                elseif m == "Middle" then origin = Vector2.new(vp.X * 0.5, vp.Y * 0.5)
                elseif m == "Mouse" then
                    local mp; pcall(function() mp = UserInputService:GetMouseLocation() end)
                    origin = mp or Vector2.new(vp.X * 0.5, vp.Y * 0.5)
                end
                local to    = Vector2.new(minX + w * 0.5, maxY)
                local thick = Config.ESPTracerThickness or 1
                local tcol  = dyn or Config.ESPTracerColor
                local baseA = 1 - Config.ESPTracerTransparency
                local trS   = outline and nd(o, "tracerShadow", "Line") or o.tracerShadow

                if Config.ESPTracerGradient then
                    if o.tracer then o.tracer.Visible = false end
                    if trS then
                        if outline then
                            trS.From = origin; trS.To = to; trS.Thickness = thick + 2; trS.Color = BLACK
                            trS.Transparency = oAlpha; trS.Visible = true
                        else trS.Visible = false end
                    end
                    local segs = ndArr(o, "tracerSeg", "Line", 3)
                    for k = 1, 3 do
                        local L = segs[k]
                        if L then
                            local f = origin:Lerp(to, (k - 1) / 3)
                            local t = origin:Lerp(to, k / 3)
                            local a = (0.15 + 0.85 * (k / 3)) * baseA
                            L.From = f; L.To = t; L.Color = tcol; L.Thickness = thick
                            L.Transparency = math.clamp(a, 0, 1); L.Visible = true
                        end
                    end
                else
                    if o.tracerSeg then for _, l in ipairs(o.tracerSeg) do l.Visible = false end end
                    local tr = nd(o, "tracer", "Line")
                    if tr then
                        if trS then
                            if outline then
                                trS.From = origin; trS.To = to; trS.Thickness = thick + 2; trS.Color = BLACK
                                trS.Transparency = oAlpha; trS.Visible = true
                            else trS.Visible = false end
                        end
                        tr.From = origin; tr.To = to; tr.Color = tcol
                        tr.Thickness = thick; tr.Transparency = baseA; tr.Visible = true
                    end
                end
            elseif o.tracer then
                o.tracer.Visible = false
                if o.tracerShadow then o.tracerShadow.Visible = false end
                if o.tracerSeg then for _, l in ipairs(o.tracerSeg) do l.Visible = false end end
            end

            -- ── HEAD RETICLE MARKER ──────────────────────────────────────────
            if Config.ESPHeadMarker or Config.ESPHeadDot then
                local hm  = nd(o, "headMarker", "Circle")
                local hmS = outline and nd(o, "headMarkerShadow", "Circle") or o.headMarkerShadow
                if hm then
                    local head = char:FindFirstChild("Head")
                    if head then
                        local hsp, inv = cam:WorldToViewportPoint(head.Position)
                        if inv and hsp.Z > 0 then
                            local p = Vector2.new(hsp.X, hsp.Y)
                            local r = math.clamp(Config.ESPHeadDotSize or 4, 2, 16)
                            local isDot = (Config.ESPHeadMarkerShape == "Dot")
                            if isDot then r = 2.5 end
                            if hmS then
                                if outline then
                                    hmS.Filled = true; hmS.NumSides = 16; hmS.Radius = r + 1.5; hmS.Position = p
                                    hmS.Color = BLACK; hmS.Transparency = oAlpha; hmS.Visible = true
                                else hmS.Visible = false end
                            end
                            hm.Filled = isDot
                            hm.NumSides = 16
                            hm.Thickness = 1.5
                            hm.Radius = r
                            hm.Position = p
                            hm.Color = Config.ESPHeadMarkerColor or (dyn or Config.ESPHeadDotColor)
                            hm.Transparency = fadeMul
                            hm.Visible = true
                        else
                            hm.Visible = false; if hmS then hmS.Visible = false end
                        end
                    else
                        hm.Visible = false; if hmS then hmS.Visible = false end
                    end
                end
            elseif o.headMarker then
                o.headMarker.Visible = false
                if o.headMarkerShadow then o.headMarkerShadow.Visible = false end
            end

            -- ── STATUS & THREAT BADGES (Right Pane) ─────────────────────────
            pcall(function()
                local flags = {}
                if Config.ESPFlagStaring then
                    local head = char:FindFirstChild("Head")
                    local myRPos = ctx.myRoot and ctx.myRoot.Position
                    if head and myRPos then
                        local toMe = (myRPos - head.Position)
                        if toMe.Magnitude > 1 then
                            toMe = toMe.Unit
                            local look = head.CFrame.LookVector
                            if (look.X * toMe.X + look.Y * toMe.Y + look.Z * toMe.Z) > 0.965 then
                                flags[#flags + 1] = { text = "[STARING]", color = Color3.fromRGB(255, 59, 78) }
                            end
                        end
                    end
                end
                if Config.ESPFlagDeflect and isDeflecting and isDeflecting(player) then
                    flags[#flags + 1] = { text = "[DEFLECT]", color = Color3.fromRGB(53, 215, 199) }
                end
                if Config.ESPFlagShield then
                    local wep = espWeapon(o, player)
                    if wep and (wep:find("Shield") or wep:find("Riot")) then
                        flags[#flags + 1] = { text = "[SHIELD]", color = Color3.fromRGB(255, 194, 75) }
                    end
                end
                if Config.ESPFlagInvincible and isSpawnProtected and isSpawnProtected(player) then
                    flags[#flags + 1] = { text = "[INVINCIBLE]", color = Color3.fromRGB(255, 215, 0) }
                end
                if Config.ESPFlagLowHP and _curFrac and _curFrac <= 0.25 then
                    flags[#flags + 1] = { text = "[LOW HP]", color = Color3.fromRGB(255, 42, 42) }
                end

                local fDraws = ndArr(o, "flagTexts", "Text", 5)
                local flagX = maxX + 4
                local flagY = minY
                for fi = 1, 5 do
                    local fl = fDraws[fi]
                    if fl then
                        local fd = flags[fi]
                        if fd then
                            fl.Font = font
                            fl.Size = math.max(9, math.floor(10 * tscale))
                            fl.Outline = textOutline
                            fl.Center = false
                            fl.Position = Vector2.new(flagX, flagY)
                            fl.Text = fd.text
                            fl.Color = fd.color
                            fl.Transparency = fadeMul
                            fl.Visible = true
                            flagY = flagY + fl.Size + 2
                        else
                            fl.Visible = false
                        end
                    end
                end
            end)

            -- ── LOCK CHEVRON / OVERLAYS ─────────────────────────────────────
            if Config.ESPLockChevron and o._primary then
                pcall(function()
                    local cv = nd(o, "lockChev", "Triangle")
                    if cv then
                        local pt  = o._primT and math.clamp((ctx.now - o._primT) / 0.14, 0, 1) or 1
                        local e   = 1 - (1 - pt) * (1 - pt)
                        local cxp = minX + w * 0.5
                        local yTop = (minY - 24) + (1 - e) * 6
                        cv.Filled = true
                        cv.PointA = Vector2.new(cxp, yTop + 6)
                        cv.PointB = Vector2.new(cxp - 5, yTop)
                        cv.PointC = Vector2.new(cxp + 5, yTop)
                        cv.Color  = Color3.fromRGB(255, 194, 75)
                        cv.Transparency = e
                        cv.Visible = true
                    end
                end)
            elseif o.lockChev then o.lockChev.Visible = false end

            if Config.ESPPeekAlert then
                pcall(function()
                    local v = o._vis and true or false
                    if v and not o._peekWasVis then o._peekT = ctx.now end
                    o._peekWasVis = v
                    local pb = nd(o, "peekBox", "Square")
                    if pb then
                        if o._peekT and (ctx.now - o._peekT) < 0.12 then
                            sq(pb, minX - 4, minY - 4, w + 8, h + 8, false, dyn or Config.ESPBoxColor, 1, 2)
                        else pb.Visible = false end
                    end
                end)
            elseif o.peekBox then o.peekBox.Visible = false end

            if Config.ESPFacingIndicator then
                pcall(function()
                    local myPos = ctx.myRoot and ctx.myRoot.Position
                    local fp = nd(o, "facePip", "Circle")
                    if fp and myPos and o.root then
                        local look = o.root.CFrame.LookVector
                        local to   = myPos - o.root.Position
                        local m    = to.Magnitude
                        if m > 1 then
                            to = to / m
                            local dp = look.X * to.X + look.Y * to.Y + look.Z * to.Z
                            if dp > 0.985 then
                                fp.Filled = true; fp.NumSides = 12; fp.Radius = 3
                                fp.Position = Vector2.new(math.floor(minX + w * 0.5), math.floor(minY - 12))
                                fp.Color = Config.ColorEnemy; fp.Transparency = 1; fp.Visible = true
                            else fp.Visible = false end
                        else fp.Visible = false end
                    end
                end)
            elseif o.facePip then o.facePip.Visible = false end

            if Config.ESPHealTick then
                pcall(function()
                    if _prevHP and _curFrac and _curFrac > _prevHP + 0.005 then o._healT = ctx.now end
                    local he = nd(o, "healEdge", "Square")
                    if he then
                        if o._healT and (ctx.now - o._healT) < 0.2 then
                            sq(he, minX - 2, minY - 2, w + 4, h + 4, false, Color3.fromRGB(61, 224, 122), 1, 2)
                        else he.Visible = false end
                    end
                end)
            elseif o.healEdge then o.healEdge.Visible = false end

            if Config.ESPLookLine then
                pcall(function()
                    local ll = nd(o, "lookLine", "Line")
                    if not ll then return end
                    local llS = outline and nd(o, "lookLineShadow", "Line") or o.lookLineShadow
                    if (not o._lookPts) or (_espFrame - (o._lookFrame or -9)) >= 2 then
                        o._lookFrame = _espFrame
                        local pts = o._lookPts; if not pts then pts = {}; o._lookPts = pts end
                        local head = char:FindFirstChild("Head")
                        if head then
                            local look = head.CFrame.LookVector
                            local p1   = head.Position
                            local p2   = p1 + look * math.clamp(Config.ESPLookLineLength or 8, 2, 32)
                            local s1, v1 = cam:WorldToViewportPoint(p1)
                            local s2, v2 = cam:WorldToViewportPoint(p2)
                            if v1 and v2 and s1.Z > 0 and s2.Z > 0 then
                                pts.f = Vector2.new(s1.X, s1.Y); pts.t = Vector2.new(s2.X, s2.Y)
                                local toward = false
                                local myPos = ctx.myRoot and ctx.myRoot.Position
                                if myPos then
                                    local to = myPos - p1
                                    local m  = to.Magnitude
                                    if m > 1 then
                                        to = to / m
                                        toward = (look.X * to.X + look.Y * to.Y + look.Z * to.Z) > 0.985
                                    end
                                end
                                pts.hot = toward
                            else
                                pts.f = false
                            end
                        else
                            pts.f = false
                        end
                    end
                    local pts = o._lookPts
                    if pts and pts.f then
                        if llS then
                            if outline then
                                llS.From = pts.f; llS.To = pts.t; llS.Thickness = 3; llS.Color = BLACK
                                llS.Transparency = oAlpha; llS.Visible = true
                            else llS.Visible = false end
                        end
                        ll.From = pts.f; ll.To = pts.t; ll.Thickness = 1
                        ll.Color = pts.hot and Config.ColorEnemy or Config.ESPInfoColor
                        ll.Transparency = fadeMul; ll.Visible = true
                    else
                        ll.Visible = false; if llS then llS.Visible = false end
                    end
                end)
            elseif o.lookLine then
                o.lookLine.Visible = false
                if o.lookLineShadow then o.lookLineShadow.Visible = false end
            end

            if _curFrac ~= nil then o._lastHP = _curFrac end
        else
            hide2D(o)
        end

        -- ── THREAT TALLY ─────────────────────────────────────────────────────
        if Config.ESPThreatCount then
            local tsp = cam:WorldToViewportPoint(rootPos)
            local tOn = tsp.Z > 0 and tsp.X >= 0 and tsp.X <= vp.X and tsp.Y >= 0 and tsp.Y <= vp.Y
            if not tOn then ctx.threat = (ctx.threat or 0) + 1 end
        end

        -- ── OFF-SCREEN THREAT CHEVRONS ───────────────────────────────────────
        if Config.ESPArrows then
            local ar  = nd(o, "arrow", "Triangle")
            local arO = o.arrowOutline
            if ar then
                local asp = cam:WorldToViewportPoint(rootPos)
                local onScreen = asp.Z > 0 and asp.X >= 0 and asp.X <= vp.X and asp.Y >= 0 and asp.Y <= vp.Y
                if not onScreen then
                    local cen  = Vector2.new(vp.X * 0.5, vp.Y * 0.5)
                    local adir = Vector2.new(asp.X - cen.X, asp.Y - cen.Y)
                    if asp.Z <= 0 then adir = Vector2.new(-adir.X, -adir.Y) end
                    if adir.Magnitude < 1 then adir = Vector2.new(0, -1) end
                    adir = adir.Unit
                    local edge = cen + adir * (math.min(vp.X, vp.Y) * 0.38)
                    local perp = Vector2.new(-adir.Y, adir.X)
                    local ac   = dyn or Config.ESPBoxColor
                    if arO then arO.Visible = false end
                    local aAlpha = 1 - Config.ESPBoxTransparency
                    if Config.ESPArrowDistFade then
                        aAlpha = aAlpha * (1 - 0.65 * math.clamp(dist / math.max(Config.ESPMaxDistance, 1), 0, 1))
                    end
                    ar.Filled = false
                    ar.PointA = edge + adir * 20
                    ar.PointB = (edge - adir * 10) + perp * 8
                    ar.PointC = (edge - adir * 10) - perp * 8
                    ar.Color = ac; ar.Transparency = aAlpha; ar.Visible = true
                    if Config.ESPArrowDistLabel then
                        local dl = nd(o, "arrowDist", "Text")
                        if dl then
                            local lpos = edge - adir * 24
                            dl.Font = FONTS[Config.ESPFont] or 2
                            dl.Size = 10; dl.Center = true; dl.Outline = true
                            dl.Color = Config.ESPInfoColor
                            dl.Text = ("%dm"):format(dist)
                            dl.Position = Vector2.new(math.floor(lpos.X), math.floor(lpos.Y - 5))
                            dl.Transparency = aAlpha
                            dl.Visible = true
                        end
                    elseif o.arrowDist then o.arrowDist.Visible = false end
                else
                    ar.Visible = false
                    if arO then arO.Visible = false end
                    if o.arrowDist then o.arrowDist.Visible = false end
                end
            end
        elseif o.arrow then
            o.arrow.Visible = false
            if o.arrowOutline then o.arrowOutline.Visible = false end
            if o.arrowDist then o.arrowDist.Visible = false end
        end

        -- ── CHAMS ────────────────────────────────────────────────────────────
        if Config.ESPChams then
            local hl = ensureCham(o, char)
            if hl then
                local vc = Config.ESPChamsVisSplit
                    and (o._vis and (isTeammate(player) and Config.ColorTeam or Config.ColorEnemy)
                                 or (isTeammate(player) and Config.ColorTeamOcc or Config.ColorEnemyOcc))
                    or nil
                local state = vc or dyn or Config.ESPChamsFillColor
                local style = Config.ESPChamsStyle
                if style == "Shade" then
                    hl.FillColor           = state
                    hl.OutlineColor        = Color3.new(1, 1, 1)
                    hl.FillTransparency    = 0.62
                    hl.OutlineTransparency = 0
                    hl.Enabled             = true
                elseif style == "Neon" then
                    hl.FillColor           = state
                    hl.OutlineColor        = vc or dyn or Config.ESPChamsOutlineColor
                    hl.FillTransparency    = 0.88
                    hl.OutlineTransparency = 0
                    hl.Enabled             = true
                elseif style == "Ghost" then
                    hl.FillColor           = state
                    hl.OutlineColor        = Color3.new(1, 1, 1)
                    hl.FillTransparency    = 1
                    hl.OutlineTransparency = 0.25
                    hl.Enabled             = not o._vis
                else
                    if vc then
                        hl.FillColor = vc; hl.OutlineColor = vc
                    else
                        hl.FillColor = dyn or Config.ESPChamsFillColor
                        hl.OutlineColor = dyn or Config.ESPChamsOutlineColor
                    end
                    hl.FillTransparency    = Config.ESPChamsFillTransparency
                    hl.OutlineTransparency = Config.ESPChamsOutlineTransparency
                    hl.Enabled             = true
                end
            end
        elseif o.cham then o.cham.Enabled = false end
    end

    local function _byDist(a, b)
        local ad, bd = a.d, b.d
        if ad ~= ad then return false end
        if bd ~= bd then return true end
        return ad < bd
    end

    -- Declutter: flag farther boxes >60% covered by a nearer box
    local function doDeclutter(ctx)
        local myPos = ctx.myRoot and ctx.myRoot.Position
        local n = 0
        for player, o in pairs(State.ESPObjects) do
            o._declutter = false
            local c = _bboxCache[player]
            if c and o.root and o.root.Parent then
                n = n + 1
                local e = _dcArr[n]; if not e then e = {}; _dcArr[n] = e end
                e.o = o; e.c = c
                local rp = o.root.Position
                e.d = (myPos and rp) and (myPos - rp).Magnitude or math.huge
            end
        end
        for i = #_dcArr, n + 1, -1 do _dcArr[i] = nil end
        table.sort(_dcArr, _byDist)
        for i = 1, n - 1 do
            local A = _dcArr[i]; local ca = A.c
            local aMinX, aMinY, aMaxX, aMaxY = ca[1], ca[2], ca[3], ca[4]
            for j = i + 1, n do
                local B = _dcArr[j]
                if not B.o._declutter then
                    local cb = B.c
                    local ix = math.min(aMaxX, cb[3]) - math.max(aMinX, cb[1])
                    local iy = math.min(aMaxY, cb[4]) - math.max(aMinY, cb[2])
                    if ix > 0 and iy > 0 then
                        local barea = (cb[3] - cb[1]) * (cb[4] - cb[2])
                        if barea > 0 and (ix * iy) / barea > 0.6 then B.o._declutter = true end
                    end
                end
            end
        end
    end

    -- Radar render pass
    local function renderRadar(ctx)
        if not Config.ESPRadar then
            for _, d in ipairs(_radarO.drawings) do d.Visible = false end
            return
        end
        if (_espFrame % 2) ~= 0 then return end
        local vp = ctx.vp; if not vp then return end
        local R     = math.max((Config.ESPRadarSize or 180) * 0.5, 10)
        local inset = Config.ESPRadarInset or 20
        local cx    = vp.X - inset - R
        local cy    = inset + R

        local disc = nd(_radarO, "disc", "Circle")
        if disc then
            disc.Filled = true; disc.NumSides = 32; disc.Radius = R
            disc.Position = Vector2.new(cx, cy)
            disc.Color = Color3.fromRGB(13, 18, 25)
            disc.Transparency = 0.62; disc.Visible = true
        end

        local rring = nd(_radarO, "rangeRing", "Circle")
        if rring then
            rring.Filled = false; rring.Thickness = 1; rring.NumSides = 28; rring.Radius = R * 0.5
            rring.Position = Vector2.new(cx, cy); rring.Color = Color3.new(1, 1, 1)
            rring.Transparency = 0.10; rring.Visible = true
        end

        local myPos = ctx.myRoot and ctx.myRoot.Position
        if not myPos then return end
        local rot = 0
        if Config.ESPRadarRotate then
            local look = cam.CFrame.LookVector
            rot = -math.atan2(look.X, look.Z)
        end
        local cosR, sinR = math.cos(rot), math.sin(rot)
        local range = math.max(Config.ESPRadarRange or 250, 1)

        local ticks = ndArr(_radarO, "ticks", "Line", 4)
        for i = 0, 3 do
            local L = ticks[i + 1]
            if L then
                local ang = i * (math.pi * 0.5) + rot
                local dxT, dyT = math.sin(ang), -math.cos(ang)
                L.From = Vector2.new(cx + dxT * (R - 6), cy + dyT * (R - 6))
                L.To   = Vector2.new(cx + dxT * R, cy + dyT * R)
                L.Thickness = 1
                if i == 0 then L.Color = Color3.fromRGB(255, 194, 75); L.Transparency = 0.9
                else L.Color = Color3.new(1, 1, 1); L.Transparency = 0.35 end
                L.Visible = true
            end
        end

        if Config.ESPRadarGrid then
            local grid = ndArr(_radarO, "grid", "Line", 2)
            for gi = 1, 2 do
                local L = grid[gi]
                if L then
                    local ang = rot + (gi - 1) * (math.pi * 0.5)
                    local gx, gy = math.sin(ang), -math.cos(ang)
                    L.From = Vector2.new(cx - gx * R, cy - gy * R)
                    L.To   = Vector2.new(cx + gx * R, cy + gy * R)
                    L.Thickness = 1
                    L.Color = Color3.fromRGB(168, 180, 192)
                    L.Transparency = 0.10
                    L.Visible = true
                end
            end
        elseif _radarO.grid then
            for _, L in ipairs(_radarO.grid) do L.Visible = false end
        end

        if Config.ESPRadarSweep then
            local sw = ndArr(_radarO, "sweep", "Line", 3)
            local baseAng = ((ctx.now or 0) % 4) / 4 * (math.pi * 2) + rot
            for si = 1, 3 do
                local L = sw[si]
                if L then
                    local ang = baseAng - (si - 1) * 0.12
                    local sx, sy = math.sin(ang), -math.cos(ang)
                    L.From = Vector2.new(cx, cy)
                    L.To   = Vector2.new(cx + sx * (R - 2), cy + sy * (R - 2))
                    L.Thickness = si == 1 and 2 or 1
                    L.Color = Color3.fromRGB(255, 194, 75)
                    L.Transparency = si == 1 and 0.35 or (si == 2 and 0.18 or 0.08)
                    L.Visible = true
                end
            end
        elseif _radarO.sweep then
            for _, L in ipairs(_radarO.sweep) do L.Visible = false end
        end

        local idx = 0
        local closestIdx, closestH = nil, math.huge
        local closestPx, closestPy, closestDotR = 0, 0, 0
        for player, o in pairs(State.ESPObjects) do
            local root = o.root
            if root and root.Parent then
                local rp = root.Position
                local dx = rp.X - myPos.X
                local dz = rp.Z - myPos.Z
                local sx = (dx / range) * R
                local sz = (dz / range) * R
                local rx = sx * cosR - sz * sinR
                local rz = sx * sinR + sz * cosR
                local mag = math.sqrt(rx * rx + rz * rz)
                if mag > R then rx = rx / mag * R; rz = rz / mag * R end
                idx = idx + 1
                local px, py = cx + rx, cy + rz
                local hdist  = math.sqrt(dx * dx + dz * dz)
                local dotR   = math.clamp(5 - (hdist / range) * 2, 3, 5)
                local team   = isTeammate(player)
                local filled = (not Config.ESPRadarVisSplit) or (o._vis and true or false)
                local col
                if Config.ESPRadarVisSplit and not o._vis then
                    col = team and Config.ColorTeamOcc or Config.ColorEnemyOcc
                else
                    col = team and Config.ColorTeam or Config.ColorEnemy
                end
                if hdist < closestH then closestH = hdist; closestIdx = idx; closestPx = px; closestPy = py; closestDotR = dotR end
                local dsh = ndArr(_radarO, "dotShadow", "Circle", idx)
                local sD = dsh[idx]
                if sD then
                    sD.Filled = true; sD.NumSides = 12; sD.Radius = dotR + 1
                    sD.Position = Vector2.new(px, py); sD.Color = BLACK
                    sD.Transparency = 0.6; sD.Visible = true
                end
                local dots = ndArr(_radarO, "dots", "Circle", idx)
                local d = dots[idx]
                if d then
                    d.Filled = filled
                    if not filled then d.Thickness = 1 end
                    d.NumSides = 12; d.Radius = dotR
                    d.Position = Vector2.new(px, py); d.Color = col
                    d.Transparency = 1; d.Visible = true
                end
                local chevs = ndArr(_radarO, "chev", "Triangle", idx)
                local cv = chevs[idx]
                if cv then
                    local dy = rp.Y - myPos.Y
                    if dy > 6 or dy < -6 then
                        local dir = dy > 6 and -1 or 1
                        cv.Filled = false
                        cv.PointA = Vector2.new(px, py + dir * (dotR + 4))
                        cv.PointB = Vector2.new(px - 3, py + dir * (dotR + 1))
                        cv.PointC = Vector2.new(px + 3, py + dir * (dotR + 1))
                        cv.Color = col; cv.Transparency = 1; cv.Visible = true
                    else cv.Visible = false end
                end
            end
        end

        local nearRing = nd(_radarO, "nearRing", "Circle")
        if nearRing then
            if closestIdx then
                local pulse = 1 + 0.28 * (0.5 + 0.5 * math.sin((ctx.now or 0) * 1.6 * math.pi * 2))
                nearRing.Filled = false; nearRing.Thickness = 1.2; nearRing.NumSides = 24
                nearRing.Radius = (closestDotR + 3) * pulse
                nearRing.Position = Vector2.new(closestPx, closestPy)
                nearRing.Color = Color3.fromRGB(255, 194, 75)
                nearRing.Transparency = 1; nearRing.Visible = true
            else
                nearRing.Visible = false
            end
        end
        if _radarO.dots      then for i = idx + 1, #_radarO.dots do _radarO.dots[i].Visible = false end end
        if _radarO.dotShadow then for i = idx + 1, #_radarO.dotShadow do _radarO.dotShadow[i].Visible = false end end
        if _radarO.chev      then for i = idx + 1, #_radarO.chev do _radarO.chev[i].Visible = false end end

        local selfTri = nd(_radarO, "self", "Triangle")
        if selfTri then
            selfTri.Filled = true
            selfTri.PointA = Vector2.new(cx, cy - 5)
            selfTri.PointB = Vector2.new(cx - 4, cy + 4)
            selfTri.PointC = Vector2.new(cx + 4, cy + 4)
            selfTri.Color = Color3.fromRGB(255, 194, 75); selfTri.Transparency = 1; selfTri.Visible = true
        end
        local rimShadow = nd(_radarO, "rimShadow", "Circle")
        if rimShadow then
            rimShadow.Filled = false; rimShadow.Thickness = 2; rimShadow.NumSides = 32; rimShadow.Radius = R
            rimShadow.Position = Vector2.new(cx, cy); rimShadow.Color = BLACK
            rimShadow.Transparency = 0.55; rimShadow.Visible = true
        end
        local rim = nd(_radarO, "rim", "Circle")
        if rim then
            rim.Filled = false; rim.Thickness = 1; rim.NumSides = 32; rim.Radius = R
            rim.Position = Vector2.new(cx, cy)
            rim.Color = Color3.fromRGB(168, 180, 192)
            rim.Transparency = 0.45; rim.Visible = true
        end
    end

    local function render()
        local _now = tick()
        local _dt  = _now - _lastRenderT
        if _now - _lastRenderT < 0.0083 then return end   -- cap ESP work ~120Hz
        _lastRenderT = _now
        _espFrame = _espFrame + 1
        _createBudget = CREATE_BUDGET_PER_FRAME

        if not Config.ESP then
            State.PrimaryTarget = nil
            for _, o in pairs(State.ESPObjects) do hideAll(o, true) end
            for _, d in ipairs(_radarO.drawings) do d.Visible = false end
            for _, d in ipairs(_module.drawings) do d.Visible = false end
            return
        end

        State.RainbowHue = (State.RainbowHue + 0.002) % 1
        local ctx = _ctx
        ctx.vp     = cam.ViewportSize
        ctx.myRoot = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
        ctx.rb     = (Config.ESPColorMode == "Rainbow") and Color3.fromHSV(State.RainbowHue, 1, 1) or nil
        ctx.outline      = (Config.ESPOutline or Config.ESPOutlines) and true or false
        ctx.outlineAlpha = 1 - (Config.ESPOutlineTransparency or 0.35)
        ctx.hasDrawing   = hasDrawing
        ctx.dt          = math.clamp(_dt, 0, 0.1)
        ctx.now         = _now
        ctx.textOutline = Config.ESPTextOutline ~= false
        ctx.threat      = 0

        if Config.ESPDeclutter and (ctx.now - _dcLastT) >= 0.05 then
            _dcLastT = ctx.now; pcall(doDeclutter, ctx)
        end

        local cap = Config.ESPMaxPlayers or 0
        if cap and cap > 0 then
            local arr = _renderArr
            local n = 0
            local myPos = ctx.myRoot and ctx.myRoot.Position
            for player, o in pairs(State.ESPObjects) do
                n = n + 1
                local e = arr[n]; if not e then e = {}; arr[n] = e end
                e.p = player; e.o = o
                local rp = o.root and o.root.Parent and o.root.Position
                e.d = (myPos and rp) and (myPos - rp).Magnitude or math.huge
            end
            for i = #arr, n + 1, -1 do arr[i] = nil end
            pcall(table.sort, arr, _byDist)
            if Config.ESPPrimaryEmphasis or Config.ESPLockChevron or Config.FXTargetInfo then
                for i = 1, n do arr[i].o._primary = false end
                local bestO = arr[1] and arr[1].o
                local bestD = (arr[1] and arr[1].d) or math.huge
                local lockO, lockD
                for i = 1, n do if arr[i].o == _lock.obj then lockO = arr[i].o; lockD = arr[i].d; break end end
                local locked = resolveLock(bestO, bestD, lockO, lockD, ctx.now)
                State.PrimaryTarget = nil
                if locked then
                    locked._primary = true
                    for i = 1, n do if arr[i].o == locked then State.PrimaryTarget = arr[i].p break end end
                end
            else
                State.PrimaryTarget = nil
            end
            for i = 1, n do
                local e = arr[i]
                if i <= cap then
                    e.o._dist = e.d
                    pcall(renderPlayer, e.p, e.o)
                else
                    hideAll(e.o)
                end
            end
        else
            if Config.ESPPrimaryEmphasis or Config.ESPLockChevron or Config.FXTargetInfo then
                local myPos = ctx.myRoot and ctx.myRoot.Position
                local bestD, bestO = math.huge, nil
                local lockO, lockD
                for player, o in pairs(State.ESPObjects) do
                    o._primary = false
                    local rp = o.root and o.root.Parent and o.root.Position
                    local d = (myPos and rp) and (myPos - rp).Magnitude or math.huge
                    if d < bestD then bestD = d; bestO = o end
                    if o == _lock.obj then lockO = o; lockD = d end
                end
                local locked = resolveLock(bestO, bestD, lockO, lockD, ctx.now)
                State.PrimaryTarget = nil
                if locked then
                    locked._primary = true
                    for player, o in pairs(State.ESPObjects) do
                        if o == locked then State.PrimaryTarget = player break end
                    end
                end
            else
                State.PrimaryTarget = nil
            end
            for player, o in pairs(State.ESPObjects) do
                o._dist = nil
                pcall(renderPlayer, player, o)
            end
        end

        pcall(renderRadar, ctx)
        if Config.ESPThreatCount then
            pcall(function()
                local t = nd(_module, "threat", "Text")
                if t then
                    local cnt = ctx.threat or 0
                    if cnt > 0 then
                        t.Font = FONTS[Config.ESPFont] or 2
                        t.Size = 14; t.Center = true; t.Outline = true
                        t.Color = Config.ColorEnemy
                        t.Text = cnt .. " <"
                        t.Position = Vector2.new(math.floor(ctx.vp.X * 0.5), math.floor(ctx.vp.Y * 0.5 + 28))
                        t.Transparency = 1; t.Visible = true
                    else t.Visible = false end
                end
            end)
        elseif _module.threat then _module.threat.Visible = false end
    end

    function ESP.init()
        for _, p in ipairs(getSafePlayers()) do
            if p ~= lp then
                p.CharacterAdded:Connect(function()
                    task.wait(0.5); if Config.ESP then buildESP(p) end
                end)
            end
        end
        Players.PlayerAdded:Connect(function(p)
            p.CharacterAdded:Connect(function()
                task.wait(0.5); if Config.ESP then buildESP(p) end
            end)
        end)
        Players.PlayerRemoving:Connect(function(p) cleanESP(p) end)
        if Config.ESP and not _renderConn then
            _renderConn = RunService.RenderStepped:Connect(render)
            ESP.rebuildAll()
        end
    end

    function ESP.enable()
        Config.ESP = true; ESP.rebuildAll()
        if not _renderConn then _renderConn = RunService.RenderStepped:Connect(render) end
    end
    function ESP.disable()
        Config.ESP = false; ESP.rebuildAll()
        State.PrimaryTarget = nil
        if _renderConn then _renderConn:Disconnect(); _renderConn = nil end
    end
    function ESP.unload()
        if _renderConn then _renderConn:Disconnect(); _renderConn = nil end
        State.PrimaryTarget = nil
        for p in pairs(State.ESPObjects) do cleanESP(p) end
        for _, pool in ipairs({ _radarO, _module }) do
            for _, d in ipairs(pool.drawings) do
                pcall(function() if d.Remove then d:Remove() end end)
            end
            pool.drawings = {}
            pool.disc, pool.rim, pool.self, pool.dots, pool.chev, pool.threat = nil, nil, nil, nil, nil, nil
            pool.rangeRing, pool.ticks, pool.dotShadow, pool.rimShadow, pool.nearRing = nil, nil, nil, nil, nil
            pool.grid, pool.sweep = nil, nil
        end
    end
end

-- ── UTILITY ESP ─────────────────────────────────────────────────────────────
-- World-object ESP for thrown gadgets (grenades / molotovs / flashbangs / tripmines / satchels /
-- warpstones). Detection is EVENT-DRIVEN: one Workspace.DescendantAdded listener does a cheap
-- lowercase substring match on the instance Name (thrown entities are always NEW instances, and
-- every skinned variant keeps its base word — "Soul Grenade", "DIY Tripmine", "Potion Satchel").
-- NO per-item connections and NO per-frame workspace scans (the classic utility-ESP mistakes):
-- one central ~30Hz render pass walks the small live-item table, culls by distance, projects and
-- feeds pooled screenDraw primitives (dot + casing + pulse ring + label). Items self-expire when
-- unparented. Draw objects go back to the shim pool via :Remove() on expiry.
local UtilESP = {}
do
    local hasDrawing = screenDraw ~= nil

    local BLACK = Color3.new(0, 0, 0)
    -- SIGNAL tokens: explosives read as ENEMY red, disorient as GOLD, mobility as VISIBLE cyan.
    local C_RED  = Color3.fromRGB(255, 59, 78)     -- #FF3B4E explosive
    local C_GOLD = Color3.fromRGB(255, 194, 75)    -- #FFC24B disorient/trap
    local C_CYAN  = Color3.fromRGB(53, 215, 199)   -- #35D7C7 mobility
    local C_TEXT1 = Color3.fromRGB(243, 246, 250)  -- #F3F6FA label text (shapes carry the state color, text stays neutral)

    -- keyword -> display + class color + danger pulse. Matched against lowercase names.
    local KINDS = {
        { k = "tripmine",  label = "TRIPMINE",  color = C_GOLD, danger = true  },
        { k = "grenade",   label = "GRENADE",   color = C_RED,  danger = true  },
        { k = "molotov",   label = "MOLOTOV",   color = C_RED,  danger = true  },
        { k = "satchel",   label = "SATCHEL",   color = C_RED,  danger = true  },
        { k = "flashbang", label = "FLASHBANG", color = C_GOLD, danger = true  },
        { k = "warpstone", label = "WARPSTONE", color = C_CYAN, danger = false },
    }

    local _items = {}          -- [Instance] = { root=BasePart, kind=KINDS entry, dot, dotB, ring, label, dist }
    local _addConn, _renderConn = nil, nil
    local _lastT = 0

    local function matchKind(name)
        local n = string.lower(name)
        for _, kd in ipairs(KINDS) do
            if string.find(n, kd.k, 1, true) then return kd end
        end
        return nil
    end

    -- our OWN characters/viewmodels also carry gadget-named tools — only track LOOSE world models
    -- (not descendants of any player character or the ViewModels rig)
    local function isWorldItem(inst)
        local a = inst.Parent
        while a and a ~= Workspace do
            local nm = a.Name
            if nm == "ViewModels" then return false end
            if Players:GetPlayerFromCharacter(a) then return false end
            a = a.Parent
        end
        return a == Workspace
    end

    local function rootOf(inst)
        if inst:IsA("BasePart") then return inst end
        if inst:IsA("Model") then
            return inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart")
        end
        return nil
    end

    local function drop(inst)
        local it = _items[inst]
        if not it then return end
        for _, key in ipairs({ "dot", "dotB", "ring", "label" }) do
            local d = it[key]
            if d then pcall(function() d:Remove() end) end
        end
        _items[inst] = nil
    end

    local function track(inst)
        if _items[inst] then return end
        if not (inst:IsA("Model") or inst:IsA("BasePart")) then return end
        local kd = matchKind(inst.Name)
        if not kd then return end
        if not isWorldItem(inst) then return end
        local root = rootOf(inst)
        if not root then
            -- model streamed in before its parts: retry once shortly after
            task.delay(0.1, function()
                if inst.Parent and not _items[inst] then
                    local r2 = rootOf(inst)
                    if r2 then _items[inst] = { root = r2, kind = kd } end
                end
            end)
            return
        end
        _items[inst] = { root = root, kind = kd }
    end

    local function hideItem(it)
        if it.dot   then it.dot.Visible   = false end
        if it.dotB  then it.dotB.Visible  = false end
        if it.ring  then it.ring.Visible  = false end
        if it.label then it.label.Visible = false end
    end

    local function render()
        local now = tick()
        if now - _lastT < 0.033 then return end   -- ~30Hz is plenty for slow-moving world items
        _lastT = now
        if not Config.UtilityESP or not hasDrawing then return end
        local cam = Camera; if not cam then return end
        local myC = lp.Character
        local myR = myC and myC:FindFirstChild("HumanoidRootPart")
        local maxD = Config.UtilityESPMaxDistance or 250
        for inst, it in pairs(_items) do
            if not inst.Parent or not it.root or not it.root.Parent then
                drop(inst)
            else
                local pos = it.root.Position
                local d = myR and (myR.Position - pos).Magnitude
                    or (cam.CFrame.Position - pos).Magnitude
                local sp, on = cam:WorldToViewportPoint(pos)
                if d <= maxD and on and sp.Z > 0 then
                    local col = it.kind.color
                    local p = Vector2.new(sp.X, sp.Y)
                    -- distance-scaled marker (4px near -> 2px far)
                    local r = math.clamp(4 - (d / maxD) * 2, 2, 4)
                    if not it.dotB then it.dotB = screenDraw("Circle") end
                    if it.dotB then
                        it.dotB.Filled = true; it.dotB.NumSides = 12; it.dotB.Radius = r + 1
                        it.dotB.Position = p; it.dotB.Color = BLACK
                        it.dotB.Transparency = 0.7; it.dotB.Visible = true
                    end
                    if not it.dot then it.dot = screenDraw("Circle") end
                    if it.dot then
                        it.dot.Filled = true; it.dot.NumSides = 12; it.dot.Radius = r
                        it.dot.Position = p; it.dot.Color = col
                        it.dot.Transparency = 1; it.dot.Visible = true
                    end
                    -- danger pulse ring (grenades/mines/etc.): breathes r+4 -> r+9 @1.6Hz
                    if it.kind.danger and Config.UtilityESPRing then
                        if not it.ring then it.ring = screenDraw("Circle") end
                        if it.ring then
                            local pulse = 0.5 + 0.5 * math.sin(now * 1.6 * math.pi * 2)
                            it.ring.Filled = false; it.ring.NumSides = 20
                            it.ring.Thickness = 1.5
                            it.ring.Radius = r + 4 + 5 * pulse
                            it.ring.Position = p; it.ring.Color = col
                            it.ring.Transparency = 1 - 0.55 * pulse
                            it.ring.Visible = true
                        end
                    elseif it.ring then it.ring.Visible = false end
                    if Config.UtilityESPLabels then
                        if not it.label then
                            it.label = screenDraw("Text")
                            if it.label then
                                it.label.Center = true; it.label.Outline = true
                                it.label.Font = 2; it.label.Size = 12
                            end
                        end
                        if it.label then
                            it.label.Text = it.kind.label .. " · " .. math.floor(d + 0.5) .. "m"
                            it.label.Position = Vector2.new(math.floor(sp.X), math.floor(sp.Y - 22))
                            it.label.Color = C_TEXT1   -- one-glance rule: dot/ring carry the class hue
                            it.label.Transparency = 1
                            it.label.Visible = true
                        end
                    elseif it.label then it.label.Visible = false end
                else
                    hideItem(it)
                end
            end
        end
    end

    local function connect()
        if not _addConn then
            -- hot path: this fires for EVERY new workspace instance (bullets, fx, debris) — do the
            -- cheap class + name rejection inline and only defer for actual gadget matches.
            _addConn = Workspace.DescendantAdded:Connect(function(inst)
                if not Config.UtilityESP then return end
                if not (inst:IsA("Model") or inst:IsA("BasePart")) then return end
                if not matchKind(inst.Name) then return end
                task.defer(track, inst)
            end)
        end
        if not _renderConn then
            _renderConn = RunService.RenderStepped:Connect(function() pcall(render) end)
        end
    end
    local function disconnect()
        if _addConn then _addConn:Disconnect(); _addConn = nil end
        if _renderConn then _renderConn:Disconnect(); _renderConn = nil end
    end

    local function sweepExisting()
        -- one-time catch-up scan on enable (items already mid-air / planted before we listened)
        for _, inst in ipairs(Workspace:GetDescendants()) do
            if inst:IsA("Model") or inst:IsA("BasePart") then
                if matchKind(inst.Name) then pcall(track, inst) end
            end
        end
    end

    function UtilESP.enable()
        Config.UtilityESP = true
        connect()
        task.spawn(sweepExisting)
    end
    function UtilESP.disable()
        Config.UtilityESP = false
        disconnect()
        for inst in pairs(_items) do drop(inst) end
    end
    function UtilESP.init()
        if Config.UtilityESP then pcall(UtilESP.enable) end
    end
    function UtilESP.unload()
        pcall(UtilESP.disable)
    end
end

-- ── LAB (in-game HvH telemetry — measure, don't guess) ──────────────────────
local Lab = {}
do
    local _gui, _label, _conn, _hpConn, _caConn
    -- stT/stTotal/stLast: TIME-IN-STATE HISTOGRAM (2026-08-09). Added for a symptom nothing else here can
    -- resolve — "sometimes Polar beats them perfectly, sometimes it just doesn't". Every other number in
    -- this overlay is either instantaneous or damage-weighted, so a round we spent stuck in one bad branch
    -- looks identical to a round we spent shooting. State.RageStatus is set on EVERY path through 07c's
    -- tick (its early returns each name their own reason), so accumulating seconds per status is a direct
    -- readout of where the fight actually went. Per the duty-cycle thesis our uptime is the whole problem,
    -- and this is the only thing in the bundle that measures it.
    local s = {
        lastT = 0, lastShots = 0, lastEvents = 0,
        taken = 0, takenAtk = 0, takenHide = 0, takenReload = 0, takenTrans = 0,
        sps = 0, eps = 0,
        stT = {}, stTotal = 0, stLast = 0,
    }

    local function combatState()
        if State.RageTranslocating then return "TRANS" end
        if Config.RageVoidPhase and State.RageVoidActive then return "HIDE" end
        if State.RageFiring then return "ATTACK" end
        local item = getEquippedItem()
        if item then
            if (item._reload_cooldown or 0) > tick() then return "RELOAD" end
            local okA, ammo = pcall(function() return item:Get("Ammo") end)
            if okA and type(ammo) == "number" and ammo <= 0 then return "RELOAD" end
        end
        return "OUT"
    end

    -- avg studs the current target's hitbox jumps per frame (their desync strength)
    local function enemyDesync()
        local t = State.Target;        if not t then return 0 end
        local buf = State.RageBacktrackBuf[t]; if not buf or #buf < 3 then return 0 end
        local sum, n = 0, 0
        for i = math.max(2, #buf - 8), #buf do
            sum = sum + (buf[i].pos - buf[i - 1].pos).Magnitude; n = n + 1
        end
        return n > 0 and sum / n or 0
    end

    -- how far our replicated body currently sits from our camera (are we desynced now?)
    local function selfDesync()
        local c = lp.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        return root and (root.Position - Camera.CFrame.Position).Magnitude or 0
    end

    local function pct(p, w) return w > 0 and math.floor(p / w * 100 + 0.5) or 0 end

    -- Polar seam S28. Mirrors 07c's restoreDuringFire() exactly, off the two flags it publishes, so the
    -- overlay states the DECISION rather than leaving the operator to infer it from `phys`. Derived here
    -- (4x/s) instead of published from 07c because RagePerfectRestore is a live config read.
    local function restoreLabel()
        -- Polar seam S37: the glue FORCES "kicia" for as long as it is live, because the park is the
        -- rendezvous and leaving the body there is not a desync, it is leaving the match. Report the mode
        -- that is actually running, not the config key.
        -- @polarcore-seam:S44 — only "full" forces the transport. Under "lite" the redirect is live but the
        -- body parks and restores exactly as configured, so reporting "kicia" there would be a lie of the
        -- same kind this function was written to stop. Read the mode 07c publishes, not RageGlueBound alone.
        if State.RageGlueBound and State.RageGumMode == "on" then
            return "GUM on (kicia, movement live)"
        end
        if State.RageGlueBound and State.RageGumMode == "lite" then
            -- fall through to the configured mode below, but say the redirect is up
            return "GUM lite + " .. tostring(Config.RageRestoreMode)
        end
        local m = Config.RageRestoreMode
        if m == "kicia" then return "kicia (forced, LEAKS unglued)" end
        if m == "render" then return "render-only (forced)" end
        -- "auto" resolves to "none" in 07c. This line used to read "kicia (auto, movement live)" for it,
        -- which was the exact opposite of what shipped — the default has been "none" since 2026-08-09.
        return "none (S27, no movement)"
    end


    local function hookSelfHP()
        local c = lp.Character
        local h = c and c:FindFirstChildOfClass("Humanoid"); if not h then return end
        if _hpConn then _hpConn:Disconnect() end
        local last = h.Health
        _hpConn = h.HealthChanged:Connect(function(new)
            if new < last - 0.5 then
                local d, st = last - new, combatState()
                s.taken = s.taken + d
                if st == "ATTACK" then s.takenAtk = s.takenAtk + d
                elseif st == "TRANS" then s.takenTrans = s.takenTrans + d
                elseif st == "RELOAD" then s.takenReload = s.takenReload + d
                else s.takenHide = s.takenHide + d end
            end
            last = new
        end)
    end

    function Lab.reset()
        s.taken, s.takenAtk, s.takenHide, s.takenReload, s.takenTrans = 0, 0, 0, 0, 0
        s.stT, s.stTotal, s.stLast = {}, 0, 0
        State.RageDealtTotal = 0
    end

    function Lab.enable()
        Config.RageLab = true
        if not _gui then
            _gui = Instance.new("ScreenGui")
            _gui.Name = "_lh_lab"; _gui.ResetOnSpawn = false; _gui.IgnoreGuiInset = true
            local ok = pcall(function() _gui.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
            if not ok then _gui.Parent = lp:WaitForChild("PlayerGui") end
            _label = Instance.new("TextLabel")
            _label.Position = UDim2.fromOffset(14, 120)
            _label.Size = UDim2.fromOffset(520, 208)   -- widened for the S28 RESTORE readout on the phys line
            _label.BackgroundColor3 = Color3.fromRGB(8, 10, 16)
            _label.BackgroundTransparency = 0.2
            _label.TextColor3 = Color3.fromRGB(0, 230, 160)
            _label.Font = Enum.Font.Code; _label.TextSize = 14
            _label.TextXAlignment = Enum.TextXAlignment.Left
            _label.TextYAlignment = Enum.TextYAlignment.Top
            _label.Text = "LAB"; _label.Parent = _gui
        end
        _gui.Enabled = true
        s.lastT = tick(); s.lastShots = State.Shots; s.lastEvents = State.Hits
        s.stT, s.stTotal, s.stLast = {}, 0, 0
        hookSelfHP()
        if _caConn then _caConn:Disconnect() end
        _caConn = lp.CharacterAdded:Connect(function() task.wait(0.3); if Config.RageLab then hookSelfHP() end end)
        if _conn then _conn:Disconnect() end
        _conn = RunService.Heartbeat:Connect(function()
            if not Config.RageLab then return end
            local now = tick()
            -- Accumulate BEFORE the 0.25s render gate: the histogram has to see every frame, or a status
            -- that only ever occupies one or two frames (Priming, a target switch) vanishes from it.
            if s.stLast > 0 then
                local slice = now - s.stLast
                local k = tostring(State.RageStatus or "Idle")
                s.stT[k] = (s.stT[k] or 0) + slice
                s.stTotal = s.stTotal + slice
            end
            s.stLast = now
            local dt = now - s.lastT
            if dt < 0.25 then return end
            s.lastT = now
            s.sps = math.floor((State.Shots - s.lastShots) / dt)
            s.eps = (State.Hits - s.lastEvents) / dt
            s.lastShots = State.Shots; s.lastEvents = State.Hits
            local dealt = math.floor(State.RageDealtTotal or 0)
            local taken = math.floor(s.taken)
            local ratio = taken > 0 and (dealt / taken) or (dealt > 0 and 999 or 0)
            local sd = selfDesync()
            local sdStr = isSanePos((lp.Character and lp.Character:FindFirstChild("HumanoidRootPart") and lp.Character.HumanoidRootPart.Position) or Vector3.zero)
                and string.format("%d studs", math.floor(sd)) or "VOID!! (flung)"
            -- counter-cheat readout: flag the current target + count detected cheaters
            local cheaters = 0
            for _, pl in ipairs(getSafePlayers()) do
                if pl ~= lp and Rage._isCheater and Rage._isCheater(pl) then cheaters = cheaters + 1 end
            end
            local tgtTag = (State.Target and Rage._isCheater and Rage._isCheater(State.Target)) and "  <<CHEATER>>" or ""
            -- Top 3 statuses by time. Allocates once per render tick (4/s), never per frame. Sorted by
            -- seconds held, so the first entry IS the answer to "where did this round go".
            local top = "-"
            if s.stTotal > 0 then
                local names = {}
                for k in s.stT do
                    names[#names + 1] = k
                end
                table.sort(names, function(a, b) return s.stT[a] > s.stT[b] end)
                top = ""
                for i = 1, math.min(3, #names) do
                    top = top .. string.format("%s %d%%  ", names[i], pct(s.stT[names[i]], s.stTotal))
                end
            end
            _label.Text = string.format(
                "── LUAHOOK LAB ──\n"
                .. "state: %-6s   self-desync: %s\n"
                .. "enemy desync: %.1f studs/frame%s\n"
                .. "cheaters detected: %d\n"
                .. "fire: %d shots/s   hit-events/s: %.1f\n"
                .. "DEALT: %d   TAKEN: %d   trade x%.2f\n"
                .. "we die while:\n"
                .. "  ATTACK %d (%d%%)  TRANS %d (%d%%)  HIDE %d (%d%%)  RELOAD %d (%d%%)\n"
                -- BLANK must read 0 forever (a shot refused for failing |eye-char2|<=400). BELOW-PLANE is the
                -- kill-floor-clamp removal readout: frames parked under the fallen-parts sweep, and deaths
                -- attributed to one. deaths staying 0 across a soak is what licenses the unclamped park.
                -- RESTORE-INDEPENDENCE checks: LATCH = captures refused because no restore landed after a park
                -- (studs = how far that pose sat from the park), ORDER = a restore ran after the park inside one
                -- Heartbeat, OOB-park = a legacy counter with no incrementer since Apex was deleted (so it is now
                -- a constant 0 rather than a live check). All three MUST read 0 forever.
                -- REAL-SHOT LEAK: the two counters that decide the stray-tracer question. LEAK = real
                -- StartShooting packets the __namecall backstop dropped; TRACER = real _LocalTracers calls
                -- suppressed (the visible wall/sky line). Unlike every other canary here these are EXPECTED
                -- to be non-zero if the leak theory is right -- they are a measurement, not an alarm. Both
                -- staying 0 across a fight while strays are still seen would FALSIFY the theory outright.
                -- @polarcore-seam:S41 DRIFT — the underground readout, and the only live evidence for it.
                -- Frames the body was found >1.5 studs off the park we wrote last Heartbeat, plus the size
                -- of the most recent one. Under the default restore mode nothing but the physics solver can
                -- move it in that window, so a climbing count against a target standing under the map IS
                -- the ejection: we park inside rock, the solver pushes us out through the floor, and the
                -- operator ends up above a target he cannot hit. Expected 0 against a normal target and
                -- expected NON-ZERO against a buried one -- like LEAK/TRACER this is a measurement, not an
                -- alarm. If it stays 0 while the symptom is still seen, the diagnosis is wrong: look at
                -- target selection next, not at the park.
                .. "BLANK %d   below-plane %d f / %d deaths   DRIFT %d f (%d st, y%+d)  CLAMP %d\n"
                -- @polarcore-seam:S39 BAIT — one-frame evacuations of the attack park to the lip of a
                -- zero-delay kill volume. This is the counter the seam never had: it was gated for a week
                -- on a measurement asking "did we get hit less", which this mechanism structurally cannot
                -- move. It scores when a PURSUING ragebot follows our replicated body in and dies. Rising
                -- BAIT with our own deaths flat is it working; BAIT rising alongside our deaths means the
                -- destination is inside the volume rather than under it -- make the offset more negative.
                -- @polarcore-seam:S45 VOIDFIRE — packets sent THROUGH an opponent's hide, by gluing to their
                -- hitbox instance while their coordinate is past SANE_POS_LIMIT. This is the counter that
                -- says whether the UE fix is running at all. Against UE it should climb every cycle; if it
                -- reads 0 the seam did not execute and nothing about the mechanism has been tested -- check
                -- Rage._gumDiag() for the resolved gum mode first. Requires GUM = on.
                .. "BAIT %d   VOIDFIRE %d\n"
                .. "LEAK %d   TRACER %d\n"
                .. "LATCH %d (%.1f st)   ORDER %d   OOB-park %d\n"
                -- S9/S28 readout, and the single most important line here now. `phys` ends in one of:
                --   verified          every flag read back correct -> the assembly history is undecimated,
                --                     so the park is on the wire the instant it is written and the restore
                --                     runs during the burst. This is Kicia's configuration. RESTORE=on.
                --   set, unreadable   no getfflag on this executor. RESTORE=off unless RagePerfectRestore
                --                     is "force" -- flip it only if you accept the gamble.
                --   REFUSED / no fflag setter   the flags did not take. RESTORE=off, and Polar is running
                --                     exactly the S27 build that was confirmed working. Not a bug.
                -- RESTORE is the decision that came out of it, so the two are read together.
                .. "phys %s  raw %s  RESTORE %s\n"
                -- THE ORACLE. The server's own verdict on every forged round. ON/OFF is hits landed on the
                -- rage target vs anywhere else. The two distances are for the LAST off-target impact:
                -- from-self small (single/low-double digits) means the server resolved that shot from our
                -- REAL pose, so the park had not replicated. OFF staying 0 through a fight where the
                -- operator still SEES a wall round means the round is not one of our packets at all.
                .. "SERVER: on %d  off %d   last off: %.0fst from me / %.0fst from target\n"
                -- KNIFE: swings sent, and WHY the last frame did or did not swing. "no item" / "cooldown" /
                -- "no StartAiming enum" / "send failed" / "swinging". Added after the bot failed silently.
                .. "KNIFE: %d swings   %s\n"
                -- WHERE THE ROUND WENT. Percent of wall-clock time spent in each of 07c's tick statuses,
                -- top 3. "Attacking" is the only one that can deal damage; everything else is a named
                -- reason we were not shooting. A round that feels weak and a round that feels perfect
                -- differ HERE first — this line says whether we were rejected or simply absent.
                .. "TIME(%ds): %s",
                combatState(), sdStr, enemyDesync(), tgtTag, cheaters,
                s.sps, s.eps, dealt, taken, ratio,
                math.floor(s.takenAtk), pct(s.takenAtk, s.taken),
                math.floor(s.takenTrans), pct(s.takenTrans, s.taken),
                math.floor(s.takenHide), pct(s.takenHide, s.taken),
                math.floor(s.takenReload), pct(s.takenReload, s.taken),
                State.RageBlankCanary or 0,
                State.RageBelowPlaneFrames or 0, State.RageBelowPlaneDeaths or 0,
                State.RageParkDriftFrames or 0, State.RageParkDrift or 0, State.RageParkDriftY or 0,
                State.RageParkClampFrames or 0,
                State.RageTranslocateBaits or 0, State.RageVoidFires or 0,
                State.RageLeakCanary or 0, State.RageTracerCanary or 0,
                State.RageParkLatchCanary or 0, State.RageLatchStuds or 0,
                State.RageOrderCanary or 0, State.RageOOBParkCanary or 0,
                tostring(State.RagePhysRate or "off"), tostring(State.RageRawSet == true), restoreLabel(),
                State.RageHitsOn or 0, State.RageHitsOff or 0,
                State.RageOffFromSelf or 0, State.RageOffFromTarget or 0,
                State.RageKnifeSwings or 0, tostring(State.RageKnifeStatus or "idle"),
                math.floor(s.stTotal), top)
        end)
    end

    function Lab.disable()
        Config.RageLab = false
        if _gui then _gui.Enabled = false end
        if _conn then _conn:Disconnect(); _conn = nil end
        if _hpConn then _hpConn:Disconnect(); _hpConn = nil end
        if _caConn then _caConn:Disconnect(); _caConn = nil end
    end

    function Lab.init() end
end

-- ═══════════════════════════════════════════════════════════════════════════════════════════════
-- 11c_gamevisuals.lua — UNLOCK ALL + SKINS / CHARMS / WRAPS / FINISHERS
-- ═══════════════════════════════════════════════════════════════════════════════════════════════
-- ⚠ REWRITE #13, 2026-08-16. ★ VACATE THE FIELD, NOT THE OBJECT. Finishers: CLONE BEFORE HIDING.
--
-- ── ★★★ THE ONE-LINE ANSWER, AFTER THREE REWRITES ───────────────────────────────────────────────
-- #11 called _CreateViewModel with `item.ViewModel` still pointing at the LIVE viewmodel → nothing
-- happened. #12 destroyed the viewmodel first and then called it with `item.ViewModel` still pointing at
-- the CORPSE → the gun disappeared. Those are not two bugs, they are one: the constructor will not build
-- while that field is occupied, and it hands back whatever is already there. **Destroying the object does
-- not vacate the field** — ClientViewModel.Destroy (:565-587) never touches item.ViewModel — which is
-- exactly why #12 turned "no effect" into "no gun": we adopted the corpse it handed back.
-- #13 clears `item.ViewModel` and only then builds. Nothing is torn down to do it, so a refusal costs one
-- wasted call and the pointer goes straight back; the old viewmodel is destroyed only once a verified
-- replacement is in hand. usableReplacement rejects the same object, an already-_destroyed one, and one
-- with no Model — #12 checked none of those.
--
-- ── ★★ THE HISTORY, IN ONE PLACE, SO NOBODY UNDOES THIS AGAIN ───────────────────────────────────
-- Operator (08-15): "while in game I choose a different skin and it just breaks the gun and breaks
-- stuff." Rewrite #10 responded by DELETING the retrofit and shipping UE's write-Data-then-EquipItem
-- path instead. Operator (08-16 #1): "manual picker only wraps load instantly, skins however need a
-- respawn." Rewrite #11 restored the rebuild but INVERTED Kicia's order — construct, then destroy — so
-- that a throw could not leave the player gunless. Operator (08-16 #2): "still the manual picker only
-- shows the new selected skin after respawn." No broken gun that time; no effect either.
--
-- ★ THAT THIRD REPORT IS THE INFORMATIVE ONE. A constructor that simply declines to build a second
-- viewmodel while item.ViewModel is still live produces exactly it: #11 took either its `fresh == vm` or
-- its `built == false` branch, both of which SETTLE the compare, so the poll never retried.
-- ClientItem._CreateViewModel is inside the VM-obfuscated ClientItem module — unreadable on disk,
-- untestable without a client — so #12 stops reasoning about it and does what the one working rival
-- does. Kicia DESTROYS FIRST (leak :37116-37162). Rewrite #12 keeps #11's construct-first attempt as a
-- free PROBE (if the constructor is re-entrant it is strictly better and costs nothing), falls through
-- to Kicia's exact order when the probe is declined, and adds a third attempt Kicia does not have: if the
-- post-destroy build also fails, rebuild from the LIVE triple so the player gets an unstyled gun back
-- rather than none. A pre-flight refuses to enter the destroy at all unless every payload key resolved to
-- a real enum, which is the one fault that ever produced "it just breaks the gun".
--
-- WHY THE UE PATH CANNOT WORK, from both dumps:
--   * ClientViewModel.new reads Data.Name exactly ONCE (:52) and clones the mesh from it (:55). A skin
--     is therefore fixed at construction — no write to a live viewmodel can change it.
--   * ClientFighter:EquipItem(index) is the weapon-SLOT switch (MechanicsController:447-459 binds keys
--     1-4 to it). It changes which viewmodel renders, never what one looks like.
--   * UE has no rebuild anywhere. Its cosmetic changer is proto 259 -> 286
--     (SafeUpdateLocalEquippedItemID: writes .Name at pc 108, item.ViewModel.Data at pc 218-219 through
--     ToEnum, reads EquippedItem.Data.ItemIndex at pc 261-263, calls EquipItem at pc 65/183) plus a
--     birth hook (root pc 16069 assigns _CreateViewModel = proto 804, which mutates the serial). Its
--     only ItemModel/SetArmsData/_UpdateWrap contact is proto 763, which is its chams system. Its
--     apply-to-all even says so out loud: "cant apply weapon skins to all!" (proto 267).
--   ⇒ UE's manual picker does not restyle the weapon in your hand either. Copying it harder was never
--     going to fix this, which is why #10 measured as a regression.
--
-- KICIA CAN, and does exactly what #10 deleted — `cosmetics.ViewModelReloader._ReloadWithCosmetics`
-- (leak :37101-37190): Destroy the viewmodel, ClientItem._CreateViewModel(item, encoded serial),
-- rawset item.ViewModel, copy the arms data off the fighter, Equip(new, true), zero the equip spring.
--
-- ★ SO WHY DID OURS BREAK THE GUN? Not the rebuild — the SERIAL. The retrofit destroyed first and then
-- handed _CreateViewModel a payload whose inner Data keys were plain strings. ReplicatedClass._Setup
-- (:171-177) calls `SetReplicate(self:FromEnum(k), v)` over every inner key and EnumLibrary.FromEnum
-- ASSERTS on an unregistered one, so construction threw — and item.ViewModel was left pointing at the
-- viewmodel we had already destroyed. That is the whole bug, and it is the same key-domain fault
-- rewrite #8 fixed for the birth path and never for this one.
-- Two changes make that state unreachable rather than merely unlikely:
--   1. the rebuild payload is ENUM-KEYED (enumKey, the encoder styleSerial already uses), and
--   2. we CONSTRUCT BEFORE DESTROYING. A throw or a nil aborts with the old viewmodel still built,
--      still parented and still pointed at — the player keeps their gun and the cosmetic lands at the
--      next natural construction, which is #10's behaviour, i.e. the floor, not a regression.
-- Kicia destroys first and has no such fallback; this is one place we are ahead of it.
--
-- Everything else UE does is KEPT, because it is free and it is what the next construction reads:
-- Data is still written on both the item and the viewmodel through the game's own SetReplicate
-- (ReplicateToClient is `IS_SERVER and Signal.new() or nil`, ReplicatedClass:25, so nothing hits the
-- wire). What is gone is the EquipItem call: a real gameplay action with a draw animation that
-- refreshed nothing.
--
-- ── ★ EMOTES ARE REMOVED, on operator instruction ────────────────────────────────────────────────
-- "it still doesnt work ... just remove it for now, we can finish it later". Every emote surface is
-- gone: the EquippedEmotes mask, the overrides, the cancel watcher, both EmoteController hooks, the GUI
-- controls and the saved slots. The research is NOT lost — the reason it never worked (a local emote has
-- nothing to cancel it, so IsEmoting() stays true and the weapon stops rendering, the arms are disabled
-- for math.huge and the camera sticks in third person) is written up in memory under
-- `emotes-never-end-locally-2026-08-15` for whoever resumes it.
--
-- ── ★ NOTHING PRINTS, AND SINCE 2026-08-16 NOTHING RENDERS THE HISTORY EITHER ────────────────────
-- note() has not printed since #10 (Diagnose is deleted), and on 08-16 the operator removed the status
-- line and the History box from the tab too ("only show what skins are loaded ... remove status asw ppl
-- dont need to know that"). The BUFFER STAYS: note() still writes State.GVStatus and still fills the
-- ring GameVisuals.history() exposes, at no UI cost, because the reason it exists is unchanged — four
-- rewrites shipped with no way to tell "never installed" apart from "installed and did nothing".
-- What the tab shows now is GameVisuals.summary(), and GameVisuals.ready() is what lets it say
-- "not active yet" instead of looking empty and broken.
--
-- ── BUG B · UNLOCK ALL DID NOT DRIVE THE GAME'S OWN MENU ────────────────────────────────────────
-- .../Equipment/Interface/Customize/Cosmetics.luau:
--     :138  IsLocked = not CosmeticLibrary:OwnsCosmetic(Get("CosmeticInventory"), name, weapon)
--     :208  if selectedWeapon and (not IsLocked and IsWeaponCosmetic) then
--               Remotes.Data.EquipCosmetic:FireServer(weapon, type, name, { IsInverted = ... })
-- so a LOCKED slot never equips — unlock-all is a hard prerequisite — and an UNLOCKED one hands the
-- pick to the SERVER, which rejects a cosmetic we do not own. Nothing ever told us what was clicked.
-- CosmeticLibrary:OwnsCosmeticNormally is `inv[name] == true` (:74-78) and OwnsCosmetic short-circuits
-- on it (:80-82), so a flat `true` is sufficient and weapon-independent — #7's per-weapon set was
-- unnecessary and broke PickEmote:149, which calls OwnsCosmetic with NO weapon argument.
-- PlayerDataUtility.GetWeaponData (:112-118) only iterates `Get("WeaponInventory")`, so the equipped
-- tick, the Inverted button and OnlyUseFavorites all come through the data mask with NO function hook.
--
-- ── HOW THE THREE RIVALS ACTUALLY DO THIS ───────────────────────────────────────────────────────
--   daydreamer  the GAME'S OWN menu. Its entire cosmetics GUI is one toggle (cosmetics.lua:1120-1134).
--               Replaces 8 functions (dctrl.Get, CurrentData.Get, GetWeaponData, 5x OwnsCosmetic*) and
--               swallows the equip with hookmetamethod(game,"__namecall") (:896, :974-984).
--   Kicia       the GAME'S OWN menu, via SlotBinder (leak 90605-90765): setupvalues a proxy over the
--               CosmeticSlot prototype, and when `Frame` is touched from a caller whose source matches
--               "Cosmetics$" it does debug.setupvalue(caller, 9, false) — upvalue 9 of generate_slot is
--               IsWeaponCosmetic, so the :208 guard goes false and THE REMOTE NEVER FIRES. It then
--               connects its own MouseButton1Click to observe the pick. Two mechanisms, one guessed index.
--   UE          its OWN popout, "Cosmetic Changer" (dump proto 259) with a live 3D viewport grid
--               (proto 273: ApplyWrap / RecordOriginalWrapProperties / PivotTo). NO unlock-all at all —
--               EquipCosmetic, OwnsCosmetic, CosmeticInventory, WeaponInventory are 0 occurrences.
--
-- ── WHAT WE DO INSTEAD (one mechanism where Kicia needs two) ─────────────────────────────────────
-- generate_slot's upvalue for ReplicatedStorage is used at exactly ONE place in the whole module — the
-- equip fire at :217 (verified: v_u_1 appears only at :3, :5-8 module init, and :217). So swapping that
-- ONE upvalue for a decoy both SUPPRESSES the wire and DELIVERS (weapon, type, name, opts) with the
-- game's own arguments and its own IsInverted flag. Resolved by CLASS IDENTITY, never by index.
--
-- ── THE GOVERNING FACT: three cosmetics, three DIFFERENT refresh semantics ───────────────────────
--   SKIN   ViewModel.Data.Name   read ONCE, ClientViewModel.new :43-52  -> needs a NEW viewmodel
--   WRAP   ViewModel.Data.Wrap   read on EVERY call, GetWrap :217-224   -> live, applies instantly
--   CHARM  ViewModel.Data.Charm  read ONCE, _Setup :910                 -> needs a NEW viewmodel
-- CHARM is worse than SKIN: _Setup DESTROYS _charm_pivot_attachment when the item is built with no
-- charm, so a gun that spawned bare cannot grow one until it is next constructed.
-- ⇒ WRAP is settled in place, with no rebuild and no draw animation. SKIN and CHARM are written into
--   Data and then need a construction, so Layer 4 makes the game perform one.
--
-- ★ WRAP HAS A PRECONDITION NOBODY EVER CHECKED. GetWrap :219 is
--       local v56 = ClientItem.ClientFighter:Get("IsSpectating") or not GetSetting("Wraps Disabled")
--       if v56 then v56 = self:Get("Wrap") end
--   so with "Wraps Disabled" ON in the game's own settings NO wrap ever resolves. The history reports it.
--
-- ── THE LAYERS ──────────────────────────────────────────────────────────────────────────────────
--   0 · MASK      one table swap on CurrentData.Data covers every reader of CosmeticInventory,
--                 WeaponInventory and FavoritedCosmetics. No accessor is replaced.
--   1 · CAPTURE   CosmeticSlot.new + the ReplicatedStorage upvalue decoy. The game's own menu becomes
--                 the selection surface and nothing reaches the server.
--   2 · BIRTH     _ci._CreateViewModel + _cvm.new — mutate the serial before the game constructs.
--   3 · RESOLVER  _cvm.GetWrap, _fctrl.GetWrap, _ilib.GetViewModelImageFromWeaponData, _cent.
--                 ReplicateFromServer. The game asks these every time, so a wrap needs no Data write.
--   4 · APPLY     wrap live in place; skin/charm through Kicia's rebuild — probe once with the old
--                 viewmodel alive, then destroy-and-build in Kicia's order, then a bare recovery build.
--                 Data is written on whatever viewmodel exists afterwards either way, so a refused
--                 rebuild degrades to "lands at the next construction" and never to no gun.
--
-- ── ★ FINISHERS PLAY ON A CLONE (2026-08-16) ────────────────────────────────────────────────────
-- ⚠ #12 CLONED THE BODY *AFTER* HIDING IT, so the finisher played on an invisible copy — operator: "i
-- just dont see the person i killed its just the effects". Kicia acquires the clone first and hides only
-- once it holds one (leak :142722-142729). #13 goes one step further and hides only after the copy's
-- Humanoid and HumanoidRootPart are confirmed, so a failed clone leaves the real body untouched and the
-- game's own finisher still has something to play on.
-- ★ UE DOES SHIP A FINISHER CHANGER (an earlier note here said it did not — that was wrong). It reaches
-- the same place by a different door: debug.getconstants on ClientEntity.ReplicateFromServer, then
-- debug.setconstant of "_PlayFinisher" to "\0_PlayFinisher " (dump root pc 14472 / 14610 / 19001 / 17738)
-- with its own method installed under the new key. But UE's body has NO PlayServer, PlayClient, SetSerial
-- or NoCollisionConstraint anywhere in 948 protos — it renames the finisher and calls the game's original.
-- So UE gets PlayClient only and has the exact limitation being fixed here. Kicia's clone is the only
-- mechanism on disk that recovers the PlayServer half.
-- Operator: "the effects of it works but the enemy animations dont." A Rivals finisher is TWO halves
-- (Modules/Finisher.luau): PlayClient is particles, sound and the victim's animation; PlayServer is
-- _Ragdoll / _AnchorModel / _HideBody / Knockback — and Ragdoll.luau's PlayClient is EMPTY, so a whole
-- family of finishers is nothing but PlayServer. ClientEntity:_PlayFinisher (:207-224) runs PlayClient
-- alone, because the server ran the other half on the real body — the WRONG finisher's half, once we
-- substitute. Running the right PlayServer on the real character is not open to us either: it destroys
-- server-owned Motor6Ds. Kicia's FinisherHook (leak :142616-142676) solves both by playing on a CLONE it
-- owns: hide the real corpse, clone it, zero the clone's health, de-collide its parts, and run BOTH
-- halves locally. GVFinisherClone gates it; off restores the old PlayClient-only behaviour.
--
-- ⚠ THE HONEST RISK. Layers 1-3 replace functions on live game classes, which IS the surface class of
-- the changer that got detected. Two working rivals do exactly this. GVBirthHook gates all of it so it
-- can be switched off without losing unlock-all, and every replacement is saved and put back.
-- ═══════════════════════════════════════════════════════════════════════════════════════════════

local GameVisuals = {}
GameVisuals.uiAlive = true   -- cleared by 13_gui's Unload override so the status mirror stops with the GUI
;(function()
    local NONE_COSMETIC   = "NONE_COSMETIC"
    local RANDOM_COSMETIC = "RANDOM_COSMETIC"
    -- The apply poll. With the birth hook live this is not the primary path — it only catches a weapon
    -- that already existed when a selection changed. Cheap: three table reads per item, allocating
    -- nothing when it matches.
    local POLL_S = 0.35
    -- ★ REBUILD DEBOUNCE. The live rebuild tears down and re-creates a viewmodel, so it must happen ONCE
    -- per change and never on a poll tick. Guards against a selection the game refuses to honour turning
    -- the 0.35 s poll into a rebuild loop.
    local REBUILD_COOLDOWN = 1.5

    -- The capture hooks live at the bottom because they need helpers defined above, but enable/disable
    -- reference them — hence the forward declarations. A `local function` written after a caller leaves
    -- that caller reading a nil GLOBAL of the same name (the trap that shipped as "attempt to compare
    -- nil < number"); the build's `declorder` gate now covers `local function` too.
    local captureInstall, captureRestore
    -- Same reason again: the setters above the persistence block call saveSoon, and enable()'s Heartbeat
    -- calls saveDrain. Declared as locals rather than left to become accidental GLOBALS — this file is
    -- concatenated into one chunk with 22 other modules, so a stray global is a name collision waiting.
    local saveSoon, saveDrain

    -- ★ THE HISTORY IS THE ONLY OUTPUT CHANNEL NOW. note() used to print every line to the console and
    -- Diagnose dumped the whole resolution chain there; both are gone on operator instruction ("avoid
    -- printing results or diagnose to console, user doesnt need that, only to know history of what was
    -- done"). What is NOT gone is the information — every refusal still lands here, and 13_gui renders
    -- the tail of it. That matters: four rewrites of this feature shipped with no way to tell "the
    -- mechanism never installed" apart from "it installed and did nothing", and this buffer is the fix
    -- for exactly that. Moving the channel is fine; deleting it would be a regression.
    local _log, _lastNote = {}, nil
    local function note(msg)
        State.GVStatus = msg
        -- A failing apply is retried every poll, so without the de-dup the history fills with one
        -- repeated line. Repeats still update the status label; only the log entry is skipped.
        if msg == _lastNote then return end
        _lastNote = msg
        table.insert(_log, os.date("%H:%M:%S") .. "  " .. msg)
        if #_log > 60 then table.remove(_log, 1) end
    end

    -- Newest first, because the GUI shows the tail and the last thing that happened is the thing you
    -- opened the panel to read.
    function GameVisuals.history(n)
        local out = {}
        local want = n or 12
        for i = #_log, math.max(1, #_log - want + 1), -1 do table.insert(out, _log[i]) end
        if #out == 0 then table.insert(out, "nothing yet") end
        return out
    end

    local ENUM = {}
    local function enumOf(key)
        if ENUM[key] ~= nil then return ENUM[key] end
        local e = nil
        -- EnumLibrary:ToEnum ASSERTS when the name is unregistered, so this must stay pcall'd.
        -- ReplicatedClass:ToEnum (:103-106) just delegates to this same singleton, so calling it here
        -- is equivalent to daydreamer's `citem_inst:ToEnum(...)` / `rclass:ToEnum(...)`.
        pcall(function() e = Rivals.Enums:ToEnum(key) end)
        ENUM[key] = e
        return e
    end

    -- ── MODULE RESOLUTION ───────────────────────────────────────────────────────────────────────
    -- One table rather than nine locals, which keeps this IIFE well clear of the 190-register proto cap.
    local M = { cvm = nil, ci = nil, pdc = nil, fctrl = nil, ilib = nil, cent = nil,
                cslot = nil, copts = nil, shop = nil }

    local function moduleAt(path)
        local m = nil
        pcall(function() m = loadGameModule(lp.PlayerScripts, path) end)
        return m
    end

    local function repModuleAt(path)
        local m = nil
        pcall(function() m = loadGameModule(ReplicatedStorage, path) end)
        return m
    end

    -- loadGameModule BLOCKS (WaitForChild + a load wait, 01_bootstrap L234-238), so this yields. An
    -- earlier version set a `_resolved` flag BEFORE doing the work, which meant a second caller arriving
    -- during the yield cached the nils as final and poisoned the module for the whole session. Cache
    -- only what succeeded, guard re-entry, and back off between retries so enabling in the lobby (before
    -- these modules exist) cannot turn the poll into a stall generator.
    -- ⚠ EVERY MISS COSTS TEN SECONDS. waitModule uses WaitForChild(name, 10) per path element
    -- (01_bootstrap L173-182), and this runs from the Heartbeat poll — so an optional module that does
    -- not exist on this build would stall the poll for 10 s every backoff window, forever. The core
    -- four are retried until they resolve because nothing works without them; the four optional ones
    -- get a hard THREE attempts and are then given up on, which Diagnose reports as a plain nil.
    local _resolving, _resolveAt, _optTries = false, 0, 0
    local function resolveModules()
        if M.cvm ~= nil and M.ci ~= nil and M.pdc ~= nil and _optTries >= 3 then return end
        if M.cvm ~= nil and M.ci ~= nil and M.pdc ~= nil and M.cslot ~= nil
            and M.copts ~= nil and M.shop ~= nil then return end
        if _resolving then return end
        local now = tick()
        if now < _resolveAt then return end
        _resolveAt = now + 5
        _resolving = true
        if M.cvm == nil then
            M.cvm = moduleAt({"Modules","ClientReplicatedClasses","ClientFighter","ClientItem","ClientViewModel"})
        end
        if M.ci   == nil then M.ci   = moduleAt({"Modules","ClientReplicatedClasses","ClientFighter","ClientItem"}) end
        if M.cent == nil then M.cent = moduleAt({"Modules","ClientReplicatedClasses","ClientEntity"}) end
        if M.pdc  == nil then M.pdc  = moduleAt({"Controllers","PlayerDataController"}) end
        if _optTries < 3 then
            _optTries = _optTries + 1
            -- The equip-capture targets. CosmeticSlot is required by exactly two modules (Customize's
            -- Cosmetics.luau and NameDisplay.luau), which is what makes the hook's source guard exact.
            if M.cslot == nil then M.cslot = moduleAt({"Modules","CosmeticSlot"}) end
            if M.copts == nil then
                M.copts = moduleAt({"Modules","UserInterface","Equipment","Interface","Customize","Options"})
            end
            if M.shop  == nil then M.shop  = repModuleAt({"Modules","ShopLibrary"}) end
        end
        if M.fctrl == nil then M.fctrl = Rivals.Fighter end
        if M.ilib  == nil then M.ilib  = Rivals.ItemLib end
        _resolving = false
    end

    -- ── SELECTION STORE ─────────────────────────────────────────────────────────────────────────
    -- daydreamer's shape (cosmetics.lua:839-864): Choices[weaponName][cosmeticType] = <record table>,
    -- where the type is the GAME's own capitalised label — "Skin" / "Charm" / "Wrap" / "Finisher" —
    -- and the record is a full CosmeticLibrary clone. "Cleared" is the sentinel record
    -- { Name = NONE_COSMETIC }, never nil, so "no charm" and "charm unchanged" stay different values.
    GameVisuals.Choices = {}

    local function selectionFor(itemName)
        return GameVisuals.Choices[itemName]
    end

    -- ── LAYER 0 · THE DATA MASK ─────────────────────────────────────────────────────────────────
    -- Kicia's technique and NOT daydreamer's. `ReplicatedClass.Get` is literally `return self.Data[key]`
    -- (:41) and `PlayerDataController.Get` is `self.CurrentData:Get(...)` (:27), so swapping the Data
    -- TABLE covers dctrl:Get, CurrentData:Get, GetWeaponData and every raw `.Data[k]` read with no
    -- function replacement anywhere. daydreamer instead replaces eight accessors for the same result.
    local _maskTarget, _maskInner, _maskConn = nil, nil, nil
    local _spoof = {}
    -- [weapon][cosmeticName] = true. Written by the swallowed FavoriteCosmetic click so the star in the
    -- game's own menu still lights, and read by everyFavorite. Nothing about it reaches the server.
    local _favOverride = {}

    -- ⚠ EQUIP-CAPTURE STATE, DECLARED HERE AND NOT WITH LAYER 1 AT THE BOTTOM — ON PURPOSE.
    -- GameVisuals.enable's Heartbeat closure reads _captureBound, and enable() is defined ABOVE Layer 1.
    -- A `local` written after that closure leaves it reading a nil GLOBAL of the same name, and the poll
    -- then dies on `nil < 2` every frame. That shipped: "attempt to compare nil < number". It is the
    -- exact trap already documented for _oidWeapon a few hundred lines down, hit a second time, and it
    -- is now caught for every local in the bundle by the build's `declorder` gate.
    --   _captureBound  reaches 2 when both doors are covered (cosmetic rows + option buttons)
    --   _captured      how many equip clicks actually landed in the decoy
    --   _lastFn        the last generate_slot we patched, so a hundred-row page pays one upvalue scan
    local _rsPatch, _captured, _captureBound = {}, 0, 0
    local DECOY, _lastFn = nil, nil

    -- Persistence state, up here for the same declare-above-use reason: disable() flushes a pending save
    -- and disable() is defined above the persistence block.
    local _saveAt, _fsWarned = nil, false

    local function maskActive()
        if _maskTarget == nil then return false end
        local cur = nil
        pcall(function() cur = M.pdc.CurrentData end)
        return cur == _maskTarget
    end

    local function maskRemove()
        if _maskTarget == nil then return end
        local target, inner = _maskTarget, _maskInner
        _maskTarget, _maskInner = nil, nil
        pcall(function() rawset(target, "Data", inner) end)
    end

    local function maskInstall()
        resolveModules()
        if M.pdc == nil then return false, "PlayerDataController did not resolve" end
        local cur = nil
        pcall(function() cur = M.pdc.CurrentData end)
        if cur == nil then return false, "no CurrentData yet (still loading)" end
        if cur == _maskTarget then return true, nil end
        -- CurrentData was replaced under us: drop the stale proxy before taking the new one.
        maskRemove()
        local inner = rawget(cur, "Data")
        if type(inner) ~= "table" then return false, "CurrentData.Data is not a table" end
        local proxy = setmetatable({}, {
            __index = function(_, k)
                local p = _spoof[k]
                if p ~= nil then return p(inner[k]) end
                return inner[k]
            end,
            -- Writes MUST pass through, or every legitimate write the game makes to player data is
            -- silently discarded — far worse than not masking at all.
            __newindex = function(_, k, v) inner[k] = v end,
            -- Kicia's proxy is an empty table, so Data.X returns a value while pairs(Data) yields
            -- nothing: an object that behaves impossibly under next/serialisation, and one of the five
            -- tells that made the DETECTED changer obvious. Ours agrees with itself.
            __iter = function() return next, inner end,
            __len  = function() return #inner end,
        })
        rawset(cur, "Data", proxy)
        _maskTarget, _maskInner = cur, inner
        return true, nil
    end

    -- Client-side `Replicate(key)` fires ONLY `_value_changed_events[key]` — ReplicatedClass :57-68
    -- with `ReplicateToClient = IS_SERVER and Signal.new() or nil` (:25), so on the client it is always
    -- nil. Zero wire traffic, zero server involvement: it is the game's own "re-render, my data changed"
    -- bus and it is free to ring. Every reader in the equip menu is wired to it (Cosmetics.luau:267-282).
    local function refresh(key)
        pcall(function()
            local cur = M.pdc.CurrentData
            if cur ~= nil then cur:Replicate(key) end
        end)
    end

    local function refreshAll()
        refresh("CosmeticInventory")
        refresh("FavoritedCosmetics")
        refresh("WeaponInventory")
    end

    -- ★ THE INVENTORY VALUE SHAPE, settled from the game's own source. CosmeticLibrary:74-82:
    --     OwnsCosmeticNormally(inv, name)     -> inv[name] == true
    --     OwnsCosmeticUniversally(inv, name)  -> inv[name].IsUniversal
    --     OwnsCosmeticForWeapon(inv,name,wep) -> inv[name][wep]
    --     OwnsCosmetic(...)                   -> Normally or Universally or ForWeapon
    -- A flat `true` satisfies the FIRST branch and short-circuits, so it is owned for every weapon and
    -- for the no-weapon call PickEmote:149 makes. #7 wrote a per-weapon SET for charms/wraps/finishers,
    -- which forced the third branch and left emotes resolving `inv[name][nil]` -> nil. daydreamer's
    -- `unlockcos` (cosmetics.lua:214-222) writes a flat true; so do we.
    local function everyCosmetic(real)
        local out = {}
        if type(real) == "table" then
            for k, v in pairs(real) do out[k] = v end
        end
        pcall(function()
            local cos = Rivals.Cosmetics.Cosmetics
            if type(cos) ~= "table" then return end
            for name, entry in pairs(cos) do
                if type(entry) == "table" and out[name] == nil then out[name] = true end
            end
        end)
        return out
    end

    -- The game indexes this two levels deep — FavoritedCosmetics[weapon][name] (Cosmetics.luau:42-45)
    -- — so the per-weapon table has to be copied too, or writing our overlay into it would mutate the
    -- player's real saved favourites.
    local function everyFavorite(real)
        local out = {}
        if type(real) == "table" then
            for k, v in pairs(real) do out[k] = v end
        end
        for weapon, marks in pairs(_favOverride) do
            local merged = {}
            if type(out[weapon]) == "table" then
                for k, v in pairs(out[weapon]) do merged[k] = v end
            end
            for k, v in pairs(marks) do merged[k] = v end
            out[weapon] = merged
        end
        return out
    end

    -- daydreamer's `mergeequipped` (cosmetics.lua:318-329). The NONE sentinel clears the field rather
    -- than writing a record, because the game reads `weaponData[type]` and tests it for nil.
    local function mergeChoices(entry, weapon)
        local slot = GameVisuals.Choices[weapon]
        if slot == nil then return entry end
        for _, kind in pairs({ "Skin", "Charm", "Wrap", "Finisher" }) do
            local sel = slot[kind]
            if sel ~= nil then
                if sel.Name == NONE_COSMETIC then
                    entry[kind] = nil
                elseif sel.Name == RANDOM_COSMETIC then
                    entry[kind] = sel
                else
                    entry[kind] = sel
                end
            end
        end
        return entry
    end

    local function ownableWeapons()
        local out = {}
        pcall(function()
            if M.shop == nil or type(M.shop.GetReleasedOwnableWeapons) ~= "function" then return end
            local list = M.shop:GetReleasedOwnableWeapons()
            if type(list) ~= "table" then return end
            for _, name in pairs(list) do
                if type(name) == "string" then table.insert(out, name) end
            end
        end)
        return out
    end

    -- ★ THIS IS WHAT MAKES THE GAME'S OWN MENU SHOW OUR PICKS AS EQUIPPED, with no function hook at all.
    -- PlayerDataUtility.GetWeaponData (:112-118) is pure — it only walks Get("WeaponInventory") looking
    -- for `.Name` — and Customize/Cosmetics.luau:79 reads `GetWeaponData(weapon)[type]` for the tick,
    -- while Options.luau:53,132,156 reads it for Inverted and OnlyUseFavorites. daydreamer hooks
    -- GetWeaponData to do this; we do not have to, because we own the table it reads.
    local function weaponInventory(real)
        local out, seen = {}, {}
        if type(real) == "table" then
            for i, entry in pairs(real) do
                if type(entry) == "table" then
                    local copy = {}
                    for k, v in pairs(entry) do copy[k] = v end
                    if type(copy.Name) == "string" then
                        seen[copy.Name] = true
                        mergeChoices(copy, copy.Name)
                    end
                    out[i] = copy
                else
                    out[i] = entry
                end
            end
        end
        if Config.GVUnlockWeapons == true then
            for _, wname in pairs(ownableWeapons()) do
                if not seen[wname] then
                    seen[wname] = true
                    table.insert(out, mergeChoices(
                        { Name = wname, Level = 1, XP = 0, IsFavorited = false }, wname))
                end
            end
        end
        return out
    end

    local function applyMaskFields()
        if Config.GVUnlockAll == true then
            _spoof.CosmeticInventory = everyCosmetic
        else
            _spoof.CosmeticInventory = nil
        end
        -- Favourites are independent of unlock-all: the star can be clicked on something we really own.
        if Config.GVUnlockAll == true or next(_favOverride) ~= nil then
            _spoof.FavoritedCosmetics = everyFavorite
        else
            _spoof.FavoritedCosmetics = nil
        end
        -- WeaponInventory carries the SELECTION, not the unlock, so it is live whenever anything is
        -- chosen — otherwise the menu shows no tick for a skin that is visibly on the gun.
        if next(GameVisuals.Choices) ~= nil or Config.GVUnlockWeapons == true then
            _spoof.WeaponInventory = weaponInventory
        else
            _spoof.WeaponInventory = nil
        end
    end

    local function maskNeeded()
        return Config.GVUnlockAll == true or Config.GVUnlockWeapons == true
            or next(GameVisuals.Choices) ~= nil or next(_favOverride) ~= nil
    end

    -- ★ MASK LIFETIME. `PlayerDataController._CreatePlayerData` REPLACES CurrentData with a fresh
    -- ClientPlayerData and fires PlayerDataAdded — on the startup _RequestPlayerData and on every
    -- server push. Installing once orphans the proxy on the first push and unlock-all then dies with no
    -- error anywhere. Kicia connects that signal and re-installs; so do we.
    local function watchPlayerData()
        if _maskConn ~= nil then return end
        pcall(function()
            local sig = M.pdc.PlayerDataAdded
            if sig == nil then return end
            _maskConn = sig:Connect(function()
                if not maskNeeded() then return end
                task.defer(function()
                    if maskInstall() then
                        applyMaskFields()
                        refreshAll()
                    end
                end)
            end)
        end)
    end

    local function syncMask()
        applyMaskFields()
        if not maskNeeded() then
            maskRemove()
            refreshAll()
            return true, nil
        end
        local ok, why = maskInstall()
        if not ok then return false, why end
        watchPlayerData()
        refreshAll()
        return true, nil
    end

    function GameVisuals.setUnlockAll(on)
        Config.GVUnlockAll = (on == true)
        local ok, why = syncMask()
        if ok then
            note("unlock all " .. tostring(Config.GVUnlockAll))
        else
            note("unlock all: " .. tostring(why))
        end
    end

    function GameVisuals.setUnlockWeapons(on)
        Config.GVUnlockWeapons = (on == true)
        local ok, why = syncMask()
        if ok then
            note("unlock weapons " .. tostring(Config.GVUnlockWeapons))
        else
            note("unlock weapons: " .. tostring(why))
        end
    end

    -- ── THE PAYLOAD ─────────────────────────────────────────────────────────────────────────────
    -- `ResolveMetadata` returns non-nil only for a "Season N" charm, yielding {SeasonELO,
    -- SeasonLeaderboardRank} — read ONLY by _SetupSeasonRankCharm (Charm.luau :90-97). We do not fake
    -- season ranks, so this is always nil. Kept as the one named seam rather than deleted, because
    -- omitting Metadata entirely is a real behaviour and a season-charm feature plugs in exactly here.
    local function charmMetadata(_)
        return nil
    end

    -- daydreamer's `clonecos` (cosmetics.lua:260-282), verbatim in behaviour.
    local function cloneCosmetic(name, ctype, inverted)
        local base = nil
        pcall(function() base = Rivals.Cosmetics.Cosmetics[name] end)
        if type(base) ~= "table" then return nil end
        local data = {}
        for k, v in pairs(base) do data[k] = v end
        data.Name = name
        if data.Type == nil then data.Type = ctype end
        -- The game seeds RANDOM_COSMETIC resolution from this; a real equipped record carries one.
        data.Seed = math.random(1, 1000000)
        local id = enumOf(name)
        if id ~= nil then
            data.Enum     = id
            data.ObjectID = id
        end
        if inverted == true then data.Inverted = true end
        if ctype == "Charm" then
            local md = charmMetadata(name)
            if md ~= nil then data.Metadata = md end
        end
        return data
    end

    -- daydreamer's `getrandomcos` (cosmetics.lua:284-303): pick uniformly from what the GAME says we
    -- own, which with unlock-all on is everything. Skins additionally must belong to this weapon.
    local function randomCosmetic(ctype, weapon, inverted)
        local pool = {}
        pcall(function()
            local cos = Rivals.Cosmetics.Cosmetics
            local inv = M.pdc and M.pdc:Get("CosmeticInventory")
            if type(cos) ~= "table" then return end
            for name, entry in pairs(cos) do
                if type(entry) == "table" and entry.Type == ctype and entry.Hidden ~= true then
                    local owned = true
                    pcall(function() owned = Rivals.Cosmetics:OwnsCosmetic(inv, name, weapon) and true or false end)
                    if owned and (ctype ~= "Skin" or entry.ItemName == weapon) then
                        table.insert(pool, name)
                    end
                end
            end
        end)
        if #pool == 0 then return nil end
        return cloneCosmetic(pool[math.random(#pool)], ctype, inverted)
    end

    -- daydreamer's `resolvecos` (cosmetics.lua:305-316). Returns the record to apply, or nil for
    -- "leave the game's own value alone". The NONE sentinel resolves to nil here and is turned into an
    -- explicit clear by the caller that needs one.
    local function resolveSel(weapon, ctype)
        local slot = GameVisuals.Choices[weapon]
        local sel = slot and slot[ctype]
        if sel == nil then return nil end
        if sel.Name == NONE_COSMETIC then return nil end
        if sel.Name == RANDOM_COSMETIC then
            -- ★ THE ROLL IS MEMOISED, AND IT HAS TO BE. resolveSel is called from the retrofit poll as
            -- well as from the birth hook, and the poll compares the live viewmodel's Data.Name against
            -- whatever this returns. Re-rolling per call means the two never match, so a Random skin
            -- would destroy and rebuild the weapon every POLL_S — three times a second, forever.
            -- daydreamer never meets this because it is birth-only and has nothing to compare against.
            -- Cleared by setFor, so re-picking Random is what re-rolls.
            if sel.Resolved == nil then
                sel.Resolved = randomCosmetic(ctype, weapon, sel.Inverted)
            end
            return sel.Resolved
        end
        return sel
    end

    -- True when the operator has expressed ANY intent for this weapon, including "clear it".
    local function hasIntent(weapon, ctype)
        local slot = GameVisuals.Choices[weapon]
        return slot ~= nil and slot[ctype] ~= nil
    end

    -- The three keys ClientViewModel actually reads. Writes into `dst` under `key(...)`, which is
    -- identity for the retrofit's plain string-keyed base and enumKey for the live serial.
    local function buildPayload(weapon, dst, key)
        if hasIntent(weapon, "Skin") then
            local s = resolveSel(weapon, "Skin")
            dst[key("Name")] = (s ~= nil) and s.Name or weapon
        end
        if hasIntent(weapon, "Wrap") then
            dst[key("Wrap")] = resolveSel(weapon, "Wrap")
        end
        if hasIntent(weapon, "Charm") then
            dst[key("Charm")] = resolveSel(weapon, "Charm")
        end
        return dst
    end

    local function identityKey(k) return k end

    -- ── LAYERS 2 + 3 · THE BIRTH AND RESOLVER HOOKS ─────────────────────────────────────────────
    -- ★ THE MECHANISM. Every entry is saved and put back by hooksRestore; a replaced game function
    -- that outlives our chunk is the same class of bug as an un-reverted debug.setupvalue.
    local HOOKS = {}

    local function hookField(tbl, key, make)
        if tbl == nil then return false end
        local orig = nil
        pcall(function() orig = tbl[key] end)
        if type(orig) ~= "function" then return false end
        for _, h in pairs(HOOKS) do
            if h.tbl == tbl and h.key == key then return true end
        end
        -- ★ OWN PROPERTY OR INHERITED? Some of these targets are module tables where the function is a
        -- plain field; others are singletons whose methods live on a prototype behind __index. Assigning
        -- over an INHERITED method creates a shadow on the instance, and restoring that by assignment
        -- would leave the original function sitting there as a new own-property forever. Deleting the
        -- shadow instead is the true restore. Defaults to `false` if rawget is refused, because
        -- reassigning is the safe direction — clearing a field that was genuinely ours to begin with
        -- would delete the game's real function.
        local inherited = false
        pcall(function() inherited = (rawget(tbl, key) == nil) end)
        local ok = false
        pcall(function()
            tbl[key] = make(orig)
            ok = true
        end)
        if not ok then return false end
        table.insert(HOOKS, { tbl = tbl, key = key, orig = orig, inherited = inherited })
        return true
    end

    local function hooksRestore()
        for i = #HOOKS, 1, -1 do
            local h = HOOKS[i]
            pcall(function()
                if h.inherited then
                    h.tbl[h.key] = nil
                else
                    h.tbl[h.key] = h.orig
                end
            end)
            HOOKS[i] = nil
        end
    end

    -- ★ THE ORIGINAL, NOT OUR WRAPPER. Once hooksInstall has run, reading M.ci._CreateViewModel back off
    -- the module returns the hook we installed — so the live rebuild below would style an already
    -- enum-encoded serial a second time and set the _building breadcrumb for a construction that does not
    -- need it. HOOKS already holds the real function; use it, and fall back to the field only when the
    -- hook is not installed.
    local function origOf(tbl, key)
        if tbl == nil then return nil end
        for _, h in pairs(HOOKS) do
            if h.tbl == tbl and h.key == key then return h.orig end
        end
        local fn = nil
        pcall(function() fn = tbl[key] end)
        return fn
    end

    -- Whose weapon is this? daydreamer gates every hook on `owner == lp` (cosmetics.lua:618-621);
    -- GVEveryone widens that to everyone, which is Kicia's RemoteViewModelRefresher behaviour and is
    -- equally invisible to them — it only repaints their guns on OUR screen.
    local function ownedByUs(item)
        local owner = nil
        pcall(function() owner = item.ClientFighter.Player end)
        if owner == lp then return true end
        if Config.GVEveryone == true and owner ~= nil then return true end
        return false
    end

    -- ★★ THE KEY DOMAIN, AND THE WHOLE OF BUG A. ReplicatedClass._Setup (:171-177) iterates serial.Data
    -- calling `SetReplicate(self:FromEnum(k), v)`, and EnumLibrary.FromEnum (:54-60) ASSERTS when the
    -- key is not a known enum — _Setup does not pass the soft flag. So an inner key that is a plain
    -- string kills the constructor outright. The OUTER "Data" key is free either way because
    -- _DecodeSerial (:128-142) normalises it and "Data" is itself a registered enum, which is why we
    -- still probe the enum key first and fall back to the literal exactly as daydreamer does
    -- (cosmetics.lua:624-631). Mutated IN PLACE, before the viewmodel exists — no Destroy, no rebuild.
    local function enumKey(k)
        local e = enumOf(k)
        if e ~= nil then return e end
        return k
    end

    -- ★ THE ONE FUNNEL BOTH BIRTH HOOKS GO THROUGH, WHICH IS WHY THE BYPASS LIVES HERE. The rebuild's
    -- last-ditch recovery attempt has to construct a viewmodel the game cannot possibly refuse, and it
    -- reaches ClientItem._CreateViewModel through the SAVED ORIGINAL — but that original still calls the
    -- HOOKED ClientViewModel.new, which would style the recovery serial with the very cosmetic that had
    -- just been rejected. Setting this for the duration of that one call is the only way to get a
    -- genuinely unstyled construction out of a hooked constructor.
    local _bypassStyle = false

    local function styleSerial(serial, weapon)
        if _bypassStyle then return false end
        if type(serial) ~= "table" or type(weapon) ~= "string" then return false end
        if selectionFor(weapon) == nil then return false end
        local touched = false
        pcall(function()
            local dk = enumOf("Data")
            local slot = nil
            if dk ~= nil and type(serial[dk]) == "table" then
                slot = serial[dk]
            elseif type(serial.Data) == "table" then
                slot = serial.Data
            end
            if slot == nil then return end
            -- INNER KEYS ARE ALWAYS ENUM, whichever way the envelope arrived. #7 used identity here for
            -- the literal-envelope case and that is precisely what made the gun disappear.
            buildPayload(weapon, slot, enumKey)
            touched = true
        end)
        return touched
    end

    -- Set by the _CreateViewModel hook so the nested ClientViewModel.new hook knows which weapon it is
    -- building for. daydreamer keeps exactly this breadcrumb (`state.constructing_weapon`, :619) because
    -- `cvm.new(rdata, cliitm)` can be reached with a ClientItem whose Name is not yet readable.
    local _building = nil

    -- ObjectID -> weapon name, for the world wrap path. FighterController:GetWrap only ever receives an
    -- ObjectID, so this map is the only way back to a weapon name. daydreamer rebuilds it on a 5 s timer
    -- (`rebuildoidmap`, :779-789); same cadence here, driven off the poll we already run.
    -- ⚠ DECLARED HERE, ABOVE hooksInstall, ON PURPOSE: the GetWrap closure below captures it, and a
    -- `local` written after that closure would leave it reading a nil GLOBAL of the same name instead.
    local _oidWeapon, _oidAt = {}, 0

    -- One identity window per game call, which is Kicia's pattern: it wraps Destroy, _CreateViewModel,
    -- SetArmsData and Equip each in its own coroutine with setthreadidentity(2) around it. Setting the
    -- identity once for a whole sequence loses it if any call yields and something else runs.
    -- Every identity call is pcall'd: an executor that refuses one used to throw OUTSIDE the inner pcall
    -- and kill the whole spawned rebuild thread with no message at all.
    -- ⚠ DECLARED HERE, ABOVE hooksInstall, ON PURPOSE. The finisher hook below calls it, and a `local
    -- function` written after that closure would leave the closure reading a nil GLOBAL of the same name
    -- — the declare-below-use trap the build's `declorder` gate exists to catch.
    local function atIdentity2(fn)
        local prev = 8
        if getthreadidentity ~= nil then pcall(function() prev = getthreadidentity() end) end
        local setter = setthreadidentity
        if setter == nil then setter = setidentity end
        if setter ~= nil then pcall(setter, 2) end
        local ok, err = pcall(fn)
        if setter ~= nil then pcall(setter, prev) end
        return ok, err
    end

    -- ── FINISHERS · THE CLONE PATH ──────────────────────────────────────────────────────────────
    -- ★★ WHY THERE IS A CLONE AT ALL, AND IT IS THE WHOLE FIX (operator 2026-08-16: "the effects of it
    -- works but the enemy animations dont").
    -- Every Rivals finisher is TWO halves (Modules/Finisher.luau). PlayClient is particles, sounds and —
    -- in 36 of the 105 modules — a Humanoid animation. PlayServer is the body: _Ragdoll (destroys every
    -- Motor6D and replaces it with a BallSocketConstraint), _AnchorModel, _HideBody, Knockback.
    -- Ragdoll.luau, which a large family of finishers inherits from, has an EMPTY PlayClient — literally
    -- everything it does is PlayServer.
    -- The game's own client path (ClientEntity:_PlayFinisher, :207-224) runs PlayClient ONLY, because the
    -- server ran PlayServer on the real body and replicated the result. When we substitute a finisher
    -- locally the server ran the WRONG one's PlayServer, so we get our particles on someone else's corpse.
    -- Running the right PlayServer on the real character is not an option either: it would destroy
    -- server-owned Motor6Ds on a body we do not own.
    -- Kicia (leak :142616-142676) solves both at once. It plays the finisher on a CLONE of the victim it
    -- created and therefore fully owns, hides the real corpse, and runs BOTH halves locally.
    local FINISHER_FOLDER = nil
    local function finisherFolder()
        if FINISHER_FOLDER == nil then
            pcall(function() FINISHER_FOLDER = ReplicatedStorage.Modules.Finishers end)
        end
        return FINISHER_FOLDER
    end

    -- Character models replicate with Archivable = false, so a plain :Clone() hands back nil. Flip it for
    -- the length of the copy and put it back — leaving it true would be a visible attribute change on a
    -- server-owned instance for the rest of the round.
    local function cloneCharacter(model)
        local copy = nil
        pcall(function()
            local was = model.Archivable
            model.Archivable = true
            copy = model:Clone()
            model.Archivable = was
        end)
        return copy
    end

    -- Kicia's f9526. The real body has to disappear or the finisher plays on a duplicate standing inside
    -- the corpse. Transparency rather than Destroy: these are the server's parts and it may still be
    -- replicating to them.
    local function hideCorpse(model)
        pcall(function()
            for _, d in pairs(model:GetDescendants()) do
                if d:IsA("BasePart") then d.Transparency = 1
                elseif d:IsA("Decal") then d:Destroy()
                elseif d:IsA("BillboardGui") then d.Enabled = false end
            end
        end)
    end

    -- Kicia's f9518 + f9512, step for step.
    -- ★★★ THE CLONE IS TAKEN BEFORE THE CORPSE IS HIDDEN, AND THAT ORDER IS THE ENTIRE BUG #12 SHIPPED.
    -- hideCorpse sets Transparency = 1 on every BasePart of the real body; cloning after it copies an
    -- invisible body, so the finisher played on a corpse nobody can see — operator: "i just dont see the
    -- person i killed its just the effects". Kicia acquires the clone first and only calls its hide (up6)
    -- once the clone is in hand (leak :142722-142729), which also means a failed clone leaves the real
    -- body untouched and the game's own finisher still has something to play on.
    local function playFinisherOnClone(ent, model, mod, isFinal, killer, serial)
        local copy = cloneCharacter(model)
        if copy == nil then return false end
        local hum, root = nil, nil
        pcall(function()
            hum  = copy:FindFirstChildOfClass("Humanoid")
            root = copy:FindFirstChild("HumanoidRootPart")
        end)
        if hum == nil or root == nil then
            pcall(function() copy:Destroy() end)
            return false
        end
        -- Committed from here: we hold a usable copy, so the real body can go. Kicia hides one step
        -- earlier and can still bail afterwards on this same check, leaving an invisible corpse with no
        -- finisher at all; waiting until the copy is verified closes that hole.
        hideCorpse(model)
        -- The nametag and any highlight came across with the copy, and it is the ORIGINAL's that
        -- hideCorpse switched off — so without this the corpse gets its name back, floating over a body
        -- that is supposed to be mid-finisher. Kicia never meets this because its clones are pre-built
        -- from a stripped "decorated model"; ours is taken straight off the live character.
        pcall(function()
            for _, d in pairs(copy:GetDescendants()) do
                if d:IsA("BillboardGui") or d:IsA("SurfaceGui") or d:IsA("Highlight") then d:Destroy() end
            end
        end)
        local ok = false
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            -- A live Humanoid keeps running its own state machine and fights the finisher's animation;
            -- zero health is how Kicia hands the body over.
            hum.Health = 0
            local parts = {}
            for _, c in pairs(copy:GetChildren()) do
                if c:IsA("BasePart") then
                    -- Its own pcall: an unregistered collision group throws, and losing the de-collide
                    -- costs a jittery ragdoll, where losing the rest of this block costs the finisher.
                    pcall(function() c.CollisionGroup = "Players" end)
                    table.insert(parts, c)
                end
            end
            -- Pairwise, because a ragdolled limb set that collides with itself explodes off the map.
            for i = 1, #parts do
                for j = i + 1, #parts do
                    local nc = Instance.new("NoCollisionConstraint")
                    nc.Part0 = parts[i]
                    nc.Part1 = parts[j]
                    nc.Parent = parts[i]
                end
            end
            copy:PivotTo(model:GetPivot())
            copy.Parent = model.Parent
            ok = true
        end)
        if not ok then
            pcall(function() copy:Destroy() end)
            return false
        end
        -- The clone outlives nothing: when the game takes the real character away, ours goes with it.
        pcall(function()
            model.Destroying:Once(function()
                if copy.Parent ~= nil then copy:Destroy() end
            end)
        end)
        local fin = nil
        atIdentity2(function()
            local prev = rawget(ent, "_current_finisher")
            if prev ~= nil then pcall(prev.Destroy, prev) end
            fin = mod.new(hum, isFinal, killer)
            rawset(ent, "_current_finisher", fin)
            fin:SetSerial(serial)
            -- ★★ BOTH HALVES, SPAWNED. This is the line the old implementation was missing. Both yield
            -- (nearly every PlayClient has a wait in it), so neither may block the replication handler,
            -- and each is pcall'd because a finisher that errors half way must not take the other down.
            task.spawn(function() pcall(fin.PlayServer, fin) end)
            task.spawn(function() pcall(fin.PlayClient, fin) end)
        end)
        if fin == nil then
            pcall(function() copy:Destroy() end)
            return false
        end
        return true
    end

    local function hooksInstall()
        resolveModules()
        if Config.GVBirthHook == false then return false, "birth hook disabled in config" end
        local n = 0

        -- BIRTH. The two constructors, both mutating the serial before the original runs.
        if hookField(M.ci, "_CreateViewModel", function(orig)
            return function(item, serial)
                local weapon = nil
                pcall(function() weapon = item.Name end)
                local mine = ownedByUs(item)
                _building = mine and weapon or nil
                if mine and weapon ~= nil then pcall(styleSerial, serial, weapon) end
                -- pcall'd ONLY so the breadcrumb is cleared even when the game's own constructor
                -- throws. A leaked _building would make the next unrelated ClientViewModel.new style
                -- itself with this weapon's cosmetics. The error is re-raised unchanged at level 0 so
                -- the game sees exactly what it would have seen without us in the call chain.
                local ok, res = pcall(orig, item, serial)
                _building = nil
                if not ok then error(res, 0) end
                return res
            end
        end) then n = n + 1 end

        if hookField(M.cvm, "new", function(orig)
            return function(serial, item)
                local weapon = _building
                if weapon == nil and item ~= nil then
                    pcall(function() if ownedByUs(item) then weapon = item.Name end end)
                end
                if weapon ~= nil then pcall(styleSerial, serial, weapon) end
                local vm = orig(serial, item)
                -- ★ THE DOUBLE-TAP, from daydreamer :685-691. The first _UpdateWrap immediately after
                -- construction can land before the model's parts exist, and the wrap then never paints.
                -- One retry a frame later costs nothing and is the difference between a wrap that works
                -- and a wrap that works sometimes.
                if vm ~= nil and weapon ~= nil and resolveSel(weapon, "Wrap") ~= nil then
                    local upd = nil
                    pcall(function() upd = M.cvm._UpdateWrap end)
                    if type(upd) == "function" then
                        task.spawn(function()
                            pcall(upd, vm)
                            task.wait(0.1)
                            if rawget(vm, "_destroyed") ~= true then pcall(upd, vm) end
                        end)
                    end
                end
                return vm
            end
        end) then n = n + 1 end

        -- RESOLVERS. The game asks these every time, so they need no Data write at all — which is
        -- what makes a wrap change genuinely free.
        if hookField(M.cvm, "GetWrap", function(orig)
            return function(vm)
                local weapon, mine = nil, false
                pcall(function()
                    local item = vm.ClientItem
                    weapon = item.Name
                    mine = ownedByUs(item)
                end)
                if mine and weapon ~= nil and hasIntent(weapon, "Wrap") then
                    return resolveSel(weapon, "Wrap")
                end
                return orig(vm)
            end
        end) then n = n + 1 end

        -- FighterController:GetWrap(objectID) (:89-95) is the WORLD path — it finds the item by
        -- ObjectID across every fighter and returns `item:GetWrap()`. Without this the wrap shows on the
        -- first-person viewmodel and not on the weapon hanging off the third-person body.
        if hookField(M.fctrl, "GetWrap", function(orig)
            return function(ctrl, oid)
                local res = orig(ctrl, oid)
                if res ~= nil then return res end
                local weapon = _oidWeapon and _oidWeapon[tostring(oid)] or nil
                if weapon == nil then return nil end
                return resolveSel(weapon, "Wrap")
            end
        end) then n = n + 1 end

        -- The 2D menu / HUD icon. Without it a working swap still looks half-applied, because the
        -- weapon card keeps showing the base gun. daydreamer :600-614.
        if hookField(M.ilib, "GetViewModelImageFromWeaponData", function(orig)
            return function(lib, wdata, hires)
                if type(wdata) == "table" and type(wdata.Name) == "string" then
                    local skin = resolveSel(wdata.Name, "Skin")
                    if skin ~= nil then
                        local img = nil
                        pcall(function()
                            local info = lib.ViewModels[skin.Name]
                            if info ~= nil then
                                img = hires and info.ImageHighResolution or info.Image
                                if img == nil then img = info.Image end
                            end
                        end)
                        if img ~= nil then return img end
                    end
                end
                return orig(lib, wdata, hires)
            end
        end) then n = n + 1 end

        -- FINISHERS. The server announces one through ClientEntity:ReplicateFromServer("FinisherEffect",
        -- name, isFinal, eliminator, serial) (:108-112); when WE are the eliminator we swallow that call
        -- and play our own instead, on a clone, entirely locally. Kicia reaches the same place by
        -- debug.setconstant-ing the "_PlayFinisher" string inside ReplicateFromServer; a plain field hook
        -- lands in the same spot and is one mechanism instead of two.
        -- ⚠ EVERY BAILOUT MUST HAPPEN BEFORE hideCorpse. Once the real body is hidden there is no way back
        -- to the game's own finisher, so the order below is: decide, then commit.
        if hookField(M.cent, "ReplicateFromServer", function(orig)
            return function(ent, action, ...)
                if action ~= "FinisherEffect" then return orig(ent, action, ...) end
                local args = { ... }
                -- Kicia compares args[3] against LocalPlayer directly (leak :22599, :22690), which settles
                -- that the eliminator arrives as a Player instance; the other two forms are kept as cheap
                -- insurance against a wire change.
                local killer = args[3]
                local isUs = false
                pcall(function()
                    if typeof(killer) == "Instance" then isUs = (killer == lp)
                    elseif type(killer) == "number" then isUs = (killer == lp.UserId)
                    elseif type(killer) == "string" then isUs = (killer:lower() == lp.Name:lower()) end
                end)
                if not isUs then return orig(ent, action, ...) end
                -- Kicia keys the lookup off the ELIMINATOR'S EQUIPPED WEAPON (leak :142728). Ours falls
                -- back through the picker's last weapon and then any weapon with a finisher chosen, which
                -- is daydreamer's rule (:736-743) — without that, a finisher put on the AR does nothing on
                -- a sniper kill and looks broken.
                local held = nil
                pcall(function()
                    local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
                    local it = lf and lf.EquippedItem
                    if it ~= nil then held = it.Name end
                end)
                local fin, weapon = nil, nil
                for _, w in pairs({ held, GameVisuals.lastWeapon }) do
                    if fin == nil and type(w) == "string" then
                        fin = resolveSel(w, "Finisher")
                        if fin ~= nil then weapon = w end
                    end
                end
                if fin == nil then
                    for w in pairs(GameVisuals.Choices) do
                        if fin == nil then
                            fin = resolveSel(w, "Finisher")
                            if fin ~= nil then weapon = w end
                        end
                    end
                end
                if fin == nil then return orig(ent, action, ...) end
                local rendered = false
                pcall(function() rendered = ent:IsRendered() end)
                if not rendered then return orig(ent, action, ...) end
                local mod, model = nil, nil
                pcall(function()
                    local folder = finisherFolder()
                    local node = folder and folder:FindFirstChild(tostring(fin.Name)) or nil
                    if node ~= nil then atIdentity2(function() mod = require(node) end) end
                    model = rawget(ent, "Model")
                end)
                if type(mod) ~= "table" or type(mod.new) ~= "function" or model == nil then
                    return orig(ent, action, ...)
                end
                if Config.GVFinisherClone == false then
                    -- The old behaviour, kept behind a toggle: the game's own _PlayFinisher on the real
                    -- body. PlayClient only, so particles land and the corpse does not move.
                    local played = false
                    pcall(function()
                        ent:_PlayFinisher(fin.Name, args[2], args[3], args[4])
                        played = true
                    end)
                    if played then return end
                    return orig(ent, action, ...)
                end
                -- ⚠ hideCorpse LIVES INSIDE playFinisherOnClone, after the copy is verified. Calling it
                -- here is what #12 did, and it meant the clone was taken from an already-invisible body.
                if playFinisherOnClone(ent, model, mod, args[2], args[3], args[4]) then
                    note((weapon or "?") .. " finisher -> " .. tostring(fin.Name))
                    return
                end
                -- The clone never got far enough to hide anything, so the real body is still there and
                -- the game's own finisher can play on it exactly as if we had never intervened.
                note("finisher clone failed for " .. tostring(fin.Name))
                return orig(ent, action, ...)
            end
        end) then n = n + 1 end

        if n == 0 then return false, "no hook target resolved (modules not loaded yet?)" end
        return true, n
    end

    local function rebuildOidMap()
        local now = tick()
        if now < _oidAt then return end
        _oidAt = now + 5
        pcall(function()
            local f = Rivals.Fighter:GetFighter(lp)
            if f == nil or type(f.Items) ~= "table" then return end
            for _, item in pairs(f.Items) do
                local oid = nil
                pcall(function() oid = item:Get("ObjectID") end)
                if oid ~= nil then _oidWeapon[tostring(oid)] = item.Name end
            end
        end)
    end

    -- ── UPVALUE SCAN ────────────────────────────────────────────────────────────────────────────
    -- Used only by the equip capture now. An executor whose `getupvalues` returns an EMPTY table used to
    -- short-circuit here and make the singular-accessor fallback dead code.
    local function upvaluesOf(fn)
        local ups = nil
        pcall(function() ups = debug.getupvalues(fn) end)
        if type(ups) == "table" and next(ups) ~= nil then return ups end
        if debug.getupvalue == nil then return nil end
        ups = {}
        for i = 1, 64 do
            local ok, v = pcall(debug.getupvalue, fn, i)
            if not ok then break end
            ups[i] = v
        end
        if next(ups) == nil then return nil end
        return ups
    end

    -- ── LAYER 4 · THE APPLY, UE'S WAY ─────────────────────────────────────────
    -- ★★ THIS REPLACED A DESTROY-AND-REBUILD RETROFIT ON 2026-08-15, AND IT IS THE HEADLINE FIX.
    -- The old path hand-rolled ClientViewModel.Destroy -> _CreateViewModel -> SetArmsData -> Equip to
    -- restyle the weapon already in your hand. That is what "breaks the gun and breaks stuff" was:
    -- Destroy (ClientViewModel:565-587) tears down Equipped / Unequipped / AnimationPlayed /
    -- AnimationStopped / the Charm / the Animator / ItemModel / Model, and then ReplicatedClass.Destroy
    -- (:117-127) destroys every _value_changed_events signal -- so every listener on that viewmodel is
    -- severed while only `item.ViewModel` gets repointed at the replacement. Gun.luau:44 also caches its
    -- shoot-animation COUNT at construction, so a replacement desyncs the shoot index. And the game
    -- itself never does any of it: Rivals only opens the Equipment menu in the lobby, so no game code
    -- path has ever re-cosmeticked a live viewmodel.
    --
    -- UE's SafeUpdateLocalEquippedItemID (dump proto 286, path 0.122.23) does it the safe way instead:
    -- write the cosmetic into Data (`.Name` at pc 108, `item.ViewModel.Data` at pc 218-219, keys through
    -- ToEnum), read `EquippedItem.Data.ItemIndex` (pc 261-263), and call the game's own `EquipItem`
    -- (pc 65 and 183). No Destroy, no _CreateViewModel, no SetArmsData, no Equip by hand.
    --
    -- ★★★ AND THAT IS NOT ENOUGH — MEASURED 2026-08-16: "manual picker only wraps load instantly, skins
    -- however need a respawn". Re-read from the dump, UE's EquipItem is the weapon-slot switch
    -- (MechanicsController:447-459 binds keys 1-4 to it); it changes WHICH viewmodel renders, never what
    -- one looks like. ClientViewModel.new reads Data.Name exactly once (:52) and clones the mesh from it
    -- (:55), so a skin cannot change on a viewmodel that already exists. UE has no rebuild anywhere: its
    -- only ItemModel/SetArmsData/_UpdateWrap contact (dump proto 763) is its chams system, and its
    -- apply-to-all openly refuses skins ("cant apply weapon skins to all!", proto 267). Copying UE harder
    -- could never have fixed this.
    --
    -- KICIA CAN, and does it in `cosmetics.ViewModelReloader._ReloadWithCosmetics` (leak :37101-37190):
    -- Destroy the viewmodel, `ClientItem._CreateViewModel(item, encoded serial)`, rawset item.ViewModel,
    -- copy the arms data off the fighter, Equip(new, true), zero the equip spring. So the rebuild IS the
    -- mechanism, and rewrite #10 deleted it instead of fixing it.
    --
    -- ★ WHY OURS BROKE THE GUN, now certain. The old retrofit destroyed FIRST and then handed
    -- _CreateViewModel a serial whose inner Data keys were plain strings (buildPayload(..., identityKey)).
    -- ReplicatedClass._Setup (:171-177) calls `SetReplicate(self:FromEnum(k), v)` for every inner key and
    -- EnumLibrary.FromEnum ASSERTS on an unregistered one — so construction threw and item.ViewModel was
    -- left pointing at the object we had already destroyed. That is "it just breaks the gun".
    -- Two changes make that state unreachable:
    --   1. the payload is ENUM-KEYED (enumKey, the same encoder styleSerial already uses), and
    --   2. we CONSTRUCT BEFORE DESTROYING. A throw or a nil now aborts with the old viewmodel untouched.
    -- ★ PER-ITEM, NOT GLOBAL. One shared timer meant that a pass over several weapons (disable(),
    -- "Reset all", or GVEveryone across a lobby) rebuilt the first item and refused every other one for
    -- the next 1.5 s. Weak keys so a ClientItem the game has thrown away does not keep an entry alive.
    local _rebuildAt = setmetatable({}, { __mode = "k" })
    -- ★ THE COOLDOWN IS FOR THE POLL, NOT FOR THE OPERATOR. A deliberate action -- Clear this weapon,
    -- Reset all, switching the feature off -- has to land NOW, and all three of those revert by writing
    -- the NONE sentinel and then immediately dropping the slot, so a refusal has no later retry to fall
    -- back on. Without this, clearing within 1.5 s of picking silently did nothing until the next spawn.
    -- Only the debounce is bypassed; the rage-firing guard is not, because that one protects damage.
    local _forceRebuild = false
    -- ★ THE ONLY DIAGNOSTIC LEFT, AND IT IS NOW ON THE PANEL. The Status line and the History box were
    -- both removed on 2026-08-16 ("ppl dont need to know that"), which is fine right up until a rebuild
    -- is refused and the operator has no way to tell "it applied" from "it silently deferred to the next
    -- spawn" — the exact ambiguity that cost this feature four rewrites. Keyed by weapon, cleared on every
    -- successful pass, and rendered as a short suffix on that weapon's line in the Loaded list.
    local _lastRefusal = {}

    -- The live Data is STRING-keyed (_Setup writes it through FromEnum), so these are plain lookups.
    local function liveTriple(vm)
        local name, charm, wrap = nil, nil, nil
        pcall(function()
            local src = rawget(vm, "Data")
            if type(src) ~= "table" then return end
            name  = src.Name
            charm = src.Charm
            wrap  = src.Wrap
        end)
        return name, charm, wrap
    end

    -- ── WRAPS ARE LIVE — and now they are the ONLY thing applied in place ──────────────────
    -- _UpdateWrap (:692) calls GetWrap and re-applies from scratch after a ResetWrap, so it is both
    -- idempotent AND reversible — passing nil genuinely REMOVES a wrap rather than leaving the old one
    -- painted on. With the GetWrap hook bound this is belt-and-braces; without it, it is the whole path.
    local function applyWrapLive(vm, wrap)
        local data = nil
        pcall(function() data = rawget(vm, "Data") end)
        if type(data) ~= "table" then return false, "ViewModel.Data unreadable" end
        local upd = nil
        pcall(function() upd = M.cvm._UpdateWrap end)
        if type(upd) ~= "function" then return false, "ClientViewModel._UpdateWrap not found" end
        rawset(data, "Wrap", wrap)
        local ok, err = atIdentity2(function() upd(vm) end)
        if not ok then return false, "wrap update failed: " .. tostring(err) end
        return true, nil
    end

    local function wrapLabel(w)
        if type(w) ~= "table" then return "none" end
        return tostring(w.Name)
    end

    -- ★ THE WRITE. UE writes BOTH the item's Data and the live viewmodel's Data, so we do the same.
    -- SetReplicate is the game's own setter and is LOCAL-ONLY on the client: Replicate fires
    -- ReplicateToClient, and that is `IS_SERVER and Signal.new() or nil` (ReplicatedClass:25), so on our
    -- side it sets the value and rings the local data-changed events. Nothing reaches the wire.
    -- STRING keys, because Set is a plain `self.Data[key] = value` (:44-46) and the live table is the one
    -- _Setup already normalised through FromEnum.
    -- ★★ INTENT-GATED, AND THAT IS LOAD-BEARING. buildPayload only fills a key the operator has actually
    -- chosen something for, so raw.Charm is nil both for "clear the charm" and for "never touched it".
    -- The old rebuild could not tell the difference and did not need to — it built a FRESH viewmodel, so
    -- an absent key simply meant the new one had none. Writing into the EXISTING Data is not the same:
    -- there, nil DELETES. Writing every key unconditionally would strip a charm or wrap the player really
    -- owns the moment they pick a skin, and the compare below would then never settle, rebuilding every
    -- cooldown forever. So both the write and the compare ask hasIntent first.
    local INTENT_OF = { Name = "Skin", Charm = "Charm", Wrap = "Wrap" }

    local function wants(base, dataKey)
        return hasIntent(base, INTENT_OF[dataKey])
    end

    local function writeData(obj, raw, base)
        if obj == nil then return false end
        local wrote = false
        for _, key in pairs({ "Name", "Charm", "Wrap" }) do
          if wants(base, key) then
            local ok = false
            pcall(function()
                obj:SetReplicate(key, raw[key])
                ok = true
            end)
            -- A refused SetReplicate must not lose the value: fall back to the raw table so the next
            -- construction still reads the right cosmetic.
            if not ok then
                pcall(function()
                    local d = rawget(obj, "Data")
                    if type(d) == "table" then
                        d[key] = raw[key]
                        ok = true
                    end
                end)
            end
            if ok then wrote = true end
          end
        end
        return wrote
    end

    -- The arms (shirt texture + skin colour) are the fighter's, not the viewmodel's, and _Setup resets
    -- them to the defaults with `SetArmsData(nil, nil, nil)` (:933). Kicia re-reads them off the fighter
    -- and pushes them back onto the replacement (:37176-37180); without that a rebuilt weapon comes back
    -- with bare black arms.
    local function armsDataOf(item)
        local packed = nil
        pcall(function()
            local f = item.ClientFighter
            if f == nil then return end
            local get = f.GetArmsData
            if type(get) ~= "function" then return end
            packed = table.pack(get(f))
        end)
        return packed
    end

    -- ★ ENUM-KEYED, AND COMPLETE. Two separate requirements:
    --   * ENUM keys, because ReplicatedClass._Setup runs FromEnum over every inner key and asserts.
    --   * every cosmetic present, because a rebuild starts from nothing — an absent key here means the
    --     replacement genuinely has no charm, so a cosmetic the operator has expressed no intent about
    --     must be carried over from the viewmodel we are replacing or it is silently stripped.
    -- Built from a MINIMAL base rather than a copy of the live Data: a copy drags the old ObjectID over
    -- the fresh one ReplicatedClass.new (:23) just minted, so the replacement inherits the identity of
    -- the object it replaced and FighterController:GetWrap(oid) resolves to a destroyed viewmodel.
    local function rebuildPayload(base, vm)
        local liveName, liveCharm, liveWrap = liveTriple(vm)
        local raw = {}
        if hasIntent(base, "Skin") then
            local s = resolveSel(base, "Skin")
            raw[enumKey("Name")] = (s ~= nil) and s.Name or base
        else
            raw[enumKey("Name")] = liveName or base
        end
        if hasIntent(base, "Charm") then
            raw[enumKey("Charm")] = resolveSel(base, "Charm")
        else
            raw[enumKey("Charm")] = liveCharm
        end
        if hasIntent(base, "Wrap") then
            raw[enumKey("Wrap")] = resolveSel(base, "Wrap")
        else
            raw[enumKey("Wrap")] = liveWrap
        end
        return raw
    end

    -- ★★ THE PRE-FLIGHT, AND IT IS WHAT MAKES DESTROY-FIRST SAFE TO SHIP AGAIN.
    -- _Setup runs FromEnum over every top-level Data key and FromEnum ASSERTS on an unregistered one, so
    -- a payload with even one plain-string key is a construction that is GUARANTEED to throw. Reaching
    -- the destroy with such a payload is precisely what shipped as "it just breaks the gun". enumKey
    -- silently falls back to the literal string when EnumLibrary has no entry, which is the right thing
    -- for the birth hook (the serial is already half-built by the game) and exactly the wrong thing here.
    -- So: before anything is torn down, confirm every key we are about to send round-tripped to a real
    -- enum. Kicia has no such check; it does not need one because it never builds keys by fallback.
    -- The test is exact and needs no knowledge of what the enum ids look like: enumKey writes the value
    -- under the ENUM when it has one and under the LITERAL STRING when it does not, so a value still
    -- sitting at raw["Wrap"] is by definition a key that will assert. A key the payload never set is nil
    -- either way and is not a problem. (The degenerate case where the enum id IS its own name is allowed
    -- through — FromEnum would resolve it, so it is not the fault we are looking for.)
    local function payloadKeysAreEnums(raw)
        for _, k in pairs({ "Name", "Charm", "Wrap" }) do
            if rawget(raw, k) ~= nil and enumOf(k) ~= k then return false, k end
        end
        return true, nil
    end

    -- The five steps that turn a freshly built viewmodel into the one the player is holding. Shared by
    -- all three attempts below so they cannot drift apart.
    -- ★ Equip IS UNCONDITIONAL, and that is Kicia's behaviour, not a simplification. ClientViewModel.new
    -- starts every viewmodel at `_is_equipped = false` (:102) and ONLY Equip (:305-318) flips it, so a
    -- replacement that is never equipped is a replacement that never renders — the held weapon simply
    -- vanishes. #11 gated this on the old viewmodel's flag, which reads false for any weapon rebuilt
    -- during the equip animation.
    local function adoptViewModel(item, fresh, arms)
        pcall(function() rawset(item, "ViewModel", fresh) end)
        -- One identity window PER game call, for the reason atIdentity2 documents: a single window around
        -- the whole sequence is lost the moment any one of them yields.
        if arms ~= nil then
            atIdentity2(function() M.cvm.SetArmsData(fresh, table.unpack(arms, 1, arms.n)) end)
        end
        -- `true` is the game's own instant-equip flag (:314-318): no draw animation, quieter sound.
        atIdentity2(function() M.cvm.Equip(fresh, true) end)
        -- Kicia zeroes the spring on top of that (:37184-37188) so the replacement is already in
        -- position rather than springing in from 0.5. Guarded: these are Spring internals
        -- (Spring.luau:11-12), so an implementation change costs a small animation, never the swap.
        pcall(function()
            local sp = rawget(fresh, "_equip_spring")
            if sp ~= nil then sp._position0 = 0 ; sp._velocity0 = 0 end
        end)
    end

    -- ★ WHAT COUNTS AS A REPLACEMENT. Three separate ways the constructor can hand back something that is
    -- not one, and #12 shipped without checking two of them:
    --   * the SAME object, which a "you already have one" guard returns and which we then destroyed;
    --   * an object already flagged _destroyed, i.e. the corpse we just tore down;
    --   * an object with no Model, which can never be parented and so can never render.
    -- Adopting any of those is the difference between "the skin did not change" and "the gun is gone".
    local function usableReplacement(fresh, vm)
        if fresh == nil or fresh == vm then return false end
        local ok = false
        pcall(function()
            ok = (rawget(fresh, "_destroyed") ~= true) and (rawget(fresh, "Model") ~= nil)
        end)
        return ok
    end

    -- One construction attempt. The caller must have cleared item.ViewModel first — see rebuildViewModel.
    -- ★ THE RETURN-VALUE FALLBACK IS NOT DEFENSIVE PADDING. ClientItem is VM-obfuscated, so whether
    -- _CreateViewModel RETURNS the viewmodel or merely assigns self.ViewModel cannot be read off disk;
    -- Kicia takes the return value and bails on nil, which would make it silently inert on a constructor
    -- of the second shape. Because the field was cleared before the call, anything sitting there
    -- afterwards is unambiguously the object this call just built.
    local function tryBuild(create, item, serial, vm)
        local fresh = nil
        atIdentity2(function() fresh = create(item, serial) end)
        if fresh == nil then pcall(function() fresh = rawget(item, "ViewModel") end) end
        if usableReplacement(fresh, vm) then return fresh end
        return nil
    end

    local function dropViewModel(drop, vm)
        -- Skipped if the constructor already tore it down itself — Destroy is not idempotent (it Destroys
        -- signals that may already be gone), and `_destroyed` is the game's own flag for exactly this
        -- question (:70, :567).
        pcall(function()
            if rawget(vm, "_destroyed") ~= true then atIdentity2(function() drop(vm) end) end
        end)
    end

    -- ★★★ THE LIVE REBUILD, ROUND THREE — AND THE ORDER IS NOW KICIA'S, WITH A FREE PROBE IN FRONT.
    --
    -- Rewrite #11 constructed before destroying, reasoning that a throw would then leave the player with
    -- their gun. It shipped, and the operator measured: "manual picker only shows the new skin after a
    -- respawn". No broken gun — no effect at all. That is the signature of a constructor that DECLINES to
    -- build a second viewmodel while `item.ViewModel` is still live: #11 then took either the
    -- `fresh == vm` branch or the `built == false` branch, both of which SETTLE the compare, so the poll
    -- never tried again and the cosmetic waited for the next natural construction.
    -- ClientItem._CreateViewModel lives in the VM-obfuscated ClientItem module, so whether it is
    -- re-entrant cannot be read off disk and cannot be tested without a client. What CAN be read off disk
    -- is Kicia, the one artifact that demonstrably restyles a live weapon, and Kicia DESTROYS FIRST
    -- (leak :37116-37162). We stop arguing with it.
    --
    -- Three attempts, in this order, and only the first one is ours:
    --   1. PROBE — build with the old viewmodel still alive. Free: if the constructor is re-entrant this
    --      is #11's path, one construction, no window in which the player has no weapon. If it declines,
    --      nothing has been torn down and we simply continue.
    --   2. KICIA — destroy, then build. The measured-working sequence, entered only after the pre-flight
    --      has confirmed the payload cannot assert inside _Setup.
    --   3. RECOVER — if 2's build also fails we are past the destroy, so build one more time from the
    --      LIVE triple (base weapon, live charm, live wrap). The player gets their gun back unstyled
    --      instead of nothing. Kicia has no third attempt; this is the one place we are ahead of it.
    --
    -- Returns (ok, why, transient) — `transient` marks a refusal the caller should retry on the next poll
    -- rather than settle.
    local function rebuildViewModel(item, base, vm)
        -- The rebuild is the birth hook pointed at an existing weapon: it works by letting the GAME
        -- construct, with our _CreateViewModel/new hooks styling the serial on the way through. With the
        -- birth hook off there is nothing to style and the replacement would come back as the base gun.
        if Config.GVBirthHook == false then return false, "style at construction is off", false end
        if State.RageFiring == true then return false, nil, true end
        local now = tick()
        if not _forceRebuild and now < (_rebuildAt[item] or 0) then return false, nil, true end
        local create = origOf(M.ci, "_CreateViewModel")
        if type(create) ~= "function" then return false, "_CreateViewModel missing — needs a respawn", false end
        local drop = nil
        pcall(function() drop = M.cvm.Destroy end)
        if type(drop) ~= "function" then return false, "Destroy missing — needs a respawn", false end
        -- ★ CHECKED HERE, BEFORE ANYTHING IS TORN DOWN. adoptViewModel reaches Equip through M.cvm at call
        -- time inside a pcall, so a missing one fails silently — and a replacement that is never equipped
        -- never renders (`_is_equipped` starts false, :102, and only Equip flips it). Finding that out
        -- after the destroy means an invisible weapon; finding it out here means a message.
        local equip = nil
        pcall(function() equip = M.cvm.Equip end)
        if type(equip) ~= "function" then return false, "Equip missing — needs a respawn", false end
        _rebuildAt[item] = now + REBUILD_COOLDOWN

        local arms = armsDataOf(item)
        -- The outer envelope may be either domain — _DecodeSerial (:128-142) rewrites every OUTER key to
        -- its string name whichever way it arrived, which is why Kicia enum-encodes it and we do not and
        -- both work. The INNER keys are a different story: _Setup reads `.Data` by literal string and then
        -- FromEnums every key inside it, so those must be enums or the constructor asserts.
        local raw = rebuildPayload(base, vm)
        local serial = { Data = raw }

        -- ── 1 · CLEAR THE FIELD, THEN BUILD ──────────────────────────────────────────────────────────
        -- ★★★ THIS ONE LINE IS THE WHOLE OF #13, AND IT IS WHAT BOTH PREVIOUS REWRITES WERE MISSING.
        -- #11 called the constructor with item.ViewModel still pointing at the live viewmodel and got
        -- NOTHING. #12 destroyed first and called it with item.ViewModel still pointing at the CORPSE and
        -- got NO GUN. Both are one behaviour: a constructor that refuses to build when the field is
        -- already occupied and hands back what is there. Destroying the object does not vacate the field —
        -- ClientViewModel.Destroy (:565-587) never touches item.ViewModel — which is why #12 made it
        -- worse rather than better, and it is the observation that finally separates the two reports.
        -- So: vacate the FIELD, not the object. Nothing is torn down, the old viewmodel is still whole,
        -- and if the build fails we simply put the pointer back. The gunless state is unreachable here.
        local prevField = nil
        pcall(function() prevField = rawget(item, "ViewModel") end)
        pcall(function() rawset(item, "ViewModel", nil) end)
        local fresh = tryBuild(create, item, serial, vm)
        if fresh ~= nil then
            adoptViewModel(item, fresh, arms)
            dropViewModel(drop, vm)
            return true, nil, false
        end
        -- Nothing usable came back and nothing has been destroyed. Put the live weapon's pointer back
        -- before doing anything else, so a failure here costs a wasted call and not the gun.
        pcall(function() rawset(item, "ViewModel", prevField) end)

        -- ── 2 · KICIA'S ORDER ────────────────────────────────────────────────────────────────────────
        -- Clearing the field was not enough: the constructor may be refusing because the old MODEL is
        -- still parented, not because the field is set. Kicia destroys first (leak :37116-37162) and Kicia
        -- works, so that is the fallback. Everything past this point is committed, which is why the
        -- pre-flight runs FIRST and refuses outright rather than leaving the player holding nothing.
        local keysOk, badKey = payloadKeysAreEnums(raw)
        if not keysOk then
            return false, "no enum for '" .. tostring(badKey) .. "' — needs a respawn", false
        end
        dropViewModel(drop, vm)
        pcall(function() rawset(item, "ViewModel", nil) end)
        fresh = tryBuild(create, item, serial, vm)
        if fresh ~= nil then
            adoptViewModel(item, fresh, arms)
            return true, nil, false
        end

        -- ── 3 · RECOVER ──────────────────────────────────────────────────────────────────────────────
        -- Past the destroy with no replacement: the player currently has no weapon rendered. Build the
        -- weapon they started with, unstyled, so the worst case is a missing cosmetic rather than a
        -- missing gun. _bypassStyle is mandatory here — the saved original _CreateViewModel still calls
        -- our HOOKED ClientViewModel.new, which would re-apply the cosmetic the constructor just rejected
        -- and fail again for the same reason. The flag is cleared even if the call throws.
        local liveName, liveCharm, liveWrap = liveTriple(vm)
        local bare = {}
        bare[enumKey("Name")]  = liveName or base
        bare[enumKey("Charm")] = liveCharm
        bare[enumKey("Wrap")]  = liveWrap
        _bypassStyle = true
        fresh = tryBuild(create, item, { Data = bare }, vm)
        _bypassStyle = false
        if fresh ~= nil then
            adoptViewModel(item, fresh, arms)
            return false, "game refused it — needs a respawn", false
        end
        -- Nothing worked and the old viewmodel is gone. Leave the field pointing back at it rather than
        -- at nil: everything from Arms.luau to MouseCrosshair indexes item.ViewModel unguarded every
        -- frame, and a nil there turns one missing weapon into a stream of errors somewhere else.
        pcall(function() rawset(item, "ViewModel", vm) end)
        return false, "rebuild failed — respawn to restore", false
    end

    local function sameSub(a, b)
        if a == nil and b == nil then return true end
        if a == nil or b == nil then return false end
        return a.Name == b.Name
    end

    -- ★ EVERY EXIT HERE IS NAMED. This function once had four silent `return false` paths, so a feature
    -- that never even reached the apply was indistinguishable from one that applied and had no visible
    -- effect. That is the single reason four rewrites produced no information.
    local function applyToItem(item, base)
        local vm = nil
        pcall(function() vm = item.ViewModel end)
        local sel = selectionFor(base)
        if vm == nil then
            if sel ~= nil then note(base .. ": item has no ViewModel yet") end
            return false
        end
        local curName, curCharm, curWrap = liveTriple(vm)
        if curName == nil then
            if sel ~= nil then note(base .. ": ViewModel.Data unreadable") end
            return false
        end

        -- Nothing selected, nothing to do. The old code snapshotted the pristine Data here so a Reset
        -- could rebuild back to it; with no rebuild there is nothing to rebuild TO, and the base weapon
        -- comes back on its own at the next construction.
        if sel == nil then return true end
        local raw = buildPayload(base, { Name = base }, identityKey)
        if raw == nil then raw = { Name = base } end

        -- ── WRAP FIRST, AND IN PLACE. The game re-reads Data.Wrap on every GetWrap call, so this is the
        -- one cosmetic that is genuinely instant, and settling it here means a wrap-only change never
        -- triggers a rebuild at all -- no draw animation, no torn-down viewmodel, for a change that
        -- needs neither.
        local wrapOk = true
        if wants(base, "Wrap") and not sameSub(curWrap, raw.Wrap) then
            local wok, wwhy = applyWrapLive(vm, raw.Wrap)
            if wok then
                note(base .. " wrap -> " .. wrapLabel(raw.Wrap))
            else
                note(base .. ": " .. tostring(wwhy))
                wrapOk = false
            end
        end

        -- Name is read once in ClientViewModel.new (:52) and Charm once in _Setup (:910), so neither can
        -- change on a live viewmodel -- these two are the only reasons to build a replacement.
        -- ⚠ BOTH TESTS ARE INTENT-GATED. Without that, a player holding a real charm they own would fail
        -- `sameSub(curCharm, nil)` on every pass the moment they picked a skin, so the compare would never
        -- settle and the rebuild would fire every cooldown for the rest of the session.
        local needName  = wants(base, "Name")  and curName ~= raw.Name
        local needCharm = wants(base, "Charm") and not sameSub(curCharm, raw.Charm)
        if not needName and not needCharm then
            -- ★ vm.Name IS THE HONEST SIGNAL, AND IT IS THE ONLY ONE. ClientViewModel.new resolves
            -- `self.Name = self:Get("Name")` once at :52 and clones the mesh from it at :55; our
            -- SetReplicate writes Data, never that field. So Data.Name is what we ASKED for and vm.Name is
            -- what the player is actually holding — which makes this the one place the two can be compared
            -- to tell a rebuild that landed from a rebuild that was refused and papered over. Used only to
            -- retire the panel's warning; the compare above deliberately still settles on Data, because
            -- settling on vm.Name would rebuild a refused weapon every cooldown forever.
            if wants(base, "Name") then
                local shown = nil
                pcall(function() shown = rawget(vm, "Name") end)
                if shown == raw.Name then _lastRefusal[base] = nil end
            else
                _lastRefusal[base] = nil
            end
            return wrapOk
        end

        -- ★ REBUILD FIRST, WRITE SECOND, AND THE ORDER MATTERS BOTH WAYS.
        -- rebuildPayload reads the CURRENT viewmodel for any cosmetic the operator has no intent about,
        -- so writeData must not have run yet; and writeData must still run afterwards so that a refused
        -- rebuild leaves the cosmetic sitting in item.Data for the next natural construction — the
        -- "lands on next spawn" behaviour, which is the floor this can never fall below.
        local rok, rwhy, transient = rebuildViewModel(item, base, vm)
        writeData(item, raw, base)
        -- ★ WRITING Data ON THE LIVE VIEWMODEL IS WHAT STOPS THIS REPEATING. Nothing re-reads Data.Name on
        -- a built viewmodel (vm.Name and vm.Info were resolved in ClientViewModel.new :52-54), so the write
        -- cannot change what is on screen — it exists so liveTriple reports the new name and the next poll
        -- sees needName false. After a TRANSIENT refusal (cooldown, rage firing) we must NOT settle or the
        -- retry never happens.
        -- ★ AND IT GOES ON WHATEVER item.ViewModel IS NOW, NEVER ON THE LOCAL `vm`. Two of the rebuild's
        -- three attempts can leave a DIFFERENT object there: Kicia's destroy-then-build replaces it, and
        -- even the recovery attempt replaces it while reporting failure. Writing to the local `vm` in
        -- those cases writes to a destroyed corpse, liveTriple keeps reporting the old name off the live
        -- one, and the poll rebuilds the weapon every cooldown for the rest of the session.
        if transient ~= true then
            local nowVm = nil
            pcall(function() nowVm = item.ViewModel end)
            writeData(nowVm or vm, raw, base)
        end
        -- A TRANSIENT refusal (cooldown, rage firing) is not a verdict — leave any existing warning alone
        -- rather than clearing it for a pass that never even attempted the rebuild.
        if transient ~= true then _lastRefusal[base] = nil end
        if rok then
            note(base .. " -> " .. tostring(raw.Name))
        elseif rwhy ~= nil then
            _lastRefusal[base] = rwhy
            note(base .. " -> " .. tostring(raw.Name) .. " (" .. rwhy .. ")")
        end
        return true
    end

    local function itemsOf(player)
        local items = nil
        -- GetFighter (:33-56) is the game's own accessor and falls back through model and UserId
        -- lookups; the raw _player_to_fighter read it wraps is kept as the backstop.
        pcall(function()
            local f = Rivals.Fighter:GetFighter(player)
            if f ~= nil and type(f.Items) == "table" then items = f.Items end
        end)
        if items == nil then
            pcall(function()
                local map = Rivals.Fighter._player_to_fighter
                local f = map and map[player]
                if f ~= nil and type(f.Items) == "table" then items = f.Items end
            end)
        end
        return items
    end

    local function applyToPlayer(player)
        local items = itemsOf(player)
        if items == nil then
            -- Without this line a missing fighter entry (lobby, dead, not yet spawned) looks exactly
            -- like a working feature that changed nothing.
            if next(GameVisuals.Choices) ~= nil then
                note("no fighter items for " .. player.Name .. " (not spawned in a match?)")
            end
            return 0
        end
        local n, matched, carried = 0, false, ""
        for _, item in pairs(items) do
            if type(item) == "table" then
                local base = nil
                pcall(function() base = item.Name end)
                if type(base) == "string" then
                    carried = carried .. base .. " "
                    if selectionFor(base) ~= nil then matched = true end
                    if applyToItem(item, base) then n = n + 1 end
                end
            end
        end
        -- ★ THE SILENT FAILURE THAT COST FOUR REWRITES. Choices is keyed by ClientItem.Name (the base
        -- weapon, e.g. "Assault Rifle"), which is what CosmeticLibrary's `entry.ItemName` gives us. If a
        -- selection names a weapon the player is not carrying, EVERY applyToItem takes the no-selection
        -- branch and returns false without a word, and the poll reports a clean zero — indistinguishable
        -- from a broken mechanism. Naming the carried weapons makes it one line.
        if player == lp and next(GameVisuals.Choices) ~= nil and not matched then
            note("no carried weapon matches a selection — carrying: " .. carried)
        end
        return n
    end

    function GameVisuals.apply()
        if Config.GameVisuals ~= true then return 0 end
        -- The mask is the only other caller and it does not run when unlock-all is off, so without this
        -- a wrap-only user would reach applyWrapLive with M.cvm still nil and be told _UpdateWrap does
        -- not exist. Cheap: four nil-checks once resolved, backed off to 5 s while it is not.
        resolveModules()
        rebuildOidMap()
        local n = applyToPlayer(lp)
        if Config.GVEveryone == true then
            for _, p in pairs(Players:GetPlayers()) do
                if p ~= lp then n = n + applyToPlayer(p) end
            end
        end
        State.GVApplied = n
        return n
    end

    -- ★ CLEARING IS AN EXPLICIT "None", NOT A DELETED SLOT — and that is what makes a reset land on the
    -- spot like a pick does. Deleting the slot leaves hasIntent false, applyToItem takes its
    -- no-selection branch and the weapon keeps the skin until it is next constructed. Writing the
    -- NONE_COSMETIC sentinel keeps the intent, so the rebuild runs with Name = the base weapon and the
    -- gun comes back immediately. resolveSel already turns the sentinel into nil for every reader, and
    -- summary()/saveConfig already skip it, so nothing downstream sees a "selection".
    local function noneSlot()
        return {
            Skin     = { Name = NONE_COSMETIC },
            Charm    = { Name = NONE_COSMETIC },
            Wrap     = { Name = NONE_COSMETIC },
            Finisher = { Name = NONE_COSMETIC },
        }
    end

    -- "Reset all", in TWO phases and both are needed.
    --   1. NONE everywhere + apply -> the guns revert on the spot, because only an explicit intent makes
    --      applyToItem do anything at all.
    --   2. THEN empty the table -> "reset" means forget my picks, not force the base weapon forever.
    --      Persisting the NONE sentinels instead would reload them next session and strip a skin the
    --      player genuinely owns and equipped in the real menu.
    function GameVisuals.restore()
        for weapon in pairs(GameVisuals.Choices) do
            GameVisuals.Choices[weapon] = noneSlot()
        end
        _forceRebuild = true
        pcall(GameVisuals.apply)
        _forceRebuild = false
        GameVisuals.Choices = {}
        pcall(syncMask)
        note("reset")
        saveSoon()
    end

    -- ── LIFECYCLE ───────────────────────────────────────────────────────────────────────────────
    local _conn, _last, _loaded = nil, 0, false

    function GameVisuals.enable()
        Config.GameVisuals = true
        resolveModules()
        local hok, hwhy = hooksInstall()
        if hok then
            note("hooks bound (" .. tostring(hwhy) .. ")")
        else
            note("hooks: " .. tostring(hwhy))
        end
        local cok, cwhy = captureInstall()
        if not cok then note("menu capture unavailable (" .. tostring(cwhy) .. ")") end
        local mok, mwhy = syncMask()
        if not mok then note("mask: " .. tostring(mwhy)) end
        -- ★ THE TWO NUMBERS THAT USED TO LIVE IN DIAGNOSE, now in the history where the operator can
        -- actually see them. `hooks` separates "the mechanism never installed" from "it installed and did
        -- nothing" — six rewrites were unfalsifiable for want of exactly that. `menu doors` says whether
        -- both call sites of the equip capture were reached, and `captured` whether a click ever landed
        -- in the decoy: doors>0 with captured=0 after clicking in the game's menu means the upvalue we
        -- swapped is not the one the click reads.
        note("hooks=" .. #HOOKS .. "  menu doors=" .. _captureBound .. "/2  captured=" .. _captured)
        -- ★ AUTO-LOAD. Deliberately AFTER the mask and hooks are up, so loadConfig's single apply() has
        -- somewhere to land. _loaded guards against enable() being called twice with no disable between —
        -- which happens on a re-execute — while disable() clears it, so toggling the feature off and on
        -- correctly re-reads the loadout that disable() just wiped out of memory.
        if Config.GVRemember ~= false and not _loaded then
            _loaded = true
            local lok, lwhy = GameVisuals.loadConfig()
            if not lok and lwhy ~= "no saved cosmetics" then note("load: " .. tostring(lwhy)) end
        end
        if _conn ~= nil then return end
        -- The birth hook covers everything built from now on; this poll only catches weapons that
        -- already existed when a selection changed, and re-tries the hooks if the modules were not
        -- loaded yet at enable time.
        _conn = RunService.Heartbeat:Connect(function()
            if Config.GameVisuals ~= true then return end
            local now = tick()
            if now - _last < POLL_S then return end
            _last = now
            if #HOOKS == 0 and Config.GVBirthHook ~= false then pcall(hooksInstall) end
            if _captureBound < 2 and Config.GVBirthHook ~= false then pcall(captureInstall) end
            if maskNeeded() and not maskActive() then pcall(syncMask) end
            pcall(GameVisuals.apply)
            saveDrain()
        end)
    end

    function GameVisuals.disable()
        Config.GameVisuals = false
        -- ★ FLUSH BEFORE ANYTHING IS WIPED. The save is debounced by 1 s, so switching the feature off
        -- within a second of a pick would otherwise lose it: the poll that drains the debounce is about to
        -- be disconnected and Choices is about to be emptied.
        if _saveAt ~= nil then
            _saveAt = nil
            pcall(GameVisuals.saveConfig)
        end
        -- Cleared so the NEXT enable() re-reads the file. disable() empties Choices, so without this the
        -- feature would come back on with nothing selected while the saved loadout sat on disk.
        _loaded = false
        if _conn ~= nil then
            _conn:Disconnect()
            _conn = nil
        end
        if _maskConn ~= nil then
            pcall(function() _maskConn:Disconnect() end)
            _maskConn = nil
        end
        captureRestore()
        -- ★ PUT THE GUNS BACK BEFORE DROPPING THE HOOKS, and clear to the explicit NONE sentinel rather
        -- than emptying the table — an empty Choices makes applyToItem take its no-selection branch, so
        -- `Choices = {}` here (what shipped) reverted nothing at all and the player kept a skin they had
        -- just switched the feature off to be rid of. The rebuild needs the birth hooks, hence the
        -- ordering: revert, then hooksRestore.
        for weapon in pairs(GameVisuals.Choices) do
            GameVisuals.Choices[weapon] = noneSlot()
        end
        _forceRebuild = true
        pcall(applyToPlayer, lp)
        _forceRebuild = false
        GameVisuals.Choices = {}
        hooksRestore()
        _favOverride = {}
        _spoof.CosmeticInventory  = nil
        _spoof.FavoritedCosmetics = nil
        _spoof.WeaponInventory    = nil
        maskRemove()
        note("off")
    end

    -- ── CATALOGUE (GUI dropdowns) ───────────────────────────────────────────────────────────────
    -- Built from the GAME's own CosmeticLibrary at runtime, never a hardcoded list — a hardcoded list
    -- goes stale on a content update and then names a viewmodel the game does not have.
    local CAT = nil

    local function sortTail(t)
        local head = table.remove(t, 1)
        table.sort(t)
        table.insert(t, 1, head)
        -- Random sits directly under None so the two synthetic entries stay together at the top.
        table.insert(t, 2, "Random")
    end

    local function buildCatalog()
        if CAT ~= nil then return end
        CAT = {
            Skin = { "None" }, Charm = { "None" }, Wrap = { "None" }, Finisher = { "None" },
            weapons = { "None" }, byWeapon = {}, owner = {},
        }
        pcall(function()
            local cos = Rivals.Cosmetics.Cosmetics
            if type(cos) ~= "table" then return end
            for name, entry in pairs(cos) do
                if type(entry) == "table" and entry.Hidden ~= true then
                    local t = entry.Type
                    if t == "Skin" and type(entry.ItemName) == "string" then
                        local item = entry.ItemName
                        CAT.owner[name] = item
                        CAT.owner[item .. " | " .. name] = item
                        table.insert(CAT.Skin, item .. " | " .. name)
                        if CAT.byWeapon[item] == nil then
                            CAT.byWeapon[item] = { "None" }
                            table.insert(CAT.weapons, item)
                        end
                        table.insert(CAT.byWeapon[item], name)
                    elseif CAT[t] ~= nil then
                        table.insert(CAT[t], name)
                    end
                end
            end
        end)
        sortTail(CAT.Skin) ; sortTail(CAT.Charm) ; sortTail(CAT.Wrap)
        sortTail(CAT.Finisher)
        -- The weapon list is a target, not a cosmetic — "Random" there would mean nothing.
        local head = table.remove(CAT.weapons, 1)
        table.sort(CAT.weapons)
        table.insert(CAT.weapons, 1, head)
        for _, list in pairs(CAT.byWeapon) do sortTail(list) end
    end

    function GameVisuals.listOf(kind)
        buildCatalog()
        return CAT[kind] or { "None" }
    end

    function GameVisuals.skinList()  return GameVisuals.listOf("Skin")  end
    function GameVisuals.charmList() return GameVisuals.listOf("Charm") end
    function GameVisuals.wrapList()  return GameVisuals.listOf("Wrap")  end
    function GameVisuals.finisherList() return GameVisuals.listOf("Finisher") end

    function GameVisuals.weaponList()
        buildCatalog()
        return CAT.weapons
    end

    function GameVisuals.skinsFor(item)
        buildCatalog()
        local list = CAT.byWeapon[item]
        if list == nil then return { "None" } end
        return list
    end

    -- ── SETTERS ─────────────────────────────────────────────────────────────────────────────────
    -- These NEVER early-return on the master toggle. A selection made before enabling used to be
    -- silently discarded, which is indistinguishable from the feature not working. Record always;
    -- apply only when enabled.
    local _weapon = nil
    GameVisuals.lastWeapon = nil

    function GameVisuals.setWeapon(name)
        if name == nil or name == "None" then _weapon = nil else _weapon = name end
        GameVisuals.lastWeapon = _weapon
    end

    -- Charms, wraps and finishers go on the weapon the operator is holding, which is the only
    -- unambiguous target, falling back to the weapon chosen in the dropdown above.
    local function heldItemName()
        local base = nil
        pcall(function()
            local lf = Rivals.Fighter and Rivals.Fighter.LocalFighter
            local it = lf and lf.EquippedItem
            if it ~= nil then base = it.Name end
        end)
        if type(base) == "string" then return base end
        return _weapon
    end

    -- The one place a selection is written. `kind` is the GAME's capitalised cosmetic Type, and the
    -- name may arrive either from our own dropdown ("None" / "Random") or straight out of the game's
    -- menu, which uses nil for cleared and its own RANDOM_COSMETIC sentinel. daydreamer normalises both
    -- the same way (`isnone` / `israndom`, cosmetics.lua:192-198).
    function GameVisuals.setFor(weapon, kind, name, inverted)
        if type(weapon) ~= "string" or type(kind) ~= "string" then return end
        buildCatalog()
        local slot = GameVisuals.Choices[weapon]
        if slot == nil then
            slot = {}
            GameVisuals.Choices[weapon] = slot
        end
        if name == nil or name == "None" or name == NONE_COSMETIC then
            slot[kind] = { Name = NONE_COSMETIC }
        elseif name == "Random" or name == RANDOM_COSMETIC then
            slot[kind] = { Name = RANDOM_COSMETIC, Type = kind, Inverted = inverted == true }
        else
            local rec = cloneCosmetic(name, kind, inverted)
            if rec == nil then
                note("unknown " .. kind .. ": " .. tostring(name))
                return
            end
            slot[kind] = rec
        end
        GameVisuals.lastWeapon = weapon
        note(weapon .. " " .. kind .. " = " .. tostring(name))
        -- The menu reads its equipped tick out of WeaponInventory, so the mask has to be re-stamped
        -- before the game is told to redraw — otherwise the pick applies to the gun but the menu keeps
        -- showing the old one as equipped.
        pcall(syncMask)
        pcall(GameVisuals.apply)
        saveSoon()
    end

    function GameVisuals.setSkin(label)
        buildCatalog()
        -- The dropdown yields a bare skin name once the list has narrowed to a weapon, and the
        -- "Weapon | Skin" label otherwise. CAT.owner is keyed by BOTH, so neither form is parsed.
        if label == nil or label == "None" then
            if _weapon ~= nil then GameVisuals.setFor(_weapon, "Skin", nil) end
            return
        end
        if label == "Random" then
            local w = _weapon or heldItemName()
            if w == nil then
                note("pick a Weapon above, or hold the one you want to change")
                return
            end
            GameVisuals.setFor(w, "Skin", "Random")
            return
        end
        local item = CAT.owner[label]
        if item == nil then
            note("unknown skin: " .. tostring(label))
            return
        end
        local skin = label
        local bar = string.find(label, " | ", 1, true)
        if bar ~= nil then skin = string.sub(label, bar + 3) end
        GameVisuals.setFor(item, "Skin", skin)
    end

    -- Charm / Wrap / Finisher all share one entry point; only the target resolution differs from skins.
    function GameVisuals.setOn(kind, name)
        local base = _weapon or heldItemName()
        if base == nil then
            note("pick a Weapon above, or hold the one you want to change")
            return
        end
        local inv = nil
        if kind == "Wrap" then inv = Config.GVWrapInverted == true end
        GameVisuals.setFor(base, kind, name, inv)
    end

    function GameVisuals.setCharm(name)    GameVisuals.setOn("Charm", name)    end
    function GameVisuals.setWrap(name)     GameVisuals.setOn("Wrap", name)     end
    function GameVisuals.setFinisher(name) GameVisuals.setOn("Finisher", name) end

    function GameVisuals.setWrapInverted(on)
        Config.GVWrapInverted = (on == true)
        -- Re-stamp every wrap already chosen, otherwise the flag only affects the NEXT selection.
        for _, slot in pairs(GameVisuals.Choices) do
            local w = slot.Wrap
            if type(w) == "table" and w.Name ~= NONE_COSMETIC then
                w.Inverted = Config.GVWrapInverted
                -- For a Random wrap the record the GAME reads is the memoised roll, not the sentinel,
                -- so stamping only the sentinel would leave the flag visibly doing nothing.
                if type(w.Resolved) == "table" then w.Resolved.Inverted = Config.GVWrapInverted end
            end
        end
        note("wrap inverted " .. tostring(Config.GVWrapInverted))
        pcall(GameVisuals.apply)
        saveSoon()
    end

    -- ⛔ GameVisuals.applyToAll LIVED HERE UNTIL 2026-08-16 AND WAS REMOVED on operator instruction
    -- ("bug with apply charm/wrap/finisher to all ... rather than fixing it just remove that whole
    -- thing"). It copied one weapon's charm/wrap/finisher onto every other weapon in the catalogue.
    -- Worth recording that UE's own version refuses half the job for the same structural reason a skin
    -- cannot be copied: a skin belongs to exactly ONE weapon (its CosmeticLibrary entry carries ItemName),
    -- and UE's button says so out loud — "cant apply weapon skins to all!" (dump proto 267).

    -- Same two phases as restore(): NONE + apply to revert this weapon on the spot, then drop the slot so
    -- the clear is "forget it", not "force the base weapon every session from now on".
    function GameVisuals.clearWeapon()
        local base = _weapon or heldItemName()
        if base == nil then return end
        GameVisuals.Choices[base] = noneSlot()
        _forceRebuild = true
        pcall(GameVisuals.apply)
        _forceRebuild = false
        GameVisuals.Choices[base] = nil
        note("cleared " .. base)
        pcall(syncMask)
        saveSoon()
    end

    -- One line per weapon: what is actually loaded right now. This is the ONLY thing the Game Visuals tab
    -- renders since the status line and the history box were removed on 2026-08-16 ("only show what skins
    -- are loaded ... and if removed then its gone"), so a weapon with nothing set produces no line at all.
    function GameVisuals.summary()
        local out = {}
        for weapon, slot in pairs(GameVisuals.Choices) do
            local bits = {}
            for _, kind in pairs({ "Skin", "Wrap", "Charm", "Finisher" }) do
                local v = slot[kind]
                if v ~= nil and v.Name ~= NONE_COSMETIC then
                    local shown = tostring(v.Name)
                    if v.Name == RANDOM_COSMETIC then
                        -- The sentinel is meaningless on screen; the memoised roll is the thing the
                        -- player is actually looking at (resolveSel caches it in .Resolved).
                        shown = "Random"
                        if type(v.Resolved) == "table" and v.Resolved.Name ~= nil then
                            shown = "Random (" .. tostring(v.Resolved.Name) .. ")"
                        end
                    end
                    table.insert(bits, string.lower(kind) .. " " .. shown)
                end
            end
            if #bits > 0 then
                local line = weapon .. " — " .. table.concat(bits, " · ")
                -- ★ THE ONE PIECE OF DIAGNOSIS THE PANEL STILL CARRIES. A selection that the game refused
                -- to apply live looks identical to one that applied, and that ambiguity is what made four
                -- rewrites of this feature impossible to debug from the field. One suffix fixes it and
                -- tells the player something true and useful at the same time.
                local why = _lastRefusal[weapon]
                if why ~= nil then line = line .. "  (" .. tostring(why) .. ")" end
                table.insert(out, line)
            end
        end
        table.sort(out)
        return out
    end

    -- Is the mechanism actually installed? The GUI has no status line any more, so this is what lets the
    -- loaded-cosmetics list say "not active yet" instead of just looking empty and broken. #HOOKS is the
    -- one number that separates "never bound" from "bound and had no effect" — the ambiguity that made
    -- six rewrites of this feature unfalsifiable.
    function GameVisuals.ready()
        return #HOOKS > 0
    end

    -- ── PERSISTENCE ─────────────────────────────────────────────────────────────────────────────
    -- ★ WHY THIS EXISTS AT ALL. LinoriaLib's SaveManager already saves the GV dropdowns, so it LOOKS
    -- covered — but the dropdowns are not the state. The in-game menu capture (Layer 1) writes straight
    -- into GameVisuals.Choices without touching a control, and one dropdown cannot hold a per-weapon map
    -- anyway: pick a skin on the AR and another on the Sniper and only the last one survives. So the
    -- selection gets its own file.
    --
    -- ★ NAMES ONLY, NEVER THE CLONE. cloneCosmetic copies the whole live CosmeticLibrary record; freezing
    -- one of those to disk means that after a content update we hand the game a record describing a
    -- viewmodel it no longer ships. Storing { Name, Inverted } and re-cloning on load always reads the
    -- library that is actually running. The NONE_COSMETIC / RANDOM_COSMETIC sentinels round-trip as their
    -- own names because setFor already normalises both.
    --
    -- Both rivals persist the same unremarkable way — HttpService:JSONEncode + writefile, isfile/readfile/
    -- JSONDecode back (Kicia under kiciahook/rivals_v3/…). Nothing here is copied from either; there is
    -- nothing to copy.
    local CFG_DIR, CFG_FILE = "LuaHook", "LuaHook/cosmetics.json"

    local function fsReady()
        if type(writefile) ~= "function" or type(readfile) ~= "function"
            or type(isfile) ~= "function" then
            if not _fsWarned then
                _fsWarned = true
                note("no filesystem API — picks last this session only")
            end
            return false
        end
        -- makefolder on an existing folder throws on some executors, so test first and swallow either way.
        pcall(function()
            if type(isfolder) ~= "function" or type(makefolder) ~= "function" then return end
            if not isfolder(CFG_DIR) then makefolder(CFG_DIR) end
        end)
        return true
    end

    function GameVisuals.saveConfig()
        if Config.GVRemember == false then return false, "remember picks is off" end
        if not fsReady() then return false, "no filesystem API" end
        local doc = { v = 1, choices = {} }
        for weapon, slot in pairs(GameVisuals.Choices) do
            local entry = nil
            for _, kind in pairs({ "Skin", "Charm", "Wrap", "Finisher" }) do
                local sel = slot[kind]
                if type(sel) == "table" and type(sel.Name) == "string" then
                    if entry == nil then entry = {} end
                    entry[kind] = { Name = sel.Name, Inverted = sel.Inverted == true }
                end
            end
            if entry ~= nil then doc.choices[weapon] = entry end
        end
        local ok, err = pcall(function()
            writefile(CFG_FILE, game:GetService("HttpService"):JSONEncode(doc))
        end)
        if not ok then return false, tostring(err) end
        return true, nil
    end

    -- Debounced, because the in-game menu produces a burst of picks as the operator clicks through a page
    -- and one disk write per click is both wasteful and a needlessly regular I/O pattern. Drained by the
    -- Heartbeat poll.
    saveSoon = function()
        if Config.GVRemember == false then return end
        _saveAt = tick() + 1
    end

    saveDrain = function()
        if _saveAt == nil or tick() < _saveAt then return end
        _saveAt = nil
        local ok, why = GameVisuals.saveConfig()
        if not ok and why ~= "remember picks is off" and why ~= "no filesystem API" then
            note("save failed: " .. tostring(why))
        end
    end

    -- ★ ONE syncMask AND ONE apply FOR THE WHOLE FILE, not one per entry. Routing a saved loadout through
    -- setFor would re-stamp the mask and walk every carried item once per cosmetic, which on a full
    -- loadout is dozens of redundant rebuild comparisons at exactly the moment the feature starts up.
    function GameVisuals.loadConfig()
        if not fsReady() then return false, "no filesystem API" end
        local raw = nil
        pcall(function()
            if isfile(CFG_FILE) then raw = readfile(CFG_FILE) end
        end)
        if type(raw) ~= "string" or #raw == 0 then return false, "no saved cosmetics" end
        local doc = nil
        pcall(function() doc = game:GetService("HttpService"):JSONDecode(raw) end)
        if type(doc) ~= "table" then return false, "cosmetics.json did not decode" end
        buildCatalog()
        local n, skipped = 0, 0
        if type(doc.choices) == "table" then
            for weapon, entry in pairs(doc.choices) do
                if type(weapon) == "string" and type(entry) == "table" then
                    local slot = GameVisuals.Choices[weapon]
                    if slot == nil then
                        slot = {}
                        GameVisuals.Choices[weapon] = slot
                    end
                    for _, kind in pairs({ "Skin", "Charm", "Wrap", "Finisher" }) do
                        local sel = entry[kind]
                        if type(sel) == "table" and type(sel.Name) == "string" then
                            local inverted = sel.Inverted == true
                            if sel.Name == NONE_COSMETIC then
                                slot[kind] = { Name = NONE_COSMETIC }
                                n = n + 1
                            elseif sel.Name == RANDOM_COSMETIC then
                                slot[kind] = { Name = RANDOM_COSMETIC, Type = kind, Inverted = inverted }
                                n = n + 1
                            else
                                -- Re-cloned from the LIVE library, so a cosmetic the game has since
                                -- removed is dropped here rather than handed to the viewmodel constructor.
                                local rec = cloneCosmetic(sel.Name, kind, inverted)
                                if rec == nil then
                                    skipped = skipped + 1
                                else
                                    slot[kind] = rec
                                    n = n + 1
                                end
                            end
                        end
                    end
                    if next(slot) == nil then GameVisuals.Choices[weapon] = nil end
                end
            end
        end
        pcall(syncMask)
        pcall(GameVisuals.apply)
        local msg = "loaded " .. n .. " saved picks"
        if skipped > 0 then msg = msg .. " (" .. skipped .. " no longer in the game)" end
        note(msg)
        return true, n
    end

    -- ── LAYER 1 · THE EQUIP CAPTURE ─────────────────────────────────────────────────────────────
    -- The game's own Equipment menu becomes the selection surface, and NOTHING reaches the server.
    --
    -- Customize/Cosmetics.luau builds each row in a local `generate_slot` closure (:180-229). Its
    -- upvalue for ReplicatedStorage is read at exactly ONE place in the whole module — the equip fire at
    -- :217 (verified: v_u_1 appears at :3 and :5-8, which are module init and already executed, and at
    -- :217). Swapping that upvalue for a decoy therefore does BOTH jobs at once: the remote call lands
    -- in our function instead of on the wire, and it arrives with the game's own arguments —
    -- (weapon, cosmeticType, name-or-nil, { IsInverted }).
    --
    -- Kicia needs two mechanisms for this (flip upvalue 9 to suppress, then attach its own click
    -- listener to observe) and pins both to a guessed index; daydreamer needs hookmetamethod(game,
    -- "__namecall"). We resolve the upvalue by CLASS IDENTITY — the one upvalue that is an Instance
    -- whose ClassName is "ReplicatedStorage" — so a game update that reorders upvalues cannot make us
    -- overwrite something else.
    --
    -- generate_slot is created fresh inside every _Generate call, so it is reached the way Kicia reaches
    -- it: from a hook on CosmeticSlot.new, whose caller at level 2 IS generate_slot. Options.luau's two
    -- option buttons (Inverted, OnlyUseFavorites at :147 and :160) live in different closures created
    -- inside Options._Init, and those hold a REF to _Init's own upvalue — so patching _Init covers them,
    -- and it covers FavoriteCosmetic (:124) at the same time.
    -- The poll retries only while _captureBound is short of 2, so a resolved capture costs nothing per
    -- frame. That variable and _rsPatch / _captured / DECOY / _lastFn are declared UP AT THE TOP with the
    -- other cross-layer state, because enable()'s Heartbeat closure reads _captureBound — see the note
    -- there for the nil-global crash that caused.
    local function isReplicatedStorage(v)
        local ok = false
        pcall(function() ok = (typeof(v) == "Instance" and v.ClassName == "ReplicatedStorage") end)
        return ok
    end

    -- ★ THE STACK LEVEL IS SEARCHED, NOT ASSUMED. `debug.info(2, ...)` looks like the right level from
    -- inside the CosmeticSlot.new wrapper, but the call has to be pcall'd (not every executor implements
    -- the "f" option) and both pcall and the closure it wraps occupy CallInfo frames — so the constant
    -- would be wrong by an amount that depends on the executor, and the failure is a SILENT no-op.
    -- Walking outward and matching the frame instead is immune to that.
    -- ⚠ SIX modules require CosmeticSlot — Collection, EquipEmote, PickEmote, RewardSlot,
    -- Customize/Cosmetics and Customize/NameDisplay — so the match must be exact. `Cosmetics$` is
    -- Kicia's own guard (leak 90615) and it selects the one module that fires the equip.
    local function cosmeticsCaller()
        for lvl = 2, 8 do
            local src, fn = nil, nil
            -- A level past the top of the stack yields nil rather than throwing, and an intermediate C
            -- frame yields "[C]" — neither is a reason to stop, because the frame we want may be
            -- further out. Only an outright error ends the walk.
            local ok = pcall(function() src, fn = debug.info(lvl, "sf") end)
            if not ok then return nil end
            if type(src) == "string" and type(fn) == "function"
                and string.match(src, "Cosmetics$") ~= nil then
                return fn
            end
        end
        return nil
    end

    local function onEquipPicked(weapon, ctype, cname, opts)
        _captured = _captured + 1
        if type(weapon) ~= "string" or type(ctype) ~= "string" then return end
        local inverted = nil
        if type(opts) == "table" then inverted = opts.IsInverted == true end
        if ctype == "Wrap" and inverted ~= nil then Config.GVWrapInverted = inverted end
        GameVisuals.setFor(weapon, ctype, cname, inverted)
    end

    -- The star button. Swallowing it and doing nothing else would leave the star visibly dead, so the
    -- pick is recorded in a local overlay that everyFavorite merges — the UI then lights up exactly as
    -- it would have, and nothing claims ownership on the wire. Cosmetics.luau:44 and Options.luau:115
    -- read the list under GetNoneSpecificCosmeticName(name, type), which (CosmeticLibrary:162-171)
    -- suffixes ONLY the NONE sentinel, so that is the one case that needs the transform applied here.
    local function onFavouritePicked(weapon, cname, state, ctype)
        if type(weapon) ~= "string" or type(cname) ~= "string" then return end
        local key = cname
        if cname == NONE_COSMETIC and type(ctype) == "string" then key = cname .. "_" .. ctype end
        local slot = _favOverride[weapon]
        if slot == nil then
            slot = {}
            _favOverride[weapon] = slot
        end
        slot[key] = (state == true) or nil
        refresh("FavoritedCosmetics")
    end

    local function makeDecoy()
        local equip = {}
        equip.FireServer = function(_, weapon, ctype, cname, opts)
            pcall(onEquipPicked, weapon, ctype, cname, opts)
        end
        local fav = {}
        fav.FireServer = function(_, weapon, cname, state, ctype)
            pcall(onFavouritePicked, weapon, cname, state, ctype)
        end
        return { Remotes = { Data = { EquipCosmetic = equip, FavoriteCosmetic = fav } } }
    end

    -- Idempotent, and safe to call on every poll: a closure already carrying the decoy is skipped.
    -- ★ _lastFn matters for cost, not correctness. This runs once per COSMETIC ROW — a menu page builds
    -- a hundred of them — and without the memo every row would pay a full upvalue scan, which on an
    -- executor lacking debug.getupvalues degrades to 64 pcalls apiece.
    local function patchRemoteUpvalue(fn)
        if type(fn) ~= "function" then return false end
        if fn == _lastFn then return true end
        if debug.setupvalue == nil then return false end
        if DECOY == nil then DECOY = makeDecoy() end
        local ups = upvaluesOf(fn)
        if ups == nil then return false end
        for i, v in pairs(ups) do
            if v == DECOY then return true end
            if isReplicatedStorage(v) then
                local ok = false
                pcall(function()
                    debug.setupvalue(fn, i, DECOY)
                    ok = true
                end)
                if ok then
                    _lastFn = fn
                    table.insert(_rsPatch, { fn = fn, idx = i, orig = v })
                    -- generate_slot is minted fresh inside every _Generate, so if Luau gives each
                    -- closure its own upvalue cell this list grows by one per menu open. Bound it:
                    -- restore and drop the oldest, which by then belongs to a dead closure anyway.
                    -- (If the cell IS shared with the module scope the early `v == DECOY` return above
                    -- fires instead and the list never grows past one — this is the other case.)
                    while #_rsPatch > 24 do
                        local oldest = _rsPatch[1]
                        pcall(function() debug.setupvalue(oldest.fn, oldest.idx, oldest.orig) end)
                        table.remove(_rsPatch, 1)
                    end
                    return true
                end
                return false
            end
        end
        return false
    end

    captureRestore = function()
        for i = #_rsPatch, 1, -1 do
            local p = _rsPatch[i]
            pcall(function() debug.setupvalue(p.fn, p.idx, p.orig) end)
            _rsPatch[i] = nil
        end
        _captureBound = 0
        _lastFn = nil
    end

    captureInstall = function()
        resolveModules()
        if Config.GVBirthHook == false then return false, "menu capture disabled with the birth hook" end
        if debug.setupvalue == nil then return false, "executor lacks debug.setupvalue" end
        local bound = 0
        -- (a) the cosmetic rows. debug.info(2) inside the wrapper is generate_slot itself.
        if hookField(M.cslot, "new", function(orig)
            return function(...)
                if debug.info ~= nil then
                    local fn = cosmeticsCaller()
                    if fn ~= nil then pcall(patchRemoteUpvalue, fn) end
                end
                return orig(...)
            end
        end) then bound = bound + 1 end
        -- (b) the Inverted / OnlyUseFavorites / Favorite buttons.
        if M.copts ~= nil then
            local initFn = nil
            pcall(function() initFn = M.copts._Init end)
            if patchRemoteUpvalue(initFn) then bound = bound + 1 end
        end
        _captureBound = bound
        if bound == 0 then return false, "no capture target resolved yet" end
        return true, bound
    end

end)()

-- ── INIT ───────────────────────────────────────────────────────────────────
-- isolate each so one module failing to init can't abort the whole load (which could leave hooks
-- half-applied). The Gun hook is already crash-isolated separately.
pcall(Visuals.init); pcall(Rage.init); pcall(Aimbot.init); pcall(Trigger.init); pcall(ESP.init); pcall(Weather.init); pcall(UtilESP.init)

-- HUD is an independent master (decoupled from Visuals). Start it if on by default/saved.
if Config.HUD then pcall(Visuals.enableHUD) end
pcall(HUDPlus.init)   -- rides the HUD master (starts its updater only when Config.HUD is on)

-- ── AC BYPASS  Channel A neutralization — MOVED to 00b_ac_emitter_scrub.lua ──────────────────
-- The old `ACReportBypass` (rawset shared.r numeric slots -> no-op) and `ChannelBKill` (getgc
-- hookfunction on TakeTheL/ban/kick reporters) blocks that lived HERE were REMOVED 2026-07-12.
-- WHY: both TAMPERED the egress (silenced handlers / no-op'd reporters). The wire oracle + the
-- independent review showed egress-tampering is itself a liability: it cannot silence the
-- keepalive (Channel B is continuous; its ABSENCE is a flag), and shadowing/no-op'ing report
-- handlers is a distinguishable client state. They are REPLACED by the SCRUB-AT-EMITTER-INPUT
-- design in 00b_ac_emitter_scrub.lua, which lets the genuine clean pipeline run over {1,2,3,4,5}
-- filler so the frame that leaves is byte-identical to a real clean report BY CONSTRUCTION, and
-- leaves Channel B untouched. The setmetatable hang (Layer 1, 01_bootstrap) remains the
-- load-bearing bypass. See C:\Kernaled\ac-re\BYPASS_UPDATED_DESIGN.txt for the full rationale.
-- IMPORTANT: purge any STALE saved LinoriaLib config that force-enables the retired
-- Config.ACReportBypass / Config.ChannelBKill flags (they are now dead toggles).

-- ── LINORIA GUI ────────────────────────────────────────────────────────────
-- LINORIA GUI (MOBILE OPTIMISED – conditional)
local repo = 'https://raw.githubusercontent.com/mstudio45/LinoriaLib/main/'
local Library, ThemeManager, SaveManager
-- UPSTREAM BUG PATCHED AT LOAD (2026-07-28 — this crash killed the whole script).
-- Library.lua:396 fetches its Lucide icon pack from a THIRD repo:
--     local FetchIcons, Icons = pcall(function() return loadstring(game:HttpGet(
--         ".../deividcomsono/lucide-roblox-direct/.../source.lua"))() end)
-- pcall returns (success, result). A fetch that ERRORS gives FetchIcons=false and the guard at
-- :408 catches it — but a fetch that SUCCEEDS and returns nil (empty body, or a source with no
-- return statement) gives FetchIcons=TRUE with Icons=nil. Then :412 runs
--     local Success, Icon = pcall(Icons.GetAsset, IconName)
-- and `Icons.GetAsset` is indexed BEFORE pcall is entered, so the nil-index throws OUTSIDE it.
-- That surfaces inside Library:CreateWindow (getAsset -> getIcon -> getCustomIcon ->
-- setBackgroundImage) and kills the whole chunk, because CreateWindow is outside this pcall.
-- `Icons.` is used exactly ONCE (:412) and `if not FetchIcons then` appears exactly ONCE (:408),
-- so re-pointing that one guard at Icons fixes the bug at its root — icons still work whenever
-- the fetch genuinely succeeds. Guarded: if the pattern stops matching we load source unmodified.
-- ★ FETCHED CONCURRENTLY, 2026-08-15. These were three SEQUENTIAL round trips to GitHub, all of them on
-- the critical path before any window can exist — part of what the operator saw as "the script loads
-- after some timer". They are three independent documents; only the loadstring ORDER matters, so the
-- fetches overlap and the execution stays exactly as it was. Failure semantics are unchanged too: if
-- any of the three does not arrive we raise inside this pcall, which is what a throwing HttpGet did
-- before, so the warn-and-return path below still fires.
local ok, err = pcall(function()
    local files, pending = {}, 3
    local urls = { 'Library.lua', 'addons/ThemeManager.lua', 'addons/SaveManager.lua' }
    for i = 1, 3 do
        task.spawn(function()
            local got, body = pcall(function() return game:HttpGet(repo .. urls[i]) end)
            if got and type(body) == 'string' and #body > 0 then files[i] = body end
            pending = pending - 1
        end)
    end
    local deadline = tick() + 20
    while pending > 0 and tick() < deadline do task.wait() end
    for i = 1, 3 do
        if files[i] == nil then error('failed to fetch ' .. urls[i], 0) end
    end
    local src = files[1]
    local patched, n = src:gsub('if not FetchIcons then', 'if not Icons then')
    if n > 0 then src = patched end
    Library      = loadstring(src)()
    ThemeManager = loadstring(files[2])()
    SaveManager  = loadstring(files[3])()
end)
if not ok or not Library then warn("[Engine] Linoria load failed:", err); return end

-- Only apply mobile flags when actually on a touch device
Library.IsMobile = isMobile
-- CURSOR FIX (2nd-monitor offset): always use the native OS cursor. The Linoria custom cursor is a
-- Drawing-library Triangle that renders in physical/desktop-pixel space, so on a secondary or DPI-scaled
-- monitor the drawn pointer sits shifted from where Roblox actually hit-tests GuiButtons ("clicks land off").
-- This is the same root cause we fixed for ESP by moving to the IgnoreGuiInset ScreenGui shim. Forcing
-- false makes MouseIconEnabled=true (the fork's cursor loop) so pointer + click always coincide on every
-- monitor/DPI. Touch already hit-tests natively, so mobile loses nothing. (Was: = isMobile — a touchscreen
-- laptop driving an external monitor reports TouchEnabled=true and silently got the offset drawn cursor.)
Library.ShowCustomCursor = false
Library.ShowToggleFrameInKeybinds = isMobile       -- toggle frame only on mobile

-- Refined default palette = the out-of-box look (a saved theme from the Settings tab overrides it on load).
-- Neutral near-black panels + a single cool accent; wrapped in pcall so an API drift can't break the load.
pcall(function()
    Library.MainColor       = Color3.fromRGB(26, 27, 31)
    Library.BackgroundColor = Color3.fromRGB(17, 18, 21)
    Library.AccentColor     = Color3.fromRGB(96, 165, 250)
    Library.OutlineColor    = Color3.fromRGB(43, 45, 52)
    Library.FontColor       = Color3.fromRGB(239, 241, 245)
end)

local windowOptions = {
    Title = 'LuaHook',
    Center = true,
    AutoShow = false,
    TabPadding = 8,
    MenuFadeTime = 0.2,
    NotifySide = 'Right',          -- notifications slide in from the right (out of the way of the tab rail)
    Resizable = true,              -- PC + mobile can resize/rescale the window
    UnlockMouseWhileOpen = true,   -- free OS cursor while the menu is open (re-locks for gameplay on close)
}

-- pcall'd: CreateWindow reaches into the library's asset/icon machinery, which depends on two
-- remote fetches we do not control. An unguarded throw here kills the whole chunk mid-load and
-- leaves the rage engine (already initialised by 12_init) running with no way to reach it.
local okWin, Window = pcall(function() return Library:CreateWindow(windowOptions) end)
if not okWin or not Window then
    warn("[LuaHook] GUI window failed to build:", Window)
    return
end

-- Lucide tab icons (mstudio45 fork: AddTab(Name, Icon)) for a cleaner, quicker-to-scan tab rail.
local Tabs = {
    Combat    = Window:AddTab('Combat'),
    Rage      = Window:AddTab('Rage'),
    ESP       = Window:AddTab('ESP'),
    -- ★ ONE Visuals TAB SINCE 2026-08-16. 'World Visuals' and 'Game Visuals' were two entries in the
    -- rail; they are now two sub-tabs inside this one (see the VISUALS TAB block for how, and why it
    -- takes two Tabboxes rather than one).
    Visuals   = Window:AddTab('Visuals'),
    HUD       = Window:AddTab('HUD'),
    Settings  = Window:AddTab('Settings'),
}
local Options = Library.Options or {}
local Toggles = Library.Toggles or {}
Library.Options = Options
Library.Toggles = Toggles

-- Sync background blur with window visibility
do
    local function findBlur()
        if Library.Window and Library.Window.Parent then
            for _, child in ipairs(Library.Window.Parent:GetChildren()) do
                if child ~= Library.Window and child:IsA("Frame") and child:FindFirstChildOfClass("BlurEffect") then
                    return child
                end
            end
        end
    end
    local blur = findBlur()
    if blur then
        blur.Visible = Library.Window.Visible
        Library.Window:GetPropertyChangedSignal("Visible"):Connect(function()
            blur.Visible = Library.Window.Visible
        end)
    end
end

