    R:AddSlider('AimbotSmoothness', { Text='Smoothness (0 = hard lock)',
        Default=Config.AimbotSmoothness, Min=0, Max=100, Rounding=0,
        Callback=function(v) Config.AimbotSmoothness = v end })
