-- ── VISUALS TAB ────────────────────────────────────────────────────────────
do
    local WL, WR, GL, GR
    local okTabs = pcall(function()
        local LTB = Tabs.Visuals:AddLeftTabbox('Visuals')
        local RTB = Tabs.Visuals:AddRightTabbox('Visuals')
        WL, WR = LTB:AddTab('World'), RTB:AddTab('World')
        GL, GR = LTB:AddTab('Game'),  RTB:AddTab('Game')
        local function pairTabs(a, b)
            local showA, showB = a.Show, b.Show
            if type(showA) ~= 'function' or type(showB) ~= 'function' then return end
            a.Show = function() showA(a) ; showB(b) end
            b.Show = function() showB(b) ; showA(a) end
        end
        pairTabs(WL, WR)
        pairTabs(GL, GR)
        local function hideTabRow(a, b)
            local inner = a.Container.Parent
            local outer = inner.Parent
            local row = nil
            for _, c in ipairs(inner:GetChildren()) do
                local lay = c:FindFirstChildOfClass('UIListLayout')
                if lay ~= nil and lay.FillDirection == Enum.FillDirection.Horizontal then row = c end
            end
            if row == nil then return end
            row.Visible = false
            local dy = 0
            for _, t in ipairs({ a, b }) do
                local p, s = t.Container.Position, t.Container.Size
                dy = p.Y.Offset - 2
                t.Container.Position = UDim2.new(p.X.Scale, p.X.Offset, 0, 2)
                t.Container.Size     = UDim2.new(s.X.Scale, s.X.Offset, 1, -2)
                local rawResize = t.Resize
                if type(rawResize) == 'function' then
                    t.Resize = function()
                        rawResize(t)
                        if t.Container.Visible then
                            local o = outer.Size
                            outer.Size = UDim2.new(o.X.Scale, o.X.Offset, o.Y.Scale, o.Y.Offset - dy)
                        end
                    end
                end
            end
        end
        hideTabRow(WR, GR)
    end)
    if not okTabs or WL == nil or WR == nil or GL == nil or GR == nil then
        WL = Tabs.Visuals:AddLeftGroupbox('World')
        WR = Tabs.Visuals:AddRightGroupbox('World')
        GL = Tabs.Visuals:AddLeftGroupbox('Game')
        GR = Tabs.Visuals:AddRightGroupbox('Game')
    end

