                    if Config.GameVisuals == true and GameVisuals.ready() ~= true then
                        lines = { 'not active yet' }
                    else
                        lines = {}
                    end
                end
                local joined = table.concat(lines, '\n')
                if joined ~= shown then
                    shown = joined
                    for i = 1, LOADED_LINES do
