task.spawn(function()
    pcall(function()
        ThemeManager:SetLibrary(Library)
        SaveManager:SetLibrary(Library)
        SaveManager:IgnoreThemeSettings()
        -- ★ THE COSMETIC DROPDOWNS ARE EXCLUDED, ADDED 2026-08-16, AND IT IS A BUG FIX not tidiness.
        -- SaveManager:Save walks Library.Options and Library.Toggles, and SaveManager:Load calls SetValue
        -- on every one it finds — which fires the Callback. GameVisuals.enable() reads
        -- LuaHook/cosmetics.json first, and then LoadAutoloadConfig ran right over the top of it: a
        -- config saved with the manual picker untouched holds GVSkin/GVCharm/GVWrap/GVFinisher = 'None',
        -- and replaying those calls setFor(weapon, kind, nil), which writes the NONE sentinel over the
        -- selection that had just been restored from disk. Two stores owning one piece of state, and the
        -- wrong one winning. cosmetics.json is the owner: it is per-WEAPON (a single dropdown cannot hold
        -- a map) and it is also what the in-game menu capture writes to, without touching a control at
        -- all.
        -- ⚠ THE LIST STAYS EVEN THOUGH THE CONTROLS ARE GONE (manual picker removed 2026-08-16).
        -- SetIgnoreIndexes on a name with no control is a no-op, and a config SAVED while the picker
        -- existed still carries those five keys - dropping them would let an old config replay exactly
        -- the callbacks described above. 'LH_ConfigName' is here for the same reason: a leftover from a
        -- custom config section this fork replaced with 'SaveManager_ConfigName'.
        SaveManager:SetIgnoreIndexes({ 'MenuKeybind', 'LH_ConfigName',
            'GVWeapon', 'GVSkin', 'GVCharm', 'GVWrap', 'GVFinisher' })
        ThemeManager:SetFolder('LuaHook')
        SaveManager:SetFolder('LuaHook/configs')
        SaveManager:BuildConfigSection(Tabs.Settings)
        ThemeManager:ApplyToTab(Tabs.Settings)

        local origNotify = Library.Notify
        Library.Notify = function() end
        SaveManager:LoadAutoloadConfig()
        Library.Notify = origNotify

        pcall(function() Library:Toggle() end)
    end)
end)

-- ── WATERMARK ──────────────────────────────────────────────────────────────
if not Library.SetWatermarkVisibility then
    Library.SetWatermarkVisibility = function(self, bool)
        if self.Watermark then self.Watermark.Visible = bool end
    end
end

local _wmAlive   = true
local _origUnload = Library.Unload
Library.Unload = function(self, ...)
    _wmAlive = false
    -- RESTORE the original Gun.StartShooting and clear the hook flags so a later re-execute installs a
    -- fresh hook instead of leaving this (now-unloaded) instance's hook live — the cause of "no guns".
    pcall(function()
        if shared._LH_GunOrig and Rivals.Gun then
            if setreadonly then pcall(setreadonly, Rivals.Gun, false) end
            Rivals.Gun.StartShooting = shared._LH_GunOrig
        end
        shared._gunHooked  = nil
        shared._LH_GunOrig = nil
        -- RESTORE the Katana._StartDeflecting deflect-detection hook (same sentinel pattern as the gun hook)
        if shared._LH_KatanaMod and shared._LH_KatanaDeflOrig then
            if setreadonly then pcall(setreadonly, shared._LH_KatanaMod, false) end
            shared._LH_KatanaMod._StartDeflecting = shared._LH_KatanaDeflOrig
        end
        shared._LH_KatanaMod      = nil
        shared._LH_KatanaDeflOrig = nil
        -- clear the Layer-1 sentinel so a re-execute re-installs the setmetatable hang (on executors that
        -- reset hookfunction state on re-inject but persist getgenv, a stale sentinel would skip re-hooking).
        if getgenv then getgenv().__LH_SetmtBP = nil end
    end)
    -- UNDO EVERY CONSTANT PATCH. Unlike a hook, a patched constant is a write into the game's own proto:
    -- it survives our chunk being unloaded and would leave a permanently modified game function behind.
    -- Outside the pcall above so a failure there cannot skip it.
    pcall(ViewAngle.restore)     -- an upvalue left swapped freezes the player's look angle for the session
    pcall(ConstPatch.revertAll)
    -- A swapped viewmodel outlives our chunk exactly like a patched constant does: the item holds OUR
    -- rebuilt ClientViewModel, so unloading without this leaves the player on a skin they do not own for
    -- the rest of the session, with no UI left to change it back.
    GameVisuals.uiAlive = false   -- stops the status-label mirror; the ScreenGui is about to be destroyed
    pcall(GameVisuals.disable)
    return _origUnload(self, ...)
end

pcall(function() Library:SetWatermark('LuaHook v1 beta') end)
-- Match the default-OFF ShowWatermark toggle so the Linoria watermark doesn't clash with the
-- SIGNAL v4 FX pill on load (the toggle re-shows it on demand).
pcall(function() Library:SetWatermarkVisibility(false) end)
task.spawn(function()
    while _wmAlive do
        pcall(function()
            if not Library.Watermark then return end
            local hits, shots = State.Hits, State.Shots
            local acc = shots > 0 and math.floor((hits / shots) * 100) or 0
            local text = string.format(
                'LuaHook v1 beta  ·  %s  ·  Shots: %d  ·  Hits: %d  ·  Acc: %d%%',
                lp.DisplayName, shots, hits, acc
            )
            if Config.Rage then
                text = text .. '  ·  Rage: ' .. (State.RageStatus or 'Idle')
            end
            Library.Watermark.Text = text
        end)
        task.wait(0.5)
    end
end)

